ALTER TABLE public.exercise_library
  ADD COLUMN IF NOT EXISTS name_en TEXT,
  ADD COLUMN IF NOT EXISTS instructions_en TEXT[];

UPDATE public.exercise_library
SET name_en = name,
    instructions_en = COALESCE(
      ARRAY(
        SELECT replace(replace(x, chr(157), ''), chr(13), '')
        FROM unnest(instructions) WITH ORDINALITY AS u(x, n)
        ORDER BY n
      ),
      '{}')
WHERE name_en IS NULL;

DO $do$
DECLARE
  n INTEGER;
BEGIN
  UPDATE public.exercise_library AS e
  SET name = t.value->>'name',
      instructions = ARRAY(
        SELECT y
        FROM jsonb_array_elements_text(t.value->'instructions')
             WITH ORDINALITY AS j(y, i)
        ORDER BY i
      )
  FROM jsonb_each($pt$
{
"3_4_Sit-Up":{"name":"Abdominal 3/4","instructions":["Deite-se no chão e prenda os pés. Suas pernas devem ficar flexionadas nos joelhos.","Coloque as mãos atrás ou ao lado da cabeça. Comece com as costas apoiadas no chão. Esta será a sua posição inicial.","Flexione o quadril e a coluna para elevar o tronco em direção aos joelhos.","No topo da contração, seu tronco deve ficar perpendicular ao chão. Inverta o movimento, descendo apenas ¾ do percurso.","Repita pela quantidade recomendada de repetições."]},
"90_90_Hamstring":{"name":"Alongamento Posterior de Coxa 90/90","instructions":["Deite-se de costas, com uma perna totalmente estendida.","Com a outra perna, flexione o quadril e o joelho a 90 graus. Você pode segurar a perna com as mãos se necessário. Esta será a sua posição inicial.","Estenda a perna para cima, fazendo uma breve pausa no topo. Retorne à posição inicial.","Repita por 10-20 repetições e depois troque de perna."]},
"Ab_Crunch_Machine":{"name":"Abdominal na Máquina","instructions":["Selecione uma carga leve e sente-se na máquina abdominal, posicionando os pés sob os apoios e segurando as alças superiores. Seus braços devem ficar dobrados em um ângulo de 90 graus enquanto os tríceps descansam nos apoios. Esta será a sua posição inicial.","Ao mesmo tempo, comece a elevar as pernas enquanto flexiona a parte superior do tronco. Expire ao executar esse movimento. Dica: certifique-se de usar um movimento lento e controlado. Concentre-se em usar o abdômen para mover o peso enquanto relaxa as pernas e os pés.","Após uma pausa de um segundo, retorne lentamente à posição inicial enquanto inspira.","Repita o movimento pela quantidade prescrita de repetições."]},
"Ab_Roller":{"name":"Roda Abdominal","instructions":["Segure a roda abdominal com as duas mãos e ajoelhe-se no chão.","Agora posicione a roda no chão à sua frente, apoiando-se nas mãos e nos joelhos (como na posição de flexão de braço ajoelhada). Esta será a sua posição inicial.","Role lentamente a roda abdominal para a frente, estendendo o corpo até ficar reto. Dica: desça o máximo que conseguir sem encostar o corpo no chão. Inspire durante esta fase do movimento.","Após uma pausa na posição estendida, comece a puxar o corpo de volta à posição inicial enquanto expira. Dica: vá devagar e mantenha o abdômen contraído o tempo todo."]},
"Adductor":{"name":"Adutores com Rolo de Espuma","instructions":["Deite-se de bruços com uma perna sobre um rolo de espuma.","Gire a perna de modo que o rolo de espuma fique em contato com a parte interna da coxa. Transfira o máximo de peso suportável para o rolo de espuma.","Tentando relaxar os músculos da parte interna da coxa, deslize sobre o rolo de espuma entre o quadril e o joelho, mantendo os pontos de tensão por 10-30 segundos. Repita com a outra perna."]},
"Adductor_Groin":{"name":"Alongamento de Adutores e Virilha","instructions":["Deite-se de costas com os pés elevados em direção ao teto.","Peça a um parceiro para segurar seus pés ou tornozelos. Afaste as pernas o máximo que puder. Esta será a sua posição inicial.","Tente apertar as pernas uma contra a outra por 10 segundos ou mais, enquanto seu parceiro impede o movimento.","Agora relaxe os músculos das pernas enquanto seu parceiro empurra seus pés para longe um do outro, alongando até onde for confortável. Avise seu parceiro quando o alongamento estiver adequado para evitar estiramento excessivo ou lesão."]},
"Advanced_Kettlebell_Windmill":{"name":"Moinho Avançado com Kettlebell","instructions":["Faça um clean (arremesso até o ombro) e um desenvolvimento acima da cabeça com um kettlebell usando um braço.","Mantendo o braço com o kettlebell totalmente estendido o tempo todo, empurre o quadril para o lado do kettlebell elevado. Mantenha o braço livre atrás das costas e gire os pés em um ângulo de 45 graus para o lado oposto ao do kettlebell.","Abaixe o tronco o máximo possível.","Faça uma pausa de um segundo e inverta o movimento até retornar à posição inicial."]},
"Air_Bike":{"name":"Abdominal Bicicleta","instructions":["Deite-se de costas no chão com a lombar pressionada contra o solo. Coloque as mãos ao lado da cabeça, tomando cuidado para não forçar o pescoço durante o exercício. Eleve os ombros para a posição inicial de abdominal.","Traga os joelhos para cima até ficarem perpendiculares ao chão, com as canelas paralelas ao solo. Esta será a sua posição inicial.","Simultaneamente, execute um movimento lento de pedalada, estendendo a perna direita à frente e trazendo o joelho esquerdo em direção ao peito. Leve o cotovelo direito perto do joelho esquerdo girando o tronco para o lado enquanto expira.","Retorne à posição inicial enquanto inspira.","Flexione o tronco para o lado oposto enquanto pedala as pernas, aproximando o cotovelo esquerdo do joelho direito ao expirar.","Continue alternando dessa forma até completar todas as repetições recomendadas para cada lado."]},
"All_Fours_Quad_Stretch":{"name":"Alongamento de Quadríceps em Quatro Apoios","instructions":["Comece apoiado nas mãos e nos joelhos, depois levante uma perna do chão e segure o pé com a mão.","Use a mão para segurar o pé ou o tornozelo, mantendo o joelho totalmente flexionado para alongar o quadríceps e os flexores do quadril.","Concentre-se em estender o quadril, empurrando-o em direção ao chão. Segure por 10-20 segundos e depois troque de lado."]},
"Alternate_Hammer_Curl":{"name":"Rosca Martelo Alternada","instructions":["Fique em pé com o tronco ereto e um halter em cada mão, segurando-os com os braços estendidos ao longo do corpo. Os cotovelos devem ficar próximos ao tronco.","As palmas das mãos devem ficar voltadas para o corpo. Esta será a sua posição inicial.","Mantendo o braço superior imóvel, flexione o braço direito à frente contraindo o bíceps enquanto expira. Continue o movimento até o bíceps ficar totalmente contraído e o halter na altura do ombro. Segure a contração por um segundo apertando o bíceps. Dica: apenas o antebraço deve se mover.","Comece a descer o halter lentamente de volta à posição inicial enquanto inspira.","Repita o movimento com a mão esquerda. Isso equivale a uma repetição.","Continue alternando dessa maneira pela quantidade recomendada de repetições."]},
"Alternate_Heel_Touchers":{"name":"Abdominal Toque Alternado nos Calcanhares","instructions":["Deite-se no chão com os joelhos flexionados e os pés apoiados a cerca de 18-24 polegadas de distância. Seus braços devem ficar estendidos ao lado do corpo. Esta será a sua posição inicial.","Flexione e incline o tronco cerca de 3-4 polegadas para o lado direito e toque o calcanhar direito, mantendo a contração por um segundo. Expire durante esse movimento.","Retorne lentamente à posição inicial enquanto inspira.","Agora flexione o tronco cerca de 3-4 polegadas para o lado esquerdo e toque o calcanhar esquerdo, mantendo a contração por um segundo. Expire durante esse movimento e volte à posição inicial inspirando. Tocar ambos os calcanhares conta como 1 repetição.","Continue alternando os lados até completar todas as repetições prescritas."]},
"Alternate_Incline_Dumbbell_Curl":{"name":"Rosca Alternada no Banco Inclinado com Halteres","instructions":["Sente-se em um banco inclinado segurando um halter em cada mão com os braços estendidos para baixo. Dica: mantenha os cotovelos próximos ao tronco. Esta será a sua posição inicial.","Mantendo o braço superior imóvel, eleve o halter direito contraindo o bíceps enquanto expira. Ao fazer isso, gire a mão para que a palma fique voltada para cima. Continue até o bíceps contrair totalmente e o halter chegar à altura do ombro. Segure por um segundo apertando o bíceps. Dica: apenas os antebraços devem se mover.","Comece a descer o halter lentamente de volta à posição inicial enquanto inspira.","Repita o movimento com a mão esquerda. Isso equivale a uma repetição.","Continue alternando dessa forma pela quantidade recomendada de repetições."]},
"Alternate_Leg_Diagonal_Bound":{"name":"Salto Diagonal Alternado","instructions":["Assuma uma postura confortável com um pé ligeiramente à frente do outro.","Comece impulsionando com a perna da frente, levando o joelho oposto para a frente e o mais alto possível antes de aterrissar. Tente cobrir a maior distância lateral possível a cada salto.","Pode ajudar usar uma linha no chão como referência para medir a distância de um lado para o outro.","Repita a sequência com a outra perna."]},
"Alternating_Cable_Shoulder_Press":{"name":"Desenvolvimento Alternado no Cabo","instructions":["Posicione as polias na parte inferior da torre e selecione uma carga adequada.","Segure os pegadores na altura dos ombros, com as palmas das mãos voltadas para a frente. Esta será a sua posição inicial.","Mantendo a cabeça erguida e o peito aberto, estenda um cotovelo para empurrar um lado diretamente acima da cabeça.","Após pausar no topo, retorne à posição inicial e repita do lado oposto."]},
"Alternating_Deltoid_Raise":{"name":"Elevação Alternada de Deltoides","instructions":["Em pé, segure um par de halteres ao lado do corpo.","Mantendo os cotovelos levemente flexionados, eleve os halteres diretamente à frente até a altura dos ombros, evitando balançar o corpo.","Retorne os halteres para o lado do corpo.","Na repetição seguinte, eleve os halteres lateralmente até aproximadamente a altura dos ombros.","Retorne à posição inicial e continue alternando entre elevação frontal e lateral."]},
"Alternating_Floor_Press":{"name":"Supino no Chão Alternado com Kettlebell","instructions":["Deite-se no chão com dois kettlebells próximos aos ombros.","Posicione um no peito e depois o outro, segurando as alças com as palmas voltadas para a frente.","Estenda ambos os braços para sustentar os kettlebells acima do peito. Abaixe um kettlebell até o peito, girando o punho em direção ao kettlebell que permanece elevado.","Empurre o kettlebell de volta para cima e repita do lado oposto."]},
"Alternating_Hang_Clean":{"name":"Hang Clean Alternado com Kettlebell","instructions":["Coloque dois kettlebells entre os pés. Para entrar na posição inicial, empurre o quadril para trás e olhe para a frente.","Faça um clean com um kettlebell até o ombro enquanto mantém o outro pendurado. Traga o kettlebell ao ombro estendendo as pernas e o quadril enquanto puxa o peso, girando o punho no processo.","Abaixe esse kettlebell de volta à posição suspensa e faça o clean com o outro kettlebell. Repita."]},
"Alternating_Kettlebell_Press":{"name":"Desenvolvimento Alternado com Kettlebell","instructions":["Faça um clean com dois kettlebells até os ombros, estendendo as pernas e o quadril enquanto puxa os pesos e gira os punhos.","Empurre um kettlebell diretamente acima da cabeça estendendo o cotovelo, girando a mão para que a palma fique para a frente enquanto mantém o outro kettlebell imóvel.","Abaixe o kettlebell de volta à posição inicial e empurre imediatamente com o outro braço."]},
"Alternating_Kettlebell_Row":{"name":"Remada Alternada com Kettlebell","instructions":["Coloque dois kettlebells à frente dos pés. Flexione levemente os joelhos e empurre o quadril para trás ao máximo. Incline o tronco e segure ambos os kettlebells pelas alças para entrar na posição inicial.","Puxe um kettlebell do chão enquanto segura o outro. Retraia a escápula do lado ativo ao flexionar o cotovelo, trazendo o kettlebell em direção ao abdômen ou às costelas.","Abaixe o kettlebell de volta e repita com o outro braço."]},
"Alternating_Renegade_Row":{"name":"Remada Renegada Alternada","instructions":["Coloque dois kettlebells no chão afastados na largura dos ombros. Apoie-se nas pontas dos pés e nas mãos como se fosse fazer uma flexão de braço, mantendo o corpo reto. Use as alças dos kettlebells como apoio; pode ser útil afastar mais os pés para manter o equilíbrio.","Pressione um kettlebell contra o chão e faça a remada com o outro, retraindo a escápula e flexionando o cotovelo para puxá-lo ao lado do tronco.","Abaixe o kettlebell até o chão e repita com a mão oposta. Continue alternando pelas repetições desejadas."]},
"Ankle_Circles":{"name":"Círculos com o Tornozelo","instructions":["Segure-se em um objeto firme, como um rack de agachamento, para manter o equilíbrio.","Eleve a perna direita no ar (cerca de 2 polegadas do chão) e faça um movimento circular com o dedão do pé, como se desenhasse um círculo grande. Dica: um círculo equivale a 1 repetição. Respire normalmente durante o movimento.","Ao terminar com o pé direito, repita com a perna esquerda."]},
"Ankle_On_The_Knee":{"name":"Alongamento Tornozelo no Joelho","instructions":["Deitado de costas, flexione os joelhos e mantenha os pés apoiados no chão.","Coloque o tornozelo de um pé sobre o joelho oposto.","Segure a coxa ou o joelho da perna de baixo e puxe ambas as pernas em direção ao peito. Relaxe o pescoço e os ombros. Segure por 10-20 segundos e depois troque de lado."]},
"Anterior_Tibialis-SMR":{"name":"Liberação Miofascial do Tibial Anterior","instructions":["Comece sentado no chão com as pernas flexionadas e os pés apoiados no solo.","Usando um rolo muscular ou bastão de liberação, aplique pressão nos músculos da parte externa das canelas. Trabalhe de logo abaixo do joelho até acima do tornozelo, pausando nos pontos de tensão por 10-30 segundos. Repita na outra perna."]},
"Anti-Gravity_Press":{"name":"Desenvolvimento Antigravidade","instructions":["Coloque uma barra no chão atrás da cabeceira de um banco inclinado.","Deite-se de bruços no banco. Com pegada pronada, pegue a barra do chão. Flexione os cotovelos realizando uma rosca inversa para trazer a barra perto do peito. Esta será a sua posição inicial.","Para começar, empurre a barra para a frente da cabeça estendendo os cotovelos. Mantenha os braços paralelos ao chão durante todo o movimento.","Retorne à posição inicial e repita até completar a série."]},
"Arm_Circles":{"name":"Círculos com os Braços","instructions":["Fique em pé e estenda os braços lateralmente. Os braços devem ficar paralelos ao chão e perpendiculares (ângulo de 90 graus) ao tronco. Esta será a sua posição inicial.","Comece lentamente a fazer círculos de cerca de 1 pé de diâmetro com cada braço estendido. Respire normalmente durante o movimento.","Continue o movimento circular por cerca de dez segundos. Em seguida, inverta o sentido girando na direção oposta."]},
"Arnold_Dumbbell_Press":{"name":"Desenvolvimento Arnold com Halteres","instructions":["Sente-se em um banco com encosto e segure dois halteres à sua frente na altura da parte superior do peito, com as palmas voltadas para o corpo e os cotovelos flexionados. Dica: seus braços devem ficar próximos ao tronco, lembrando a posição final de uma rosca com halteres.","Para iniciar o movimento, eleve os halteres enquanto gira os punhos até que as palmas fiquem voltadas para a frente.","Continue elevando os halteres até que os braços fiquem totalmente estendidos acima da cabeça. Expire durante essa fase do movimento.","Após uma pausa de um segundo no topo, comece a descer os halteres à posição original girando as palmas de volta para você. Dica: o braço esquerdo gira no sentido anti-horário e o direito no sentido horário. Inspire enquanto desce.","Repita pela quantidade recomendada de repetições."]},
"Around_The_Worlds":{"name":"Volta ao Mundo com Halteres","instructions":["Deite-se em um banco reto segurando um halter em cada mão com as palmas voltadas para o teto. Dica: os braços devem ficar paralelos ao chão e ao lado das coxas. Para evitar lesões, mantenha os cotovelos levemente flexionados. Esta será a sua posição inicial.","Mova os halteres descrevendo um semicírculo da posição inicial até acima da cabeça. Todo o movimento deve ocorrer com os braços paralelos ao chão. Inspire durante esta fase.","Inverta o movimento para retornar os halteres à posição inicial enquanto expira."]},
"Atlas_Stone_Trainer":{"name":"Treinador de Atlas Stone","instructions":["Este equipamento é eficaz para desenvolver força para Atlas Stone quando não há acesso às pedras reais, sendo normalmente feito com pontas de barra ou tubos pesados.","Comece carregando o peso desejado na barra. Posicione-se sobre a carga com os pés afastados, envolvendo o implemento com os braços e flexionando o quadril.","Puxe o peso para cima passando dos joelhos ao estender o quadril. Assim que passar dos joelhos, apoie-o nas coxas sentando para trás e abraçando-o firmemente contra o peito.","Finalize estendendo o quadril e os joelhos para elevar o peso o mais alto possível. Retorne o peso para o colo ou para o chão para as repetições seguintes."]},
"Atlas_Stones":{"name":"Atlas Stones","instructions":["Comece com a Atlas Stone entre os pés. Flexione o quadril para envolver a pedra verticalmente com os braços, tentando encaixar os dedos por baixo dela. Muitas pedras têm uma pequena base plana que facilita a pegada.","Puxando a pedra contra o tronco, empurre o chão com a parte posterior dos pés para tirá-la do solo.","Quando a pedra passar dos joelhos, apoie-a no colo sentando para trás e trazendo-a para cima das coxas.","Agache fundo para posicionar a pedra bem alta no peito enquanto ajusta a pegada por cima dela. Levante-se estendendo o quadril, aproxime-se da plataforma e incline-se para trás estendendo o quadril para colocar a pedra o mais alto possível."]},
"Axle_Deadlift":{"name":"Levantamento Terra com Barra Grossa (Axle)","instructions":["Aproxime-se da barra para que ela fique centralizada sobre os pés, afastados na largura do quadril. Flexione o quadril para segurar a barra na largura dos ombros, permitindo a protração das escápulas. Normalmente utiliza-se pegada mista.","Com pés e pegada ajustados, inspire fundo, abaixe o quadril e flexione os joelhos até as canelas encostarem na barra. Olhe para a frente, mantenha o peito aberto e as costas firmes e comece a empurrar pelos calcanhares para subir a carga.","Depois que a barra passar dos joelhos, puxe-a vigorosamente para trás, aproximando as escápulas enquanto projeta o quadril à frente contra a barra.","Abaixe a barra flexionando o quadril e guiando-a de volta até o chão."]},
"Back_Flyes_-_With_Bands":{"name":"Crucifixo Inverso com Elástico","instructions":["Passe um elástico ao redor de um poste fixo, como a coluna de um rack de agachamento.","Segure as alças do elástico e dê alguns passos para trás até gerar tensão no elástico.","Estenda os braços diretamente à sua frente. Dica: os braços devem ficar estendidos e paralelos ao chão, perpendiculares ao tronco. Mantenha os pés firmes no chão na largura dos ombros. Esta será a sua posição inicial.","Ao expirar, abra os braços para os lados e para trás, mantendo-os estendidos e paralelos ao chão até ficarem abertos lateralmente.","Após uma breve pausa, retorne à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Backward_Drag":{"name":"Arraste de Trenó para Trás","instructions":["Carregue um trenó com o peso desejado e prenda uma corda ou tiras que você possa segurar.","Inicie o exercício deslocando-se para trás por uma distância determinada. Incline o corpo para trás e estenda as pernas em passos curtos para se mover o mais rápido possível."]},
"Backward_Medicine_Ball_Throw":{"name":"Arremesso de Medicine Ball para Trás","instructions":["Este exercício é melhor executado com um parceiro; se estiver sozinho, você pode arremessar a bola e buscá-la ou jogá-la contra uma parede.","Fique em pé alguns metros à frente do seu parceiro, ambos virados para a mesma direção, segurando a bola medicinal entre as pernas.","Agache e reverta o movimento com força, estendendo todo o corpo ao arremessar a bola por cima da cabeça em direção ao seu parceiro.","Seu parceiro pode rolar a bola de volta para você. Repita pelo número desejado de repetições."]},
"Balance_Board":{"name":"Prancha de Equilíbrio","instructions":["Coloque uma prancha de equilíbrio à sua frente.","Suba nela e tente se equilibrar.","Mantenha o equilíbrio pelo tempo desejado."]},
"Ball_Leg_Curl":{"name":"Flexão de Pernas na Bola Suíça","instructions":["Deite-se de costas no chão com os pés apoiados em cima da bola suíça.","Posicione a bola de modo que, com as pernas estendidas, seus tornozelos fiquem sobre ela. Esta será a sua posição inicial.","Eleve o quadril do chão, mantendo o peso apoiado nas escápulas e nos pés.","Flexione os joelhos puxando a bola o mais perto possível de você, contraindo os posteriores de coxa.","Após uma breve pausa, retorne à posição inicial."]},
"Band_Assisted_Pull-Up":{"name":"Barra Fixa Assistida com Elástico","instructions":["Prenda o elástico no centro da barra fixa. Você pode variar a espessura do elástico para ajustar o nível de assistência.","Puxe a ponta inferior do elástico para baixo e encaixe um joelho flexionado dentro da alça, garantindo que não escorregue. Faça uma pegada média a aberta na barra. Esta será a sua posição inicial.","Puxe o corpo para cima contraindo as dorsais e flexionando os cotovelos, direcionando-os para os lados do corpo. Suba tentando passar o queixo acima da barra, evitando balanços ou trancos.","Após uma breve pausa, retorne à posição inicial."]},
"Band_Good_Morning":{"name":"Bom Dia com Elástico","instructions":["Usando um elástico de 41 polegadas, pise em uma das pontas com os pés levemente afastados. Flexione o quadril para passar a outra ponta por trás do pescoço. Esta será a sua posição inicial.","Mantendo as pernas retas, estenda o quadril até ficar quase na vertical.","Garanta que as costas não arredondem ao descer de volta para a posição inicial."]},
"Band_Good_Morning_Pull_Through":{"name":"Bom Dia com Elástico (Pull Through)","instructions":["Prenda o elástico ao redor de um poste. Afastando-se um pouco, passe a extremidade oposta por trás do pescoço; suas mãos podem ajudar a manter o elástico posicionado.","Inicie flexionando o quadril e levando os glúteos para trás o máximo possível. Mantenha as costas retas e incline-se à frente até cerca de 90 graus, com os joelhos apenas levemente flexionados.","Retorne à posição inicial impulsionando o quadril para a frente até ficar em pé novamente."]},
"Band_Hip_Adductions":{"name":"Adução de Quadril com Elástico","instructions":["Prenda um elástico ao redor de um poste firme ou outro ponto fixo.","Fique em pé com o lado esquerdo voltado para o poste e passe o pé direito pelo elástico, prendendo-o ao redor do tornozelo.","Mantenha o corpo ereto e segure-se no poste se necessário. Esta será a sua posição inicial.","Mantendo o joelho estendido, eleve a perna direita lateralmente o máximo possível.","Retorne à posição inicial e repita pela contagem desejada.","Troque de lado."]},
"Band_Pull_Apart":{"name":"Abertura de Braços com Elástico (Pull Apart)","instructions":["Comece com os braços estendidos diretamente à sua frente, segurando o elástico com as duas mãos.","Inicie o movimento fazendo uma abertura inversa, levando as mãos lateralmente para os lados.","Mantenha os cotovelos estendidos durante o movimento, trazendo o elástico até o peito. Mantenha os ombros encaixados para trás durante todo o exercício.","Faça uma pausa ao completar o movimento e retorne à posição inicial de forma controlada."]},
"Band_Skull_Crusher":{"name":"Tríceps Testa com Elástico","instructions":["Prenda um elástico na base de um rack ou do banco. Deite-se no banco alinhando a cabeça com o elástico.","Segure o elástico e eleve os cotovelos para que os braços fiquem perpendiculares ao chão. Com os cotovelos flexionados, o elástico ficará acima da sua cabeça. Esta será a sua posição inicial.","Estenda os cotovelos para esticar os braços, mantendo a parte superior do braço fixa. Pause no topo do movimento e retorne à posição inicial."]},
"Barbell_Ab_Rollout":{"name":"Roda Abdominal com Barra","instructions":["Para este exercício, entre em posição de flexão de braço, mas em vez de apoiar as mãos no chão, segure uma barra olímpica (carregada com 5-10 lbs de cada lado). Esta será a sua posição inicial.","Mantendo uma leve curvatura nas costas, eleve o quadril e role a barra em direção aos pés enquanto expira. Dica: durante o movimento, seus glúteos devem subir, o abdômen deve permanecer firme e a postura das costas estável. Mantenha os braços perpendiculares ao chão o tempo todo para não sobrecarregar ombros e costas.","Após uma contração de um segundo no topo, role a barra lentamente para a frente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Ab_Rollout_-_On_Knees":{"name":"Roda Abdominal com Barra - Ajoelhado","instructions":["Segure uma barra olímpica carregada com 5-10 lbs de cada lado e ajoelhe-se no chão.","Posicione a barra no chão à sua frente, apoiando-se nas mãos e nos joelhos (como em uma flexão de braço ajoelhada). Esta será a sua posição inicial.","Role lentamente a barra para a frente em linha reta, estendendo o corpo. Dica: desça o máximo possível sem encostar o corpo no chão. Inspire durante essa fase do movimento.","Após uma pausa de um segundo na posição estendida, puxe o corpo de volta à posição inicial enquanto expira. Dica: vá devagar e mantenha o abdômen contraído o tempo todo."]},
"Barbell_Bench_Press_-_Medium_Grip":{"name":"Supino Reto com Barra - Pegada Média","instructions":["Deite-se de costas em um banco reto. Usando uma pegada média (que forme um ângulo de 90 graus no meio do movimento entre antebraços e braços), tire a barra do suporte e segure-a reta acima de você com os braços estendidos. Esta será a sua posição inicial.","A partir da posição inicial, inspire e desça a barra lentamente até que ela toque o meio do peito.","Após uma breve pausa, empurre a barra de volta à posição inicial enquanto expira. Concentre-se em empurrar usando os músculos do peito. Estenda os braços e contraia o peitoral no topo, segure por um segundo e desça novamente devagar. Dica: idealmente, a descida deve durar cerca do dobro do tempo da subida.","Repita o movimento pela quantidade prescrita de repetições.","Ao terminar, recoloque a barra no suporte."]},
"Barbell_Curl":{"name":"Rosca Direta com Barra","instructions":["Fique em pé com o tronco ereto segurando uma barra com pegada na largura dos ombros. As palmas das mãos devem ficar voltadas para a frente e os cotovelos próximos ao tronco. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos levando a barra para cima enquanto contrai o bíceps e expira. Dica: apenas os antebraços devem se mover.","Continue até que o bíceps esteja totalmente contraído e a barra na altura dos ombros. Segure a contração por um segundo apertando bem o bíceps.","Comece lentamente a abaixar a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Curls_Lying_Against_An_Incline":{"name":"Rosca com Barra Deitado no Banco Inclinado","instructions":["Deite-se de bruços contra um banco inclinado, com os braços segurando uma barra pendurada abaixo do tronco. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos elevando a barra o máximo possível enquanto contrai o bíceps. Expire durante essa fase. Dica: apenas os antebraços devem se mover; não balance os braços.","Após uma contração de um segundo, retorne lentamente à posição inicial enquanto inspira. Dica: certifique-se de descer completamente.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Deadlift":{"name":"Levantamento Terra com Barra","instructions":["Fique em pé diante de uma barra montada.","Mantendo as costas o mais retas possível, flexione os joelhos, incline-se à frente e segure a barra com pegada pronada média (largura dos ombros). Esta será a posição inicial. Dica: se for difícil segurar a barra assim, use pegada mista ou straps.","Segurando a barra, inicie o levantamento empurrando o chão com as pernas enquanto traz o tronco para a posição ereta ao expirar. Em cima, abra o peito e contraia as costas levando as escápulas para trás, em postura firme.","Retorne à posição inicial flexionando os joelhos e inclinando o tronco à frente pelo quadril, mantendo as costas retas. Quando as anilhas tocarem o chão, você estará pronto para a próxima repetição.","Execute a quantidade de repetições prescrita no seu treino."]},
"Barbell_Full_Squat":{"name":"Agachamento Completo com Barra","instructions":["Este exercício é mais seguro dentro de um rack de agachamento. Ajuste a barra no suporte logo acima da altura dos ombros. Com a altura definida e o peso montado, entre sob a barra e apoie-a na parte superior das costas (logo abaixo do pescoço).","Segure a barra com ambas as mãos de cada lado e retire-a do suporte empurrando com as pernas enquanto estende o tronco.","Dê um passo para trás saindo do suporte e posicione os pés em abertura média na largura dos ombros, com as pontas levemente voltadas para fora. Mantenha a cabeça erguida e as costas retas o tempo todo. Esta será a sua posição inicial.","Comece a descer lentamente flexionando os joelhos e jogando o quadril para trás, mantendo a postura reta e a cabeça erguida. Desça até que os posteriores de coxa encostem nas panturrilhas. Inspire durante a descida.","Comece a subir enquanto expira, empurrando o chão com os calcanhares ou o meio dos pés até estender pernas e quadril e voltar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Glute_Bridge":{"name":"Elevação Pélvica no Chão com Barra","instructions":["Sente-se no chão com uma barra montada sobre as pernas; usar uma barra grossa ou uma proteção acolchoada reduz bastante o desconforto. Role a barra até ficar diretamente sobre o quadril e deite-se de costas no chão.","Inicie o movimento empurrando o chão com os calcanhares e estendendo o quadril verticalmente contra a barra. Seu peso deve ficar apoiado na parte superior das costas e nos calcanhares.","Estenda o quadril o máximo possível e depois inverta o movimento para retornar à posição inicial."]},
"Barbell_Guillotine_Bench_Press":{"name":"Supino Guilhotina com Barra","instructions":["Usando uma pegada média (que forme um ângulo de 90 graus no meio do movimento entre antebraços e braços), retire a barra do suporte e segure-a diretamente sobre o pescoço com os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça a barra lentamente até ficar a cerca de 1 polegada do pescoço.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando os músculos do peito. Estenda os braços e contraia o peitoral por um segundo antes de descer lentamente de novo. A descida deve levar pelo menos o dobro do tempo da subida.","Repita o movimento pela quantidade prescrita de repetições.","Ao terminar, recoloque a barra no suporte."]},
"Barbell_Hack_Squat":{"name":"Agachamento Hack com Barra","instructions":["Fique em pé segurando uma barra atrás do corpo com os braços estendidos e os pés na largura dos ombros. Dica: use pegada na largura dos ombros com as palmas voltadas para trás; straps podem ajudar na firmeza. Esta será a sua posição inicial.","Mantendo a cabeça erguida e as costas retas, agache até que a parte superior das coxas fique paralela ao chão. Inspire enquanto desce lentamente.","Empurrando principalmente pelos calcanhares e contraindo as coxas, suba de volta enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Hip_Thrust":{"name":"Elevação Pélvica no Banco com Barra (Hip Thrust)","instructions":["Sente-se no chão com um banco logo atrás de você e uma barra montada sobre as pernas. Usar uma proteção na barra ajuda a reduzir o desconforto.","Role a barra até posicioná-la diretamente sobre o quadril e apoie a parte superior das costas no banco, com as escápulas próximas à borda superior.","Inicie o movimento empurrando o chão com os pés e estendendo o quadril verticalmente contra a barra. O peso deve ser sustentado pelas escápulas e pelos pés. Estenda ao máximo e retorne à posição inicial."]},
"Barbell_Incline_Bench_Press_-_Medium_Grip":{"name":"Supino Inclinado com Barra - Pegada Média","instructions":["Deite-se em um banco inclinado. Usando uma pegada média (que forme um ângulo de 90 graus no meio do movimento entre antebraços e braços), retire a barra do suporte e segure-a reta acima de você com os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça lentamente até sentir a barra tocar a parte superior do peito.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando os músculos do peito. Estenda os braços, contraia o peitoral por um segundo e desça novamente devagar. Dica: a descida deve levar pelo menos o dobro do tempo da subida.","Repita o movimento pela quantidade prescrita de repetições.","Ao terminar, recoloque a barra no suporte."]},
"Barbell_Incline_Shoulder_Raise":{"name":"Elevação de Ombros Inclinado com Barra","instructions":["Deite-se em um banco inclinado. Usando uma pegada média (ligeiramente mais aberta que a largura dos ombros), retire a barra do suporte e segure-a acima do peito com os braços estendidos. Esta será a sua posição inicial.","Mantendo os braços estendidos, empurre a barra para cima protraindo as escápulas e desencostando os ombros do banco enquanto expira.","Retorne a barra à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Lunge":{"name":"Avanço com Barra","instructions":["Este exercício é mais seguro dentro de um rack de agachamento. Ajuste a barra logo abaixo da altura dos ombros, entre sob ela e apoie-a na parte superior das costas (logo abaixo do pescoço).","Segure a barra com as duas mãos e retire-a do suporte empurrando com as pernas enquanto estende o tronco.","Afaste-se do suporte, dê um passo à frente com a perna direita e agache flexionando o quadril, mantendo o tronco ereto e o equilíbrio. Inspire na descida. Observação: não deixe o joelho ultrapassar a linha dos dedos dos pés para evitar sobrecarga articular.","Empurrando principalmente pelo calcanhar do pé da frente, suba de volta à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições e depois execute com a perna esquerda."]},
"Barbell_Rear_Delt_Row":{"name":"Remada para Deltoide Posterior com Barra","instructions":["Fique em pé segurando uma barra com pegada pronada aberta (mais larga que a largura dos ombros, palmas voltadas para o corpo).","Flexione levemente os joelhos e incline o tronco à frente mantendo a curvatura natural das costas. Deixe os braços pendurados à frente segurando a barra. Com o tronco paralelo ao chão, abra os cotovelos para longe do corpo. Dica: tronco e braços devem formar a letra \"T\". Agora você está pronto para começar.","Mantendo os braços perpendiculares ao tronco, puxe a barra em direção à parte superior do peito contraindo os deltoides posteriores enquanto expira. Dica: o movimento lembra um supino invertido; evite usar o bíceps e use os braços apenas como ganchos.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Rollout_from_Bench":{"name":"Roda Abdominal com Barra a Partir do Banco","instructions":["Coloque uma barra montada no chão próxima à extremidade de um banco. Ajoelhe-se com as duas pernas sobre o banco e segure a barra com pegada média a fechada. Esta será a sua posição inicial.","Para começar, estenda o quadril rolando lentamente a barra para a frente. Enquanto avança, flexione os ombros para rolar a barra acima da cabeça, mantendo os braços estendidos durante todo o movimento.","Quando tiver levado a barra o mais à frente possível, retorne à posição inicial."]},
"Barbell_Seated_Calf_Raise":{"name":"Elevação de Panturrilha Sentado com Barra","instructions":["Coloque um bloco ou step a cerca de 12 polegadas à frente de um banco reto.","Sente-se no banco e apoie a ponta dos pés sobre o bloco.","Peça a alguém para apoiar uma barra sobre suas coxas, cerca de 3 polegadas acima dos joelhos, e mantê-la firme. Esta será a sua posição inicial.","Suba na ponta dos pés o mais alto possível contraindo as panturrilhas enquanto expira.","Após uma contração de um segundo, desça lentamente à posição inicial. Dica: para máximo aproveitamento, alongue as panturrilhas ao máximo na descida.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Shoulder_Press":{"name":"Desenvolvimento de Ombros com Barra","instructions":["Sente-se em um banco com encosto dentro de um rack de agachamento. Posicione a barra em uma altura logo acima da cabeça e segure-a com pegada pronada (palmas para a frente).","Retire a barra e estenda os braços acima da cabeça; em seguida, abaixe-a até a altura dos ombros, ligeiramente à frente da cabeça. Esta é a sua posição inicial.","Desça a barra lentamente até os ombros enquanto inspira.","Empurre a barra de volta para cima até a posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Shrug":{"name":"Encolhimento de Ombros com Barra","instructions":["Fique em pé com os pés na largura dos ombros segurando uma barra à frente do corpo com pegada pronada (palmas voltadas para as coxas). Dica: as mãos devem ficar um pouco mais abertas que a largura dos ombros; você pode usar straps para melhorar a pegada. Esta será a sua posição inicial.","Eleve os ombros o mais alto possível enquanto expira e segure a contração por um segundo. Dica: evite tentar puxar a barra usando o bíceps.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Shrug_Behind_The_Back":{"name":"Encolhimento por Trás das Costas com Barra","instructions":["Fique em pé com os pés na largura dos ombros segurando uma barra atrás das costas com pegada pronada (palmas voltadas para trás). Dica: as mãos devem ficar um pouco mais abertas que a largura dos ombros; você pode usar straps para melhorar a pegada. Esta será a sua posição inicial.","Eleve os ombros o mais alto possível enquanto expira e segure a contração por um segundo. Dica: evite tentar puxar a barra usando o bíceps; os braços devem permanecer estendidos o tempo todo.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Side_Bend":{"name":"Flexão Lateral do Tronco com Barra","instructions":["Fique em pé segurando uma barra apoiada na parte superior das costas (logo abaixo do pescoço), com os pés na largura dos ombros. Esta será a sua posição inicial.","Mantendo as costas retas e a cabeça erguida, incline apenas a cintura para a direita o máximo possível. Inspire ao descer para o lado, segure por um segundo e volte à posição inicial enquanto expira. Dica: mantenha o restante do corpo imóvel.","Agora repita o movimento inclinando para o lado esquerdo, segure por um segundo e retorne à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Side_Split_Squat":{"name":"Agachamento Lateral com Barra","instructions":["Fique em pé segurando uma barra apoiada na parte superior das costas (logo abaixo do pescoço). Afaste bastante os pés, apontando o pé da perna da frente para o lado. Esta será a sua posição inicial.","Abaixe o corpo em direção ao lado do pé angulado flexionando o joelho e o quadril da perna condutora enquanto mantém a outra perna apenas levemente flexionada. Inspire enquanto desce.","Retorne à posição inicial estendendo o quadril e o joelho da perna condutora. Expire ao executar o movimento.","Após completar a quantidade recomendada de repetições, repita com a perna oposta."]},
"Barbell_Squat":{"name":"Agachamento Livre com Barra","instructions":["Este exercício é mais seguro dentro de um rack de agachamento. Ajuste a barra logo abaixo da altura dos ombros, entre sob ela e apoie-a na parte superior das costas (logo abaixo do pescoço).","Segure a barra com as duas mãos e retire-a do suporte empurrando com as pernas enquanto estende o tronco.","Afaste-se do suporte e posicione os pés em abertura média na largura dos ombros, com as pontas levemente voltadas para fora. Mantenha a cabeça erguida e as costas retas o tempo todo. Esta será a sua posição inicial.","Comece a descer lentamente flexionando os joelhos e o quadril, mantendo a postura reta e a cabeça erguida, até que o ângulo entre coxas e panturrilhas fique ligeiramente menor que 90 graus. Inspire na descida. Dica: os joelhos devem permanecer alinhados aos pés, evitando projetá-los excessivamente além da ponta dos dedos para não sobrecarregar a articulação.","Comece a subir enquanto expira, empurrando o chão com os calcanhares até estender as pernas e voltar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Squat_To_A_Bench":{"name":"Agachamento com Barra até o Banco","instructions":["Este exercício é mais seguro dentro de um rack de agachamento. Para começar, posicione um banco reto ou uma caixa atrás de você.","O banco reto serve para ensinar você a jogar o quadril para trás e atingir a profundidade correta.","Em seguida, ajuste a barra no suporte na altura ideal para você. Com o peso montado, entre sob a barra e apoie-a na parte superior das costas (logo abaixo do pescoço).","Segure a barra com as duas mãos e retire-a do suporte empurrando com as pernas enquanto estende o tronco.","Afaste-se do suporte e posicione os pés em abertura média na largura dos ombros, com as pontas levemente voltadas para fora. Mantenha a cabeça erguida para não perder o equilíbrio e mantenha as costas retas. Esta será a sua posição inicial.","Desça lentamente a barra flexionando os joelhos e jogando o quadril para trás, mantendo a postura ereta, até encostar levemente no banco atrás de você. Inspire durante a descida. Dica: evite projetar os joelhos excessivamente além dos dedos dos pés para não gerar estresse articular.","Comece a subir enquanto expira, empurrando o chão com os calcanhares ao estender pernas e quadril para retornar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Barbell_Step_Ups":{"name":"Subida no Banco (Step-Up) com Barra","instructions":["Fique em pé com uma barra apoiada na parte superior das costas (logo abaixo do pescoço) atrás de uma plataforma elevada. Esta é a sua posição inicial.","Coloque o pé direito sobre a plataforma. Suba estendendo o quadril e o joelho da perna direita, usando principalmente o calcanhar para elevar o corpo, e apoie também o pé esquerdo na plataforma. Expire ao fazer força para subir.","Desça com a perna esquerda flexionando o quadril e o joelho da perna direita enquanto inspira. Volte à posição inicial colocando o pé direito ao lado do esquerdo no chão.","Repita com a perna direita pela quantidade recomendada de repetições e depois execute com a perna esquerda."]},
"Barbell_Walking_Lunge":{"name":"Avanço Caminhando com Barra","instructions":["Comece em pé com os pés na largura dos ombros e uma barra apoiada na parte superior das costas.","Dê um passo à frente com uma perna, flexionando os joelhos para abaixar o quadril até que o joelho de trás quase toque o chão. Mantenha o tronco ereto e o joelho da frente alinhado sobre o pé da frente.","Impulsione pelo calcanhar da perna da frente e estenda ambos os joelhos para se levantar.","Avance com o pé de trás, repetindo o movimento com a perna oposta."]},
"Battling_Ropes":{"name":"Corda Naval","instructions":["Para este exercício você precisará de uma corda pesada ancorada pelo centro a 15-20 pés de distância. Fique em pé diante da corda segurando uma ponta em cada mão com os braços estendidos ao lado do corpo. Esta será a sua posição inicial.","Inicie o movimento elevando rapidamente um braço até a altura do ombro o mais rápido possível.","Enquanto deixa esse braço descer à posição inicial, eleve o lado oposto.","Continue alternando os braços esquerdo e direito, ondulando as cordas para cima e para baixo o mais rápido possível."]},
"Bear_Crawl_Sled_Drags":{"name":"Arraste de Trenó em Caminhada de Urso","instructions":["Usando um colete de tração ou cinto largo, prenda a corrente nas costas de modo que você fique de costas para o trenó. Abaixe-se apoiando as mãos no chão, mantendo as costas retas e os joelhos flexionados. Esta é a sua posição inicial.","Comece a avançar impulsionando com as pernas, alternando esquerda e direita. Use as mãos para manter o equilíbrio e ajudar a puxar, mantendo as costas retas ao percorrer a distância definida."]},
"Behind_Head_Chest_Stretch":{"name":"Alongamento de Peitoral com Mãos Atrás da Cabeça","instructions":["Sente-se ereto no chão com seu parceiro atrás de você.","Coloque as mãos atrás da cabeça e empurre os cotovelos para trás o máximo possível enquanto seu parceiro os segura. Esta será a sua posição inicial.","Tente puxar suavemente os cotovelos para a frente com as mãos ainda atrás da cabeça por 10 segundos ou mais, enquanto seu parceiro impede o movimento.","Agora relaxe os músculos e peça ao seu parceiro para puxar suavemente seus cotovelos para trás até onde for confortável. Avise quando o alongamento estiver adequado para evitar lesões."]},
"Bench_Dips":{"name":"Mergulho no Banco","instructions":["Posicione um banco atrás das costas, perpendicular ao seu corpo. Virado para a frente, apoie as mãos na borda do banco com os braços totalmente estendidos na largura dos ombros e as pernas estendidas à frente, perpendiculares ao tronco. Esta será a sua posição inicial.","Desça o corpo lentamente enquanto inspira, flexionando os cotovelos até formar um ângulo ligeiramente menor que 90 graus entre braço e antebraço. Dica: mantenha os cotovelos o mais próximos possível do corpo, com os antebraços sempre apontando para baixo.","Usando o tríceps para empurrar o tronco para cima, eleve-se de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Bench_Jump":{"name":"Salto sobre o Banco","instructions":["Posicione uma caixa ou banco 1-2 pés à sua frente. Fique em pé com os pés na largura dos ombros. Esta será a sua posição inicial.","Faça um agachamento curto preparando o salto e balance os braços para trás.","Impulsione dessa posição estendendo quadril, joelhos e tornozelos para saltar o mais alto possível, balançando os braços para a frente e para cima.","Salte por cima do banco aterrissando com os joelhos flexionados para absorver o impacto com as pernas.","Vire-se para o lado oposto e salte de volta sobre o banco."]},
"Bench_Press_-_Powerlifting":{"name":"Supino Reto - Powerlifting","instructions":["Deite-se no banco posicionando a cabeça além da barra se possível. Encaixe os pés para trás sob o corpo e arqueie as costas. Usando a barra para ajudar a sustentar o peso, eleve os ombros e retraia as escápulas, firmando o trapézio no banco. Mantenha o corpo bem tenso durante todo o movimento.","Qualquer que seja a largura da pegada, cubra o anel da barra. Retire a barra do suporte sem protrair os ombros, concentrando-se em apertar a barra e tentar \"rasgá-la\" ao meio.","Abaixe a barra até a parte inferior do peito ou parte superior do abdômen, mantendo barra, punhos e cotovelos alinhados o tempo todo.","Pause quando a barra tocar o tronco e então empurre para cima com o máximo de força possível, mantendo os cotovelos fechados até travar os braços."]},
"Bench_Press_-_With_Bands":{"name":"Supino Reto com Elástico","instructions":["Em um banco reto, prenda um elástico sob o pé do banco mais próximo da sua cabeça.","Com o elástico preso, segure as duas alças e deite-se no banco.","Estenda os braços segurando as alças à frente do corpo na largura dos ombros.","Gire os punhos para que as palmas das mãos fiquem voltadas para a frente (longe de você). Esta será a sua posição inicial.","Desça as alças lentamente até os cotovelos formarem um ângulo de 90 graus, mantendo controle total.","Ao expirar, empurre as alças para cima usando o peitoral. Estenda os braços, aperte o peito por um segundo e desça novamente devagar. Dica: a descida deve durar pelo menos o dobro do tempo da subida.","Repita o movimento pela quantidade prescrita de repetições."]},
"Bench_Press_with_Chains":{"name":"Supino Reto com Correntes","instructions":["Ajuste a corrente guia encurtando-a no comprimento desejado e coloque as correntes nas pontas da barra.","Deite-se no banco posicionando a cabeça além da barra se possível. Encaixe os pés para trás, arqueie as costas e retraia as escápulas firmando o trapézio no banco. Mantenha o corpo tenso durante todo o movimento e cubra o anel da barra com a pegada.","Retire a barra do suporte sem protrair os ombros, mantendo barra, punhos e cotovelos alinhados. Abaixe a barra até a parte inferior do peito ou topo do abdômen.","Pause quando a barra tocar o tronco e empurre para cima com o máximo de força, mantendo os cotovelos fechados até estender os braços."]},
"Bench_Sprint":{"name":"Subida Rápida no Banco (Bench Sprint)","instructions":["Fique em pé no chão com um pé apoiado sobre um banco ou caixa, mantendo o calcanhar próximo à borda.","Impulsione com o pé que está em cima do banco estendendo o quadril e o joelho.","Aterrisse com o pé oposto em cima da caixa enquanto o outro retorna à posição inicial no chão.","Continue alternando rapidamente de um pé para o outro até completar a série."]},
"Bent-Arm_Barbell_Pullover":{"name":"Pullover com Barra e Braços Flexionados","instructions":["Deite-se em um banco reto segurando uma barra com pegada na largura dos ombros.","Segure a barra diretamente acima do peito mantendo os braços levemente flexionados. Esta será a sua posição inicial.","Mantendo os braços flexionados, desça a barra lentamente em arco atrás da cabeça enquanto inspira até sentir o alongamento no peitoral.","Nesse ponto, traga a barra de volta à posição inicial pelo mesmo arco enquanto expira.","Segure o peso na posição inicial por um segundo e repita pelo número prescrito de repetições."]},
"Bent-Arm_Dumbbell_Pullover":{"name":"Pullover com Halter e Braços Flexionados","instructions":["Coloque um halter em pé sobre um banco reto.","Garantindo que o halter esteja seguro, deite-se perpendicularmente ao banco (formando uma cruz) apoiando apenas os ombros. O quadril deve ficar abaixo do banco, com pernas flexionadas, pés firmes no chão e cabeça fora do banco.","Segure o halter com as duas mãos diretamente acima do peito mantendo os braços levemente flexionados, com as palmas pressionando a parte interna da anilha superior. Esta será a posição inicial. Cuidado: verifique sempre se as anilhas do halter estão bem travadas.","Mantendo os braços fixos nessa flexão, desça o halter lentamente em arco atrás da cabeça enquanto inspira até sentir o alongamento no peitoral.","Em seguida, traga o halter de volta à posição inicial pelo mesmo arco enquanto expira.","Segure por um segundo na posição inicial e repita pelo número prescrito de repetições."]},
"Bent-Knee_Hip_Raise":{"name":"Elevação de Quadril com Joelhos Flexionados","instructions":["Deite-se de costas no chão com os braços ao lado do corpo.","Flexione os joelhos em cerca de 75 graus e eleve os pés a aproximadamente 2 polegadas do chão.","Usando o abdômen inferior, puxe os joelhos em sua direção mantendo o ângulo de 75 graus até tirar o quadril do chão girando a pelve para trás. Expire nessa fase. Dica: ao final, seus joelhos ficarão sobre o peito.","Contraia o abdômen no topo por um segundo e retorne lentamente à posição inicial enquanto inspira. Dica: mantenha o movimento controlado o tempo todo.","Repita pela quantidade recomendada de repetições."]},
"Bent_Over_Barbell_Row":{"name":"Remada Curvada com Barra","instructions":["Segurando uma barra com pegada pronada (palmas para baixo), flexione levemente os joelhos e incline o tronco à frente pelo quadril mantendo as costas retas até quase ficar paralelo ao chão. Dica: mantenha a cabeça erguida e os braços pendurados perpendiculares ao chão. Esta é a sua posição inicial.","Mantendo o tronco imóvel, expire e puxe a barra em sua direção, com os cotovelos próximos ao corpo e usando os antebraços apenas para sustentar o peso. No topo, contraia as costas e pause brevemente.","Em seguida, inspire e desça a barra lentamente de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench":{"name":"Crucifixo Inverso Curvado com Halteres e Testa no Banco","instructions":["Fique em pé segurando um halter em cada mão diante de um banco inclinado.","Mantendo a curvatura natural das costas, incline-se à frente até encostar a testa no banco. Deixe os braços pendurados perpendiculares ao chão, com as palmas voltadas uma para a outra e o tronco paralelo ao solo. Esta será a sua posição inicial.","Mantendo o tronco imóvel e os cotovelos levemente flexionados, eleve os halteres lateralmente até os braços ficarem paralelos ao chão enquanto expira. Cuidado: evite balançar o tronco ou puxar os braços para trás em vez de para os lados.","Após uma contração de um segundo no topo, abaixe lentamente os halteres de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Bent_Over_Low-Pulley_Side_Lateral":{"name":"Elevação Lateral Curvada na Polia Baixa","instructions":["Selecione o peso e segure o pegador da polia baixa com a mão direita.","Incline o tronco pelo quadril até ficar quase paralelo ao chão, com as pernas levemente flexionadas e a mão esquerda apoiada na coxa esquerda. O braço direito deve ficar estendido abaixo do ombro com leve flexão no cotovelo. Esta será a sua posição inicial.","Eleve o braço direito lateralmente até ficar paralelo ao chão e alinhado à orelha direita enquanto expira.","Abaixe lentamente o peso de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições e depois execute com o outro braço."]},
"Bent_Over_One-Arm_Long_Bar_Row":{"name":"Remada Cavalinho Unilateral Curvada","instructions":["Coloque peso em uma das extremidades de uma barra olímpica, travando a outra extremidade no canto de duas paredes ou contra um objeto pesado para que não deslize.","Incline o tronco à frente até ficar quase paralelo ao chão e flexione levemente os joelhos.","Segure a barra com uma mão logo atrás das anilhas carregadas e apoie a outra mão no joelho. Esta será a sua posição inicial.","Puxe a barra para cima mantendo o cotovelo próximo ao corpo até as anilhas tocarem a parte inferior do peito. Contraia as costas e segure um segundo no topo enquanto expira. Dica: não balance o tronco; apenas o braço deve se mover.","Desça a barra lentamente até a posição inicial alongando bem as dorsais. Dica: não deixe as anilhas tocarem o chão; prefira anilhas menores (25 lb) às maiores (35-45 lb) para ter maior amplitude.","Repita pela quantidade recomendada de repetições e troque de braço."]},
"Bent_Over_Two-Arm_Long_Bar_Row":{"name":"Remada Cavalinho Curvada com Duas Mãos","instructions":["Coloque peso em uma das extremidades de uma barra olímpica, travando a outra extremidade no canto de duas paredes ou contra um objeto pesado para que não deslize.","Incline o tronco à frente até ficar quase paralelo ao chão e flexione levemente os joelhos.","Segure a barra com as duas mãos logo atrás das anilhas carregadas. Esta será a sua posição inicial.","Puxe a barra para cima com os cotovelos próximos ao corpo até as anilhas tocarem a parte inferior do peito. Contraia as costas e segure por um segundo no topo enquanto expira. Dica: você pode usar um pegador triângulo ou barra em V acoplado sob a barra.","Desça a barra lentamente até a posição inicial alongando bem as dorsais. Dica: não deixe as anilhas tocarem o chão; prefira anilhas menores (25 lb) às maiores (35-45 lb) para aumentar a amplitude.","Repita pela quantidade recomendada de repetições."]},
"Bent_Over_Two-Dumbbell_Row":{"name":"Remada Curvada com Halteres","instructions":["Com um halter em cada mão (palmas voltadas para o corpo), flexione levemente os joelhos e incline o tronco à frente mantendo as costas retas até quase ficar paralelo ao chão. Dica: mantenha a cabeça erguida e os braços pendurados perpendiculares ao chão. Esta é a sua posição inicial.","Mantendo o tronco imóvel, puxe os halteres ao lado do corpo enquanto expira, com os cotovelos rentes ao tronco e sem fazer força desnecessária com o antebraço. No topo, contraia as costas e segure por um segundo.","Abaixe lentamente os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Bent_Over_Two-Dumbbell_Row_With_Palms_In":{"name":"Remada Curvada com Halteres - Pegada Neutra","instructions":["Com um halter em cada mão (palmas voltadas uma para a outra), flexione levemente os joelhos e incline o tronco à frente mantendo as costas retas até quase ficar paralelo ao chão. Dica: mantenha a cabeça erguida e os braços pendurados perpendiculares ao chão. Esta é a sua posição inicial.","Mantendo o tronco imóvel, puxe os halteres ao lado do corpo enquanto expira, aproximando as escápulas. No topo, contraia as costas e segure por um segundo.","Abaixe lentamente os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Bent_Press":{"name":"Bent Press com Kettlebell","instructions":["Faça um clean (arremesso) com um kettlebell até o ombro, estendendo as pernas e o quadril enquanto gira o punho. Esta será a sua posição inicial.","Incline o tronco para o lado oposto ao kettlebell até conseguir tocar o chão com a mão livre, mantendo os olhos no kettlebell. Ao mesmo tempo, empurre o peso verticalmente estendendo o cotovelo e mantendo o braço perpendicular ao chão.","Retorne à posição ereta com o kettlebell acima da cabeça, abaixe-o de volta ao ombro e repita pelo número desejado de repetições."]},
"Bicycling":{"name":"Ciclismo","instructions":["Para começar, sente-se na bicicleta e ajuste o selim à sua altura."]},
"Bicycling_Stationary":{"name":"Bicicleta Ergométrica","instructions":["Para começar, sente-se na bicicleta e ajuste o selim à sua altura.","Selecione a opção desejada no painel (pode ser necessário começar a pedalar para ligá-lo). Você pode usar o modo manual ou escolher um programa, inserindo idade e peso para estimar calorias gastas. A resistência pode ser ajustada ao longo do treino e os sensores no guidão monitoram sua frequência cardíaca."]},
"Board_Press":{"name":"Supino com Pranchas (Board Press)","instructions":["Deite-se no banco posicionando a cabeça além da barra se possível. De uma a cinco pranchas de madeira (2x6 polegadas) podem ser presas juntas e seguradas por um parceiro, com elásticos ou sob a camiseta.","Encaixe os pés para trás, arqueie as costas e retraia as escápulas firmando o trapézio no banco. Mantenha essa tensão corporal durante todo o movimento.","Use uma pegada padrão de supino ou na largura dos ombros para focar no tríceps. Retire a barra do suporte sem protrair os ombros, mantendo barra, punhos e cotovelos alinhados enquanto aperta a barra.","Desça a barra até tocar as pranchas e empurre-a para cima com o máximo de força, mantendo os cotovelos fechados até estender os braços."]},
"Body-Up":{"name":"Body-Up (Extensão de Tríceps na Prancha)","instructions":["Assuma a posição de prancha no chão, sustentando o peso do corpo nas pontas dos pés e nos antebraços com o tronco reto. Os antebraços devem ficar na largura dos ombros. Esta será a sua posição inicial.","Pressionando as palmas das mãos firmemente contra o chão, estenda os cotovelos para elevar o corpo do solo. Mantenha o tronco firme durante o movimento.","Abaixe lentamente os antebraços de volta ao chão flexionando os cotovelos.","Repita."]},
"Body_Tricep_Press":{"name":"Extensão de Tríceps com Peso Corporal na Barra","instructions":["Posicione uma barra em um rack na altura do peito.","Em pé, segure a barra na largura dos ombros e dê um ou dois passos para trás, com os pés juntos e os braços estendidos, inclinando o corpo sobre a barra. Esta será a sua posição inicial.","Comece flexionando os cotovelos para abaixar o corpo em direção à barra.","Faça uma breve pausa e inverta o movimento estendendo os cotovelos.","Para progredir além do peso corporal, adicione correntes sobre os ombros."]},
"Bodyweight_Flyes":{"name":"Crucifixo com Peso Corporal","instructions":["Posicione duas barras W carregadas igualmente no chão, lado a lado, garantindo que possam rolar.","Assuma a posição de flexão de braço sobre as barras, apoiando o peso nas pontas dos pés e nas mãos com os braços estendidos e o corpo reto.","Segure as barras com as mãos. Esta será a sua posição inicial.","Com movimento lento e controlado, afaste as mãos da linha central do corpo rolando as barras para os lados. Inspire durante essa fase.","Depois de afastar as barras ao máximo, retorne à posição inicial puxando-as de volta para o centro enquanto expira."]},
"Bodyweight_Mid_Row":{"name":"Remada Média com Peso Corporal","instructions":["Segure uma barra fixa com pegada média a aberta e as palmas voltadas para longe de você. Pendurado, traga os joelhos ao peito, incline-se para trás e passe as pernas para o lado oposto da barra de apoio. Esta será a sua posição inicial.","Começando com os braços estendidos, flexione os cotovelos e retraia as escápulas para puxar o corpo para cima até que as pernas encostem na estrutura.","Após uma breve pausa, retorne à posição inicial."]},
"Bodyweight_Squat":{"name":"Agachamento com Peso Corporal","instructions":["Fique em pé com os pés na largura dos ombros. Você pode colocar as mãos atrás da cabeça. Esta será a sua posição inicial.","Inicie o movimento flexionando os joelhos e o quadril, jogando o quadril para trás.","Desça até a amplitude máxima que conseguir e inverta o movimento rapidamente até retornar à posição inicial. Durante o agachamento, mantenha a cabeça e o peito erguidos e empurre os joelhos para fora."]},
"Bodyweight_Walking_Lunge":{"name":"Avanço Caminhando com Peso Corporal","instructions":["Comece em pé com os pés na largura dos ombros e as mãos na cintura.","Dê um passo à frente com uma perna, flexionando os joelhos para abaixar o quadril até o joelho de trás quase tocar o chão. Mantenha o tronco ereto e o joelho da frente alinhado sobre o pé da frente.","Impulsione pelo calcanhar do pé da frente e estenda ambos os joelhos para se levantar.","Dê o próximo passo com o pé de trás, repetindo o avanço com a perna oposta."]},
"Bosu_Ball_Cable_Crunch_With_Side_Bends":{"name":"Abdominal no Cabo sobre Bosu com Flexão Lateral","instructions":["Conecte um pegador padrão a cada lado de uma polia dupla na posição mais baixa.","Pegue um Bosu e posicione-o centralizado à frente da máquina de cabos.","Deite-se sobre o Bosu com a curvatura da lombar apoiada na cúpula, mantendo os glúteos próximos ao chão sem tocá-lo.","Estenda os braços para trás e segure os pegadores de cada cabo.","Com os pés bem afastados, estenda os braços à frente entre os joelhos, mantendo as mãos na altura dos joelhos.","Mantenha os braços estendidos e alinhados ao ângulo do cabo. Eleve o tronco em movimento de abdominal sem dobrar nem abaixar os braços.","Mantendo os braços firmes, desça lentamente à posição inicial arqueando as costas sobre o Bosu para alongar o abdômen.","Repita essa sequência até a falha.","Ao atingir a falha, mantenha o abdômen contraído e eleve o tronco para uma posição de prancha, tirando as costas do Bosu.","Abaixe os braços estendidos ao lado do corpo e faça flexões laterais alternadas tentando alcançar os calcanhares para finalizar trabalhando os oblíquos."]},
"Bottoms-Up_Clean_From_The_Hang_Position":{"name":"Hang Clean com Kettlebell Invertido (Bottoms-Up)","instructions":["Inicie o exercício em pé segurando um kettlebell em uma das mãos.","Balance o kettlebell para trás com vigor e inverta o movimento com força, apertando a alça o máximo possível para subir o kettlebell invertido até a altura do ombro."]},
"Bottoms_Up":{"name":"Abdominal Infra com Elevação Vertical (Bottoms Up)","instructions":["Deite-se de costas no chão com as pernas estendidas e os braços ao lado do corpo. Esta será a sua posição inicial.","Traga os joelhos em direção ao peito flexionando quadril e joelhos; em seguida, estenda as pernas diretamente para cima, perpendiculares ao chão, girando e elevando a pelve para tirar os glúteos do solo.","Após uma breve pausa, retorne à posição inicial."]},
"Box_Jump_Multiple_Response":{"name":"Salto na Caixa (Contínuo)","instructions":["Assuma uma postura relaxada de frente para a caixa ou plataforma a cerca de um braço de distância, com os braços ao lado do corpo e os joelhos levemente flexionados.","Usando os braços para gerar impulso inicial, salte para cima e para a frente, aterrissando com os dois pés simultaneamente sobre a caixa.","Desça ou salte imediatamente de volta ao ponto inicial e repita a sequência."]},
"Box_Skip":{"name":"Salto Alternado em Caixas (Box Skip)","instructions":["Você precisará de várias caixas alinhadas com cerca de 8 pés de distância entre elas.","Comece de frente para a primeira caixa com uma perna ligeiramente atrás da outra.","Impulsione com a perna de trás buscando ganhar a maior altura possível com o quadril.","Assim que aterrissar na caixa, impulsione a outra perna para a frente e para cima para saltar da caixa, aterrissando entre as duas primeiras caixas com a mesma perna que tocou a primeira caixa.","Em seguida, avance para a próxima caixa e repita."]},
"Box_Squat":{"name":"Agachamento na Caixa (Box Squat)","instructions":["O agachamento na caixa permite controlar a profundidade e desenvolver força explosiva. Comece em um power rack com uma caixa na altura adequada atrás de você, geralmente na linha do paralelo, podendo ajustar mais alto ou mais baixo.","Entre sob a barra e apoie-a na parte posterior dos ombros. Aperte as escápulas e gire os cotovelos à frente como se tentasse dobrar a barra. Retire a barra do suporte mantendo a lombar firme e dê um passo atrás. Use base mais aberta para focar costas, glúteos, adutores e posteriores, ou mais fechada para quadríceps, olhando para a frente.","Com costas, ombros e core firmes, empurre os joelhos para fora e jogue o quadril para trás ao descer até sentar na caixa, mantendo as canelas perpendiculares ao chão. Pause na caixa relaxando os flexores do quadril, sem nunca quicar nela.","Mantendo o peso nos calcanhares e empurrando pés e joelhos para fora, suba com explosão guiando o movimento pela cabeça e mantendo o corpo firme dos pés à cabeça."]},
"Box_Squat_with_Bands":{"name":"Agachamento na Caixa com Elásticos","instructions":["Comece em um power rack com uma caixa na altura desejada atrás de você. Prenda os elásticos nas pontas da barra e fixe-os nos pinos do rack ou em halteres pesados no chão (travados com anilhas se necessário) para obter a tensão adequada.","Entre sob a barra e apoie-a na parte posterior dos ombros, apertando as escápulas e girando os cotovelos à frente. Retire a barra do suporte mantendo a lombar firme e posicione os pés conforme o foco muscular desejado, olhando para a frente.","Com tronco firme, empurre os joelhos para fora e jogue o quadril para trás até sentar na caixa com as canelas perpendiculares ao chão. Pause na caixa relaxando os flexores do quadril, sem quicar.","Com o peso nos calcanhares, empurre os joelhos para fora e suba explosivamente guiando com a cabeça e mantendo a tensão corporal. Recoloque a barra no suporte com cuidado."]},
"Box_Squat_with_Chains":{"name":"Agachamento na Caixa com Correntes","instructions":["Comece em um power rack com uma caixa na altura adequada atrás de você, geralmente buscando a altura paralela ou conforme seu objetivo.","Para montar as correntes, passe a corrente guia sobre as mangas da barra e prenda a corrente pesada com um mosquetão, ajustando o comprimento para que alguns elos ainda toquem o chão no topo do movimento.","Entre sob a barra, apoie-a na parte posterior dos ombros, aperte as escápulas e retire a barra do suporte mantendo a lombar firme. Posicione os pés conforme a ênfase desejada e olhe para a frente.","Com costas e core firmes, empurre joelhos e quadril para trás até sentar na caixa com as canelas verticais. Pause na caixa sem quicar.","Mantendo o peso nos calcanhares e empurrando joelhos para fora, suba explosivamente mantendo todo o corpo rígido até retornar à posição inicial."]},
"Brachialis-SMR":{"name":"Liberação Miofascial do Braquial","instructions":["Deite-se de lado com o braço apoiado sobre um rolo de espuma, alinhado ao corpo e pressionando a parte lateral externa do bíceps contra o rolo.","Eleve o quadril do chão sustentando o peso no braço e nos pés. Mantenha por 10-30 segundos e depois troque de lado."]},
"Bradford_Rocky_Presses":{"name":"Desenvolvimento Bradford / Rocky","instructions":["Sente-se em um banco para desenvolvimento com uma barra na altura dos ombros em pegada pronada (palmas para a frente). Dica: a pegada deve ser mais aberta que a largura dos ombros, formando um ângulo de 90 graus entre antebraço e braço quando a barra desce. Esta é a sua posição inicial.","Retire a barra e eleve-a acima da cabeça estendendo os braços.","Abaixe a barra lentamente atrás da cabeça enquanto inspira.","Eleve a barra de volta acima da cabeça enquanto expira.","Desça a barra lentamente até a posição inicial à frente enquanto inspira. Isso completa uma repetição.","Continue alternando dessa maneira até concluir todas as repetições recomendadas."]},
"Butt-Ups":{"name":"Elevação de Quadril na Prancha (Butt-Ups)","instructions":["Assuma a posição de prancha apoiando os cotovelos e antebraços no chão, com os braços flexionados em um ângulo de 90 graus.","Arqueie levemente as costas em vez de mantê-las totalmente retas.","Eleve os glúteos em direção ao teto, contraindo fortemente o abdômen para aproximar as costelas do quadril, formando uma ponte alta. Expire durante essa subida.","Desça lentamente de volta à posição inicial enquanto inspira. Dica: não deixe a lombar ceder para baixo.","Repita pela quantidade recomendada de repetições."]},
"Butt_Lift_Bridge":{"name":"Elevação Pélvica no Chão (Ponte)","instructions":["Deite-se de costas no chão com os braços ao lado do corpo, joelhos flexionados e pés na largura dos ombros. Esta será a sua posição inicial.","Empurrando principalmente com os calcanhares, eleve o quadril do chão mantendo as costas retas. Expire durante a subida e segure no topo por um segundo.","Retorne lentamente à posição inicial enquanto inspira."]},
"Butterfly":{"name":"Voador (Peck Deck)","instructions":["Sente-se na máquina com as costas totalmente apoiadas no encosto.","Segure os apoios ou pegadores. Dica: ajuste o banco para que seus braços fiquem paralelos ao chão. Esta será a sua posição inicial.","Empurre os pegadores juntos lentamente contraindo o peitoral no centro. Expire durante essa fase e segure a contração por um segundo.","Retorne lentamente à posição inicial enquanto inspira até sentir o peitoral alongar completamente.","Repita pela quantidade recomendada de repetições."]},
"Cable_Chest_Press":{"name":"Supino Sentado no Cabo","instructions":["Ajuste o peso adequado e sente-se segurando os pegadores. Seus braços devem formar cerca de 45 graus com o tronco, com cabeça e peito erguidos e cotovelos dobrados a cerca de 90 graus. Esta será a sua posição inicial.","Estenda os cotovelos empurrando os pegadores juntos à sua frente, mantendo as escápulas retraídas durante toda a execução.","Após pausar na extensão completa, retorne à posição inicial mantendo a tensão nos cabos.","Você também pode variar o exercício desencostando as costas do apoio, ajustando para inclinado/declinado ou alternando os braços."]},
"Cable_Crossover":{"name":"Crossover na Polia Alta","instructions":["Posicione as polias na altura acima da cabeça, selecione a carga desejada e segure um pegador em cada mão.","Dê um passo à frente da linha entre as duas polias enquanto aproxima as mãos à frente do corpo, inclinando levemente o tronco pela cintura. Esta será a sua posição inicial.","Mantendo uma leve flexão nos cotovelos para proteger o tendão do bíceps, abra os braços lateralmente em um arco amplo até sentir o alongamento no peitoral enquanto inspira. Dica: tronco e ângulo dos cotovelos permanecem fixos; o movimento ocorre apenas nos ombros.","Retorne os braços à posição inicial pelo mesmo arco enquanto expira.","Segure por um segundo na posição contraída e repita pela quantidade prescrita de repetições."]},
"Cable_Crunch":{"name":"Abdominal no Cabo (Polia Alta)","instructions":["Ajoelhe-se abaixo de uma polia alta equipada com corda.","Segure a corda e puxe-a para baixo até que suas mãos fiquem próximas ao rosto.","Flexione levemente o quadril e permita que a carga faça uma leve extensão da lombar. Esta será a sua posição inicial.","Com o quadril imóvel, flexione a cintura contraindo o abdômen para levar os cotovelos em direção ao meio das coxas. Expire durante a descida e segure a contração por um segundo.","Retorne lentamente à posição inicial enquanto inspira. Dica: mantenha tensão constante no abdômen e não use peso excessivo a ponto de sobrecarregar a lombar.","Repita pela quantidade recomendada de repetições."]},
"Cable_Deadlifts":{"name":"Levantamento Terra no Cabo","instructions":["Posicione as polias na parte inferior das torres, selecione a carga adequada e fique em pé exatamente entre as colunas.","Agache flexionando quadril e joelhos até alcançar os pegadores.","Segurando os pegadores, inicie a subida empurrando pelos calcanhares e estendendo quadril e joelhos com as mãos ao lado do corpo, mantendo cabeça e peito erguidos.","Ao ficar totalmente em pé, retorne à posição inicial e repita."]},
"Cable_Hammer_Curls_-_Rope_Attachment":{"name":"Rosca Martelo no Cabo com Corda","instructions":["Prenda uma corda na polia baixa e fique em pé de frente para a máquina a cerca de 12 polegadas de distância.","Segure a corda com pegada neutra (palmas voltadas uma para a outra) e mantenha o tronco ereto com a curvatura natural das costas.","Mantenha os cotovelos colados ao lado do corpo e imóveis durante todo o exercício. Dica: apenas os antebraços devem se mover. Esta será a sua posição inicial.","Usando o bíceps, puxe a corda para cima enquanto expira até os antebraços encostarem no bíceps.","Após segurar a contração por 1 segundo apertando o bíceps, abaixe lentamente a carga de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Cable_Hip_Adduction":{"name":"Adução de Quadril no Cabo","instructions":["Fique em pé de frente para o lado de uma polia baixa, com uma perna próxima à polia e a outra mais afastada.","Prenda a tornozeleira ao cabo e ao tornozelo da perna que está mais próxima da polia.","Dê um passo lateral para longe da máquina criando tensão no cabo e segure na estrutura de apoio.","Apoie-se na perna sem tornozeleira e deixe a perna presa ao cabo ser puxada em direção à polia baixa. Esta será a sua posição inicial.","Realize o movimento puxando a perna presa ao cabo à frente da perna de apoio usando a parte interna da coxa para aduzir o quadril. Expire durante o esforço.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições e depois faça com a perna oposta."]},
"Cable_Incline_Pushdown":{"name":"Pullover Inclinado no Cabo","instructions":["Deite-se em um banco inclinado de costas para uma polia alta com barra reta acoplada.","Segure a barra acima da cabeça com pegada pronada (palmas para baixo) na largura dos ombros e estenda os braços à frente até a barra ficar a cerca de 2 polegadas acima das coxas. Esta será a sua posição inicial.","Mantendo os braços estendidos, leve-os para trás em semicírculo até a barra ficar diretamente acima da cabeça enquanto inspira.","Retorne lentamente à posição inicial usando as dorsais enquanto expira e segure a contração ao chegar em baixo.","Repita pela quantidade recomendada de repetições."]},
"Cable_Incline_Triceps_Extension":{"name":"Extensão de Tríceps no Banco Inclinado com Cabo","instructions":["Deite-se em um banco inclinado de costas para uma polia alta com barra reta acoplada.","Segure a barra acima da cabeça com pegada pronada fechada (menor que a largura dos ombros) e mantenha os cotovelos fechados ao lado da cabeça, com os braços formando cerca de 25 graus em relação ao chão.","Mantendo a parte superior dos braços imóvel, estenda os cotovelos contraindo o tríceps enquanto expira e segure por um segundo.","Retorne lentamente à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Cable_Internal_Rotation":{"name":"Rotação Interna de Ombro no Cabo","instructions":["Sente-se de lado ao lado de uma polia baixa (com as pernas estendidas ou cruzadas) e segure o pegador unilateral com o braço mais próximo ao cabo. Dica: se a polia tiver ajuste de altura, você pode sentar em um banco reto.","Encoste o cotovelo na lateral do tronco dobrado a 90° com o antebraço apontando na direção da polia. Esta será a sua posição inicial.","Puxe o pegador em direção ao corpo fazendo rotação interna do ombro até o antebraço cruzar à frente do abdômen, mantendo-o sempre perpendicular ao tronco.","Retorne lentamente à posição inicial.","Repita pela quantidade recomendada de repetições e depois execute com o outro braço."]},
"Cable_Iron_Cross":{"name":"Crucifixo Cruzado no Cabo (Iron Cross)","instructions":["Ajuste as polias na posição alta, selecione a carga desejada e segure um pegador em cada mão.","Fique no centro entre as duas polias com os braços estendidos para os lados, cabeça e peito erguidos, formando um \"T\". Esta será a sua posição inicial.","Mantendo os cotovelos estendidos, puxe os braços para baixo até encostarem ao lado do corpo.","Faça uma breve pausa na contração máxima e retorne os braços à posição inicial.","Continue o movimento pelo número prescrito de repetições."]},
"Cable_Judo_Flip":{"name":"Giro de Tronco no Cabo (Judo Flip)","instructions":["Prenda uma corda na posição mais baixa da polia. Fique de lado para o cabo com os pés bem afastados e segure a corda com as duas mãos.","Gire o corpo para longe da polia trazendo a corda por cima do ombro, simulando uma queda de judô.","Transfira o peso entre os pés enquanto gira e flexiona o tronco para a frente puxando o cabo para baixo.","Retorne à posição inicial e repita até a falha.","Em seguida, reposicione-se e repita a sequência para o lado oposto."]},
"Cable_Lying_Triceps_Extension":{"name":"Tríceps Testa Deitado no Cabo","instructions":["Deite-se em um banco reto e segure a barra reta presa a uma polia baixa com pegada pronada fechada. Dica: a forma mais fácil é pedir para alguém entregar a barra depois que você deitar.","Com os braços estendidos, posicione a barra acima do tronco formando um ângulo de 90 graus entre braços e corpo. Esta será a sua posição inicial.","Abaixe a barra flexionando os cotovelos enquanto mantém a parte superior dos braços imóvel e os cotovelos fechados, até a barra tocar levemente a testa. Inspire durante a descida.","Estenda os braços contraindo o tríceps para retornar à posição inicial enquanto expira.","Segure por um segundo na posição contraída e repita pela quantidade recomendada de repetições."]},
"Cable_One_Arm_Tricep_Extension":{"name":"Extensão de Tríceps Unilateral no Cabo","instructions":["Com a mão direita, segure o pegador unilateral preso à polia alta com pegada supinada (palma voltada para cima), em pé de frente para a torre de peso.","Puxe o pegador para baixo de modo que o braço e o cotovelo fiquem travados ao lado do corpo, formando um ângulo agudo (menor que 90 graus) entre braço e antebraço. Apoie a outra mão na cintura e coloque um pé à frente para melhor equilíbrio. Esta será a sua posição inicial.","Contraindo o tríceps, empurre o pegador para baixo até o braço ficar totalmente estendido ao lado do corpo enquanto expira. Dica: apenas o antebraço deve se mover.","Aperte o tríceps e segure por um segundo na contração.","Retorne lentamente o pegador à posição inicial.","Repita pela quantidade recomendada de repetições e depois execute com o outro braço."]},
"Cable_Preacher_Curl":{"name":"Rosca Scott no Cabo","instructions":["Posicione um banco Scott a cerca de 2 pés à frente de uma máquina de polia.","Prenda uma barra reta na polia baixa.","Sente-se no banco Scott com os braços e cotovelos firmemente apoiados no suporte acolchoado e peça para alguém passar a barra da polia baixa.","Segure a barra e estenda totalmente os braços sobre o apoio do banco. Esta será a sua posição inicial.","Puxe a carga em direção aos ombros e contraia fortemente o bíceps no topo enquanto expira, segurando por um segundo.","Abaixe lentamente o peso de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Cable_Rear_Delt_Fly":{"name":"Crucifixo Inverso no Cabo","instructions":["Ajuste as polias acima da altura da cabeça e selecione a carga adequada.","Segure o cabo esquerdo com a mão direita e o cabo direito com a mão esquerda, cruzando os braços à sua frente. Esta será a sua posição inicial.","Inicie o movimento levando os braços para trás e para fora, mantendo-os estendidos durante toda a execução.","Pause no final do movimento antes de retornar os pegadores à posição inicial."]},
"Cable_Reverse_Crunch":{"name":"Abdominal Reverso no Cabo","instructions":["Prenda uma tornozeleira a uma polia baixa e coloque um colchonete no chão à frente dela.","Sente-se com os pés voltados para a polia e prenda o cabo aos tornozelos.","Deite-se, eleve as pernas e flexione os joelhos a 90 graus. Suas pernas e o cabo devem ficar alinhados; caso contrário, ajuste a altura da polia.","Com as mãos atrás da cabeça, traga os joelhos em direção ao tronco e tire o quadril do chão.","Pause por um instante e, de forma lenta e controlada, abaixe o quadril e volte as pernas ao ângulo inicial de 90 graus mantendo tensão no abdômen.","Repita o movimento até a falha."]},
"Cable_Rope_Overhead_Triceps_Extension":{"name":"Tríceps Francês no Cabo com Corda","instructions":["Prenda uma corda na polia inferior da torre.","De costas para a máquina, segure a corda com as duas mãos e estenda os braços diretamente acima da cabeça em pegada neutra (palmas voltadas uma para a outra), com os cotovelos próximos à cabeça e os braços perpendiculares ao chão. Esta será a sua posição inicial.","Abaixe a corda lentamente atrás da cabeça mantendo a parte superior dos braços imóvel. Inspire na descida e pause quando o tríceps estiver totalmente alongado.","Retorne à posição inicial estendendo os cotovelos e contraindo o tríceps enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Cable_Rope_Rear-Delt_Rows":{"name":"Remada para Deltoide Posterior no Cabo com Corda","instructions":["Sente-se na estação de remada baixa da mesma forma que faria na remada sentada para costas.","Prenda uma corda na polia e segure-a com pegada pronada, mantendo os braços estendidos paralelos ao chão e os cotovelos abertos.","Mantenha a lombar ereta e deslize o quadril para trás deixando os joelhos levemente flexionados. Esta será a sua posição inicial.","Puxe a corda em direção à parte superior do peito, logo abaixo do pescoço, mantendo os cotovelos altos e abertos para os lados enquanto expira até os cotovelos passarem ligeiramente atrás das costas. Dica: mantenha os braços horizontais durante todo o movimento.","Retorne à posição inicial estendendo os braços e alongando os ombros à frente enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Cable_Russian_Twists":{"name":"Torção Russa no Cabo","instructions":["Conecte um pegador padrão à polia ajustada na altura média.","Apoie as costas sobre uma bola suíça perpendicular ao cabo e segure o pegador com uma mão a cerca de um braço de distância da polia, mantendo tensão no cabo.","Segure o pegador com as duas mãos e estenda totalmente os braços acima do peito, alinhando as mãos diretamente à altura da polia.","Mantenha o quadril elevado e o abdômen contraído, formando uma linha reta da cabeça aos joelhos, e gire o tronco para longe da polia em um quarto de volta.","Pause por um instante e retorne de forma lenta e controlada à posição inicial, mantendo tensão lateral no cabo.","Repita o movimento até a falha.","Em seguida, reposicione-se e repita a série para o lado oposto."]},
"Cable_Seated_Crunch":{"name":"Abdominal Sentado no Cabo","instructions":["Sente-se em um banco reto de costas para uma polia alta.","Segure a corda com as duas mãos (palmas voltadas uma para a outra) e apoie-as firmemente sobre os ombros, permitindo que a carga faça uma leve extensão da lombar. Esta será a sua posição inicial.","Com o quadril imóvel, flexione a cintura levando os cotovelos em direção ao quadril enquanto expira.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Cable_Seated_Lateral_Raise":{"name":"Elevação Lateral Sentado no Cabo","instructions":["Fique entre duas polias baixas opostas e posicione um banco reto perpendicularmente atrás de você. Selecione a carga em cada polia.","Sente-se na extremidade do banco com os pés à frente dos joelhos.","Incline o tronco à frente mantendo as costas retas até apoiar o peito sobre as coxas.","Peça para alguém entregar os pegadores cruzados (mão direita na polia esquerda e vice-versa), passando os cabos por baixo dos joelhos com os braços estendidos e palmas voltadas uma para a outra. Esta será a posição inicial.","Mantendo a leve flexão fixa nos cotovelos, eleve os braços lateralmente até ficarem paralelos ao chão na altura dos ombros enquanto expira e segure a contração por um segundo.","Abaixe lentamente os braços de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições. Dica: mantenha os braços perpendiculares ao tronco e o ângulo dos cotovelos fixo (10 a 30 graus) durante todo o exercício."]},
"Cable_Shoulder_Press":{"name":"Desenvolvimento de Ombros no Cabo","instructions":["Posicione as polias na parte inferior das torres e selecione uma carga adequada.","Fique em pé exatamente entre as colunas, segure os pegadores na altura dos ombros com as palmas voltadas para a frente. Esta será a sua posição inicial.","Mantendo cabeça e peito erguidos, estenda os cotovelos para empurrar os pegadores diretamente acima da cabeça.","Após pausar no topo, retorne à posição inicial e repita."]},
"Cable_Shrugs":{"name":"Encolhimento de Ombros no Cabo","instructions":["Segure uma barra reta acoplada a uma polia baixa com pegada pronada (palmas para baixo) na largura dos ombros ou um pouco mais aberta.","Fique ereto próximo à polia com os braços estendidos à frente segurando a barra. Esta será a sua posição inicial.","Eleve a barra subindo os ombros o máximo possível enquanto expira e segure a contração no topo por um segundo. Dica: mantenha os braços estendidos o tempo todo e não use o bíceps; apenas os ombros devem subir e descer.","Abaixe a barra de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Cable_Wrist_Curl":{"name":"Rosca de Punho no Cabo","instructions":["Posicione um banco reto à frente de uma polia baixa com barra reta acoplada.","Segure a barra com pegada supinada (palmas para cima) estreita ou na largura dos ombros e apoie os antebraços sobre as coxas, deixando os punhos pendurados logo além dos joelhos.","Flexione os punhos para cima enquanto expira e segure a contração por um segundo.","Abaixe lentamente os punhos de volta à posição inicial enquanto inspira.","Mantenha os antebraços imóveis; apenas os punhos devem se mover durante o exercício.","Repita pela quantidade recomendada de repetições."]},
"Calf-Machine_Shoulder_Shrug":{"name":"Encolhimento na Máquina de Panturrilha","instructions":["Posicione-se na máquina de panturrilha em pé com as almofadas apoiadas sobre os ombros, tronco reto e braços relaxados ao lado do corpo. Esta será a sua posição inicial.","Eleve os ombros em direção às orelhas enquanto expira e segure a contração por um segundo completo.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Calf_Press":{"name":"Panturrilha no Aparelho Sentado (Calf Press)","instructions":["Ajuste o assento de modo que suas pernas fiquem apenas levemente flexionadas na posição inicial, com a ponta dos pés firme na plataforma.","Selecione o peso adequado e segure os apoios laterais. Esta será a sua posição inicial.","Estenda os joelhos quase completamente para tirar o peso do descanso, mantendo os tornozelos bem flexionados com os dedos apontando para cima. Execute empurrando a plataforma para longe com a ponta dos pés o máximo possível.","Após uma breve pausa, inverta o movimento e repita."]},
"Calf_Press_On_The_Leg_Press_Machine":{"name":"Elevação de Panturrilha no Leg Press","instructions":["Sente-se no leg press e apoie os pés na plataforma à sua frente em abertura média (largura dos ombros).","Destrave a plataforma e empurre até quase estender totalmente as pernas sem travar os joelhos, formando um ângulo de 90 graus entre tronco e pernas. Posicione apenas os dedos e a parte anterior dos pés na borda inferior da plataforma, deixando os calcanhares livres. Esta será a sua posição inicial.","Empurre a plataforma elevando os calcanhares o máximo possível enquanto expira e contrai as panturrilhas, mantendo os joelhos imóveis o tempo todo. Segure no topo por um segundo.","Retorne lentamente à posição inicial enquanto inspira, abaixando os calcanhares até alongar bem as panturrilhas.","Repita pela quantidade recomendada de repetições."]},
"Calf_Raise_On_A_Dumbbell":{"name":"Elevação de Panturrilha sobre Halter","instructions":["Segure-se em um apoio firme para equilíbrio e pise sobre a pegada de um halter, de preferência com anilhas redondas que rolem levemente para exigir mais estabilização.","Role o pé ligeiramente para a frente para alongar bem a panturrilha. Esta será a sua posição inicial.","Suba na ponta do pé rolando o halter ligeiramente para trás até obter extensão completa enquanto expira, contraindo forte a panturrilha no topo por um segundo.","Inspire enquanto desce rolando o halter levemente para a frente para aumentar o alongamento.","Repita pela quantidade recomendada de repetições."]},
"Calf_Raises_-_With_Bands":{"name":"Elevação de Panturrilha com Elástico","instructions":["Pise no centro de um elástico com a ponta dos pés garantindo que ambos os lados tenham o mesmo comprimento.","Segure as alças e eleve as mãos ao lado da cabeça como na posição inicial de desenvolvimento, com palmas para a frente e cotovelos flexionados para os lados, criando tensão no elástico. Esta será a sua posição inicial.","Mantendo as mãos na altura dos ombros, suba na ponta dos pés enquanto expira, contraindo fortemente as panturrilhas no topo.","Após uma contração de um segundo, desça lentamente à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Calf_Stretch_Elbows_Against_Wall":{"name":"Alongamento de Panturrilha com Cotovelos na Parede","instructions":["Fique em pé de frente para uma parede a alguns passos de distância.","Incline-se contra a parede apoiando o peso nos antebraços.","Tente manter os calcanhares encostados no chão e segure por 10-20 segundos. Afaste-se ou aproxime-se da parede para aumentar ou reduzir a intensidade."]},
"Calf_Stretch_Hands_Against_Wall":{"name":"Alongamento de Panturrilha com Mãos na Parede","instructions":["Fique em pé de frente para uma parede a alguns passos de distância, colocando um pé à frente do outro.","Incline-se para a frente e apoie as mãos na parede mantendo calcanhar, quadril e cabeça alinhados em linha reta.","Tente manter o calcanhar de trás no chão. Segure por 10-20 segundos e depois troque de lado."]},
"Calves-SMR":{"name":"Liberação Miofascial das Panturrilhas","instructions":["Sente-se no chão e coloque um rolo de espuma sob a panturrilha de uma perna; a outra perna pode cruzar por cima para aumentar a pressão ou apoiar no chão. Esta será a sua posição inicial.","Apoie as mãos ao lado ou atrás do corpo e eleve o quadril do chão pressionando a panturrilha contra o rolo. Deslize de abaixo do joelho até acima do tornozelo, pausando nos pontos de tensão por 10-30 segundos. Repita na outra perna."]},
"Car_Deadlift":{"name":"Levantamento Terra com Carro (Car Deadlift)","instructions":["Este equipamento de strongman normalmente possui pegadores neutros laterais, embora alguns tenham barra reta. A estrutura pode ser carregada com um veículo ou objetos pesados como pneus ou barris.","Posicione-se centralizado entre os pegadores (ou alguns centímetros atrás se puxar mais de costas), com os pés na largura do quadril. Flexione o quadril para segurar os pegadores, inspire fundo, abaixe o quadril e flexione os joelhos.","Olhe para a frente, mantenha peito aberto e costas firmes, e empurre o chão pelos calcanhares para subir a carga. Na subida, aproxime as escápulas e projete o quadril à frente.","Abaixe a carga flexionando o quadril e guiando-a de volta ao chão."]},
"Car_Drivers":{"name":"Volante com Anilha (Car Drivers)","instructions":["Em pé, segure uma anilha com as duas mãos nas posições de 3 e 9 horas, com as palmas voltadas uma para a outra e os braços estendidos diretamente à sua frente. Esta será a sua posição inicial.","Inicie o movimento girando a anilha o máximo possível para um lado, como ao virar um volante.","Inverta o movimento girando totalmente para o lado oposto.","Repita pela quantidade recomendada de repetições."]},
"Carioca_Quick_Step":{"name":"Passo Rápido Carioca","instructions":["Comece com os pés afastados poucos centímetros e o braço esquerdo elevado em postura atlética relaxada.","Com o pé direito, dê um passo rápido cruzando por trás e eleve o joelho.","Impulsione os braços ao subir o joelho direito garantindo que o joelho suba e desça em linha reta, sem girar os pés e olhando sempre para a frente enquanto se desloca lateralmente."]},
"Cat_Stretch":{"name":"Alongamento do Gato","instructions":["Apoie-se no chão em quatro apoios (mãos e joelhos).","Contraia o abdômen para dentro e arredonde a coluna, lombar, ombros e pescoço, deixando a cabeça cair.","Segure por 15 segundos."]},
"Catch_and_Overhead_Throw":{"name":"Recepção e Arremesso Acima da Cabeça com Medicine Ball","instructions":["Comece em pé de frente para uma parede ou um parceiro.","Com as duas mãos, leve a bola medicinal atrás da cabeça alongando ao máximo e arremesse-a com força para a frente.","Acompanhe o movimento preparando-se para receber o rebote. Se estiver usando uma parede, fique perto o suficiente para receber a bola e mire um pouco mais alto do que faria com um parceiro."]},
"Chain_Handle_Extension":{"name":"Extensão de Tríceps com Correntes","instructions":["Você precisará de dois pegadores de cabo, um banco reto e correntes. Prenda o meio das correntes aos pegadores e deite-se no banco com os cotovelos apontando diretamente para cima.","Estenda os cotovelos mantendo a parte superior dos braços imóvel e os punhos em pronação.","Pause na extensão completa e inverta o movimento para retornar à posição inicial."]},
"Chain_Press":{"name":"Supino com Correntes e Pegadores","instructions":["Prenda as correntes aos pegadores de cabo e deite-se no banco reto na mesma postura de um supino com halteres, com punhos pronados e braços perpendiculares ao chão. Esta será a sua posição inicial.","Abaixe as correntes flexionando os cotovelos, deixando parte dos elos apoiar no chão.","Desça até os cotovelos formarem um ângulo de 90 graus e então inverta o movimento estendendo os braços até o topo."]},
"Chair_Leg_Extended_Stretch":{"name":"Alongamento de Perna Estendida na Cadeira","instructions":["Sente-se ereto em uma cadeira e segure as laterais do assento.","Eleve uma perna estendendo o joelho e flexionando o tornozelo.","Mova lentamente essa perna para fora o máximo possível, depois retorne ao centro e abaixe-a.","Repita com a outra perna."]},
"Chair_Lower_Back_Stretch":{"name":"Alongamento Lombar na Cadeira","instructions":["Sente-se ereto em uma cadeira.","Incline o tronco para um lado passando o braço acima da cabeça, segurando na cadeira com a mão livre.","Segure por 10 segundos e repita para o outro lado."]},
"Chair_Squat":{"name":"Agachamento com Banco à Frente (Chair Squat)","instructions":["Ajuste a barra no suporte na altura ideal para você. Depois de carregá-la, entre sob a barra e apoie-a na parte posterior dos ombros.","Segure a barra com as palmas voltadas para a frente, destrave-a e retire-a do suporte estendendo as pernas.","Posicione os pés cerca de 18 polegadas à frente da linha da barra, na largura dos ombros e com os dedos levemente para fora. Olhe sempre para a frente mantendo a coluna neutra ou levemente arqueada. Esta será a sua posição inicial.","Abaixe a barra lentamente flexionando os joelhos e mantendo a postura ereta com a cabeça erguida, até o ângulo entre coxas e pernas ultrapassar 90 graus.","Comece a subir enquanto expira empurrando o chão com os calcanhares, estendendo os joelhos até retornar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Chair_Upper_Body_Stretch":{"name":"Alongamento de Tronco na Cadeira","instructions":["Sente-se na borda de uma cadeira segurando o encosto por trás.","Estenda os braços mantendo as costas retas e projete o tronco para a frente até sentir o alongamento. Segure por 20-30 segundos."]},
"Chest_And_Front_Of_Shoulder_Stretch":{"name":"Alongamento de Peitoral e Ombro Anterior","instructions":["Fique em pé com as pernas juntas segurando um bastão ou cabo de vassoura.","Segure o bastão com pegada um pouco mais aberta que a largura dos ombros à frente do corpo, com as palmas voltadas para baixo.","Eleve cuidadosamente o bastão acima e para trás da cabeça."]},
"Chest_Push_from_3_point_stance":{"name":"Arremesso de Peito em Posição de 3 Apoios","instructions":["Comece em postura de três apoios, agachado com as costas retas e uma mão no chão, com a bola medicinal posicionada diretamente à sua frente.","Dê o primeiro passo puxando a bola para o peito e posicionando as duas mãos para o lançamento.","Ao dar o segundo passo, arremesse a bola para a frente de forma explosiva com o máximo de força possível."]},
"Chest_Push_multiple_response":{"name":"Arremesso de Peito Ajoelhado (Contínuo)","instructions":["Ajoelhe-se de frente para uma parede ou um parceiro, segurando a bola medicinal firmemente contra o peito com as duas mãos.","Execute o passe impulsionando o quadril explosivamente para a frente enquanto empurra a bola com toda a força.","Acompanhe o movimento caindo para a frente e amortecendo a queda com as mãos no chão.","Retorne imediatamente à posição ereta ajoelhada e repita pelo número desejado de repetições."]},
"Chest_Push_single_response":{"name":"Arremesso de Peito Ajoelhado (Único)","instructions":["Ajoelhe-se segurando a bola medicinal firmemente contra o peito com as duas mãos.","Execute o passe impulsionando o quadril explosivamente para a frente enquanto empurra a bola o mais longe possível.","Acompanhe o movimento caindo para a frente e amortecendo a queda com as mãos no chão."]},
"Chest_Push_with_Run_Release":{"name":"Arremesso de Peito com Corrida","instructions":["Comece em postura atlética com joelhos flexionados, quadril para trás e costas retas, segurando a bola medicinal próxima às pernas. Esta será a sua posição inicial.","Ao dar o primeiro passo, traga a bola medicinal para o peito.","Ao dar o segundo passo, empurre a bola explosivamente para a frente e corra em sprint por 10 jardas logo após o lançamento."]},
"Chest_Stretch_on_Stability_Ball":{"name":"Alongamento de Peitoral na Bola Suíça","instructions":["Ajoelhe-se em quatro apoios ao lado de uma bola suíça.","Apoie um cotovelo sobre a bola mantendo o braço aberto para o lado. Esta será a sua posição inicial.","Abaixe o tronco em direção ao chão mantendo o cotovelo apoiado na bola. Segure o alongamento por 20-30 segundos e repita com o outro braço."]},
"Childs_Pose":{"name":"Postura da Criança","instructions":["Apoie-se nas mãos e nos joelhos e caminhe com as mãos para a frente.","Abaixe os glúteos para sentar sobre os calcanhares, deixando os braços deslizarem pelo chão para alongar toda a coluna.","Ao acomodar-se nos calcanhares, traga os braços para junto dos pés, apoie a testa no chão e respire profundamente relaxando as costas. Evite esta posição se tiver problemas nos joelhos."]},
"Chin-Up":{"name":"Barra Fixa Supinada","instructions":["Segure a barra fixa com as palmas voltadas para o corpo (pegada supinada) e mãos mais próximas que a largura dos ombros.","Pendurado com os braços estendidos, mantenha o tronco o mais reto possível criando leve curvatura lombar e abrindo o peito. Esta é a posição inicial. Dica: manter o tronco reto maximiza o trabalho do bíceps.","Ao expirar, puxe o corpo para cima até a cabeça alcançar a altura da barra, concentrando-se em usar o bíceps e mantendo os cotovelos próximos ao corpo. Dica: o tronco não deve balançar; apenas os braços se movem.","Após segurar um segundo apertando o bíceps no topo, abaixe lentamente o corpo até estender totalmente os braços enquanto inspira.","Repita esse movimento pela quantidade prescrita de repetições."]},
"Chin_To_Chest_Stretch":{"name":"Alongamento Queixo no Peito","instructions":["Sente-se no chão em posição confortável.","Coloque as duas mãos atrás da cabeça com os dedos entrelaçados, polegares apontando para baixo e cotovelos para a frente. Puxe suavemente a cabeça em direção ao peito e segure por 20-30 segundos."]},
"Circus_Bell":{"name":"Desenvolvimento com Halter Gigante (Circus Bell)","instructions":["O Circus Bell é um halter gigante com pegada espessa. Posicione-o entre os pés e segure a alça com as duas mãos.","Faça um clean estendendo quadril e joelhos para levá-lo até o ombro desejado, soltando a mão auxiliar.","Apoie uma das cabeças do halter atrás do ombro para equilibrar. Para erguer acima da cabeça, faça uma leve flexão de joelhos e impulsione para cima estendendo o braço e inclinando levemente o tronco para o lado oposto.","Conduza o halter de volta ao chão com controle. Recomenda-se executar sobre um tapete de borracha espesso para proteger o piso."]},
"Clean":{"name":"Clean (Arremesso aos Ombros)","instructions":["Com a barra no chão próxima às canelas, faça uma pegada pronada (ou hook grip) logo por fora das pernas. Abaixe o quadril concentrando o peso nos calcanhares, costas retas, cabeça para a frente, peito aberto e ombros ligeiramente à frente da barra.","Esta será a sua posição inicial.","Inicie a primeira puxada empurrando o chão pelos calcanhares e estendendo os joelhos, mantendo constante o ângulo das costas e os braços estendidos até passar acima dos joelhos.","Na segunda puxada, ao aproximar a barra do meio das coxas, estenda explosivamente quadril, joelhos e tornozelos como em um salto para acelerar a barra para cima, mantendo os braços estendidos sem puxar com eles.","Ao atingir extensão total, entre na terceira puxada encolhendo os ombros com vigor e girando os cotovelos rapidamente por baixo da barra para recebê-la em agachamento frontal apoiada nos ombros, descendo ao fundo do agachamento para auxiliar a recuperação.","Recupere-se imediatamente empurrando pelos calcanhares com tronco ereto e cotovelos altos até ficar totalmente em pé."]},
"Clean_Deadlift":{"name":"Levantamento Terra para Clean","instructions":["Fique em pé com a barra próxima às canelas e os pés sob o quadril levemente voltados para fora. Segure a barra com pegada pronada ou hook grip na largura dos ombros, agachando com a coluna totalmente estendida e os ombros à frente da barra.","Inicie empurrando o chão pela parte anterior dos calcanhares, mantendo o ângulo das costas constante e abrindo os joelhos para fora do caminho da barra.","Após a barra passar dos joelhos, complete o levantamento projetando o quadril contra a barra até estender totalmente quadril e joelhos."]},
"Clean_Pull":{"name":"Puxada de Clean (Clean Pull)","instructions":["Com a barra no chão próxima às canelas, faça uma pegada pronada ou hook grip logo por fora das pernas. Abaixe o quadril com o peso nos calcanhares, costas retas, peito aberto e ombros ligeiramente à frente da barra. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pelos calcanhares e estendendo os joelhos, mantendo o ângulo das costas constante, braços estendidos e cotovelos apontados para fora até passar dos joelhos.","Na segunda puxada, quando a barra chegar ao meio das coxas, estenda vigorosamente quadril, joelhos e tornozelos como um salto para acelerar a barra para cima, encerrando na extensão completa com braços ainda estendidos."]},
"Clean_Shrug":{"name":"Encolhimento de Clean","instructions":["Segure a barra na altura do meio das coxas com pegada pronada ou hook grip na largura dos ombros, mantendo as costas retas e levemente inclinadas à frente.","Encolha os ombros em direção às orelhas com explosão. Embora permita cargas maiores que o clean, evite sobrecarregar a ponto de tornar a execução lenta."]},
"Clean_and_Jerk":{"name":"Clean and Jerk (Arremesso Completo)","instructions":["Com a barra no chão próxima às canelas, faça uma pegada pronada ou hook grip logo por fora das pernas. Abaixe o quadril com o peso nos calcanhares, costas retas, peito aberto e ombros ligeiramente à frente da barra. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pelos calcanhares e estendendo os joelhos, mantendo constante o ângulo das costas e os braços estendidos até passar dos joelhos.","Na segunda puxada, ao aproximar a barra do meio das coxas, estenda explosivamente quadril, joelhos e tornozelos como em um salto para impulsionar a barra para cima mantendo os braços estendidos.","Ao atingir extensão total, encolha os ombros e puxe o corpo rapidamente para baixo da barra girando os cotovelos, recebendo-a em agachamento frontal apoiada nos ombros e descendo ao fundo do agachamento.","Recupere-se imediatamente empurrando pelos calcanhares com tronco ereto e cotovelos altos até ficar em pé.","A segunda fase é o jerk (arremesso acima da cabeça): com a barra apoiada na frente dos ombros e pés sob o quadril, faça uma leve flexão rápida dos joelhos sem jogar o quadril para trás e inverta com máxima potência.","Impulsione pelos calcanhares com velocidade e recue a cabeça do caminho quando a barra subir dos ombros.","Enquanto os pés saem do chão, posicione-os rapidamente em base dividida (um pé à frente e outro atrás), recebendo a barra com os braços totalmente travados acima da cabeça e depois juntando os pés em pé."]},
"Clean_and_Press":{"name":"Clean and Press (Arremesso e Desenvolvimento)","instructions":["Posicione os pés na largura dos ombros com os joelhos entre os braços. Com as costas retas, flexione joelhos e quadril e segure a barra próxima às canelas com pegada pronada um pouco mais aberta que os ombros e cotovelos para fora. Esta será a sua posição inicial.","Inicie puxando a barra ao estender os joelhos, avançando o quadril e subindo os ombros no mesmo ritmo mantendo constante o ângulo das costas.","Ao passar dos joelhos, estenda tornozelos, joelhos e quadril com força como em um salto, encolhendo os ombros e mantendo a barra próxima ao corpo.","Na elevação máxima, comece a entrar sob a barra descendo em posição de agachamento.","Ao atingir o ponto mais alto da barra, gire os cotovelos por baixo dela e apoie-a na frente dos ombros mantendo o tronco ereto para absorver o peso.","Fique totalmente em pé segurando a barra na posição de clean.","Sem mover os pés, empurre a barra acima da cabeça enquanto expira e abaixe-a sob controle."]},
"Clean_from_Blocks":{"name":"Clean dos Blocos","instructions":["Com a barra apoiada sobre caixas ou suportes na altura desejada, faça uma pegada pronada ou hook grip logo por fora das pernas, mantendo peso nos calcanhares, costas retas, peito aberto e ombros à frente da barra. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pelos calcanhares e estendendo os joelhos, mantendo o ângulo das costas constante, braços estendidos e cotovelos para fora.","Ao atingir extensão total, encolha os ombros e entre rapidamente sob a barra girando os cotovelos para recebê-la apoiada nos ombros em agachamento frontal.","Recupere-se imediatamente empurrando pelos calcanhares até ficar em pé e retorne a barra às caixas para a repetição seguinte."]},
"Clock_Push-Up":{"name":"Flexão de Braço Relógio","instructions":["Deite-se de bruços no chão apoiando o peso nas mãos e nas pontas dos pés.","Mantenha os braços estendidos com as mãos na largura dos ombros e o corpo totalmente reto. Esta será a sua posição inicial.","Desça flexionando os cotovelos até aproximar o peito do chão.","Em baixo, inverta o movimento empurrando-se com explosão até tirar as mãos do chão, deslocando o tronco cerca de 12-18 polegadas para um lado.","Ao impulsionar para cima, afaste o pé externo na direção do movimento, girando o corpo cerca de 30 graus para a repetição seguinte.","Retorne à posição inicial e repita dando a volta completa até voltar ao ponto de partida."]},
"Close-Grip_Barbell_Bench_Press":{"name":"Supino Reto com Barra - Pegada Fechada","instructions":["Deite-se em um banco reto. Usando pegada fechada (cerca da largura dos ombros), retire a barra do suporte e segure-a diretamente acima de você com os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça lentamente até sentir a barra tocar o meio do peito. Dica: diferentemente do supino tradicional, mantenha os cotovelos próximos ao tronco o tempo todo para maximizar o trabalho do tríceps.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando a força do tríceps. Estenda os braços no topo, segure por um segundo e desça lentamente novamente. Dica: a descida deve levar pelo menos o dobro do tempo da subida.","Repita o movimento pela quantidade prescrita de repetições.","Ao terminar, recoloque a barra no suporte."]},
"Close-Grip_Dumbbell_Press":{"name":"Supino Fechado com Halter Único","instructions":["Coloque um halter em pé sobre um banco reto.","Garantindo que o halter esteja seguro, deite-se perpendicularmente ao banco apoiando apenas os ombros, com quadril abaixo do banco, joelhos flexionados e pés firmes no chão.","Segure o halter com as duas mãos diretamente acima do peito com os braços estendidos e as palmas pressionando a face interna da anilha superior. Esta será a sua posição inicial.","Inicie o movimento descendo o halter até o peito.","Retorne à posição inicial estendendo os cotovelos."]},
"Close-Grip_EZ-Bar_Curl_with_Band":{"name":"Rosca Fechada na Barra W com Elástico","instructions":["Prenda um elástico em cada extremidade da barra W. Segure a barra pisando no meio do elástico e fique ereto com pegada supinada fechada e cotovelos próximos ao tronco. Esta será a sua posição inicial.","Mantendo a parte superior dos braços fixa, flexione os cotovelos executando a rosca e expirando ao subir a carga.","Continue até o bíceps contrair totalmente e a barra chegar à altura dos ombros, segurando por um segundo apertando forte o bíceps.","Comece lentamente a abaixar a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Close-Grip_EZ-Bar_Press":{"name":"Supino Fechado com Barra W","instructions":["Deite-se em um banco reto com uma barra W carregada com a carga adequada.","Usando pegada fechada, erga a barra e segure-a diretamente acima do tronco com os cotovelos fechados e braços perpendiculares ao chão. Esta será a sua posição inicial.","Abaixe a barra até a parte inferior do peito enquanto inspira, mantendo os cotovelos próximos ao corpo.","Usando o tríceps, empurre a barra de volta à posição inicial estendendo os cotovelos enquanto expira.","Repita."]},
"Close-Grip_EZ_Bar_Curl":{"name":"Rosca Direta Fechada com Barra W","instructions":["Fique em pé com o tronco ereto segurando uma barra W na pegada interna fechada, com as palmas voltadas para a frente (levemente inclinadas pela curva da barra) e os cotovelos próximos ao tronco. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos contraindo o bíceps enquanto expira. Dica: apenas os antebraços devem se mover.","Continue até contrair totalmente o bíceps com a barra na altura dos ombros e segure por um segundo apertando bem.","Comece lentamente a abaixar a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Close-Grip_Front_Lat_Pulldown":{"name":"Puxada Frontal Pegada Fechada","instructions":["Sente-se no aparelho de puxada alta com a barra acoplada na polia superior e ajuste o apoio de joelhos à sua altura para impedir que seu corpo seja levantado pela carga.","Segure a barra com as palmas voltadas para a frente usando pegada fechada (mãos mais próximas que a largura dos ombros).","Com os braços estendidos acima segurando a barra, incline o tronco cerca de 30 graus para trás formando leve curvatura lombar e abrindo o peito. Esta é a sua posição inicial.","Ao expirar, puxe a barra para baixo até tocar a parte superior do peito levando os ombros e cotovelos para baixo e para trás. Dica: contraia bem as costas no final e mantenha o tronco imóvel; use os antebraços apenas para segurar a barra.","Após segurar um segundo apertando as escápulas, eleve lentamente a barra de volta à posição inicial com os braços estendidos e dorsais alongadas enquanto inspira.","Repita esse movimento pela quantidade prescrita de repetições."]},
"Close-Grip_Push-Up_off_of_a_Dumbbell":{"name":"Flexão de Braço Fechada sobre Halter","instructions":["Posicione-se no chão apoiando as duas mãos sobre um halter na vertical, sustentando o peso nas pontas dos pés e mãos com tronco firme, cotovelos fechados e braços estendidos. Esta será a sua posição inicial.","Abaixe o corpo flexionando os cotovelos enquanto inspira, mantendo o corpo reto sem deixar o quadril subir ou cair.","Empurre-se de volta à posição inicial estendendo os cotovelos enquanto expira.","Após uma pausa no topo, repita o movimento pela quantidade prescrita de repetições."]},
"Close-Grip_Standing_Barbell_Curl":{"name":"Rosca Direta em Pé com Barra - Pegada Fechada","instructions":["Segure uma barra com as duas mãos, palmas para cima e afastadas poucos centímetros entre si.","Fique em pé com o tronco reto, cabeça erguida, pés na largura dos ombros e cotovelos próximos ao corpo. Esta será a sua posição inicial. Dica: mantenha braços e cotovelos imóveis durante todo o exercício.","Eleve a barra em movimento semicircular até os antebraços tocarem o bíceps enquanto expira e contraia forte por um segundo no topo. Dica: evite balançar o tronco; apenas os antebraços se movem.","Desça lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Cocoons":{"name":"Abdominal Casulo (Cocoons)","instructions":["Deite-se de costas no chão com as pernas estendidas e os braços estendidos atrás da cabeça. Esta será a sua posição inicial.","Traga os joelhos em direção ao peito girando a pelve para tirar os glúteos do chão, enquanto flexiona a coluna e traz os braços por cima da cabeça em um movimento simultâneo de abdominal.","Após uma breve pausa, retorne à posição inicial."]},
"Conans_Wheel":{"name":"Roda de Conan (Conan's Wheel)","instructions":["Com o peso carregado, segure a extremidade do implemento na pegada Zercher, apoiando a barra na dobra dos cotovelos e segurando um punho com o outro, evitando apoiar nos antebraços.","Retire o peso do suporte mantendo postura ereta e firme e comece a caminhar em passos curtos e rápidos, olhando para cima e para a frente enquanto gira em círculo sem prender a respiração até completar uma ou mais voltas."]},
"Concentration_Curls":{"name":"Rosca Concentrada","instructions":["Sente-se em um banco reto com um halter no chão entre as pernas, mantendo os joelhos afastados e os pés apoiados no solo.","Pegue o halter com o braço direito e apoie a parte posterior do braço na face interna da coxa direita. Gire a palma da mão para a frente, afastando-a da coxa. Dica: o braço deve ficar estendido com o halter suspenso acima do chão. Esta será a sua posição inicial.","Mantendo o braço imóvel, flexione o cotovelo levando o halter para cima enquanto contrai o bíceps e expira; apenas o antebraço deve se mover. Suba até contrair totalmente o bíceps na altura do ombro. Dica: no topo, mantenha o dedo mínimo mais alto que o polegar e segure a contração por um segundo.","Comece lentamente a abaixar o halter de volta à posição inicial enquanto inspira. Cuidado: evite balançar o corpo em qualquer momento.","Repita pela quantidade recomendada de repetições e depois execute com o braço esquerdo."]},
"Cross-Body_Crunch":{"name":"Abdominal Cruzado","instructions":["Deite-se de costas e flexione os joelhos em cerca de 60 graus.","Mantenha os pés apoiados no chão e coloque as mãos levemente atrás da cabeça. Esta será a sua posição inicial.","Suba o tronco levando o cotovelo e o ombro direito em direção ao joelho esquerdo enquanto traz o joelho esquerdo em direção ao ombro esquerdo. Expire ao executar o movimento. Dica: concentre-se em elevar o ombro contraindo o abdômen, e não apenas em mover o cotovelo.","Retorne à posição inicial enquanto inspira e repita com o cotovelo esquerdo e o joelho direito.","Continue alternando dessa forma até completar todas as repetições prescritas."]},
"Cross_Body_Hammer_Curl":{"name":"Rosca Martelo Cruzada","instructions":["Fique em pé com o tronco ereto segurando um halter em cada mão ao lado do corpo, com as palmas voltadas para dentro.","Mantendo as palmas voltadas para dentro sem girar o antebraço, eleve o halter do braço direito cruzando à frente do corpo em direção ao ombro esquerdo enquanto expira. Encoste o topo do halter próximo ao ombro e segure a contração por um segundo.","Abaixe lentamente o halter pelo mesmo trajeto enquanto inspira e repita com o braço esquerdo.","Continue alternando dessa maneira até completar a quantidade recomendada para cada braço."]},
"Cross_Over_-_With_Bands":{"name":"Crossover com Elástico","instructions":["Prenda um elástico ao redor de um poste fixo.","De costas para o poste, segure as alças nas extremidades do elástico e dê passos à frente até criar tensão.","Abra os braços para os lados, paralelos ao chão e perpendiculares ao tronco (formando a letra \"T\"), com as palmas para a frente e leve flexão nos cotovelos. Esta será a sua posição inicial.","Mantendo os braços estendidos, traga-os em semicírculo à frente do peito enquanto expira e contrai o peitoral. Segure a contração por um segundo.","Retorne lentamente à posição inicial enquanto inspira.","Execute pela quantidade recomendada de repetições."]},
"Crossover_Reverse_Lunge":{"name":"Avanço Reverso Cruzado","instructions":["Fique em pé com os pés na largura dos ombros. Esta será a sua posição inicial.","Execute um afundo para trás dando um passo atrás com um pé e flexionando quadril e joelho da frente enquanto gira o tronco em direção à perna da frente.","Após uma breve pausa, retorne à posição inicial e repita do outro lado, alternando continuamente."]},
"Crucifix":{"name":"Crucifixo Isométrico (Crucifix)","instructions":["Neste exercício você sustenta cargas lateralmente por tempo; embora possa ser treinado com halteres, é comum praticar com implementos de strongman como machados ou martelos.","Em pé, eleve os braços lateralmente segurando os implementos paralelos ao chão e mantenha a posição o máximo de tempo possível (normalmente escolhe-se um peso que leve à falha entre 30 e 60 segundos)."]},
"Crunch_-_Hands_Overhead":{"name":"Abdominal com Braços Estendidos Acima da Cabeça","instructions":["Deite-se de costas no chão com os joelhos flexionados formando cerca de 60 graus entre posteriores de coxa e panturrilhas.","Mantenha os pés apoiados no chão e estenda os braços atrás da cabeça com as mãos sobrepostas. Esta será a sua posição inicial.","Flexione a parte superior do tronco para a frente desencostando apenas as escápulas do chão, mantendo os braços sempre alinhados à cabeça, pescoço e ombros. Expire durante a subida e segure a contração por um segundo.","Desça lentamente até a posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Crunch_-_Legs_On_Exercise_Ball":{"name":"Abdominal com Pernas na Bola Suíça","instructions":["Deite-se de costas com os pés apoiados sobre uma bola suíça e os joelhos flexionados em um ângulo de 90 graus.","Afaste os pés cerca de 3 a 4 polegadas e aponte os dedões para dentro até se tocarem.","Apoie as mãos levemente ao lado da cabeça mantendo os cotovelos fechados. Dica: não entrelace os dedos atrás da cabeça.","Pressione a lombar contra o chão para isolar melhor o abdômen. Esta será a sua posição inicial.","Eleve os ombros cerca de quatro polegadas do chão mantendo a lombar pressionada contra o solo enquanto expira. Contraia forte o abdômen no topo por um segundo, sem usar impulso.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Crunches":{"name":"Abdominal Supra (Crunch)","instructions":["Deite-se de costas com os pés apoiados no chão ou sobre um banco com os joelhos flexionados a 90 graus.","Apoie as mãos levemente ao lado da cabeça mantendo os cotovelos abertos sem puxar o pescoço. Dica: não entrelace os dedos atrás da cabeça.","Pressionando a lombar contra o chão para isolar melhor o abdômen, comece a desencostar os ombros do solo.","Continue pressionando a lombar contra o chão enquanto contrai o abdômen e expira, elevando os ombros cerca de quatro polegadas. Segure a contração no topo por um segundo sem usar impulso.","Após a contração de um segundo, desça lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Cuban_Press":{"name":"Desenvolvimento Cubano","instructions":["Em pé, segure um halter em cada mão com pegada pronada e eleve os braços até ficarem paralelos ao chão com os antebraços pendurados (posição de espantalho). Esta será a sua posição inicial.","Inicie girando externamente os ombros mantendo os braços na mesma altura até os punhos ficarem diretamente acima dos cotovelos e os antebraços perpendiculares ao chão.","Agora empurre os halteres acima da cabeça estendendo os cotovelos.","Retorne à posição inicial enquanto inspira invertendo todas as etapas.","Repita pela quantidade recomendada de repetições."]},
"Dancers_Stretch":{"name":"Alongamento do Dançarino","instructions":["Sente-se no chão.","Cruze a perna direita sobre a esquerda mantendo o joelho direito flexionado e a perna esquerda estendida no chão.","Apoie o braço esquerdo na perna direita e a mão direita no chão.","Gire o tronco para a direita e segure por 10-20 segundos. Troque de lado."]},
"Dead_Bug":{"name":"Inseto Morto (Dead Bug)","instructions":["Deite-se de costas com os braços estendidos acima do peito em direção ao teto.","Eleve pés, joelhos e quadril formando um ângulo de 90 graus.","Expire forte para baixar as costelas e pressionar a lombar contra o chão, girando a pelve para cima e contraindo os glúteos. Mantenha essa posição durante todo o exercício. Esta será a sua posição inicial.","Inicie estendendo uma perna, alinhando joelho e quadril até levá-la próxima ao chão sem tocar.","Mantenha a lombar colada no chão e a pelve estável, evitando que as costas arqueiem.","Mantenha o core firme e retorne a perna à posição inicial.","Repita com o lado oposto, alternando até completar a série."]},
"Deadlift_with_Bands":{"name":"Levantamento Terra com Elásticos","instructions":["Para fazer levantamento terra com elásticos curtos, passe-os pela barra e pise sobre eles para montar. Para elásticos longos, fixe-os em uma base segura como halteres pesados ou o rack.","Com pés e pegada ajustados, inspire fundo, abaixe o quadril e flexione os joelhos até as canelas tocarem a barra. Olhe para a frente, mantenha o peito aberto e empurre pelos calcanhares; ao passar dos joelhos, aproxime as escápulas e projete o quadril contra a barra.","Abaixe a barra flexionando o quadril e guiando-a até o chão."]},
"Deadlift_with_Chains":{"name":"Levantamento Terra com Correntes","instructions":["Prenda as correntes nas pontas da barra ou passe o meio delas diretamente sobre a barra para aumentar progressivamente a carga na subida.","Aproxime-se da barra centralizada sobre os pés (largura do quadril), flexione o quadril para segurar a barra na largura dos ombros com pegada pronada ou mista, inspire fundo e abaixe o quadril até as canelas tocarem a barra.","Olhe para a frente, mantenha peito aberto e costas firmes e empurre o chão pelos calcanhares; ao passar dos joelhos, puxe os ombros para trás e projete o quadril contra a barra.","Abaixe a barra flexionando o quadril e guiando-a de volta ao chão."]},
"Decline_Barbell_Bench_Press":{"name":"Supino Declinado com Barra","instructions":["Prenda as pernas no apoio do banco declinado e deite-se lentamente.","Usando pegada média (formando 90 graus entre antebraço e braço no meio do movimento), retire a barra do suporte e segure-a perpendicular ao chão com os braços estendidos. Esta será a posição inicial. Dica: peça auxílio a um parceiro para tirar a barra com segurança.","Enquanto inspira, desça a barra lentamente até sentir tocar a parte inferior do peito.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando o peitoral. Estenda os braços, aperte o peito por um segundo e desça lentamente novamente. Dica: a descida deve durar pelo menos o dobro da subida.","Repita o movimento pela quantidade prescrita de repetições.","Ao terminar, recoloque a barra no suporte."]},
"Decline_Close-Grip_Bench_To_Skull_Crusher":{"name":"Supino Declinado Fechado com Tríceps Testa","instructions":["Prenda as pernas no apoio do banco declinado e deite-se lentamente.","Com pegada fechada (ligeiramente menor que a largura dos ombros), retire a barra do suporte e segure-a acima de você com braços estendidos e cotovelos fechados. Esta será a posição inicial. Dica: peça ajuda a um parceiro para retirar a barra.","Abaixe a barra até a parte inferior do peito enquanto inspira, mantendo os cotovelos próximos ao corpo.","Usando o tríceps, empurre a barra de volta à posição inicial enquanto expira.","Mantendo a parte superior dos braços imóvel, inspire e desça a barra em semicírculo flexionando apenas os cotovelos até tocar levemente a testa.","Eleve a barra de volta à posição inicial contraindo o tríceps e expirando.","Repita os passos 3 a 6 até completar a quantidade recomendada de repetições."]},
"Decline_Crunch":{"name":"Abdominal no Banco Declinado","instructions":["Prenda as pernas na extremidade do banco declinado e deite-se.","Coloque as mãos levemente ao lado da cabeça mantendo os cotovelos fechados. Dica: não entrelace os dedos atrás da cabeça.","Pressionando a lombar contra o banco para isolar o abdômen, comece a desencostar os ombros do apoio.","Continue pressionando a lombar enquanto contrai o abdômen e expira, subindo os ombros cerca de quatro polegadas. Segure a contração por um segundo sem usar impulso.","Após a contração de um segundo, desça lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Decline_Dumbbell_Bench_Press":{"name":"Supino Declinado com Halteres","instructions":["Prenda as pernas no banco declinado e deite-se segurando um halter em cada mão apoiados sobre as coxas, com as palmas voltadas uma para a outra.","Já deitado, posicione os halteres à frente do peito na largura dos ombros.","Gire os punhos para que as palmas fiquem voltadas para a frente. Esta será a sua posição inicial.","Desça os halteres lentamente lateralmente mantendo controle total. Dica: os antebraços devem ficar sempre perpendiculares ao chão.","Ao expirar, empurre os halteres para cima usando o peitoral, estenda os braços, aperte o peito por um segundo e desça devagar. Dica: a descida deve levar pelo menos o dobro do tempo da subida.","Repita o movimento pela quantidade prescrita de repetições."]},
"Decline_Dumbbell_Flyes":{"name":"Crucifixo Declinado com Halteres","instructions":["Prenda as pernas no banco declinado e deite-se segurando um halter em cada mão apoiados nas coxas, com as palmas voltadas uma para a outra.","Posicione os halteres acima do peito na largura dos ombros com as palmas frente a frente e os braços estendidos perpendiculares ao chão. Esta será a sua posição inicial.","Com uma leve flexão nos cotovelos para proteger os tendões, abra os braços lateralmente em um arco amplo até sentir alongar o peitoral enquanto inspira. Dica: o ângulo dos cotovelos permanece fixo; o movimento ocorre apenas nos ombros.","Retorne os braços à posição inicial contraindo o peitoral pelo mesmo arco enquanto expira.","Segure por um segundo na contração e repita pela quantidade prescrita de repetições."]},
"Decline_Dumbbell_Triceps_Extension":{"name":"Tríceps Testa Declinado com Halteres","instructions":["Prenda as pernas no banco declinado e deite-se segurando um halter em cada mão sobre as coxas com as palmas voltadas uma para a outra.","Posicione os halteres acima do peito na largura dos ombros com as palmas frente a frente e braços estendidos perpendiculares ao chão. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel e os cotovelos fechados, desça os halteres lentamente flexionando os cotovelos em semicírculo até os polegares ficarem ao lado das orelhas enquanto inspira.","Eleve os halteres de volta à posição inicial contraindo o tríceps e expirando.","Repita pela quantidade recomendada de repetições."]},
"Decline_EZ_Bar_Triceps_Extension":{"name":"Tríceps Testa Declinado com Barra W","instructions":["Prenda as pernas no banco declinado e deite-se lentamente.","Com pegada fechada (ligeiramente menor que a largura dos ombros), retire a barra W do suporte e segure-a acima de você com braços estendidos e cotovelos fechados. Esta será a posição inicial. Dica: peça ajuda a um parceiro para retirar a barra.","Mantendo a parte superior dos braços imóvel, desça a barra lentamente flexionando os cotovelos em semicírculo até tocar levemente a testa enquanto inspira.","Eleve a barra de volta à posição inicial contraindo o tríceps e expirando.","Repita até completar a quantidade recomendada de repetições."]},
"Decline_Oblique_Crunch":{"name":"Abdominal Oblíquo no Banco Declinado","instructions":["Prenda as pernas no banco declinado e deite-se lentamente.","Eleve o tronco até formar um ângulo de cerca de 35-45 graus em relação ao chão.","Coloque uma mão ao lado da cabeça e a outra sobre a coxa. Esta será a sua posição inicial.","Suba lentamente o tronco girando-o para a esquerda enquanto expira até o cotovelo direito tocar o joelho esquerdo, segurando a contração por um segundo. Dica: mantenha o abdômen contraído e o movimento controlado.","Retorne lentamente à posição inicial enquanto inspira.","Após completar a série para o lado direito, repita para o lado esquerdo focando na rotação e contração dos oblíquos."]},
"Decline_Push-Up":{"name":"Flexão de Braço Declinada","instructions":["Deite-se de bruços no chão com as mãos afastadas cerca de 36 polegadas sustentando o tronco e apoie os pés sobre um banco ou caixa. Esta será a sua posição inicial.","Desça o corpo até o peito quase tocar o chão enquanto inspira.","Expire e empurre o corpo de volta à posição inicial contraindo o peitoral.","Após uma breve pausa no topo, desça novamente repetindo quantas vezes forem necessárias."]},
"Decline_Reverse_Crunch":{"name":"Abdominal Reverso no Banco Declinado","instructions":["Deite-se de costas em um banco declinado e segure firmemente a parte superior do banco com as duas mãos para não escorregar.","Mantenha as pernas paralelas ao chão usando o abdômen, com joelhos e pés juntos e leve flexão nos joelhos. Esta será a sua posição inicial.","Ao expirar, traga as pernas em direção ao tronco girando a pelve para trás e tirando o quadril do banco até os joelhos quase encostarem no peito.","Segure a contração por um segundo e retorne as pernas à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Decline_Smith_Press":{"name":"Supino Declinado no Smith","instructions":["Posicione um banco declinado sob a máquina Smith em altura alcançável com os braços quase totalmente estendidos. Com pegada pronada mais larga que os ombros, destrave a barra e segure-a acima de você. Esta será a sua posição inicial.","Enquanto inspira, desça a barra sob controle flexionando os cotovelos até tocar levemente a parte inferior do peito.","Após uma breve pausa, empurre a barra de volta à posição inicial estendendo os cotovelos enquanto expira.","Repita o movimento pela quantidade prescrita de repetições.","Ao concluir a série, trave a barra de volta no suporte."]},
"Deficit_Deadlift":{"name":"Levantamento Terra em Déficit","instructions":["Suba sobre uma plataforma ou anilhas de 1 a 3 polegadas de altura. Aproxime-se da barra centralizada sobre os pés (largura do quadril), flexione o quadril e segure a barra na largura dos ombros com pegada pronada ou mista.","Com pés e pegada ajustados, inspire fundo, abaixe o quadril até as canelas tocarem a barra, mantenha peito aberto e empurre pelos calcanhares; ao passar dos joelhos, aproxime as escápulas e projete o quadril contra a barra.","Abaixe a barra flexionando o quadril e guiando-a de volta até o chão."]},
"Depth_Jump_Leap":{"name":"Salto em Profundidade com Impulso (Depth Jump Leap)","instructions":["Para este exercício você precisará de duas caixas ou bancos, um com 12 a 16 polegadas de altura e outro com 22 a 26 polegadas.","Suba na caixa mais baixa com os pés juntos próximos à borda e braços ao lado do corpo, posicionando a caixa mais alta 2 a 3 pés à sua frente.","Desça da primeira caixa caindo com os dois pés simultaneamente.","Rebata imediatamente impulsionando para cima e para a frente com os braços e estendendo o corpo para saltar sobre a caixa mais alta, amortecendo a aterrissagem com as pernas."]},
"Dip_Machine":{"name":"Máquina de Mergulho (Tríceps Máquina)","instructions":["Sente-se firmemente na máquina de mergulho, selecione o peso e segure as alças.","Mantenha os cotovelos fechados junto ao corpo para enfatizar o tríceps, com os cotovelos dobrados a 90 graus.","Contraindo o tríceps, estenda os braços para baixo enquanto expira. Dica: no ponto mais baixo, mantenha uma leve flexão para preservar a tensão no tríceps.","Deixe os braços retornarem lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Dips_-_Chest_Version":{"name":"Mergulho nas Paralelas - Foco em Peito","instructions":["Nas barras paralelas, sustente o corpo com os braços estendidos acima dos apoios.","Enquanto inspira, desça lentamente inclinando o tronco cerca de 30 graus para a frente e abrindo levemente os cotovelos até sentir um leve alongamento no peitoral.","Use o peitoral para empurrar o corpo de volta à posição inicial enquanto expira, contraindo o peito por um segundo no topo.","Repita o movimento pela quantidade prescrita de repetições."]},
"Dips_-_Triceps_Version":{"name":"Mergulho nas Paralelas - Foco em Tríceps","instructions":["Sustente o corpo nas barras paralelas com os braços quase totalmente estendidos.","Inspire e desça lentamente mantendo o tronco ereto e os cotovelos próximos ao corpo para focar no tríceps, até formar um ângulo de 90 graus entre braço e antebraço.","Expire e empurre o tronco de volta para cima usando o tríceps até retornar à posição inicial.","Repita o movimento pela quantidade prescrita de repetições."]},
"Donkey_Calf_Raises":{"name":"Elevação de Panturrilha Burrinho (Donkey Calf Raise)","instructions":["Na máquina de panturrilha burrinho, posicione a lombar e o quadril sob o apoio acolchoado, encostando a região do cóccix na almofada.","Apoie os braços nos suportes laterais e coloque a ponta dos pés no bloco com os calcanhares livres, mantendo os joelhos estendidos sem travar. Esta será a sua posição inicial.","Eleve os calcanhares o máximo possível enquanto expira contraindo as panturrilhas, mantendo os joelhos imóveis o tempo todo, e segure no topo por um segundo.","Retorne lentamente à posição inicial enquanto inspira, abaixando os calcanhares até alongar as panturrilhas.","Repita pela quantidade recomendada de repetições."]},
"Double_Kettlebell_Alternating_Hang_Clean":{"name":"Hang Clean Alternado com Dois Kettlebells","instructions":["Coloque dois kettlebells entre os pés, empurre o quadril para trás e olhe para a frente para entrar na posição inicial.","Faça um clean com um kettlebell até o ombro enquanto segura o outro.","Com movimento fluido, abaixe o kettlebell de cima enquanto impulsiona o de baixo para cima."]},
"Double_Kettlebell_Jerk":{"name":"Jerk com Dois Kettlebells","instructions":["Segure um kettlebell pela alça em cada mão.","Faça o clean dos kettlebells até os ombros estendendo pernas e quadril enquanto gira os punhos com as palmas para a frente. Esta será a sua posição inicial.","Flexione levemente os joelhos mantendo o tronco ereto.","Inverta imediatamente a direção impulsionando pelos calcanhares para gerar velocidade.","Ao mesmo tempo, empurre os kettlebells acima da cabeça até travar os braços aproveitando o impulso do corpo.","Receba os pesos em base dividida (um pé à frente e outro atrás).","Mantendo os pesos acima da cabeça, junte os pés em pé e depois abaixe os kettlebells para a próxima repetição."]},
"Double_Kettlebell_Push_Press":{"name":"Push Press com Dois Kettlebells","instructions":["Faça o clean de dois kettlebells até os ombros.","Agache alguns centímetros e inverta o movimento rapidamente, usando o impulso das pernas para empurrar os kettlebells acima da cabeça.","Com os braços estendidos acima da cabeça, abaixe os kettlebells de volta aos ombros e repita."]},
"Double_Kettlebell_Snatch":{"name":"Snatch (Arranque) com Dois Kettlebells","instructions":["Posicione dois kettlebells atrás dos pés, flexione os joelhos e jogue o quadril para trás para segurá-los.","Balance os kettlebells com força entre as pernas e inverta o sentido.","Impulsione com o quadril e estenda ambos os braços travando os kettlebells acima da cabeça em um movimento contínuo."]},
"Double_Kettlebell_Windmill":{"name":"Moinho com Dois Kettlebells","instructions":["Coloque um kettlebell à frente do pé dianteiro e faça um clean e desenvolvimento acima da cabeça com o outro kettlebell no braço oposto.","Mantendo o braço elevado sempre estendido, empurre o quadril para o lado do kettlebell acima da cabeça e gire os pés a 45 graus para o lado oposto.","Incline-se lateralmente pelo quadril até alcançar e segurar o kettlebell do chão, mantendo os olhos fixos no kettlebell acima da cabeça.","Pause por um segundo ao pegar o kettlebell do chão e inverta o movimento até retornar à posição inicial."]},
"Double_Leg_Butt_Kick":{"name":"Salto com Calcanhares nos Glúteos","instructions":["Comece em pé com os joelhos levemente flexionados.","Agache rapidamente uma pequena amplitude e salte imediatamente buscando máxima altura vertical.","No ar, flexione os joelhos tentando tocar os calcanhares nos glúteos.","Aterrisse com os joelhos levemente flexionados, amortecendo o impacto com as pernas."]},
"Downward_Facing_Balance":{"name":"Equilíbrio Prono na Bola Suíça","instructions":["Deite-se de bruços em cima de uma bola suíça.","Apoiando o abdômen na bola, caminhe com as mãos para a frente no chão e eleve as pernas estendendo cotovelos e joelhos."]},
"Drag_Curl":{"name":"Rosca Drag com Barra (Drag Curl)","instructions":["Segure uma barra com pegada supinada (palmas para a frente) levando os cotovelos para junto e atrás do tronco. Esta será a sua posição inicial.","Ao expirar, eleve a barra mantendo os cotovelos para trás e \"arrastando\" a barra em contato contínuo com o tronco. Dica: não levante os ombros.","Desça lentamente de volta à posição inicial mantendo a barra sempre em contato com o tronco.","Repita pela quantidade recomendada de repetições."]},
"Drop_Push":{"name":"Flexão com Queda entre Caixas (Drop Push)","instructions":["Posicione duas caixas baixas ou plataformas afastadas de 2 a 3 pés entre si.","Entre em posição de flexão de braço entre elas apoiando as mãos sobre as caixas.","Mantendo a postura firme, impulsione-se para cima e caia com as mãos no chão na largura dos ombros entre as caixas, amortecendo o impacto pelos braços."]},
"Dumbbell_Alternate_Bicep_Curl":{"name":"Rosca Alternada com Halteres","instructions":["Fique em pé com o tronco ereto segurando um halter em cada mão com os braços estendidos, cotovelos próximos ao corpo e palmas voltadas para as coxas.","Mantendo o braço imóvel, flexione o braço direito girando a palma para a frente e contraindo o bíceps enquanto expira até chegar à altura do ombro. Segure por um segundo apertando o bíceps. Dica: apenas os antebraços se movem.","Desça lentamente o halter à posição inicial enquanto inspira, girando a palma de volta para a coxa.","Repita o movimento com a mão esquerda. Isso equivale a uma repetição.","Continue alternando dessa forma pela quantidade recomendada de repetições."]},
"Dumbbell_Bench_Press":{"name":"Supino Reto com Halteres","instructions":["Deite-se em um banco reto com um halter em cada mão apoiados nas coxas e palmas voltadas uma para a outra.","Use as coxas para impulsionar os halteres um de cada vez e segure-os à frente do peito na largura dos ombros.","Gire os punhos para que as palmas fiquem voltadas para a frente, com os halteres ao lado do peito formando 90 graus entre braços e antebraços. Esta será a sua posição inicial.","Ao expirar, empurre os halteres para cima usando o peitoral até estender os braços, aperte o peito por um segundo e desça lentamente. Dica: a descida deve durar cerca do dobro do tempo da subida.","Repita o movimento pela quantidade prescrita de repetições."]},
"Dumbbell_Bench_Press_with_Neutral_Grip":{"name":"Supino Reto com Halteres - Pegada Neutra","instructions":["Segure um halter em cada mão e deite-se em um banco reto com os pés firmes no chão e as escápulas retraídas.","Mantendo a pegada neutra (palmas voltadas uma para a outra), comece com os braços estendidos diretamente acima do peito. Esta será a sua posição inicial.","Inicie flexionando os cotovelos e abaixando os braços junto ao tronco até os halteres chegarem ao nível do peito.","Pause brevemente e estenda os cotovelos retornando à posição inicial."]},
"Dumbbell_Bicep_Curl":{"name":"Rosca Direta com Halteres","instructions":["Fique em pé com um halter em cada mão com os braços estendidos, cotovelos próximos ao tronco e palmas voltadas para a frente. Esta será a sua posição inicial.","Mantendo os braços imóveis, expire e flexione os cotovelos contraindo o bíceps até os halteres chegarem à altura dos ombros, segurando brevemente a contração no topo.","Inspire e abaixe lentamente os halteres de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Clean":{"name":"Clean com Halteres","instructions":["Comece em pé com um halter em cada mão e os pés na largura dos ombros.","Abaixe os halteres até o chão flexionando quadril e joelhos e jogando o quadril para trás. Esta será a sua posição inicial.","Inicie saltando vigorosamente para cima estendendo quadril, joelhos e tornozelos para acelerar os halteres com pegada neutra e braços estendidos até a extensão total.","Após a extensão total, flexione novamente quadril e joelhos entrando em agachamento enquanto dobra os braços para receber os halteres nos ombros.","Ao receber os halteres no agachamento, estenda quadril e joelhos até ficar em pé com os pesos apoiados nos ombros."]},
"Dumbbell_Floor_Press":{"name":"Supino no Chão com Halteres","instructions":["Deite-se de costas no chão segurando os halteres acima do peito com os braços estendidos (os joelhos podem ficar flexionados).","Abaixe os halteres até a parte superior dos braços encostar no chão; feche os cotovelos para focar no tríceps ou abra o ângulo para enfatizar o peitoral.","Pause em baixo e empurre os halteres de volta para cima estendendo os cotovelos."]},
"Dumbbell_Flyes":{"name":"Crucifixo Reto com Halteres","instructions":["Deite-se em um banco reto com um halter em cada mão apoiados nas coxas e palmas voltadas uma para a outra.","Use as coxas para erguer os halteres até segurá-los acima do peito com as palmas frente a frente e braços quase estendidos (sem travar os cotovelos). Esta será a sua posição inicial.","Com leve flexão nos cotovelos, abra os braços lateralmente em arco amplo até sentir alongar o peitoral enquanto inspira. Dica: o ângulo dos cotovelos permanece fixo; o movimento ocorre apenas nos ombros.","Retorne os braços à posição inicial contraindo o peitoral pelo mesmo arco enquanto expira.","Segure por um segundo na contração e repita pela quantidade prescrita de repetições."]},
"Dumbbell_Incline_Row":{"name":"Remada no Banco Inclinado com Halteres","instructions":["Deite-se de bruços apoiado em um banco inclinado.","Segure um halter em cada mão com pegada neutra e braços estendidos para baixo. Esta será a sua posição inicial.","Retraia as escápulas e flexione os cotovelos puxando os halteres ao lado do corpo.","Pause no topo do movimento e retorne à posição inicial."]},
"Dumbbell_Incline_Shoulder_Raise":{"name":"Elevação de Ombros Inclinado com Halteres","instructions":["Sente-se em um banco inclinado segurando um halter em cada mão apoiados sobre as coxas.","Impulsione os halteres com as coxas, deite-se no banco e estenda os braços verticalmente acima dos ombros com as palmas para a frente. Esta será a sua posição inicial.","Mantendo os braços retos e travados, empurre os halteres para cima desencostando os ombros do banco enquanto expira.","Retorne os ombros ao banco voltando à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Lunges":{"name":"Avanço com Halteres","instructions":["Fique em pé com o tronco ereto segurando dois halteres ao lado do corpo. Esta será a sua posição inicial.","Dê um passo à frente com a perna direita cerca de 2 pés à frente do pé de apoio e abaixe o corpo mantendo o tronco ereto enquanto inspira. Observação: não deixe o joelho ultrapassar a ponta do pé e mantenha a canela da frente perpendicular ao chão.","Empurrando principalmente pelo calcanhar do pé da frente, suba de volta à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições e depois execute com a perna esquerda."]},
"Dumbbell_Lying_One-Arm_Rear_Lateral_Raise":{"name":"Crucifixo Inverso Unilateral Deitado com Halter","instructions":["Segurando um halter em uma mão, deite-se de bruços em um banco levemente inclinado (cerca de 15 graus), usando a outra mão para se segurar na perna do banco.","Mantenha a palma voltada para o tronco com o braço estendido e leve flexão no cotovelo. Esta será a sua posição inicial.","Eleve o braço com o halter lateralmente até o cotovelo atingir a altura do ombro e o braço ficar paralelo ao chão enquanto expira, segurando um segundo no topo.","Abaixe lentamente o halter à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Lying_Pronation":{"name":"Rotação Externa Pronada Deitado com Halter","instructions":["Deite-se de bruços em um banco reto segurando um halter com uma mão e apoiando a testa sobre a outra mão dobrada no banco.","Flexione o cotovelo do braço com o halter formando um ângulo de 90 graus entre braço e antebraço.","Eleve o braço para o lado de modo que fique paralelo ao chão e perpendicular ao tronco, com o antebraço apontando para baixo. Esta será a sua posição inicial.","Ao expirar, faça rotação externa do ombro levando o antebraço para a frente mantendo os 90 graus até ficar paralelo ao chão e segure por um segundo.","Ao inspirar, retorne lentamente à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Lying_Rear_Lateral_Raise":{"name":"Crucifixo Inverso Deitado com Halteres","instructions":["Segurando um halter em cada mão, deite-se de bruços em um banco levemente inclinado (cerca de 15 graus).","Mantenha as palmas voltadas para o corpo com os braços estendidos e leve flexão nos cotovelos. Esta será a sua posição inicial.","Eleve os braços lateralmente até os cotovelos atingirem a altura dos ombros e os braços ficarem paralelos ao chão enquanto expira, segurando um segundo no topo.","Abaixe lentamente os halteres à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Lying_Supination":{"name":"Rotação Externa Lateral Deitado com Halter","instructions":["Deite-se de lado em um banco reto segurando um halter no braço de cima e apoiando a cabeça na outra mão dobrada sobre o banco.","Flexione o cotovelo do braço com o halter formando um ângulo de 90 graus entre braço e antebraço.","Mantenha o braço paralelo e colado à lateral do tronco com o antebraço apontando diretamente à frente paralelo ao chão. Esta será a sua posição inicial.","Ao expirar, faça rotação externa elevando o halter em semicírculo mantendo os 90 graus até o antebraço apontar para o teto e segure por um segundo.","Ao inspirar, retorne lentamente à posição inicial.","Repita pela quantidade recomendada de repetições e depois troque de braço."]},
"Dumbbell_One-Arm_Shoulder_Press":{"name":"Desenvolvimento Unilateral com Halter","instructions":["Segure um halter e sente-se em um banco com encosto (ou fique em pé), apoiando o halter sobre a coxa se estiver sentado.","Leve o halter até a altura do ombro; mantenha a outra mão na cintura, estendida ao lado ou apoiada em uma superfície fixa.","Gire o punho para que a palma fique voltada para a frente. Esta é a sua posição inicial.","Ao expirar, empurre o halter para cima até estender totalmente o braço.","Após uma pausa de um segundo, desça lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições e depois troque de braço."]},
"Dumbbell_One-Arm_Triceps_Extension":{"name":"Tríceps Francês Unilateral com Halter","instructions":["Segure um halter e sente-se em um banco com encosto ou fique em pé.","Leve o halter ao ombro e estenda o braço acima da cabeça, mantendo-o perpendicular ao chão e próximo à cabeça; a outra mão pode apoiar o braço ativo ou ficar na cintura.","Gire o punho de modo que a palma fique para a frente e o dedo mínimo voltado para o teto. Esta será a sua posição inicial.","Abaixe lentamente o halter atrás da cabeça mantendo a parte superior do braço imóvel enquanto inspira, pausando quando o tríceps estiver totalmente alongado.","Retorne à posição inicial contraindo o tríceps enquanto expira. Dica: apenas o antebraço deve se mover.","Repita pela quantidade recomendada de repetições e troque de braço."]},
"Dumbbell_One-Arm_Upright_Row":{"name":"Remada Alta Unilateral com Halter","instructions":["Segure um halter em pé com o braço estendido à frente da coxa, leve flexão no cotovelo, costas retas e palma voltada para a coxa.","Mantenha a outra mão estendida ao lado, na cintura ou apoiada em uma superfície fixa. Esta será a sua posição inicial.","Use o deltoide lateral para puxar o halter para cima rente ao corpo enquanto expira até quase atingir a linha do queixo. Dica: o cotovelo conduz o movimento sempre acima do antebraço; pause um segundo no topo.","Abaixe o halter lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições e troque de braço."]},
"Dumbbell_Prone_Incline_Curl":{"name":"Rosca Direta no Banco Inclinado de Bruços com Halteres","instructions":["Segure um halter em cada mão e deite-se de bruços em um banco inclinado com os ombros próximos ao topo do encosto e pernas apoiadas no assento ou ao lado.","Deixe os braços pendurados naturalmente perpendiculares ao chão.","Mantenha os cotovelos próximos ao corpo e gire as palmas para a frente. Esta será a sua posição inicial.","Eleve os halteres contraindo o bíceps até flexionar totalmente os braços enquanto expira, movendo apenas os antebraços.","Abaixe os halteres até estender totalmente os braços.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Raise":{"name":"Elevação Lateral com Halteres (Cotovelos Altos)","instructions":["Fique em pé segurando um halter em cada mão ao lado do corpo com leve flexão nos cotovelos, costas retas e palmas voltadas para trás. Esta será a sua posição inicial.","Use os deltoides laterais para elevar os halteres ao lado do corpo enquanto expira até quase a linha do queixo. Dica: os cotovelos conduzem o movimento acima dos antebraços; mantenha o tronco imóvel e pause um segundo no topo.","Abaixe os halteres lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Rear_Lunge":{"name":"Avanço Reverso com Halteres","instructions":["Fique em pé com o tronco ereto segurando dois halteres ao lado do corpo. Esta será a sua posição inicial.","Dê um passo para trás com a perna direita cerca de dois pés além do pé esquerdo e abaixe o corpo mantendo o tronco ereto enquanto inspira. Dica: mantenha a canela da frente perpendicular ao chão sem deixar o joelho passar dos dedos; passos longos enfatizam glúteos e curtos enfatizam quadríceps.","Impulsione para cima voltando à posição inicial enquanto expira, usando o calcanhar para focar glúteos ou a ponta do pé para focar quadríceps.","Agora repita com a perna oposta."]},
"Dumbbell_Scaption":{"name":"Elevação no Plano Escapular com Halteres (Scaption)","instructions":["Este exercício corretivo fortalece os estabilizadores da escápula. Segure um halter leve em cada mão ao lado do corpo com os polegares apontando para cima.","Inicie elevando os braços estendidos à frente, cerca de 30 graus abertos em relação ao centro.","Continue até os braços ficarem paralelos ao chão e depois retorne à posição inicial."]},
"Dumbbell_Seated_Box_Jump":{"name":"Salto na Caixa Sentado com Halter","instructions":["Posicione uma caixa alguns pés ao lado de um banco. Sente-se no banco de frente para a caixa segurando um halter junto ao peito com as duas mãos. Esta será a sua posição inicial.","Firme os pés no chão inclinando-se à frente e estendendo quadril e joelhos para saltar para cima e para a frente.","Aterrisse sobre a caixa com os dois pés, amortecendo o impacto flexionando quadril e joelhos.","Desça um passo de cada vez e retorne à posição inicial."]},
"Dumbbell_Seated_One-Leg_Calf_Raise":{"name":"Elevação de Panturrilha Unilateral Sentado com Halter","instructions":["Coloque um bloco no chão a cerca de 12 polegadas de um banco reto.","Sente-se no banco reto e apoie um halter sobre a coxa esquerda, cerca de 3 polegadas acima do joelho.","Apoie a ponta do pé esquerdo sobre o bloco. Esta será a sua posição inicial.","Suba na ponta do pé o mais alto possível enquanto expira e contrai a panturrilha, segurando por um segundo.","Retorne lentamente à posição inicial alongando o máximo possível para baixo.","Repita pela quantidade prescrita de repetições e depois execute com a perna direita."]},
"Dumbbell_Shoulder_Press":{"name":"Desenvolvimento de Ombros com Halteres","instructions":["Segurando um halter em cada mão, sente-se em um banco com encosto e apoie os halteres na vertical sobre as coxas.","Impulsione os halteres até a altura dos ombros um de cada vez com ajuda das coxas.","Gire os punhos para que as palmas fiquem voltadas para a frente. Esta é a sua posição inicial.","Expire e empurre os halteres para cima até quase se tocarem no topo.","Após uma breve pausa no topo, abaixe lentamente os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Shrug":{"name":"Encolhimento de Ombros com Halteres","instructions":["Fique ereto com um halter em cada mão (palmas voltadas para o corpo) e os braços estendidos ao lado.","Eleve os ombros o mais alto possível enquanto expira e segure a contração por um segundo no topo. Dica: mantenha os braços estendidos o tempo todo e não use o bíceps.","Abaixe os halteres de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Side_Bend":{"name":"Flexão Lateral do Tronco com Halter","instructions":["Fique em pé segurando um halter na mão esquerda (palma voltada para o corpo) e a mão direita na cintura, com os pés na largura dos ombros. Esta será a sua posição inicial.","Mantendo as costas retas e a cabeça erguida, incline apenas a cintura para a direita o máximo possível enquanto inspira, segure por um segundo e volte à posição inicial ao expirar. Dica: mantenha o resto do corpo imóvel.","Repita inclinando para a esquerda, segure um segundo e retorne à posição inicial.","Repita pela quantidade recomendada de repetições e depois troque o halter de mão."]},
"Dumbbell_Squat":{"name":"Agachamento com Halteres","instructions":["Fique em pé segurando um halter em cada mão ao lado das pernas (palmas voltadas para dentro).","Posicione os pés em abertura média na largura dos ombros com as pontas levemente para fora, mantendo cabeça erguida e costas retas. Esta será a sua posição inicial.","Abaixe lentamente o tronco flexionando os joelhos e mantendo a postura ereta até as coxas ficarem paralelas ao chão. Dica: evite projetar os joelhos além da ponta dos pés para não gerar estresse articular.","Comece a subir enquanto expira empurrando o chão principalmente pelos calcanhares até estender as pernas e voltar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Squat_To_A_Bench":{"name":"Agachamento com Halteres até o Banco","instructions":["Fique em pé com um banco reto atrás de você segurando um halter em cada mão ao lado das pernas.","Posicione os pés na largura dos ombros com as pontas levemente para fora, mantendo cabeça erguida e costas retas. Esta será a sua posição inicial.","Abaixe lentamente o tronco flexionando os joelhos com postura ereta até encostar levemente no banco atrás de você enquanto inspira. Dica: evite projetar os joelhos além dos dedos dos pés.","Suba enquanto expira empurrando o chão principalmente pelos calcanhares até estender as pernas e voltar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Dumbbell_Step_Ups":{"name":"Subida no Banco (Step-Up) com Halteres","instructions":["Fique em pé segurando um halter em cada mão ao lado das pernas.","Coloque o pé direito sobre a plataforma elevada e suba estendendo quadril e joelho da perna direita usando principalmente o calcanhar, apoiando em seguida o pé esquerdo na plataforma enquanto expira.","Desça com a perna esquerda flexionando quadril e joelho da direita enquanto inspira, recolocando o pé direito no chão ao lado do esquerdo.","Repita com a perna direita pela quantidade recomendada de repetições e depois execute com a perna esquerda."]},
"Dumbbell_Tricep_Extension_-Pronated_Grip":{"name":"Tríceps Testa com Halteres - Pegada Pronada","instructions":["Deite-se em um banco reto segurando dois halteres diretamente acima dos ombros com os braços totalmente estendidos perpendiculares ao chão.","Mantenha as palmas das mãos voltadas para a frente e os cotovelos fechados. Esta será a sua posição inicial.","Inspire e abaixe lentamente os halteres até ficarem próximos às orelhas, mantendo a parte superior dos braços imóvel e os cotovelos fechados.","Expire e use o tríceps para empurrar os halteres de volta à posição inicial."]},
"Dynamic_Back_Stretch":{"name":"Alongamento Dinâmico de Costas e Ombros","instructions":["Fique em pé com os pés na largura dos ombros. Esta será a sua posição inicial.","Mantendo os braços estendidos, balance-os à frente e para cima de 5 a 10 vezes, aumentando a amplitude a cada repetição até os braços passarem acima da cabeça."]},
"Dynamic_Chest_Stretch":{"name":"Alongamento Dinâmico de Peitoral","instructions":["Fique em pé com as mãos juntas e os braços estendidos diretamente à sua frente. Esta será a sua posição inicial.","Mantendo os braços estendidos, abra-os rapidamente para trás o máximo possível e feche novamente à frente. Repita de 5 a 10 vezes aumentando a velocidade."]},
"EZ-Bar_Curl":{"name":"Rosca Direta com Barra W","instructions":["Fique em pé segurando uma barra W na pegada aberta externa, com as palmas voltadas para a frente (levemente inclinadas pela curva da barra) e os cotovelos próximos ao corpo. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, expire e flexione os cotovelos contraindo o bíceps, movendo apenas os antebraços.","Continue até o bíceps contrair totalmente e a barra alcançar a altura dos ombros; segure um instante no topo apertando o bíceps.","Inspire e abaixe lentamente a barra de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"EZ-Bar_Skullcrusher":{"name":"Tríceps Testa com Barra W","instructions":["Deitado no banco, segure a barra W com pegada fechada e os cotovelos fechados, mantendo os braços perpendiculares ao chão. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, desça a barra flexionando os cotovelos enquanto inspira até a barra ficar diretamente acima da testa.","Eleve a barra de volta à posição inicial estendendo os cotovelos e expirando.","Repita."]},
"Elbow_Circles":{"name":"Círculos com os Cotovelos","instructions":["Sente-se ou fique em pé com os pés levemente afastados.","Coloque as mãos sobre os ombros com os cotovelos na altura dos ombros apontando para os lados.","Faça círculos lentos com os cotovelos, expirando ao iniciar o círculo e inspirando ao completá-lo."]},
"Elbow_to_Knee":{"name":"Abdominal Cotovelo no Joelho","instructions":["Deite-se no chão cruzando a perna direita sobre o joelho esquerdo flexionado e entrelace levemente as mãos atrás da cabeça com as escápulas no solo. Esta será a sua posição inicial.","Flexione e gire o tronco levando o cotovelo esquerdo em direção ao joelho direito.","Retorne à posição inicial e repita pelo número desejado de repetições antes de trocar de lado."]},
"Elbows_Back":{"name":"Alongamento Cotovelos para Trás","instructions":["Fique em pé com a postura ereta.","Coloque as duas mãos na lombar com os dedos apontando para baixo e os cotovelos para fora.","Puxe suavemente os cotovelos para trás tentando aproximá-los um do outro."]},
"Elevated_Back_Lunge":{"name":"Avanço Reverso Elevado com Barra","instructions":["Posicione uma barra carregada no rack na altura dos ombros e coloque uma plataforma baixa atrás de você.","Apoie a barra na parte superior das costas mantendo a postura firme e suba na plataforma elevada com os dois pés. Esta será a sua posição inicial.","Dê um passo para trás com uma perna, descendo ao flexionar quadril e joelhos até o joelho de trás tocar o chão.","Faça uma breve pausa e estenda quadril e joelhos para subir de volta à posição inicial antes de alternar."]},
"Elevated_Cable_Rows":{"name":"Remada Sentada Elevada no Cabo","instructions":["Pegue uma plataforma baixa de cerca de 4-6 polegadas de altura.","Coloque-a sobre o assento da máquina de remada baixa.","Sente-se sobre a plataforma apoiando os pés na base frontal com os joelhos levemente flexionados.","Incline-se à frente mantendo o alinhamento natural das costas e segure o pegador triângulo (barra em V).","Com os braços estendidos, puxe o tronco para trás até ficar a 90 graus das pernas com peito aberto e leve curvatura lombar, alongando as dorsais. Esta é a posição inicial.","Mantendo o tronco imóvel, puxe o pegador em direção ao abdômen mantendo os braços próximos ao corpo enquanto expira, apertando bem as costas por um segundo e retornando devagar enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Elliptical_Trainer":{"name":"Elíptico","instructions":["Suba no aparelho elíptico e selecione a opção desejada no painel (modo manual ou programa, podendo inserir idade e peso para estimar calorias e ajustar a inclinação/resistência).","Use os pegadores com sensores para monitorar a frequência cardíaca e manter a intensidade adequada."]},
"Exercise_Ball_Crunch":{"name":"Abdominal na Bola Suíça","instructions":["Deite-se sobre uma bola suíça apoiando a curvatura da lombar na bola, com joelhos flexionados, pés firmes no chão, tronco superior fora da bola e braços ao lado do corpo ou cruzados no peito.","Abaixe o tronco para alongar o abdômen mantendo o pescoço neutro. Esta será a sua posição inicial.","Com o quadril imóvel, flexione a cintura contraindo o abdômen para elevar ombros e tronco mantendo a lombar em contato com a bola enquanto expira, segurando por um segundo.","Retorne à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Exercise_Ball_Pull-In":{"name":"Puxada de Joelhos na Bola Suíça","instructions":["Deite-se no chão em posição de prancha apoiando as mãos na largura dos ombros.","Apoie a parte inferior das canelas em cima de uma bola suíça com pernas estendidas e corpo alinhado. Esta será a sua posição inicial.","Mantendo as costas retas e o tronco imóvel, puxe os joelhos em direção ao peito enquanto expira rolando a bola para a frente sob os tornozelos, contraindo o abdômen por um segundo.","Estenda lentamente as pernas rolando a bola de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Extended_Range_One-Arm_Kettlebell_Floor_Press":{"name":"Supino no Chão Unilateral com Kettlebell (Amplitude Estendida)","instructions":["Deite-se no chão segurando um kettlebell pela alça em uma mão; flexione a perna do mesmo lado cruzando o joelho sobre a linha média do corpo.","Empurre o kettlebell estendendo o cotovelo e aduzindo o braço acima do corpo, e depois retorne à posição inicial."]},
"External_Rotation":{"name":"Rotação Externa de Ombro com Halter","instructions":["Deite-se de lado em um banco reto segurando um halter no braço de cima e apoiando a cabeça na outra mão dobrada.","Flexione o cotovelo do braço com o halter a 90 graus mantendo o braço paralelo ao tronco.","Mantenha o braço colado à lateral do tronco com o antebraço apontando à frente paralelo ao chão. Esta será a sua posição inicial.","Ao expirar, faça rotação externa elevando o halter em semicírculo mantendo os 90 graus até o antebraço apontar para o teto e segure por um segundo.","Ao inspirar, retorne lentamente à posição inicial.","Repita pela quantidade recomendada de repetições e depois troque de braço."]},
"External_Rotation_with_Band":{"name":"Rotação Externa de Ombro com Elástico","instructions":["Prenda um elástico em um poste na altura do cotovelo e fique em pé com o lado esquerdo voltado para o poste a alguns passos de distância.","Segure a ponta do elástico com a mão direita e pressione o cotovelo firmemente contra o lado do corpo (uma toalha ou rolo pode ajudar a mantê-lo fixo).","Com o cotovelo flexionado a 90 graus e a mão cruzando à frente do tronco, entre na posição inicial.","Execute girando o antebraço para fora mantendo o cotovelo fixo junto ao corpo.","Vá até o limite confortável, pause e retorne à posição inicial."]},
"External_Rotation_with_Cable":{"name":"Rotação Externa de Ombro no Cabo","instructions":["Ajuste a polia na altura do cotovelo e fique em pé com o lado esquerdo voltado para a torre a alguns passos de distância.","Segure o pegador com a mão direita e mantenha o cotovelo firmemente pressionado contra a lateral do corpo.","Com o cotovelo flexionado a 90 graus e a mão cruzando à frente do tronco, entre na posição inicial.","Execute girando o antebraço para fora mantendo o cotovelo fixo junto ao corpo."]},
"Face_Pull":{"name":"Face Pull no Cabo","instructions":["De frente para uma polia alta com corda ou pegador duplo acoplado, puxe o peso diretamente em direção ao rosto afastando as mãos e mantendo os braços paralelos ao chão."]},
"Farmers_Walk":{"name":"Caminhada do Fazendeiro (Farmer's Walk)","instructions":["Posicione-se em pé entre os implementos (ou halteres pesados/barras curtas).","Segure as alças e levante as cargas impulsionando pelos calcanhares com costas retas e cabeça erguida.","Caminhe com passos curtos e rápidos sem prender a respiração pela distância estipulada (normalmente 50-100 pés) o mais rápido possível."]},
"Fast_Skipping":{"name":"Saltito Rápido (Fast Skipping)","instructions":["Comece em postura relaxada com uma perna ligeiramente à frente. Esta será a sua posição inicial.","Execute o skipping alternando o padrão direito-direito-passo para esquerdo-esquerdo-passo continuamente.","Mantenha contato rápido com o chão reduzindo o tempo no ar e deslocando-se o mais rápido possível."]},
"Finger_Curls":{"name":"Rosca de Dedos com Barra","instructions":["Segure uma barra com as duas mãos na largura dos ombros e palmas voltadas para cima.","Apoie os pés firmemente no chão um pouco mais abertos que a largura dos ombros. Esta será a sua posição inicial.","Abaixe a barra o máximo possível estendendo os dedos, deixando-a rolar até a última falange.","Em seguida, feche as mãos enrolando a barra o mais alto possível enquanto expira e segure a contração no topo."]},
"Flat_Bench_Cable_Flyes":{"name":"Crucifixo Reto no Cabo","instructions":["Posicione um banco reto entre duas polias baixas alinhando o peito às polias quando estiver deitado.","Deite-se de costas no banco mantendo os pés apoiados no chão.","Peça para alguém entregar os pegadores, segurando um em cada mão com as palmas voltadas para cima.","Abra os braços lateralmente paralelos ao chão com leve flexão nos cotovelos (mantenha essa flexão constante). Esta é a sua posição inicial.","Eleve os braços em semicírculo diretamente à frente unindo as mãos acima do peito enquanto contrai o peitoral e expira, segurando por um segundo no topo.","Retorne lentamente à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Flat_Bench_Leg_Pull-In":{"name":"Abdominal Puxada de Pernas no Banco","instructions":["Deite-se em um colchonete ou banco reto com as pernas para fora da extremidade.","Coloque as mãos sob os glúteos com as palmas para baixo ou segure as laterais do banco, estendendo as pernas à frente. Esta será a sua posição inicial.","Flexione os joelhos e puxe as coxas em direção ao abdômen enquanto expira até os joelhos ficarem próximos ao peito, segurando por um segundo.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Flat_Bench_Lying_Leg_Raise":{"name":"Elevação de Pernas Deitado no Banco","instructions":["Deite-se de costas em um banco reto com as pernas estendidas para fora da extremidade.","Coloque as mãos sob os glúteos com as palmas para baixo ou segure as laterais do banco. Esta será a sua posição inicial.","Mantendo as pernas estendidas (com leve trava natural nos joelhos), eleve-as até formar um ângulo de 90 graus com o chão enquanto expira e segure no topo por um segundo.","Abaixe lentamente as pernas de volta à posição inicial enquanto inspira."]},
"Flexor_Incline_Dumbbell_Curls":{"name":"Rosca Inclinada Flexora com Halteres","instructions":["Segure cada halter deslocando a mão para a extremidade externa, mantendo os punhos estendidos para trás durante toda a execução.","Sente-se em um banco inclinado a 45 graus segurando um halter em cada mão.","Deixe os braços pendurados ao lado do corpo com cotovelos fechados e palmas voltadas para a frente sem girar os punhos durante a subida. Esta será a sua posição inicial.","Eleve os dois halteres simultaneamente contraindo o bíceps enquanto expira sem balançar os braços e segure um segundo no topo.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Floor_Glute-Ham_Raise":{"name":"Glute-Ham Raise no Chão (Nórdico)","instructions":["Você pode usar um parceiro ou prender os pés sob um apoio estável.","Ajoelhe-se com coxas e tronco na vertical enquanto seu parceiro segura firmemente seus tornozelos. Esta será a sua posição inicial.","Desça lentamente o corpo estendendo os joelhos, cuidando para NÃO flexionar o quadril ao inclinar-se à frente.","Apoie as mãos à frente ao chegar perto do chão e empurre levemente o solo com os braços para auxiliar o retorno à posição inicial."]},
"Floor_Press":{"name":"Supino no Chão com Barra (Floor Press)","instructions":["Ajuste os ganchos do rack na altura adequada e deite-se no chão com a cabeça próxima à extremidade do rack. Retraia as escápulas e retire a barra dos suportes.","Desça a barra em direção à parte inferior do peito ou topo do abdômen com os cotovelos fechados até a parte superior dos braços encostar no chão e pause, evitando quicar.","Empurre a barra de volta para cima o mais rápido possível mantendo barra, punhos e cotovelos alinhados."]},
"Floor_Press_with_Chains":{"name":"Supino no Chão com Correntes","instructions":["Ajuste os ganchos do rack na altura adequada e apoie as correntes diretamente sobre as pontas da barra.","Deite-se no chão com a cabeça próxima à extremidade do rack, retraia as escápulas e retire a barra dos suportes.","Desça a barra até a parte inferior do peito com os cotovelos fechados até a parte superior dos braços tocar o chão e pause sem quicar.","Empurre a barra de volta para cima o mais rápido possível mantendo barra, punhos e cotovelos alinhados."]},
"Flutter_Kicks":{"name":"Chutes Alternados no Banco (Flutter Kicks)","instructions":["Deite-se de bruços em um banco reto com o quadril na borda, pernas estendidas para trás e braços segurando a borda frontal do banco.","Contraia glúteos e posteriores de coxa alinhando as pernas na altura do quadril. Esta será a sua posição inicial.","Inicie elevando a perna esquerda mais alto que a direita.","Em seguida, abaixe a perna esquerda enquanto eleva a perna direita.","Continue alternando de forma controlada como na natação até completar as repetições de cada perna, respirando normalmente."]},
"Foot-SMR":{"name":"Liberação Miofascial da Planta do Pé","instructions":["Sente-se sem sapatos e posicione o arco do pé sobre um rolo específico ou tubo rígido pequeno. Esta será a sua posição inicial.","Pressione firmemente para baixo deslizando pelo arco plantar por 10-30 segundos e depois troque de pé."]},
"Forward_Drag_with_Press":{"name":"Arraste de Trenó para Frente com Empurrão","instructions":["Prenda uma corda ou corrente com duas alças ao trenó e fique de costas para ele segurando uma alça em cada mão.","Avance um passo inclinando-se à frente ao estender pernas e quadril, pausando a cada passo para estender os cotovelos e empurrar as mãos para a frente antes do passo seguinte."]},
"Frankenstein_Squat":{"name":"Agachamento Frankenstein","instructions":["Este exercício ensina o posicionamento correto da barra e do tronco durante o clean e o agachamento frontal.","Apoie a barra na parte frontal dos ombros, solte a pegada e estenda os braços reto à frente, projetando os ombros para a frente sem arredondar a coluna torácica.","Agache flexionando joelhos e quadril entre as pernas mantendo o tronco ereto e os braços altos até os posteriores tocarem as panturrilhas.","Retorne à posição em pé empurrando pela parte anterior dos calcanhares e estendendo joelhos e quadril."]},
"Freehand_Jump_Squat":{"name":"Agachamento com Salto Livre","instructions":["Cruze os braços à frente do peito.","Com a cabeça erguida e as costas retas, posicione os pés na largura dos ombros.","Mantendo peito aberto e costas retas, agache enquanto inspira até as coxas ficarem paralelas ou abaixo do chão.","Impulsionando principalmente pela ponta dos pés, salte verticalmente o mais alto possível enquanto expira.","Ao tocar o chão novamente, agache de imediato e salte outra vez.","Repita pela quantidade recomendada de repetições."]},
"Frog_Hops":{"name":"Saltos do Sapo (Frog Hops)","instructions":["Fique em pé com as mãos atrás da cabeça e agache mantendo o tronco ereto e a cabeça erguida. Esta será a sua posição inicial.","Salte para a frente alguns pés evitando altura excessiva, absorvendo a aterrissagem com as pernas e saltando novamente de 5 a 10 vezes."]},
"Frog_Sit-Ups":{"name":"Abdominal Sapo","instructions":["Deite-se de costas no chão ou colchonete com as pernas estendidas à frente.","Flexione os joelhos abrindo as coxas para os lados até unir as solas dos pés.","Puxe os pés unidos o mais próximo possível do quadril formando um losango com as pernas.","Cruze os braços sobre o peito tocando os ombros opostos. Esta será a sua posição inicial.","Ao expirar, pressione a lombar no chão e eleve a parte superior do tronco (como o primeiro quarto de um abdominal), segurando um segundo no topo.","Ao inspirar, desça lentamente de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Front_Barbell_Squat":{"name":"Agachamento Frontal com Barra","instructions":["Este exercício é mais seguro dentro de um rack de agachamento. Ajuste a barra na altura ideal, posicione os braços por baixo com cotovelos altos e apoie a barra sobre os deltoides anteriores, cruzando os braços para segurá-la.","Retire a barra do suporte empurrando com as pernas enquanto estende o tronco.","Dê um passo atrás, posicione os pés na largura dos ombros com as pontas levemente para fora, mantendo cabeça erguida e costas retas. Esta será a sua posição inicial.","Desça lentamente flexionando os joelhos mantendo a postura ereta até as coxas ficarem abaixo do paralelo enquanto inspira. Dica: evite projetar os joelhos excessivamente além dos dedos dos pés.","Suba enquanto expira empurrando o chão principalmente pelo meio dos pés até estender as pernas e voltar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Front_Barbell_Squat_To_A_Bench":{"name":"Agachamento Frontal com Barra até o Banco","instructions":["Dentro de um rack de agachamento, posicione um banco reto atrás de você e ajuste a barra na altura ideal. Apoie a barra sobre os deltoides anteriores com os cotovelos altos e os braços cruzados segurando-a.","Retire a barra do suporte empurrando com as pernas enquanto estende o tronco.","Dê um passo atrás e posicione os pés na largura dos ombros com pontas levemente para fora, mantendo cabeça erguida e costas retas. Esta será a sua posição inicial.","Desça lentamente flexionando os joelhos com postura ereta até tocar o banco com os glúteos enquanto inspira. Dica: evite projetar os joelhos além dos dedos dos pés.","Suba enquanto expira empurrando o chão pelos calcanhares até estender as pernas e retornar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Front_Box_Jump":{"name":"Salto Frontal na Caixa","instructions":["Posicione uma caixa de altura adequada 1-2 pés à sua frente e fique em pé com os pés na largura dos ombros. Esta será a sua posição inicial.","Faça um agachamento curto preparando o salto, balançando os braços para trás.","Impulsione estendendo quadril, joelhos e tornozelos para saltar o mais alto possível, balançando os braços para a frente e para cima.","Aterrisse na caixa com os joelhos flexionados amortecendo o impacto e depois desça dando um passo de cada vez."]},
"Front_Cable_Raise":{"name":"Elevação Frontal no Cabo","instructions":["Selecione a carga na polia baixa e segure o pegador unilateral com a mão esquerda.","Fique de costas para a polia com o braço esquerdo estendido à frente da coxa e a palma voltada para o corpo. Esta será a sua posição inicial.","Mantendo o tronco imóvel, eleve o braço esquerdo à frente com leve flexão no cotovelo e palma para baixo até pouco acima do paralelo ao chão enquanto expira, pausando um segundo no topo.","Inspire e abaixe lentamente o braço de volta à posição inicial.","Após completar todas as repetições desse lado, troque e execute com o braço direito."]},
"Front_Cone_Hops_or_hurdle_hops":{"name":"Saltos Frontais sobre Cones ou Barreiras","instructions":["Alinhe uma fileira de cones ou pequenas barreiras espaçados por alguns pés.","Fique em pé diante do primeiro cone com os pés na largura dos ombros. Esta será a sua posição inicial.","Salte com os dois pés juntos sobre o primeiro cone balançando ambos os braços.","Amorteça a aterrissagem flexionando os joelhos e rebatendo imediatamente para saltar o próximo cone.","Continue até ter saltado sobre todos os cones."]},
"Front_Dumbbell_Raise":{"name":"Elevação Frontal Alternada com Halteres","instructions":["Segure um par de halteres em pé com o tronco reto e os pesos à frente das coxas com as palmas voltadas para trás. Esta será a sua posição inicial.","Mantendo o tronco imóvel, eleve o halter esquerdo à frente com leve flexão no cotovelo e palma para baixo até pouco acima do paralelo ao chão enquanto expira, pausando um segundo no topo e inspirando em seguida.","Abaixe lentamente o halter esquerdo à posição inicial enquanto eleva simultaneamente o halter direito.","Continue alternando dessa forma até completar todas as repetições recomendadas para cada braço."]},
"Front_Incline_Dumbbell_Raise":{"name":"Elevação Frontal no Banco Inclinado com Halteres","instructions":["Sente-se em um banco inclinado entre 30 e 60 graus segurando um halter em cada mão.","Estenda os braços diretamente à frente com as palmas para baixo e os halteres cerca de 1 polegada acima das coxas. Esta será a sua posição inicial.","Eleve lentamente os halteres até ficarem ligeiramente acima dos ombros mantendo os cotovelos estendidos e segure por um segundo enquanto expira, mantendo cabeça apoiada e pés no chão.","Abaixe os braços de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Front_Leg_Raises":{"name":"Balanço Frontal de Perna","instructions":["Fique em pé ao lado de uma cadeira ou outro apoio segurando-se com uma mão.","Balance uma perna para a frente mantendo-a estendida e leve-a para trás o máximo que sua flexibilidade permitir. Repita 5-10 vezes e depois troque de perna."]},
"Front_Plate_Raise":{"name":"Elevação Frontal com Anilha","instructions":["Em pé, segure uma anilha com as duas mãos nas posições de 3 e 9 horas com os braços estendidos (leve flexão nos cotovelos) à frente da cintura. Esta será a sua posição inicial.","Eleve lentamente a anilha enquanto expira até ficar pouco acima da altura dos ombros e segure por um segundo, sem balançar o tronco nem dobrar os cotovelos.","Ao inspirar, abaixe lentamente a anilha de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Front_Raise_And_Pullover":{"name":"Elevação Frontal e Pullover com Barra","instructions":["Deite-se em um banco reto segurando uma barra com pegada pronada e mãos afastadas cerca de 15 polegadas.","Apoie a barra sobre as coxas com os braços estendidos e leve flexão nos cotovelos. Esta será a sua posição inicial.","Eleve a barra em movimento semicircular mantendo os braços estendidos enquanto inspira até levá-la acima da cabeça (arco de cerca de 180 graus), paralela ao chão com palmas voltadas para o teto.","Retorne a barra à posição inicial invertendo o movimento enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Front_Squat_Clean_Grip":{"name":"Agachamento Frontal (Pegada de Clean)","instructions":["Ajuste a barra no rack logo abaixo dos ombros e apoie-a sobre os deltoides tocando levemente a garganta, segurando-a apenas com os dedos em pegada de clean com cotovelos altos.","Retire a barra empurrando com as pernas, dê um passo atrás com pés na largura dos ombros e pontas levemente para fora, mantendo cabeça e cotovelos sempre altos. Esta será a sua posição inicial.","Flexione os joelhos sentando entre as pernas até os posteriores tocarem as panturrilhas, empurrando os joelhos para fora alinhados aos pés.","Suba enquanto expira empurrando pelo calcanhar ou meio do pé até retornar à posição inicial."]},
"Front_Squats_With_Two_Kettlebells":{"name":"Agachamento Frontal com Dois Kettlebells","instructions":["Faça o clean de dois kettlebells até os ombros estendendo pernas e quadril e girando os punhos.","Olhando sempre para a frente, agache o mais fundo possível empurrando os joelhos para fora com o tronco ereto e pause em baixo.","Suba impulsionando pelos calcanhares e repita."]},
"Front_Two-Dumbbell_Raise":{"name":"Elevação Frontal Simultânea com Halteres","instructions":["Segure um par de halteres em pé com o tronco reto e os pesos à frente das coxas com as palmas voltadas para o corpo. Esta será a sua posição inicial.","Mantendo o tronco imóvel, eleve os dois halteres à frente com leve flexão nos cotovelos e palmas para baixo até pouco acima do paralelo ao chão enquanto expira, pausando um segundo no topo.","Ao inspirar, abaixe os halteres lentamente de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Full_Range-Of-Motion_Lat_Pulldown":{"name":"Puxada Alta com Amplitude Completa no Cabo","instructions":["Em pé ou sentado em um banco alto, segure dois pegadores cruzados presos às polias altas (mão direita na polia esquerda e vice-versa) com as palmas voltadas para a frente.","Mantendo o peito aberto e leve curvatura lombar, puxe os pegadores para baixo em arco girando os punhos para que as palmas fiquem frente a frente no ponto final, e depois retorne lentamente."]},
"Gironda_Sternum_Chins":{"name":"Barra Fixa Esternal de Gironda","instructions":["Segure a barra fixa com pegada supinada na largura dos ombros.","Pendure-se com os braços totalmente estendidos, abra o peito e incline o tronco para trás (mantendo essa inclinação durante todo o movimento). Esta será a sua posição inicial.","Puxe o corpo em direção à barra com a coluna arqueada e a cabeça inclinada para trás enquanto expira, deixando quadril e pernas a cerca de 45 graus no topo.","Continue puxando até a parte inferior do peito (esterno) tocar a barra e segure a contração por um segundo.","Desça lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Glute_Ham_Raise":{"name":"Elevação Glúteo-Posterior (Glute Ham Raise)","instructions":["Ajuste o aparelho ao seu corpo, deitando-se de bruços com os pés firmes contra a plataforma entre os rolos e os joelhos logo atrás do apoio.","Comece da posição inferior mantendo as costas retas e flexione os joelhos empurrando os dedos dos pés na plataforma até o tronco subir à vertical.","Retorne à posição inicial controlando a descida."]},
"Glute_Kickback":{"name":"Coice para Glúteos (Glute Kickback)","instructions":["Ajoelhe-se no chão ou em um colchonete apoiando as mãos na largura dos ombros com os braços estendidos perpendiculares ao tronco, cabeça olhando à frente e joelhos dobrados a 90 graus. Esta será a sua posição inicial.","Ao expirar, eleve a perna direita para trás mantendo o ângulo de 90 graus no joelho até a coxa ficar alinhada com as costas, contraindo bem o glúteo no topo por um segundo.","Retorne à posição inicial enquanto inspira e repita com a perna esquerda.","Continue alternando as pernas até completar todas as repetições recomendadas."]},
"Goblet_Squat":{"name":"Agachamento Goblet com Kettlebell","instructions":["Fique em pé segurando um kettlebell leve pelas laterais da alça junto ao peito. Esta será a sua posição inicial.","Agache entre as pernas até os posteriores de coxa encostarem nas panturrilhas, mantendo peito e cabeça erguidos e costas retas.","Na posição inferior, pause e use os cotovelos para empurrar os joelhos para fora; retorne à posição inicial e repita por 10-20 repetições."]},
"Good_Morning":{"name":"Bom Dia com Barra","instructions":["Comece com a barra no rack na altura dos ombros, apoiando-a na parte posterior dos ombros como em um agachamento de powerlifting. Mantenha costas firmes, escápulas juntas e joelhos levemente flexionados ao dar um passo atrás.","Inicie flexionando o quadril e levando-o para trás até o tronco ficar quase paralelo ao chão, mantendo costas firmes e pescoço alinhado.","Inverta o movimento estendendo o quadril com glúteos e posteriores de coxa até retornar à posição inicial."]},
"Good_Morning_off_Pins":{"name":"Bom Dia a Partir dos Pinos","instructions":["Posicione a barra nos pinos do rack na altura do abdômen, entre sob ela apoiando-a na parte posterior dos ombros com tronco quase paralelo ao chão, costas firmes, escápulas juntas e joelhos levemente flexionados.","Inicie estendendo o quadril com glúteos e posteriores até ficar em pé com o peso, e depois abaixe lentamente a barra de volta aos pinos."]},
"Gorilla_Chin_Crunch":{"name":"Barra Fixa Supinada com Abdominal (Gorilla Chin)","instructions":["Pendure-se na barra fixa com pegada supinada (palmas voltadas para você) um pouco mais aberta que a largura dos ombros.","Flexione os joelhos a 90 graus deixando as panturrilhas paralelas ao chão e as coxas verticais. Esta será a sua posição inicial.","Ao expirar, puxe o corpo para cima enquanto traz os joelhos ao peito simultaneamente, parando quando o nariz alcançar a altura da barra.","Desça lentamente inspirando até retornar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Groin_and_Back_Stretch":{"name":"Alongamento de Virilha e Costas","instructions":["Sente-se no chão com os joelhos flexionados e os pés juntos.","Entrelace os dedos atrás da cabeça. Esta será a sua posição inicial.","Flexione o tronco para baixo levando os cotovelos para a parte interna das coxas, pause brevemente e retorne com cabeça erguida e costas retas. Repita 10-20 vezes."]},
"Groiners":{"name":"Salto do Sapo na Prancha (Groiners)","instructions":["Comece em posição de flexão de braço no chão. Esta será a sua posição inicial.","Saltando com as duas pernas juntas, traga os pés para o lado de fora das mãos mantendo a cabeça erguida.","Retorne à posição inicial e repita imediatamente de forma contínua por 10-20 repetições."]},
"Hack_Squat":{"name":"Agachamento Hack na Máquina","instructions":["Apoie as costas no encosto da máquina e encaixe os ombros sob os apoios acolchoados.","Posicione os pés na plataforma na largura dos ombros com pontas levemente voltadas para fora, mantendo cabeça erguida e costas coladas no encosto.","Segure as alças laterais e destrave as travas de segurança.","Estenda as pernas sem travar os joelhos. Esta será a sua posição inicial.","Desça lentamente flexionando os joelhos com as costas sempre apoiadas até as coxas passarem ligeiramente do paralelo enquanto inspira. Dica: não deixe os joelhos ultrapassarem a linha dos dedos dos pés.","Suba enquanto expira empurrando principalmente pelos calcanhares até estender as pernas de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Hammer_Curls":{"name":"Rosca Martelo com Halteres","instructions":["Fique em pé com o tronco ereto e um halter em cada mão com os braços estendidos e cotovelos próximos ao corpo.","As palmas das mãos devem ficar voltadas para o corpo. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, expire e flexione os cotovelos contraindo o bíceps até os halteres chegarem à altura dos ombros, segurando brevemente no topo. Dica: mova apenas os antebraços.","Após a breve pausa, inspire e abaixe lentamente os halteres de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Hammer_Grip_Incline_DB_Bench_Press":{"name":"Supino Inclinado com Halteres - Pegada Neutra","instructions":["Deite-se em um banco inclinado segurando um halter em cada mão apoiados sobre as coxas com palmas frente a frente.","Use as coxas para impulsionar os halteres um de cada vez até segurá-los na largura dos ombros.","Mantenha pegada neutra (palmas voltadas uma para a outra) e cotovelos alinhados aos ombros formando um ângulo de 90 graus entre braço e antebraço. Esta será a sua posição inicial.","Desça os pesos lentamente lateralmente mantendo controle total enquanto inspira.","Ao expirar, empurre os halteres para cima usando o peitoral, estenda os braços, segure por um segundo e desça devagar. Dica: a descida deve durar pelo menos o dobro da subida.","Repita o movimento pela quantidade prescrita de repetições.","Ao terminar, apoie os halteres de volta nas coxas e depois coloque-os no chão com segurança."]},
"Hamstring-SMR":{"name":"Liberação Miofascial dos Posteriores de Coxa","instructions":["Sentado, estenda as pernas sobre um rolo de espuma posicionado sob a parte posterior das coxas e apoie as mãos ao lado ou atrás para sustentar o corpo. Esta será a sua posição inicial.","Usando as mãos, eleve o quadril do chão e transfira o peso para uma perna relaxando os posteriores de coxa.","Deslize sobre o rolo de abaixo do quadril até acima da dobra do joelho, pausando nos pontos de tensão por 10-30 segundos. Repita na outra perna."]},
"Hamstring_Stretch":{"name":"Alongamento de Posteriores de Coxa","instructions":["Deite-se de costas com uma perna estendida para cima a 90 graus e a outra perna estendida apoiada no chão.","Passe um cinto, faixa ou corda pela planta do pé elevado. Esta será a sua posição inicial.","Puxe o cinto para gerar tensão na panturrilha e nos posteriores de coxa, segure por 10-30 segundos e repita com a outra perna."]},
"Handstand_Push-Ups":{"name":"Flexão na Parada de Mãos","instructions":["De costas para uma parede, incline o tronco e apoie as duas mãos no chão na largura dos ombros.","Impulsione as pernas para cima apoiando os pés na parede de cabeça para baixo com braços e pernas totalmente estendidos e corpo alinhado. Dica: peça ajuda na primeira vez e mantenha o olhar voltado para a parede.","Desça lentamente enquanto inspira até a cabeça quase tocar o chão. Dica: controle bem a descida para evitar impactos na cabeça.","Empurre-se de volta para cima enquanto expira até os cotovelos quase travarem.","Repita pela quantidade recomendada de repetições."]},
"Hang_Clean":{"name":"Hang Clean (Arremesso Suspenso)","instructions":["Segure a barra na altura do meio das coxas com pegada pronada ou hook grip na largura dos ombros, costas retas e tronco levemente inclinado à frente.","Estenda explosivamente quadril, joelhos e tornozelos impulsionando a barra para cima enquanto encolhe os ombros.","Entre rapidamente sob a barra recebendo-a nos ombros e recupere-se empurrando pelos calcanhares com tronco ereto e cotovelos altos até ficar em pé."]},
"Hang_Clean_-_Below_the_Knees":{"name":"Hang Clean - Abaixo dos Joelhos","instructions":["Segure a barra logo abaixo dos joelhos com pegada pronada ou hook grip na largura dos ombros, costas retas e tronco inclinado à frente.","Estenda explosivamente quadril, joelhos e tornozelos impulsionando a barra para cima, encolhendo os ombros e flexionando os braços com cotovelos para cima e para fora.","No pico da extensão, puxe-se rapidamente para baixo girando os cotovelos sob a barra para recebê-la em agachamento frontal apoiada nos ombros.","Recupere-se imediatamente empurrando pelos calcanhares com tronco ereto e cotovelos altos até ficar totalmente em pé."]},
"Hang_Snatch":{"name":"Hang Snatch (Arranque Suspenso)","instructions":["Segure a barra com pegada aberta pronada ou hook grip na altura do quadril, pés sob o quadril levemente abertos, joelhos levemente flexionados e tronco inclinado à frente com coluna firme. Esta será a sua posição inicial.","Estenda explosivamente pernas e quadril e, no pico, encolha os ombros flexionando os cotovelos para os lados.","Ao posicionar os pés na base de recepção, puxe-se rapidamente sob a barra estendendo os braços acima da cabeça e recebendo-a no agachamento fundo.","Levante-se com a barra acima da cabeça e depois retorne o peso ao chão sob controle."]},
"Hang_Snatch_-_Below_Knees":{"name":"Hang Snatch - Abaixo dos Joelhos","instructions":["Segure a barra com pegada aberta pronada ou hook grip logo abaixo dos joelhos, pés sob o quadril, joelhos levemente flexionados e coluna estendida olhando à frente. Esta será a sua posição inicial.","Estenda explosivamente pernas e quadril e, no pico, encolha os ombros flexionando os cotovelos para os lados.","Ao abrir os pés para a base de recepção, puxe-se rapidamente sob a barra recebendo-a o mais baixo possível com os braços totalmente estendidos acima da cabeça.","Levante-se com o peso acima da cabeça e depois abaixe a barra ao chão sob controle."]},
"Hanging_Bar_Good_Morning":{"name":"Bom Dia com Barra Suspensa","instructions":["Suspenda a barra por correntes ou tiras na altura do abdômen dentro do rack.","Entre sob a barra apoiando-a na parte posterior dos ombros com tronco quase paralelo ao chão, costas firmes, escápulas juntas e joelhos levemente flexionados.","Estenda o quadril usando glúteos e posteriores de coxa até ficar em pé com a carga.","Abaixe lentamente o peso de volta à posição inicial sustentada pelas correntes."]},
"Hanging_Leg_Raise":{"name":"Elevação de Pernas na Barra Fixa","instructions":["Pendure-se na barra fixa com pegada média ou aberta e braços estendidos, pernas esticadas para baixo e pelve levemente inclinada para trás. Esta será a sua posição inicial.","Eleve as pernas até formarem um ângulo de 90 graus com o tronco enquanto expira e segure a contração por cerca de um segundo.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Hanging_Pike":{"name":"Elevação Completa de Pernas na Barra (Hanging Pike)","instructions":["Pendure-se na barra fixa com pernas juntas e pegada pronada um pouco mais aberta que a largura dos ombros (straps podem ajudar na pegada).","Flexione os joelhos a 90 graus trazendo as coxas à frente paralelas ao chão. Esta será a sua posição inicial.","Eleve as pernas enquanto expira até quase encostar as canelas na barra acima de você, estendendo as pernas o máximo possível no topo.","Abaixe as pernas o mais devagar possível até a posição inicial, evitando balançar ou usar impulso.","Repita pela quantidade recomendada de repetições."]},
"Heaving_Snatch_Balance":{"name":"Snatch Balance com Impulso (Heaving)","instructions":["Este exercício educa a entrada sob a barra no snatch. Apoie uma carga leve na parte posterior dos ombros com os pés um pouco mais abertos que a largura do quadril.","Flexione levemente os joelhos e impulsione para cima para aliviar o peso da barra, entrando rapidamente por baixo dela em agachamento profundo enquanto estende os braços acima da cabeça.","Retorne à posição em pé."]},
"Heavy_Bag_Thrust":{"name":"Empurrão Explosivo no Saco Pesado","instructions":["Assuma uma postura ereta ao lado de um saco pesado com os pés afastados em base alternada e uma mão apoiada no saco na altura do peito. Esta será a sua posição inicial.","Gire a cintura empurrando o saco para a frente com o máximo de força e velocidade possíveis.","Receba o saco quando ele balançar de volta invertendo os passos."]},
"High_Cable_Curls":{"name":"Rosca Direta na Polia Alta (Crucifixo Bíceps)","instructions":["Fique em pé entre duas polias altas segurando um pegador em cada mão, com os braços abertos paralelos ao chão e palmas voltadas para cima. Esta será a sua posição inicial.","Flexione os cotovelos trazendo os pegadores em direção às orelhas enquanto contrai o bíceps e expira, mantendo a parte superior dos braços imóvel e segurando um segundo no topo.","Retorne lentamente os braços à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Hip_Circles_prone":{"name":"Círculos com o Quadril (Quatro Apoios)","instructions":["Apoie-se no chão em quatro apoios (mãos e joelhos) com boa postura e eleve um joelho dobrado do chão. Esta será a sua posição inicial.","Mantendo o joelho dobrado, gire o fêmur em arco tentando desenhar um círculo amplo com o joelho.","Execute lentamente por algumas repetições e repita do outro lado."]},
"Hip_Extension_with_Bands":{"name":"Extensão de Quadril com Elástico","instructions":["Prenda uma extremidade do elástico na base de um poste e a outra em um tornozelo.","De frente para o ponto de fixação, segure na coluna para estabilizar.","Mantendo cabeça e peito erguidos e o joelho estendido, leve a perna resistida para trás o máximo possível.","Retorne a perna à posição inicial."]},
"Hip_Flexion_with_Band":{"name":"Flexão de Quadril com Elástico","instructions":["Prenda uma extremidade do elástico na base de um poste e a outra em um tornozelo.","Fique de costas para o ponto de fixação do elástico.","Mantendo cabeça e peito erguidos, eleve o joelho até 90 graus e faça uma pausa.","Retorne a perna à posição inicial."]},
"Hip_Lift_with_Band":{"name":"Elevação Pélvica com Elástico","instructions":["Escolha um elástico adequado, prenda-o dos dois lados do rack (ou em halteres pesados) e deite-se no centro.","Ajuste o elástico diretamente sobre o quadril, flexione os joelhos apoiando os pés no chão e segure o elástico se necessário.","Mantendo os ombros no chão, impulsione pelos calcanhares elevando o quadril contra o elástico o mais alto possível.","Pause no topo do movimento e retorne à posição inicial."]},
"Hug_A_Ball":{"name":"Abraçar a Bola Suíça (Agachamento Isométrico)","instructions":["Sente-se no chão.","Posicione uma bola suíça entre as duas pernas e abaixe o quadril próximo ao chão.","Abrace a bola com os braços para apoiar o corpo, alinhando joelhos acima dos tornozelos com os pés firmes no chão e segurando bem a bola para não escorregar."]},
"Hug_Knees_To_Chest":{"name":"Abraçar os Joelhos no Peito","instructions":["Deite-se de costas e traga os dois joelhos em direção ao peito.","Segure com os braços por baixo dos joelhos, e não por cima, para evitar pressão nas articulações.","Puxe suavemente os joelhos em direção aos ombros para alongar lombar e glúteos."]},
"Hurdle_Hops":{"name":"Saltos sobre Barreiras","instructions":["Alinhe uma fileira de barreiras baixas espaçadas por alguns pés.","Fique em pé diante da primeira barreira com os pés na largura dos ombros. Esta será a sua posição inicial.","Salte com os dois pés juntos sobre a primeira barreira balançando ambos os braços.","Amorteça a aterrissagem flexionando os joelhos e rebata imediatamente para saltar a próxima barreira até completar todas."]},
"Hyperextensions_Back_Extensions":{"name":"Hiperextensão Lombar (Banco Romano)","instructions":["Deite-se de bruços no banco de hiperextensão prendendo os tornozelos firmemente sob os apoios.","Ajuste o apoio superior para que a parte alta das coxas fique apoiada, deixando espaço livre para dobrar a cintura.","Com o corpo reto, cruze os braços à frente do peito ou atrás da cabeça (você pode segurar uma anilha para carga extra). Esta será a sua posição inicial.","Incline-se lentamente para a frente pela cintura mantendo as costas retas enquanto inspira até sentir alongar os posteriores de coxa sem arredondar a coluna.","Eleve lentamente o tronco de volta à posição inicial sem hiperestender além da linha reta e sem balançar.","Repita pela quantidade recomendada de repetições."]},
"Hyperextensions_With_No_Hyperextension_Bench":{"name":"Hiperextensão Lombar no Banco Reto","instructions":["Com alguém segurando suas pernas, posicione-se na borda de um banco reto até o quadril ficar para fora com o tronco pendurado em direção ao chão.","Com o corpo alinhado, cruze os braços à frente do peito ou atrás da cabeça. Esta será a sua posição inicial.","Incline-se lentamente à frente pela cintura mantendo as costas retas enquanto inspira até quase tocar o chão ou sentir alongar os posteriores, sem nunca arredondar a coluna.","Eleve lentamente o tronco de volta à posição inicial enquanto expira sem hiperestender nem balançar.","Repita pela quantidade recomendada de repetições."]},
"IT_Band_and_Glute_Stretch":{"name":"Alongamento de Banda Iliotibial e Glúteos","instructions":["Passe um cinto, corda ou faixa ao redor de um pé e cruze essa perna estendida sobre o corpo para o lado oposto enquanto está deitado no chão. Esta será a sua posição inicial.","Mantendo o pé fora do chão, puxe a faixa gerando tensão para puxar a ponta do pé para cima; segure por 10-20 segundos e repita do outro lado."]},
"Iliotibial_Tract-SMR":{"name":"Liberação Miofascial do Trato Iliotibial","instructions":["Deite-se de lado apoiando a lateral da coxa de baixo sobre um rolo de espuma entre o quadril e o joelho, cruzando a outra perna à frente para apoio.","Transfira o máximo de peso suportável para a perna de baixo mantendo seus músculos relaxados.","Deslize a perna sobre o rolo do quadril até o joelho, pausando por 10-30 segundos nos pontos de tensão. Repita na outra perna."]},
"Inchworm":{"name":"Caminhada da Minhoca (Inchworm)","instructions":["Fique em pé com os pés juntos e, mantendo as pernas estendidas, incline-se para apoiar as mãos no chão diretamente à frente. Esta será a sua posição inicial.","Caminhe lentamente com as mãos para a frente alternando esquerda e direita mantendo as pernas estendidas.","Avance até o corpo ficar paralelo ao chão em posição de flexão de braço.","Mantendo as mãos fixas, dê passos curtos com os pés avançando poucos centímetros por vez.","Continue caminhando com os pés até alcançarem as mãos mantendo as pernas estendidas."]},
"Incline_Barbell_Triceps_Extension":{"name":"Tríceps Testa Inclinado com Barra","instructions":["Segure uma barra com pegada pronada (palmas para baixo) um pouco mais fechada que a largura dos ombros.","Deite-se em um banco inclinado ajustado entre 45 e 75 graus.","Leve a barra acima da cabeça com os braços estendidos alinhados ao tronco e cotovelos fechados. Esta será a sua posição inicial.","Abaixe a barra em semicírculo atrás da cabeça até os antebraços encostarem no bíceps enquanto inspira, mantendo a parte superior dos braços imóvel e próxima à cabeça.","Retorne à posição inicial enquanto expira contraindo o tríceps e segure por um segundo.","Repita pela quantidade recomendada de repetições."]},
"Incline_Bench_Pull":{"name":"Remada no Banco Inclinado (Pegada Pronada)","instructions":["Segure um halter em cada mão e deite-se de bruços em um banco inclinado a aproximadamente 30 graus.","Deixe os braços pendurados totalmente estendidos em direção ao chão.","Gire os punhos para adotar pegada pronada (palmas voltadas para trás/baixo).","Abra levemente os cotovelos para os lados. Esta será a sua posição inicial.","Ao expirar, puxe os halteres para cima dobrando os cotovelos para os lados (formando um \"T\" no topo até os braços alcançarem a linha das costas) e segure por um segundo.","Desça lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Incline_Cable_Chest_Press":{"name":"Supino Inclinado no Cabo","instructions":["Ajuste o peso adequado e sente-se no banco inclinado segurando os pegadores com braços a cerca de 45 graus do tronco, cabeça e peito erguidos e cotovelos a 90 graus. Esta será a sua posição inicial.","Estenda os cotovelos empurrando os pegadores juntos à frente, mantendo as escápulas retraídas durante toda a execução.","Após pausar na extensão completa, retorne à posição inicial mantendo a tensão nos cabos."]},
"Incline_Cable_Flye":{"name":"Crucifixo Inclinado no Cabo","instructions":["Posicione as polias no nível mais baixo possível junto ao chão.","Coloque um banco inclinado (a 45 graus) entre as polias, selecione o peso e segure um pegador em cada mão.","Deite-se no banco inclinado e una as mãos acima do peito com os braços estendidos. Esta será a sua posição inicial.","Com leve flexão nos cotovelos, abra os braços lateralmente em arco amplo até sentir alongar o peitoral enquanto inspira, movendo apenas a articulação dos ombros.","Retorne os braços à posição inicial contraindo o peitoral pelo mesmo arco enquanto expira e segure por um segundo.","Repita o movimento pela quantidade prescrita de repetições."]},
"Incline_Dumbbell_Bench_With_Palms_Facing_In":{"name":"Supino Inclinado com Halteres - Palmas para Dentro","instructions":["Deite-se em um banco inclinado com um halter em cada mão sobre as coxas e palmas voltadas uma para a outra.","Use as coxas para impulsionar os halteres um de cada vez até segurá-los na largura dos ombros.","Mantenha pegada neutra (palmas frente a frente) e cotovelos alinhados aos ombros formando 90 graus entre braço e antebraço. Esta será a sua posição inicial.","Desça os halteres lentamente lateralmente mantendo controle total enquanto inspira.","Ao expirar, empurre os halteres para cima usando o peitoral, estenda os braços, segure por um segundo e desça devagar. Dica: a descida deve levar pelo menos o dobro da subida.","Repita pela quantidade prescrita de repetições.","Ao terminar, apoie os halteres nas coxas e depois coloque-os no chão com segurança."]},
"Incline_Dumbbell_Curl":{"name":"Rosca no Banco Inclinado com Halteres","instructions":["Sente-se recostado em um banco inclinado segurando um halter em cada mão com os braços estendidos, cotovelos próximos ao corpo e palmas para a frente. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos contraindo o bíceps enquanto expira até os halteres chegarem à altura dos ombros, segurando por um segundo.","Comece lentamente a abaixar os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Incline_Dumbbell_Flyes":{"name":"Crucifixo Inclinado com Halteres","instructions":["Segure um halter em cada mão e deite-se em um banco inclinado a no máximo 30 graus.","Estenda os braços acima do peito mantendo leve flexão nos cotovelos.","Gire os punhos para que as palmas fiquem voltadas para você, com os dedos mínimos próximos um do outro. Esta será a sua posição inicial.","Ao inspirar, abra lentamente os braços para os lados girando os punhos até as palmas ficarem voltadas uma para a outra e depois para o teto no ponto baixo.","Ao expirar, traga os halteres de volta à posição inicial invertendo a rotação dos punhos sem mover os cotovelos.","Repita pela quantidade recomendada de repetições."]},
"Incline_Dumbbell_Flyes_-_With_A_Twist":{"name":"Crucifixo Inclinado com Halteres - Com Rotação","instructions":["Segure um halter em cada mão e deite-se em um banco inclinado a no máximo 30 graus.","Estenda os braços acima do peito mantendo leve flexão nos cotovelos.","Gire os punhos para que as palmas fiquem voltadas para você, com os dedos mínimos próximos um do outro. Esta será a sua posição inicial.","Ao inspirar, abra lentamente os braços para os lados girando os punhos até as palmas ficarem voltadas para cima ao final da descida.","Ao expirar, traga os halteres de volta à posição inicial invertendo a rotação até os dedos mínimos ficarem próximos novamente, sem dobrar os cotovelos.","Repita pela quantidade recomendada de repetições."]},
"Incline_Dumbbell_Press":{"name":"Supino Inclinado com Halteres","instructions":["Deite-se em um banco inclinado com um halter em cada mão sobre as coxas e palmas voltadas uma para a outra.","Use as coxas para impulsionar os halteres um de cada vez até segurá-los na largura dos ombros.","Gire os punhos para que as palmas fiquem voltadas para a frente. Esta será a sua posição inicial.","Mantendo controle total, expire e empurre os halteres para cima usando o peitoral.","Estenda os braços no topo, segure por um segundo e desça lentamente. Dica: a descida deve levar cerca do dobro do tempo da subida.","Repita pela quantidade prescrita de repetições.","Ao terminar, apoie os halteres nas coxas e depois no chão com segurança."]},
"Incline_Hammer_Curls":{"name":"Rosca Martelo no Banco Inclinado","instructions":["Sente-se firme em um banco inclinado segurando um halter em cada mão em pegada neutra com os braços pendurados ao lado do corpo e pés juntos. Esta será a sua posição inicial.","Inicie flexionando os cotovelos tentando manter a parte superior dos braços imóvel.","Suba até o topo do movimento, pause e retorne lentamente à posição inicial."]},
"Incline_Inner_Biceps_Curl":{"name":"Rosca Aberta no Banco Inclinado para Bíceps Interno","instructions":["Segure um halter em cada mão e deite-se em um banco inclinado.","Deixe os braços estendidos ao lado do corpo com as palmas voltadas para fora. Esta será a sua posição inicial.","Ao expirar, flexione os cotovelos levando os halteres para fora e para cima alinhados aos ombros, lembrando uma pose de duplo bíceps no topo.","Após segurar a contração por um segundo, inspire e abaixe os halteres lentamente pelo mesmo trajeto de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Incline_Push-Up":{"name":"Flexão de Braço Inclinada","instructions":["Fique em pé de frente para um banco ou plataforma elevada firme e apoie as mãos na borda um pouco mais abertas que a largura dos ombros.","Afaste os pés para trás mantendo corpo e braços retos (braços perpendiculares ao corpo) e desça flexionando os cotovelos até o peito se aproximar da borda.","Empurre o corpo para cima até estender os braços e repita."]},
"Incline_Push-Up_Close-Grip":{"name":"Flexão de Braço Inclinada - Pegada Fechada","instructions":["Fique de frente para uma barra no Smith ou plataforma elevada firme na altura adequada.","Posicione as mãos bem próximas uma da outra sobre a barra.","Afaste os pés para trás mantendo braços e corpo retos. Esta será a sua posição inicial.","Mantendo o corpo reto, desça o peito em direção à barra flexionando os braços.","Retorne à posição inicial estendendo os cotovelos."]},
"Incline_Push-Up_Depth_Jump":{"name":"Flexão de Braço Inclinada com Salto nos Steps","instructions":["Para este exercício você precisará de uma caixa de cerca de 12 polegadas e dois steps ou colchonetes espessos.","Coloque os steps logo por fora dos ombros e apoie os pés na caixa em posição de flexão inclinada com as mãos no chão entre os steps. Esta será a sua posição inicial.","Flexione os cotovelos para descer o corpo e empurre rapidamente para sair do chão, aterrissando com as mãos sobre os steps e absorvendo o impacto.","Repita o movimento retornando à posição inicial."]},
"Incline_Push-Up_Medium":{"name":"Flexão de Braço Inclinada - Pegada Média","instructions":["Fique de frente para uma barra no Smith ou plataforma elevada firme na altura adequada.","Apoie as mãos na barra afastadas na largura dos ombros.","Afaste os pés para trás mantendo braços e corpo retos. Esta será a sua posição inicial.","Mantendo o corpo reto, desça o peito em direção à barra flexionando os braços.","Retorne à posição inicial estendendo os cotovelos."]},
"Incline_Push-Up_Reverse_Grip":{"name":"Flexão de Braço Inclinada - Pegada Supinada","instructions":["Fique de frente para uma barra no Smith ou plataforma elevada firme na altura adequada.","Segure a barra com as palmas voltadas para cima (pegada supinada) na largura dos ombros.","Afaste os pés para trás mantendo braços e corpo retos. Esta será a sua posição inicial.","Mantendo o corpo reto, desça o peito em direção à barra flexionando os braços.","Retorne à posição inicial estendendo os cotovelos."]},
"Incline_Push-Up_Wide":{"name":"Flexão de Braço Inclinada - Pegada Aberta","instructions":["Fique de frente para uma barra no Smith ou plataforma elevada firme na altura adequada.","Apoie as mãos na barra mais afastadas que a largura dos ombros.","Afaste os pés para trás mantendo braços perpendiculares ao tronco e corpo reto. Esta será a sua posição inicial.","Mantendo o corpo reto, desça o peito em direção à barra flexionando os braços.","Retorne à posição inicial estendendo os cotovelos."]},
"Intermediate_Groin_Stretch":{"name":"Alongamento Intermediário de Virilha","instructions":["Deite-se de costas com as pernas estendidas, passe um cinto ou faixa ao redor de um pé e leve essa perna o máximo possível para o lado. Esta será a sua posição inicial.","Puxe suavemente o cinto para gerar tensão na virilha e posteriores de coxa, segure por 10-20 segundos e repita do outro lado."]},
"Intermediate_Hip_Flexor_and_Quad_Stretch":{"name":"Alongamento Intermediário de Flexores do Quadril e Quadríceps","instructions":["Deite-se de bruços no chão com uma corda, cinto ou faixa passada ao redor de um pé.","Flexione o joelho e estenda o quadril da perna a alongar puxando o cinto com as duas mãos até desencostar joelho e coxa do chão; segure por 10-20 segundos e repita na outra perna."]},
"Internal_Rotation_with_Band":{"name":"Rotação Interna de Ombro com Elástico","instructions":["Prenda um elástico em um poste na altura do cotovelo e fique em pé com o lado direito voltado para o poste a alguns passos de distância.","Segure a ponta do elástico com a mão direita e pressione o cotovelo firmemente contra o lado do corpo.","Com o cotovelo flexionado a 90 graus e a mão apontando para fora do tronco, entre na posição inicial.","Execute girando o antebraço para dentro em direção ao abdômen mantendo o cotovelo fixo.","Vá o máximo que conseguir, pause e retorne à posição inicial."]},
"Inverted_Row":{"name":"Remada Invertida na Barra","instructions":["Posicione uma barra no rack (ou no Smith) na altura da cintura.","Segure a barra com pegada mais aberta que a largura dos ombros e pendure-se por baixo dela com corpo reto, calcanhares no chão e braços totalmente estendidos. Esta será a sua posição inicial.","Flexione os cotovelos puxando o peito em direção à barra e retraindo as escápulas.","Pause no topo do movimento e retorne à posição inicial.","Repita pelo número desejado de repetições."]},
"Inverted_Row_with_Straps":{"name":"Remada Invertida com Fitas de Suspensão","instructions":["Pendure fitas de suspensão ou cordas em um rack ou ponto fixo, segure as alças e posicione-se pendurado com corpo reto, calcanhares no chão e braços estendidos. Esta será a sua posição inicial.","Flexione os cotovelos puxando o peito em direção às mãos e retraindo as escápulas.","Pause no topo do movimento e retorne à posição inicial.","Repita pelo número desejado de repetições."]},
"Iron_Cross":{"name":"Cruz de Ferro (Iron Cross)","instructions":[]},
"Iron_Crosses_stretch":{"name":"Alongamento Cruz de Ferro","instructions":["Deite-se de bruços no chão com os braços abertos para os lados e palmas apoiadas no solo. Esta será a sua posição inicial.","Flexione um joelho e leve essa perna por trás do corpo tentando tocar o chão próximo à mão oposta.","Retorne rapidamente à posição inicial e repita com a outra perna, alternando por 10-20 repetições."]},
"Isometric_Chest_Squeezes":{"name":"Contração Isométrica de Peitoral","instructions":["Sentado ou em pé, dobre os braços a 90 graus e junte as palmas das mãos à frente do peito com os dedos apontando para a frente.","Pressione uma mão contra a outra contraindo o peitoral, aumentando a tensão progressivamente e respirando normalmente.","Segure pelo número recomendado de segundos.","Libere a tensão lentamente.","Descanse pelo tempo recomendado e repita."]},
"Isometric_Neck_Exercise_-_Front_And_Back":{"name":"Exercício Isométrico de Pescoço - Frente e Trás","instructions":["Com a cabeça e o pescoço em posição neutra (olhando para a frente), coloque as duas mãos na testa.","Empurre suavemente a cabeça para a frente contraindo o pescoço enquanto resiste ao movimento com as mãos, aumentando a força gradualmente e respirando normalmente.","Segure pelo número recomendado de segundos.","Libere a tensão lentamente.","Descanse pelo tempo recomendado e repita colocando as mãos na parte de trás da cabeça."]},
"Isometric_Neck_Exercise_-_Sides":{"name":"Exercício Isométrico de Pescoço - Laterais","instructions":["Com a cabeça e o pescoço em posição neutra, apoie a mão esquerda no lado esquerdo da cabeça.","Empurre suavemente a cabeça para a esquerda contraindo a lateral do pescoço enquanto resiste ao movimento com a mão, aumentando a força gradualmente e respirando normalmente.","Segure pelo número recomendado de segundos.","Libere a tensão lentamente.","Descanse pelo tempo recomendado e repita com a mão direita no lado direito da cabeça."]},
"Isometric_Wipers":{"name":"Flexão Deslocada Lateral (Isometric Wipers)","instructions":["Assuma posição de flexão de braço sustentando o peso nas mãos e pontas dos pés com o corpo reto e mãos um pouco além da largura dos ombros. Esta será a sua posição inicial.","Desloque o peso do corpo o máximo possível para um lado permitindo que o cotovelo desse lado flexione ao abaixar o corpo.","Inverta o movimento estendendo o braço flexionado para empurrar-se e deslize para o outro lado.","Repita pelo número desejado de repetições."]},
"JM_Press":{"name":"Supino JM (JM Press)","instructions":["Deite-se em um banco reto segurando uma barra em pegada fechada com braços estendidos e cotovelos fechados alinhada acima da parte superior do peito. Esta será a sua posição inicial.","Comece descendo a barra como em um tríceps testa enquanto inspira; na metade do caminho, deixe os braços recuarem cerca de uma polegada em direção ao tronco até ficarem perpendiculares a ele mantendo o ângulo dos cotovelos.","Ao expirar, empurre a barra de volta para cima usando o tríceps como em um supino fechado.","Retorne à posição inicial e reinicie o movimento.","Repita pela quantidade recomendada de repetições."]},
"Jackknife_Sit-Up":{"name":"Abdominal Canivete (Jackknife)","instructions":["Deite-se de costas no chão ou colchonete com os braços estendidos atrás da cabeça e as pernas estendidas. Esta será a sua posição inicial.","Ao expirar, flexione a cintura elevando simultaneamente pernas e braços estendidos até se encontrarem a cerca de 35-45 graus do chão, tirando a parte superior do tronco do solo.","Enquanto inspira, abaixe braços e pernas de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Janda_Sit-Up":{"name":"Abdominal Janda","instructions":["Deite-se no chão em posição de abdominal com joelhos a 90 graus, pés apoiados no chão e braços cruzados no peito ou ao lado. Esta será a sua posição inicial.","Contraindo fortemente glúteos e posteriores de coxa (para inibir os flexores do quadril), inspire fundo e suba lentamente em 3 a 6 segundos enquanto expira devagar.","Ao inspirar, retorne de forma lenta e controlada à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Jefferson_Squats":{"name":"Agachamento Jefferson","instructions":["Coloque uma barra no chão.","Posicione-se em pé sobre o centro da barra no sentido do comprimento.","Flexione os joelhos mantendo as costas retas e segure a frente da barra com a mão direita em pegada neutra (palma para a esquerda).","Segure a parte de trás da barra com a mão esquerda em pegada neutra (palma para a direita), mantendo distâncias iguais do tronco para ambas as mãos.","Levante-se totalmente ereto com o peso, pés na largura dos ombros e pontas levemente para fora.","Agache flexionando os joelhos e mantendo as costas o mais verticais possível até as coxas ficarem paralelas ao chão enquanto inspira, sem deixar os joelhos passarem dos dedos dos pés.","Impulsione com os pés para subir de volta à posição inicial mantendo os braços apenas como ganchos estendidos, fazendo a força com as coxas."]},
"Jerk_Balance":{"name":"Jerk Balance (Equilíbrio no Jerk)","instructions":["Este exercício educa a entrada baixa no jerk. Comece com a barra apoiada nos ombros, tronco ereto e pés levemente afastados em base dividida.","Inicie como em um jerk normal flexionando rapidamente os joelhos com o tronco vertical e impulsionando com força sem usar os braços para elevar a carga.","Mantenha o pé de trás fixo e avance o pé da frente em uma base dividida completa ao empurrar a barra acima da cabeça, depois junte os pés em pé."]},
"Jerk_Dip_Squat":{"name":"Agachamento Curto para Jerk (Jerk Dip)","instructions":["Comece com a barra apoiada na frente dos ombros levemente próxima à garganta, pés diretamente sob o quadril e levemente voltados para fora.","Mantendo o tronco totalmente vertical, faça uma flexão curta e controlada dos joelhos sem jogar o quadril para trás e retorne impulsionando com força pelos pés."]},
"Jogging_Treadmill":{"name":"Corrida Leve na Esteira","instructions":["Suba na esteira e selecione a opção desejada no painel (modo manual ou programa, podendo ajustar inclinação e inserir idade/peso para estimar calorias).","Mantenha postura ereta enquanto corre e segure nos apoios apenas quando necessário, como ao descer ou medir a frequência cardíaca."]},
"Keg_Load":{"name":"Carregamento de Barril (Keg Load)","instructions":["Posicione a quantidade desejada de barris a uma distância da plataforma de carregamento (geralmente 30-50 pés).","Segure a alça próxima do primeiro barril, incline-o para segurar a borda inferior oposta e levante-o até o peito.","Carregue o barril o mais alto possível no peito, desloque-se rapidamente até a plataforma e coloque-o em cima estendendo quadril, joelhos e tornozelos.","Retorne ao ponto inicial para pegar o próximo barril e repita até finalizar a prova."]},
"Kettlebell_Arnold_Press":{"name":"Desenvolvimento Arnold com Kettlebell","instructions":["Faça o clean de um kettlebell até o ombro estendendo pernas e quadril, mantendo a palma voltada para dentro.","Olhando para a frente, empurre o kettlebell acima da cabeça girando o punho para que a palma fique voltada para a frente no topo.","Retorne o kettlebell à posição inicial com a palma voltada para dentro."]},
"Kettlebell_Dead_Clean":{"name":"Dead Clean com Kettlebell","instructions":["Coloque um kettlebell entre os pés, empurre o quadril para trás e olhe à frente para entrar na posição inicial.","Faça o clean do kettlebell até o ombro estendendo pernas e quadril enquanto gira o punho.","Abaixe o kettlebell de volta ao chão mantendo costas retas, quadril para trás e posteriores de coxa tensionados."]},
"Kettlebell_Figure_8":{"name":"Figura 8 com Kettlebell","instructions":["Coloque um kettlebell entre as pernas em base mais larga que os ombros, empurre o quadril para trás e mantenha as costas retas.","Pegue o kettlebell e passe-o para a outra mão por entre as pernas (a mão receptora alcança por trás das pernas), alternando continuamente em formato de oito."]},
"Kettlebell_Halo":{"name":"Halo com Kettlebell","instructions":["Fique ereto com os pés na largura do quadril segurando um kettlebell invertido pelas laterais da alça junto ao peito, com abdômen e glúteos contraídos. Esta é a sua posição inicial.","Mantendo os cotovelos próximos à cabeça, passe o kettlebell por cima de uma orelha e ao redor por trás da nuca.","Continue o círculo passando pela orelha oposta de volta à frente do peito, mantendo o peso próximo ao corpo o tempo todo.","Complete o número prescrito de voltas em um sentido e depois repita o mesmo número no sentido oposto.","Mova-se devagar mantendo cabeça, quadril e lombar imóveis; reduza o peso se a lombar arquear."]},
"Kettlebell_Halo_With_Overhead_Extension":{"name":"Halo com Extensão Acima da Cabeça com Kettlebell","instructions":["Fique ereto com os pés na largura do quadril segurando um kettlebell invertido pelas laterais da alça junto ao peito, com abdômen e glúteos contraídos. Esta é a sua posição inicial.","Mantendo os cotovelos próximos à cabeça, passe o kettlebell por cima de uma orelha até posicioná-lo atrás da cabeça e pause.","Dessa posição, estenda os cotovelos empurrando o kettlebell diretamente acima da cabeça até esticar os braços.","Flexione os cotovelos para abaixar o kettlebell de volta atrás da cabeça sob controle.","Continue o círculo passando pela orelha oposta até retornar à frente do peito para completar uma repetição.","Alterne o sentido do círculo a cada repetição mantendo cabeça, quadril e lombar imóveis."]},
"Kettlebell_Hang_Clean":{"name":"Hang Clean com Kettlebell","instructions":["Coloque o kettlebell entre os pés, empurre o quadril para trás e olhe para a frente para entrar na posição inicial.","Faça o clean do kettlebell até o ombro estendendo pernas e quadril enquanto gira o punho.","Abaixe o kettlebell para a posição suspensa entre as pernas mantendo os posteriores tensionados e a cabeça erguida o tempo todo."]},
"Kettlebell_One-Legged_Deadlift":{"name":"Levantamento Terra Unilateral com Kettlebell","instructions":["Segure um kettlebell em uma mão apoiado apenas na perna do mesmo lado.","Com leve flexão no joelho de apoio, execute um levantamento terra romeno flexionando o quadril e estendendo a perna livre atrás para equilíbrio.","Abaixe o kettlebell até o tronco ficar paralelo ao chão e retorne à posição ereta."]},
"Kettlebell_Overhead_Triceps_Extension":{"name":"Tríceps Francês com Kettlebell","instructions":["Fique em pé com os pés na largura do quadril, segure um kettlebell pelas laterais da alça com as duas mãos e empurre-o acima da cabeça com os braços estendidos.","Contraia o abdômen e mantenha os braços verticais próximos à cabeça. Esta é a sua posição inicial.","Flexione os cotovelos abaixando o kettlebell atrás da cabeça até o limite confortável sem abrir os cotovelos para fora.","Estenda os cotovelos empurrando o kettlebell de volta à posição inicial mantendo a parte superior dos braços imóvel.","Mantenha as costelas baixas e evite arquear a lombar durante a extensão."]},
"Kettlebell_Pass_Between_The_Legs":{"name":"Passagem de Kettlebell Entre as Pernas","instructions":["Coloque um kettlebell entre as pernas em base confortável, empurre o quadril para trás e mantenha as costas retas.","Pegue o kettlebell e passe-o para a outra mão por entre as pernas em trajeto de \"W\", alternando continuamente por várias repetições."]},
"Kettlebell_Pirate_Ships":{"name":"Balanço Lateral com Kettlebell (Pirate Ships)","instructions":["Com base bem aberta, segure um kettlebell com as duas mãos na altura da cintura com os braços estendidos. Esta será a sua posição inicial.","Inicie girando para um lado e balançando o kettlebell até a altura da cabeça, pausando brevemente no topo.","Deixe o kettlebell descer enquanto gira para o lado oposto elevando-o novamente até a altura da cabeça.","Repita pela quantidade desejada de repetições."]},
"Kettlebell_Pistol_Squat":{"name":"Agachamento Pistol com Kettlebell","instructions":["Segure um kettlebell pelas laterais da alça junto ao peito com as duas mãos, tire uma perna do chão e equilibre-se na outra.","Agache flexionando o joelho da perna de apoio e jogando o quadril para trás enquanto sustenta o kettlebell à frente.","Segure em baixo por um segundo e inverta o movimento empurrando pelo calcanhar com cabeça e peito erguidos.","Abaixe-se novamente e repita."]},
"Kettlebell_Seated_Press":{"name":"Desenvolvimento Sentado no Chão com Kettlebell","instructions":["Sente-se no chão e afaste confortavelmente as pernas à frente.","Faça o clean de um kettlebell até o ombro.","Empurre o kettlebell para cima e ligeiramente para o lado até travar o braço acima da cabeça e retorne à posição inicial."]},
"Kettlebell_Seesaw_Press":{"name":"Desenvolvimento Gangorra com Kettlebells","instructions":["Faça o clean de dois kettlebells até os ombros.","Empurre um kettlebell acima da cabeça.","Abaixe esse kettlebell enquanto empurra imediatamente o outro, garantindo a mesma quantidade de repetições para ambos os lados."]},
"Kettlebell_Sumo_High_Pull":{"name":"Puxada Alta Sumô com Kettlebell","instructions":["Coloque um kettlebell no chão entre os pés bem afastados, segure-o com as duas mãos, jogue o quadril bem para trás com joelhos flexionados e mantenha peito e cabeça erguidos. Esta será a sua posição inicial.","Estenda quadril e joelhos puxando simultaneamente o kettlebell até a altura dos ombros com os cotovelos altos e retorne à posição inicial."]},
"Kettlebell_Thruster":{"name":"Thruster com Kettlebells","instructions":["Faça o clean de dois kettlebells até os ombros estendendo pernas e quadril enquanto gira os punhos. Esta será a sua posição inicial.","Agache flexionando quadril e joelhos entre as pernas o mais baixo possível mantendo as costas retas e o tronco ereto.","No fundo, inverta com força empurrando pelos calcanhares e aproveite o impulso do agachamento para empurrar ambos os kettlebells acima da cabeça até estender os braços.","Para iniciar a repetição seguinte, retorne os kettlebells aos ombros."]},
"Kettlebell_Turkish_Get-Up_Lunge_style":{"name":"Turkish Get-Up com Kettlebell (Estilo Avanço)","instructions":["Deite-se de costas no chão e empurre um kettlebell para cima estendendo o cotovelo, com o joelho do mesmo lado flexionado e pé no chão.","Mantendo o braço com o kettlebell sempre estendido, apoie-se no braço livre passando à posição sentada e depois ajoelhando a perna oposta em posição de avanço.","Mantendo o olhar fixo no kettlebell, levante-se devagar, depois inverta todo o trajeto de volta ao chão e repita."]},
"Kettlebell_Turkish_Get-Up_Squat_style":{"name":"Turkish Get-Up com Kettlebell (Estilo Agachamento)","instructions":["Deite-se de costas no chão e empurre um kettlebell para cima estendendo o cotovelo, com o joelho do mesmo lado flexionado.","Mantendo o kettlebell sempre estendido acima, apoie-se no braço livre passando à posição sentada e trazendo a perna de apoio para base de agachamento.","Apoiando-se nos pés enquanto olha para o kettlebell, levante-se devagar, depois inverta todo o trajeto de volta à posição inicial e repita."]},
"Kettlebell_Windmill":{"name":"Moinho com Kettlebell","instructions":["Coloque um kettlebell à frente do pé dianteiro e faça um clean e desenvolvimento acima da cabeça com outro kettlebell no braço oposto.","Mantendo o braço elevado sempre estendido e os olhos no kettlebell acima da cabeça, empurre o quadril para esse lado com os pés a 45 graus e incline o tronco lateralmente até tocar o chão com a mão livre.","Pause um segundo ao tocar o chão e inverta o movimento de volta à posição inicial."]},
"Kipping_Muscle_Up":{"name":"Muscle Up com Kipping nas Argolas","instructions":["Segure as argolas com pegada falsa (base das palmas apoiada sobre as argolas).","Inicie balançando as pernas levemente para trás.","Contragolpeie balançando as pernas para a frente e para cima enquanto puxa o corpo com os dois braços; ao chegar ao topo da puxada, traga as argolas às axilas e role os ombros à frente levando os cotovelos para trás para entrar na posição de mergulho.","Mantendo controle e estabilidade, estenda os cotovelos para finalizar o movimento no topo.","Desça com cuidado de volta ao chão."]},
"Knee_Across_The_Body":{"name":"Alongamento Joelho Cruzado sobre o Corpo","instructions":["Deite-se de costas com a perna direita estendida; flexione a perna esquerda e leve o joelho cruzando sobre o corpo em direção ao chão segurando-o com a mão direita.","Estenda o braço esquerdo ao lado e vire a cabeça para a esquerda, mantendo os ombros relaxados no chão para alongar a lombar. Depois troque de lado."]},
"Knee_Circles":{"name":"Círculos com os Joelhos","instructions":["Fique em pé com as pernas juntas e as mãos na cintura.","Faça movimentos circulares com os joelhos enquanto respira normalmente.","Repita pela quantidade recomendada de repetições."]},
"Knee_Hip_Raise_On_Parallel_Bars":{"name":"Elevação de Pernas nas Paralelas (Cadeira Abdominal)","instructions":["Posicione-se no aparelho de elevação vertical apoiando os antebraços nos suportes e segurando as alças com os cotovelos a 90 graus.","Mantenha o tronco reto, a lombar pressionada no encosto e as pernas estendidas para baixo. Esta será a sua posição inicial.","Ao expirar, eleve as pernas estendidas até ficarem paralelas ao chão e segure a contração por um segundo sem usar impulso ou balanço.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Knee_Tuck_Jump":{"name":"Salto Agrupado (Knee Tuck Jump)","instructions":["Comece em pé com os joelhos levemente flexionados e as mãos à frente na altura do peito com palmas para baixo. Esta será a sua posição inicial.","Desça rapidamente em um quarto de agachamento e exploda para cima puxando os joelhos em direção ao peito para tentar encostá-los nas palmas das mãos.","Salte o mais alto possível e estenda as pernas para aterrissar suavemente amortecendo com os joelhos."]},
"Kneeling_Arm_Drill":{"name":"Exercício de Braços Ajoelhado para Corrida","instructions":["Ajoelhe-se com o pé esquerdo à frente e o joelho direito no chão, pressionando o calcanhar da frente para ativar glúteos e posteriores.","Inicie balançando os braços em pêndulo amplo e feche o ângulo dos cotovelos acelerando progressivamente do ritmo de trote até o de sprint.","Assim que as mãos passarem pelo quadril, acelere-as para a frente o mais rápido possível.","Troque os joelhos e repita."]},
"Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists":{"name":"Abdominal Ajoelhado no Cabo com Rotação Alternada","instructions":["Prenda uma corda na polia alta e coloque um colchonete no chão à frente dela.","Segure a corda com as duas mãos e ajoelhe-se cerca de dois pés atrás da torre.","Posicione a corda atrás da cabeça com as mãos ao lado das orelhas.","Mantendo as mãos fixas, contraia o abdômen e puxe para baixo em movimento de abdominal até os cotovelos chegarem aos joelhos.","Pause brevemente em baixo e suba de forma lenta e controlada até a posição inicial.","Repita a descida até a metade do caminho e então gire levando um cotovelo em direção ao joelho oposto.","Pause brevemente em baixo e retorne de forma controlada à posição inicial.","Repita o movimento girando o outro cotovelo em direção ao joelho oposto.","Continue alternando essa sequência até a falha."]},
"Kneeling_Cable_Triceps_Extension":{"name":"Extensão de Tríceps Ajoelhado no Cabo","instructions":["Posicione um banco transversalmente à frente de uma polia alta.","Segure a barra reta acima da cabeça com pegada pronada e mãos afastadas cerca de 6 polegadas.","Ajoelhe-se de costas para a máquina.","Apoie a cabeça e a parte posterior dos braços sobre o banco, mantendo os cotovelos dobrados com os antebraços apontando para a polia alta. Esta será a sua posição inicial.","Mantendo os braços próximos à cabeça e os cotovelos fechados, empurre a barra em semicírculo até estender totalmente os braços paralelos ao chão, contraindo o tríceps por um segundo enquanto expira.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Kneeling_Forearm_Stretch":{"name":"Alongamento de Antebraços Ajoelhado","instructions":["Ajoelhe-se em um colchonete apoiando as palmas das mãos no chão com os dedos apontando para trás em direção aos joelhos.","Incline-se lentamente para trás mantendo as palmas firmes no chão até sentir alongar punhos e antebraços; segure por 20-30 segundos."]},
"Kneeling_High_Pulley_Row":{"name":"Remada Ajoelhado na Polia Alta","instructions":["Prenda uma corda em uma polia acima da cabeça, selecione a carga e ajoelhe-se alguns pés atrás segurando a corda à frente com ambos os braços estendidos. Esta será a sua posição inicial.","Inicie flexionando os cotovelos e retraindo totalmente os ombros, puxando a corda em direção à parte superior do peito com os cotovelos abertos.","Após pausar brevemente, retorne lentamente à posição inicial."]},
"Kneeling_Hip_Flexor":{"name":"Alongamento de Flexores do Quadril Ajoelhado","instructions":["Ajoelhe-se em um colchonete apoiando o pé direito à frente no chão e estendendo a perna esquerda atrás com o peito do pé no solo.","Transfira o peso para a frente até sentir o alongamento no quadril; segure por 15 segundos e depois repita para o outro lado."]},
"Kneeling_Jump_Squat":{"name":"Agachamento com Salto de Joelhos (Kneeling Jump)","instructions":["Ajoelhe-se no chão usando o peso corporal ou com uma barra apoiada na parte posterior dos ombros dentro de um power rack.","Sente-se para trás até os glúteos encostarem nos calcanhares mantendo cabeça e peito erguidos.","Exploda o quadril para cima gerando impulso suficiente para aterrissar com os dois pés firmes no chão.","Continue o agachamento empurrando pelos calcanhares e estendendo os joelhos até ficar em pé."]},
"Kneeling_Single-Arm_High_Pulley_Row":{"name":"Remada Unilateral Ajoelhado na Polia Alta","instructions":["Prenda um pegador unilateral em uma polia alta e selecione o peso.","Ajoelhe-se em frente à torre segurando o cabo com uma mão e braço estendido. Esta será a sua posição inicial.","Começando com a palma para a frente, puxe o peso em direção ao tronco flexionando o cotovelo e retraindo a escápula, girando o punho para que a palma termine voltada para você.","Após uma breve pausa, retorne à posição inicial."]},
"Kneeling_Squat":{"name":"Agachamento Ajoelhado com Barra","instructions":["Ajuste a barra na altura adequada em um power rack e ajoelhe-se atrás dela (use um colchonete sob os joelhos). Apoie a barra na parte posterior dos ombros com escápulas retraídas e retire-a do suporte.","Olhando para a frente, sente-se para trás levando os glúteos até tocarem as panturrilhas.","Inverta o movimento retornando o tronco à posição vertical."]},
"Landmine_180s":{"name":"Rotação Landmine 180°","instructions":["Encaixe uma barra no landmine (ou apoie firmemente no canto de paredes) e carregue o peso adequado.","Eleve a ponta da barra até a altura dos ombros segurando com as duas mãos e braços estendidos à frente em base bem aberta. Esta será a sua posição inicial.","Execute girando tronco e quadril para balançar a barra até o lado esquerdo/direito mantendo os braços sempre estendidos.","Inverta o movimento balançando a barra até o lado oposto.","Continue alternando até concluir a série."]},
"Landmine_Linear_Jammer":{"name":"Empurrão Explosivo no Landmine (Jammer)","instructions":["Encaixe uma barra no landmine (ou canto seguro) com carga adequada e pegador acoplado.","Eleve a barra do chão levando o pegador até os ombros. Esta será a sua posição inicial.","Em postura atlética, agache levemente jogando o quadril para trás mantendo os braços flexionados.","Inverta de forma explosiva estendendo quadril, joelhos e tornozelos enquanto empurra a barra estendendo totalmente os braços.","Retorne à posição inicial."]},
"Lateral_Bound":{"name":"Salto Lateral Unilateral (Lateral Bound)","instructions":["Assuma posição de meio agachamento virado a 90 graus da direção do deslocamento. Esta será a sua posição inicial.","Transfira o peso para a perna externa realizando leve contramovimento.","Impulsione imediatamente saltando para o lado o mais longe possível.","Ao aterrissar, impulsione imediatamente na direção oposta retornando ao ponto inicial.","Continue indo e voltando por várias repetições."]},
"Lateral_Box_Jump":{"name":"Salto Lateral na Caixa","instructions":["Fique em pé em postura confortável ao lado de uma caixa baixa. Esta será a sua posição inicial.","Faça um quarto de agachamento rápido e inverta imediatamente saltando para cima e para o lado.","Eleve bem os joelhos para garantir que os pés ultrapassem a borda da caixa.","Aterrisse no centro da caixa amortecendo o impacto com as pernas.","Salte com cuidado para o outro lado da caixa e continue alternando de um lado para o outro."]},
"Lateral_Cone_Hops":{"name":"Saltos Laterais sobre Cones","instructions":["Alinhe vários cones em fila espaçados por alguns pés.","Fique ao lado da fila de cones virado a 90 graus da direção do deslocamento. Esta será a sua posição inicial.","Flexione levemente os joelhos e salte imediatamente para cima e para o lado por cima do primeiro cone.","Amorteça a aterrissagem com as pernas e rebata em seguida para saltar os próximos cones até o final da fila."]},
"Lateral_Raise_-_With_Bands":{"name":"Elevação Lateral com Elástico","instructions":["Pise no centro de um elástico gerando tensão com os braços estendidos ao lado das coxas, costas retas e leve flexão nos cotovelos. Esta será a sua posição inicial.","Use os deltoides laterais para elevar as alças para os lados enquanto expira até ficarem pouco acima do paralelo ao chão, segurando um segundo no topo.","Abaixe lentamente as alças de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Latissimus_Dorsi-SMR":{"name":"Liberação Miofascial do Grande Dorsal","instructions":["Deitado de lado no chão, posicione um rolo de espuma sob a lateral das costas logo atrás da axila. Esta será a sua posição inicial.","Estenda o braço do lado trabalhado para trás e transfira o peso do corpo sobre o rolo mantendo o tronco desencostado do chão; segure por 10-30 segundos e troque de lado."]},
"Leg-Over_Floor_Press":{"name":"Supino no Chão com Perna Cruzada e Kettlebell","instructions":["Deite-se no chão segurando um kettlebell pela alça apoiado no peito, cruze a perna do lado ativo sobre a outra perna e estenda o braço livre ao lado para apoio.","Empurre o kettlebell para cima até travar o braço.","Abaixe o peso até o cotovelo encostar no chão mantendo o kettlebell acima do cotovelo e repita pelo número desejado de repetições."]},
"Leg-Up_Hamstring_Stretch":{"name":"Alongamento de Posteriores com Perna Elevada","instructions":["Deite-se de costas, flexione um joelho apoiando o pé no chão para estabilizar a coluna.","Estenda a outra perna para cima tentando apontar a sola do pé para o teto.","Estenda o joelho o máximo possível e puxe suavemente a perna em direção ao rosto; depois troque de lado."]},
"Leg_Extensions":{"name":"Cadeira Extensora","instructions":["Selecione a carga na cadeira extensora e sente-se posicionando as pernas sob o rolo acolchoado (logo acima dos pés) com as mãos nas alças laterais, formando 90 graus nos joelhos. Esta será a sua posição inicial.","Usando o quadríceps, estenda totalmente as pernas enquanto expira mantendo o resto do corpo imóvel no banco e pause um segundo no topo.","Abaixe lentamente o peso de volta à posição inicial enquanto inspira, sem ultrapassar o ângulo de 90 graus.","Repita pela quantidade recomendada de repetições."]},
"Leg_Lift":{"name":"Extensão de Perna em Pé (Posterior/Glúteo)","instructions":["Fique em pé com os pés na largura dos ombros segurando um apoio firme como um rack ou o encosto de uma cadeira.","Com ou sem caneleira, eleve uma perna para trás mantendo a outra perna estendida enquanto expira.","Retorne lentamente o pé elevado ao chão enquanto inspira.","Repita pela quantidade recomendada de repetições.","Execute o mesmo movimento com a perna oposta."]},
"Leg_Press":{"name":"Leg Press 45°","instructions":["Sente-se no aparelho de leg press e apoie os pés na plataforma na largura dos ombros.","Destrave as barras de segurança e empurre a plataforma até quase estender totalmente as pernas sem travar os joelhos, formando 90 graus entre tronco e pernas. Esta será a sua posição inicial.","Enquanto inspira, desça lentamente a plataforma até formar um ângulo de 90 graus nos joelhos.","Empurrando principalmente pelos calcanhares com força do quadríceps, retorne à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições e lembre-se de travar bem os pinos de segurança ao finalizar."]},
"Leg_Pull-In":{"name":"Abdominal Puxada de Pernas no Solo","instructions":["Deite-se em um colchonete com as pernas estendidas e as mãos ao lado do corpo com palmas para baixo ou sob os glúteos. Esta será a sua posição inicial.","Flexione os joelhos e puxe as coxas em direção ao abdômen enquanto expira até os joelhos chegarem à altura do peito, mantendo as canelas paralelas ao chão e segurando um segundo no topo.","Retorne à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Leverage_Chest_Press":{"name":"Supino Articulado na Máquina","instructions":["Carregue o peso adequado nos pinos e ajuste o assento para que os pegadores fiquem alinhados à parte inferior ou média do peitoral.","Mantenha peito e cabeça erguidos e escápulas retraídas. Esta será a sua posição inicial.","Empurre os pegadores à frente estendendo os cotovelos.","Após uma breve pausa no topo, retorne até quase tocar o batente para manter a tensão muscular contínua até o fim da série."]},
"Leverage_Deadlift":{"name":"Levantamento Terra na Máquina Articulada","instructions":["Carregue os pinos com a carga adequada, posicione-se entre os pegadores inferiores, segure-os firme e abaixe o quadril inspirando com cabeça erguida e peito aberto. Esta será a posição inicial.","Estenda pernas e quadril para levantar a carga e depois retorne o peso de volta à posição inicial."]},
"Leverage_Decline_Chest_Press":{"name":"Supino Declinado na Máquina Articulada","instructions":["Carregue o peso adequado nos pinos, ajuste o assento para alinhar os pegadores à parte inferior do peitoral e mantenha peito erguido e escápulas retraídas. Esta será a posição inicial.","Empurre os pegadores à frente estendendo os cotovelos.","Após uma breve pausa no topo, retorne até pouco antes do batente para manter tensão contínua nos músculos até concluir a série."]},
"Leverage_High_Row":{"name":"Remada Alta na Máquina Articulada","instructions":["Carregue os pinos com peso adequado, ajuste o assento e o apoio de joelhos e segure os pegadores superiores com pegada pronada. Esta será a sua posição inicial.","Puxe os pegadores em direção ao tronco retraindo as escápulas e flexionando os cotovelos.","Pause no ponto final da puxada e retorne lentamente os pegadores à posição inicial.","Evite apoiar totalmente o peso no descanso entre repetições para manter tensão constante nos músculos."]},
"Leverage_Incline_Chest_Press":{"name":"Supino Inclinado na Máquina Articulada","instructions":["Carregue o peso adequado nos pinos, ajuste o assento para alinhar os pegadores à parte superior do peitoral e mantenha peito erguido e escápulas retraídas. Esta será a sua posição inicial.","Empurre os pegadores à frente estendendo os cotovelos.","Após uma breve pausa no topo, retorne até pouco antes do batente para manter tensão contínua nos músculos até o fim da série."]},
"Leverage_Iso_Row":{"name":"Remada Unilateral/Iso na Máquina Articulada","instructions":["Carregue o peso adequado nos pinos, ajuste o assento na altura do peito e segure os pegadores com pegada neutra ou pronada. Esta será a sua posição inicial.","Puxe os pegadores em direção ao tronco retraindo as escápulas enquanto flexiona os cotovelos.","Pause no ponto final da puxada e retorne lentamente, evitando encostar totalmente o peso no batente entre repetições para manter a tensão muscular."]},
"Leverage_Shoulder_Press":{"name":"Desenvolvimento na Máquina Articulada","instructions":["Carregue o peso adequado nos pinos, ajuste o assento para alinhar os pegadores ao topo dos ombros e segure-os com pegada pronada, mantendo peito e cabeça erguidos. Esta será a sua posição inicial.","Empurre os pegadores para cima estendendo os cotovelos.","Após uma breve pausa no topo, retorne até pouco antes do batente para manter tensão contínua nos músculos até concluir a série."]},
"Leverage_Shrug":{"name":"Encolhimento na Máquina Articulada","instructions":["Carregue os pinos com peso adequado e posicione-se diretamente entre os pegadores.","Segure os pegadores superiores, abaixe o quadril inspirando, olhe para a frente e mantenha o peito aberto.","Empurre o chão pelos calcanhares estendendo quadril e joelhos até ficar em pé com os braços estendidos e ombros encaixados para trás. Esta será a sua posição inicial.","Eleve o peso encolhendo os ombros em direção às orelhas em linha reta vertical.","Pause no topo do movimento e depois retorne à posição inicial."]},
"Linear_3-Part_Start_Technique":{"name":"Técnica de Largada Linear em 3 Partes","instructions":["Comece com os dois pés na linha de partida: ponta do pé esquerdo ao lado do tornozelo direito e pé direito 4-6 polegadas atrás do esquerdo.","Apoie a mão direita na linha e aproxime o nariz do joelho esquerdo.","Agache inclinando-se à frente com a cabeça abaixo do quadril e o peso apoiado na perna esquerda. Esta será a sua posição inicial.","Eleve a mão esquerda paralela ao chão apontando para trás e arranque em explosão quando estiver pronto."]},
"Linear_Acceleration_Wall_Drill":{"name":"Treino de Aceleração Linear na Parede","instructions":["Incline-se a cerca de 45 graus contra uma parede com os pés juntos e os glúteos contraídos.","Eleve rapidamente o joelho direito, pause e empurre o pé diretamente para baixo contra o chão.","Troque de perna elevando o joelho esquerdo e atacando o chão verticalmente.","Repita mais uma vez com a perna direita e, assim que tocar o chão, alterne esquerda e direita o mais rápido possível."]},
"Linear_Depth_Jump":{"name":"Salto em Profundidade Linear","instructions":["Posicione duas caixas ou bancos afastados por alguns pés e suba em uma delas de frente para a outra.","Deixe-se cair suavemente no chão entre as plataformas flexionando joelhos e quadril.","Inverta imediatamente o movimento saltando com explosão ao estender quadril, joelhos e tornozelos para subir na outra plataforma.","Aterrisse suavemente amortecendo o impacto com as pernas."]},
"Log_Lift":{"name":"Levantamento de Tronco (Log Lift)","instructions":["Fique em pé diante do tronco, segure as alças e faça o clean puxando-o bem alto contra o peito enquanto estende quadril e joelhos.","Incline a cabeça para trás criando apoio no peito, faça uma leve flexão de joelhos e impulsione em push press estendendo os braços acima da cabeça enquanto projeta a cabeça à frente.","Repita o máximo de vezes possível, controlando a descida do tronco ao retorná-lo ao chão."]},
"London_Bridges":{"name":"Descida na Corda sobre Barra (London Bridges)","instructions":["Prenda uma corda de escalada em uma viga alta e posicione abaixo dela a barra do Smith travada nos pinos de segurança (ou uma caixa firme).","Fique em pé sobre a barra segurando a corda para equilibrar-se. Esta será a sua posição inicial.","Mantendo o corpo reto, incline-se para trás e desça lentamente alternando as mãos na corda até ficar perpendicular ao chão.","Mantendo o corpo reto, inverta o movimento subindo mão sobre mão na corda até retornar à posição inicial."]},
"Looking_At_Ceiling":{"name":"Alongamento Olhando para o Teto","instructions":["Ajoelhe-se no chão segurando os calcanhares com as duas mãos.","Eleve os glúteos para cima e para a frente enquanto inclina a cabeça para trás olhando para o teto, arqueando as costas."]},
"Low_Cable_Crossover":{"name":"Crossover na Polia Baixa","instructions":["Posicione as polias no nível mais baixo, selecione a carga e segure um pegador em cada mão.","Dê um passo à frente gerando tensão nos cabos com os braços estendidos abaixo da cintura e palmas voltadas para a frente. Esta será a sua posição inicial.","Com leve flexão nos braços, eleve as mãos para cima e para o centro à frente do peito até se encontrarem com as palmas voltadas para cima.","Após uma breve pausa, retorne os braços à posição inicial."]},
"Low_Cable_Triceps_Extension":{"name":"Extensão de Tríceps Deitado na Polia Baixa","instructions":["Selecione a carga e deite-se de costas no banco de uma remada baixa com corda acoplada, com a cabeça voltada para a polia.","Segure as pontas da corda com pegada neutra (palmas frente a frente).","Posicione os cotovelos a 90 graus com a parte superior dos braços perpendicular ao tronco apontando para o teto e antebraços apontando para a polia. Esta será a sua posição inicial.","Ao expirar, estenda os antebraços até ficarem verticais mantendo braços e cotovelos imóveis, e contraia o tríceps por um segundo.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Low_Pulley_Row_To_Neck":{"name":"Remada para o Pescoço na Polia Baixa","instructions":["Sente-se na máquina de remada baixa com uma corda acoplada.","Segure as pontas da corda com pegada pronada, costas eretas quase verticais, joelhos levemente flexionados e braços estendidos à frente. Esta será a sua posição inicial.","Mantendo o tronco imóvel, puxe a corda em direção ao pescoço enquanto expira, elevando e abrindo os cotovelos com os braços paralelos ao chão até as mãos ficarem próximas às orelhas.","Após segurar por um segundo na contração, retorne lentamente à posição inicial enquanto inspira sem mover o tronco.","Repita pela quantidade recomendada de repetições."]},
"Lower_Back-SMR":{"name":"Liberação Miofascial da Lombar","instructions":["Sentado, posicione um rolo de espuma sob a lombar, cruze os braços à frente e projete os ombros à frente. Esta será a sua posição inicial.","Eleve o quadril do chão apoiando o peso na lombar, incline-se levemente para um lado para trabalhar a musculatura lateral à coluna e deslize segurando pontos de tensão por 10-30 segundos; depois repita do outro lado."]},
"Lower_Back_Curl":{"name":"Extensão Lombar no Chão","instructions":["Deite-se de bruços no chão com os braços abertos para os lados. Esta será a sua posição inicial.","Usando a musculatura lombar, estenda a coluna tirando o peito do chão sem empurrar com os braços e mantendo a cabeça erguida. Repita 10-20 vezes."]},
"Lunge_Pass_Through":{"name":"Avanço com Passagem de Kettlebell","instructions":["Fique em pé com o tronco ereto segurando um kettlebell na mão direita. Esta será a sua posição inicial.","Dê um passo à frente com o pé esquerdo e desça em avanço flexionando quadril e joelhos até o joelho de trás quase tocar o chão mantendo o tronco ereto.","No fundo do avanço, passe o kettlebell por baixo da coxa da frente para a outra mão.","Empurrando pelo calcanhar do pé da frente, retorne à posição inicial.","Repita pela quantidade recomendada alternando as pernas."]},
"Lunge_Sprint":{"name":"Avanço com Troca em Salto no Smith (Lunge Sprint)","instructions":["Ajuste a barra do Smith na altura dos ombros, apoie-a na parte posterior dos ombros, destrave-a e posicione um pé à frente e outro atrás. Esta será a sua posição inicial.","Desça o joelho de trás quase até o chão flexionando os joelhos.","No ponto mais baixo, impulsione explosivamente pelo calcanhar da frente saltando e trocando a posição das pernas no ar.","Repita pela quantidade recomendada de repetições."]},
"Lying_Bent_Leg_Groin":{"name":"Alongamento de Virilha Deitado com Joelhos Flexionados","instructions":["Deite-se de costas com os joelhos flexionados e as solas dos pés unidas enquanto seu parceiro segura seus joelhos. Esta será a sua posição inicial.","Tente fechar os joelhos um contra o outro enquanto seu parceiro impede o movimento.","Após 10-20 segundos, relaxe os músculos enquanto seu parceiro empurra suavemente os joelhos em direção ao chão, avisando quando o alongamento estiver adequado."]},
"Lying_Cable_Curl":{"name":"Rosca Deitada no Cabo","instructions":["Segure uma barra reta ou barra W acoplada à polia baixa com pegada supinada (palmas para cima) na largura dos ombros.","Deite-se de costas em um colchonete à frente da torre com os pés apoiados na estrutura da máquina e pernas estendidas.","Mantenha os braços estendidos com leve flexão e os cotovelos próximos ao corpo. Esta será a sua posição inicial.","Mantendo braços imóveis e cotovelos colados ao tronco, flexione os cotovelos puxando a barra em direção ao peito enquanto expira e contrai o bíceps.","Após segurar a contração por um segundo no topo, retorne lentamente à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Lying_Cambered_Barbell_Row":{"name":"Remada Deitado no Banco com Barra Curvada","instructions":["Posicione uma barra curvada (cambered bar) sob um banco reto.","Deite-se de bruços no banco e segure a barra com pegada pronada mais aberta que a largura dos ombros. Esta será a sua posição inicial.","Ao expirar, puxe a barra para cima mantendo os cotovelos próximos ao corpo em direção ao peito ou ao abdômen conforme a ênfase.","Após segurar um segundo no topo, abaixe lentamente de volta à posição inicial enquanto inspira."]},
"Lying_Close-Grip_Bar_Curl_On_High_Pulley":{"name":"Rosca Deitada na Polia Alta - Pegada Fechada","instructions":["Posicione um banco reto à frente de uma polia alta.","Segure a barra reta com pegada supinada (palmas para cima) na largura dos ombros.","Deite-se de costas com a cabeça na extremidade do banco.","Estenda os braços verticalmente acima dos ombros formando 90 graus com o tronco e mantendo os cotovelos fechados. Esta será a sua posição inicial.","Ao expirar, flexione os cotovelos puxando a barra em semicírculo até tocar o queixo e segure a contração do bíceps por um segundo, movendo apenas os antebraços.","Retorne lentamente à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head":{"name":"Tríceps Testa Deitado Atrás da Cabeça com Barra","instructions":["Segurando uma barra reta ou barra W com pegada pronada fechada, deite-se de costas em um banco reto com a cabeça próxima à extremidade.","Estenda os braços à frente e leve a barra em semicírculo até posicioná-la atrás da cabeça paralela ao chão, mantendo os cotovelos fechados. Esta será a sua posição inicial.","Enquanto inspira, abaixe a barra flexionando os cotovelos e mantendo a parte superior dos braços imóvel até os antebraços ficarem perpendiculares ao chão.","Ao expirar, empurre a barra de volta à posição inicial em semicírculo até os braços ficarem paralelos ao chão e contraia o tríceps por um segundo.","Repita pela quantidade recomendada de repetições."]},
"Lying_Close-Grip_Barbell_Triceps_Press_To_Chin":{"name":"Tríceps Testa até o Queixo com Barra","instructions":["Segurando uma barra reta ou barra W com pegada pronada fechada, deite-se de costas em um banco reto com a cabeça fora da extremidade.","Estenda os braços acima do peito perpendiculares ao tronco. Esta será a sua posição inicial.","Enquanto inspira, abaixe a barra em semicírculo flexionando os cotovelos e mantendo braços imóveis e cotovelos fechados até tocar levemente o queixo.","Ao expirar, empurre a barra de volta à posição inicial movendo apenas os antebraços e contraia forte o tríceps por um segundo.","Repita pela quantidade recomendada de repetições."]},
"Lying_Crossover":{"name":"Alongamento Lombar Cruzado Deitado","instructions":["Deite-se de costas com as pernas estendidas.","Cruze uma perna dobrada sobre o corpo tentando levar o joelho ao chão enquanto seu parceiro segura seu ombro no chão e controla o joelho cruzado. Esta será a sua posição inicial.","Tente empurrar o joelho dobrado para cima enquanto seu parceiro impede o movimento.","Após 10-20 segundos, relaxe a perna deixando seu parceiro pressionar suavemente o joelho em direção ao chão; depois repita do outro lado."]},
"Lying_Dumbbell_Tricep_Extension":{"name":"Tríceps Testa Deitado com Halteres","instructions":["Deite-se em um banco reto segurando dois halteres diretamente acima dos ombros com braços estendidos a 90 graus, palmas voltadas para dentro e cotovelos fechados. Esta é a posição inicial.","Enquanto inspira e mantém a parte superior dos braços imóvel, abaixe lentamente os halteres até ficarem próximos às orelhas.","Mantendo os cotovelos fechados e braços imóveis, use o tríceps para estender os halteres de volta à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Lying_Face_Down_Plate_Neck_Resistance":{"name":"Extensão de Pescoço Deitado de Bruços com Anilha","instructions":["Deite-se de bruços em um banco reto com ombros, pescoço e cabeça para fora da borda, segurando uma anilha apoiada atrás da cabeça. Esta será a sua posição inicial.","Mantendo a anilha firme atrás da cabeça, abaixe lentamente o queixo em direção ao peito enquanto inspira.","Eleve a cabeça de volta à posição inicial em semicírculo enquanto expira e segure a contração por um segundo.","Repita pela quantidade recomendada de repetições."]},
"Lying_Face_Up_Plate_Neck_Resistance":{"name":"Flexão de Pescoço Deitado de Costas com Anilha","instructions":["Deite-se de costas em um banco reto com trapézio, pescoço e cabeça para fora da borda, segurando uma anilha apoiada sobre a testa. Esta será a sua posição inicial.","Mantendo a anilha firme na testa, abaixe lentamente a cabeça para trás em semicírculo enquanto inspira.","Eleve a cabeça de volta à posição inicial em semicírculo enquanto expira e segure a contração por um segundo.","Repita pela quantidade recomendada de repetições."]},
"Lying_Glute":{"name":"Alongamento de Glúteo Deitado (Com Parceiro)","instructions":["Deite-se de costas com seu parceiro ajoelhado ao seu lado.","Flexione o quadril de uma perna tirando-a do chão e gire-a levando o pé acima do quadril oposto, com seu parceiro segurando joelho e tornozelo. Esta será a sua posição inicial.","Tente empurrar a perna contra seu parceiro enquanto ele impede o movimento.","Após 10-20 segundos, relaxe completamente enquanto seu parceiro pressiona suavemente o tornozelo e o joelho em direção ao seu peito, avisando quando estiver adequado."]},
"Lying_Hamstring":{"name":"Alongamento de Posteriores Deitado (Com Parceiro)","instructions":["Deite-se de costas com as pernas estendidas, eleve uma perna em direção ao teto e deixe seu parceiro segurar o tornozelo. Esta será a sua posição inicial.","Com seu parceiro mantendo a perna fixa, tente flexionar o joelho contraindo os posteriores por 10-20 segundos.","Em seguida relaxe a perna permitindo que seu parceiro a empurre suavemente em direção à sua cabeça; avise quando estiver adequado e troque de lado."]},
"Lying_High_Bench_Barbell_Curl":{"name":"Rosca Direta Deitado em Banco Alto com Barra","instructions":["Deite-se de bruços em um banco reto alto segurando uma barra com pegada supinada (palmas para cima), deixando a parte superior do peito além da borda e os braços pendurados perpendiculares ao chão. Esta será a sua posição inicial.","Mantendo os cotovelos fechados e a parte superior dos braços imóvel, eleve a barra contraindo o bíceps enquanto expira e segure um segundo no topo.","Ao inspirar, abaixe lentamente de volta à posição inicial sem balançar, movendo apenas os antebraços.","Repita pela quantidade recomendada de repetições."]},
"Lying_Leg_Curls":{"name":"Mesa Flexora (Flexão de Pernas Deitado)","instructions":["Ajuste a alavanca da mesa flexora à sua altura e deite-se de bruços posicionando o apoio acolchoado logo abaixo das panturrilhas.","Mantenha o tronco apoiado no banco, pernas estendidas, segure as alças laterais e alinhe os pés. Esta será a sua posição inicial.","Ao expirar, flexione os joelhos puxando as pernas para cima o máximo possível sem tirar as coxas do banco e segure um segundo na contração máxima.","Ao inspirar, retorne as pernas à posição inicial e repita pela quantidade recomendada de repetições."]},
"Lying_Machine_Squat":{"name":"Agachamento Deitado na Máquina","instructions":["Ajuste o aparelho em uma altura que permita entrar com os joelhos dobrados e coxas levemente abaixo do paralelo.","Selecione a carga, posicione-se de costas dentro da máquina com joelhos flexionados sem ultrapassar os dedos dos pés, cabeça e costas apoiadas e ombros sob as almofadas.","Segure as alças e posicione os pés na largura dos ombros levemente voltados para fora. Esta será a sua posição inicial.","Empurrando pela ponta dos pés enquanto expira, estenda o corpo contraindo os quadríceps e segure um segundo no topo.","Agache lentamente enquanto inspira parando quando as coxas ficarem paralelas à plataforma (ângulo de 90 graus nos joelhos).","Repita pela quantidade recomendada de repetições."]},
"Lying_One-Arm_Lateral_Raise":{"name":"Elevação Lateral Unilateral Deitado no Banco","instructions":["Segurando um halter em uma mão, deite-se de bruços em um banco reto usando a outra mão para segurar na perna do banco.","Mantenha a palma voltada para o corpo com o braço estendido e leve flexão no cotovelo. Esta será a sua posição inicial.","Eleve o braço com o halter lateralmente até o cotovelo atingir a altura do ombro paralelo ao chão enquanto expira, segurando um segundo no topo.","Abaixe lentamente o halter de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Lying_Prone_Quadriceps":{"name":"Alongamento de Quadríceps Deitado de Bruços","instructions":["Deite-se de bruços no chão com seu parceiro ajoelhado ao lado; flexione um joelho tentando aproximar o pé dos glúteos enquanto seu parceiro segura joelho e tornozelo. Esta será a sua posição inicial.","Tente estender o joelho enquanto seu parceiro impede qualquer movimento.","Após 10-20 segundos, relaxe os músculos enquanto seu parceiro empurra suavemente o pé em direção aos glúteos para aprofundar o alongamento.","Após 10-20 segundos, troque de lado."]},
"Lying_Rear_Delt_Raise":{"name":"Crucifixo Inverso Deitado no Banco Reto","instructions":["Segurando um halter em cada mão, deite-se de bruços em um banco reto.","Mantenha as palmas voltadas para o corpo com os braços estendidos e leve flexão nos cotovelos. Esta será a sua posição inicial.","Eleve os braços lateralmente até os cotovelos atingirem a altura dos ombros paralelos ao chão enquanto expira, segurando um segundo no topo.","Abaixe lentamente os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Lying_Supine_Dumbbell_Curl":{"name":"Rosca Deitado de Costas no Banco com Halteres","instructions":["Deite-se de costas em um banco reto segurando um halter em cada mão sobre as coxas.","Traga os halteres para os lados com os braços estendidos e palmas voltadas para o corpo (pegada neutra).","Mantendo os braços próximos ao tronco, abaixe-os estendidos em direção ao chão até o limite confortável e fixe a parte superior dos braços nessa posição. Esta será a sua posição inicial.","Ao expirar, flexione os cotovelos girando os punhos para cima (pegada supinada) até contrair totalmente o bíceps, segurando por um segundo movendo apenas os antebraços.","Retorne muito lentamente à posição inicial."]},
"Lying_T-Bar_Row":{"name":"Remada Cavalinho Apoiada no Banco","instructions":["Carregue a máquina de remada cavalinho apoiada com o peso desejado e ajuste o apoio dos pés para que a parte superior do peito fique alinhada ao topo do encosto.","Deite-se de bruços no apoio e segure os pegadores com pegada pronada, supinada ou neutra conforme o foco.","Retire o suporte do descanso e estenda os braços à frente. Esta será a sua posição inicial.","Ao expirar, puxe a carga lentamente contraindo bem as costas no topo, mantendo os braços próximos ao corpo e sem desencostar o peito do apoio.","Após segurar a contração por um segundo, retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Lying_Triceps_Press":{"name":"Tríceps Testa com Barra","instructions":["Deite-se em um banco reto com os pés no chão e uma barra W ou barra reta atrás da cabeça.","Segure a barra com pegada pronada média e eleve-a acima do rosto com os braços estendidos perpendiculares ao chão e cotovelos fechados. Esta é a sua posição inicial.","Enquanto inspira, abaixe lentamente a barra até tocar levemente a testa mantendo braços e cotovelos imóveis.","Use o tríceps para empurrar a barra de volta à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Machine_Bench_Press":{"name":"Supino na Máquina","instructions":["Sente-se na máquina de supino e selecione a carga.","Pise na alavanca auxiliar se disponível para posicionar os pegadores à frente e facilitar o início.","Segure os pegadores com pegada pronada e eleve os cotovelos deixando os braços paralelos ao chão ao lado do tronco. Estenda os braços para entrar na posição inicial.","Traga os pegadores de volta em direção ao peito enquanto inspira.","Empurre os pegadores à frente contraindo o peitoral enquanto expira e segure por um segundo antes de retornar.","Repita pela quantidade recomendada de repetições.","Ao finalizar, use a alavanca auxiliar para devolver os pegadores ao descanso com segurança."]},
"Machine_Bicep_Curl":{"name":"Rosca Bíceps na Máquina","instructions":["Ajuste o assento à sua altura, selecione a carga, apoie os braços nas almofadas e segure os pegadores. Esta será a sua posição inicial.","Execute o movimento flexionando os cotovelos e puxando os antebraços em direção aos ombros.","Pause no topo da contração e depois retorne lentamente à posição inicial.","Evite deixar o peso encostar totalmente no descanso entre as repetições para manter a tensão muscular."]},
"Machine_Preacher_Curls":{"name":"Rosca Scott na Máquina","instructions":["Sente-se na máquina Scott e selecione a carga.","Apoie a parte posterior dos braços na almofada inclinada mantendo os cotovelos fechados e segure os pegadores com pegada supinada (palmas para cima). Esta será a sua posição inicial.","Puxe os pegadores para cima enquanto expira contraindo o bíceps, segure por um segundo no topo movendo apenas os antebraços.","Abaixe lentamente os pegadores de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Machine_Shoulder_Military_Press":{"name":"Desenvolvimento de Ombros na Máquina","instructions":["Sente-se na máquina de desenvolvimento e selecione a carga.","Segure os pegadores laterais mantendo os cotovelos flexionados e alinhados ao tronco. Esta será a sua posição inicial.","Empurre os pegadores para cima enquanto expira até estender os braços e segure a contração por um segundo no topo.","Abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Machine_Triceps_Extension":{"name":"Extensão de Tríceps na Máquina","instructions":["Ajuste o assento à sua altura, selecione a carga, apoie os braços nas almofadas e segure os pegadores. Esta será a sua posição inicial.","Execute estendendo os cotovelos e afastando os antebraços dos braços.","Pause na extensão completa e depois retorne lentamente à posição inicial.","Evite retornar o peso totalmente ao batente entre as repetições para manter tensão contínua no tríceps."]},
"Medicine_Ball_Chest_Pass":{"name":"Passe de Peito com Medicine Ball","instructions":["Você precisará de um parceiro ou de uma parede firme.","Fique de frente para seu parceiro segurando a bola medicinal junto ao tronco com as duas mãos.","Traga a bola ao peito e arremesse-a à frente estendendo os cotovelos com força (pode dar um passo junto).","Seu parceiro deve segurar a bola e devolvê-la para você.","Receba a bola com as duas mãos na altura do peito."]},
"Medicine_Ball_Full_Twist":{"name":"Giro Completo com Medicine Ball (Em Dupla)","instructions":["Fique de costas para um parceiro, afastados por 2-3 pés, segurando uma bola medicinal. Esta será a sua posição inicial.","Segure a bola à frente do tronco, gire quadril e ombros no mesmo sentido que seu parceiro (por exemplo, anti-horário).","Complete a rotação até passar a bola ao parceiro pelo lado.","Depois que o parceiro pegar a bola, ambos giram para o lado oposto para repetir o passe."]},
"Medicine_Ball_Scoop_Throw":{"name":"Arremesso para Trás com Medicine Ball (Scoop Throw)","instructions":["Assuma postura de meio agachamento segurando uma bola medicinal entre as pernas com os braços estendidos.","Impulsione o quadril para a frente estendendo as pernas e saltando para cima.","Simultaneamente, balance os braços estendidos acima da cabeça soltando a bola no pico do movimento para lançá-la o mais longe possível para trás."]},
"Middle_Back_Shrug":{"name":"Encolhimento Escapular no Banco Inclinado","instructions":["Deite-se de bruços em um banco inclinado segurando um halter em cada mão com braços estendidos para baixo e palmas frente a frente. Esta será a sua posição inicial.","Ao expirar, aperte as escápulas uma contra a outra mantendo os braços estendidos e segure por um segundo completo.","Retorne à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Middle_Back_Stretch":{"name":"Alongamento do Meio das Costas","instructions":["Fique em pé com os pés na largura dos ombros e as mãos na cintura.","Gire a cintura para um lado até sentir o alongamento, segure por 10 a 15 segundos e depois gire para o outro lado."]},
"Mixed_Grip_Chin":{"name":"Barra Fixa com Pegada Mista","instructions":["Segure a barra fixa cerca de 1 polegada além da largura dos ombros com uma palma voltada para a frente e a outra voltada para você. Esta será a sua posição inicial.","Puxe o corpo para cima enquanto expira, mantendo o cotovelo do braço supinado junto ao tronco e o outro alinhado para trabalhar bem as dorsais.","Após segurar um segundo no topo, desça lentamente enquanto inspira.","Repita pela quantidade recomendada de repetições.","Na série seguinte, inverta a pegada das mãos."]},
"Monster_Walk":{"name":"Caminhada Lateral/Frontal com Elástico (Monster Walk)","instructions":["Coloque um mini elástico ao redor dos tornozelos e outro ao redor dos joelhos com tensão quando os pés estiverem na largura dos ombros.","Dê passos curtos para a frente alternando pé esquerdo e direito mantendo tensão constante.","Após vários passos, caminhe de costas de volta ao ponto de partida."]},
"Mountain_Climbers":{"name":"Alpinista (Mountain Climbers)","instructions":["Entre em posição de flexão de braço apoiando-se nas mãos e pontas dos pés, trazendo um joelho flexionado em direção ao quadril. Esta será a sua posição inicial.","Inverta explosivamente a posição das pernas estendendo a perna dobrada e trazendo o outro joelho ao peito, alternando continuamente por 20-30 segundos."]},
"Moving_Claw_Series":{"name":"Série Garra em Movimento (Corrida)","instructions":["Enquanto corre, flexione bem o joelho tentando aproximar o calcanhar dos glúteos quando o quadril se estende.","Recarregue o quadríceps trazendo a perna à frente para atacar o solo no passo seguinte.","Mantenha o movimento firme dos braços em ritmo rápido de 1-2 durante toda a corrida."]},
"Muscle_Snatch":{"name":"Muscle Snatch","instructions":["Segure uma barra montada na altura do meio das coxas com pegada aberta, pés sob o quadril, peito aberto, cabeça erguida e ombros à frente da barra. Esta será a posição inicial.","Inicie empurrando pela parte anterior dos calcanhares e faça a segunda puxada estendendo explosivamente quadril, joelhos e tornozelos mantendo a barra rente ao corpo.","Continue puxando e empurre a barra diretamente acima da cabeça até travar os braços sem dobrar novamente os joelhos."]},
"Muscle_Up":{"name":"Muscle Up nas Argolas","instructions":["Segure as argolas com pegada falsa (base das palmas sobre as argolas) e inicie uma barra puxando os cotovelos para baixo junto ao corpo.","Ao alcançar o topo da puxada, traga as argolas às axilas e gire os ombros à frente levando os cotovelos para trás para entrar na transição do mergulho.","Mantendo controle e estabilidade, estenda os cotovelos para concluir o movimento acima das argolas.","Desça com cuidado de volta ao chão."]},
"Narrow_Stance_Hack_Squats":{"name":"Agachamento Hack - Base Fechada","instructions":["Apoie as costas no encosto da máquina Hack e encaixe os ombros sob os apoios.","Posicione os pés na plataforma com base estreita (cerca de 3 polegadas ou menos entre si) e pontas levemente para fora, mantendo cabeça erguida e costas coladas no encosto.","Segure as alças laterais e destrave as travas de segurança.","Estenda as pernas sem travar os joelhos. Esta será a sua posição inicial.","Desça lentamente flexionando os joelhos até as coxas ficarem abaixo do paralelo enquanto inspira.","Suba enquanto expira empurrando principalmente pelos calcanhares até estender as pernas de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Narrow_Stance_Leg_Press":{"name":"Leg Press - Base Fechada","instructions":["Sente-se no leg press e posicione os pés na plataforma bem próximos (cerca de 3 polegadas ou menos de distância) com pontas levemente para fora, mantendo cabeça e costas apoiadas.","Destrave as travas de segurança e empurre a plataforma até estender as pernas sem travar os joelhos, formando 90 graus entre tronco e pernas. Esta será a sua posição inicial.","Enquanto inspira, desça lentamente a plataforma até formar 90 graus nos joelhos.","Empurrando principalmente pelos calcanhares com o quadríceps, retorne à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições e trave bem os pinos de segurança ao concluir."]},
"Narrow_Stance_Squats":{"name":"Agachamento com Barra - Base Fechada","instructions":["Dentro de um rack de agachamento, ajuste a barra na altura ideal, entre sob ela apoiando-a na parte posterior dos ombros.","Segure a barra com ambas as mãos e retire-a do suporte empurrando com as pernas.","Afaste-se do suporte e posicione os pés em base estreita (3-6 polegadas de distância) com pontas levemente para fora, cabeça erguida e costas retas. Esta será a sua posição inicial.","Desça lentamente flexionando os joelhos com postura ereta até as coxas passarem do paralelo enquanto inspira, sem deixar os joelhos ultrapassarem excessivamente os dedos dos pés.","Suba enquanto expira empurrando principalmente pelos calcanhares até estender as pernas e voltar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Natural_Glute_Ham_Raise":{"name":"Glute Ham Raise Natural","instructions":["Prenda os tornozelos sob o apoio de pernas de uma máquina de puxada ou banco Scott, apoiando os joelhos no assento com o tronco ereto.","Abaixe o corpo à frente de forma controlada até os joelhos ficarem quase totalmente estendidos.","Mantendo o controle, use os posteriores de coxa para puxar o corpo de volta à posição inicial.","Se necessário, utilize um elástico, ajuda de um parceiro ou empurre levemente uma caixa para auxiliar a subida."]},
"Neck-SMR":{"name":"Liberação Miofascial do Pescoço","instructions":["Posicione um rolo muscular atrás da cabeça contra a musculatura lateral do pescoço (nunca diretamente sobre a coluna cervical). Esta será a sua posição inicial.","Começando do topo da nuca, deslize lentamente pela musculatura do pescoço pausando nos pontos de tensão por 10-30 segundos."]},
"Neck_Press":{"name":"Supino no Pescoço (Neck Press)","instructions":["Deite-se em um banco reto, retire a barra do suporte com pegada média e segure-a diretamente acima do pescoço com os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça a barra lentamente até sentir tocar suavemente a região do pescoço/clavícula.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando o peitoral, estenda os braços, segure um segundo e desça novamente devagar.","Repita o movimento pela quantidade prescrita de repetições.","Ao terminar, recoloque a barra no suporte."]},
"Oblique_Crunches":{"name":"Abdominal Oblíquo Cruzado","instructions":["Deite-se de costas no chão com a lombar pressionada contra o solo, uma mão ao lado da cabeça e a outra apoiada no chão ao lado do corpo.","Apoie os pés elevados sobre uma superfície plana.","Eleve o ombro do lado cuja mão está na cabeça.","Suba o tronco girando-o para encostar o cotovelo no joelho oposto (por exemplo, cotovelo direito no joelho esquerdo).","Após o toque, abaixe o tronco até retornar à posição inicial.","Inspire durante a descida (fase excêntrica) e expire durante a subida (fase concêntrica).","Continue alternando até completar todas as repetições recomendadas para cada lado."]},
"Oblique_Crunches_-_On_The_Floor":{"name":"Abdominal Oblíquo Lateral no Chão","instructions":["Deite-se sobre o lado direito com as pernas sobrepostas e os joelhos levemente flexionados.","Coloque a mão esquerda atrás da cabeça.","Eleve o cotovelo esquerdo lateralmente contraindo principalmente os oblíquos.","Flexione ao máximo, segure a contração por um segundo e desça lentamente de volta à posição inicial.","Inspire na descida e expire na subida; ao concluir a série, repita do outro lado."]},
"Olympic_Squat":{"name":"Agachamento Olímpico (Barra Alta)","instructions":["Apoie a barra sobre o topo do trapézio com peito aberto, cabeça erguida e pés na largura do quadril levemente voltados para fora.","Desça flexionando os joelhos evitando jogar o quadril muito para trás, permitindo que os joelhos avancem alinhados aos pés para manter o tronco o mais vertical possível até os posteriores tocarem as panturrilhas.","No instante em que coxas e panturrilhas se tocarem, inverta o movimento impulsionando a barra para cima."]},
"On-Your-Back_Quad_Stretch":{"name":"Alongamento de Quadríceps Deitado no Banco","instructions":["Deite-se de costas em um banco reto ou step deixando uma perna e um braço pendurados pela lateral.","Flexione o joelho da perna pendente e segure o peito do pé sem arquear a lombar.","Contraia o abdômen para manter a pelve neutra e pressione o pé contra a mão; eleve levemente o quadril para intensificar o alongamento.","Troque de lado."]},
"On_Your_Side_Quad_Stretch":{"name":"Alongamento de Quadríceps Deitado de Lado","instructions":["Deite-se sobre o lado direito com o joelho direito flexionado a 90 graus à sua frente apoiado no chão para estabilizar o tronco.","Flexione o joelho esquerdo para trás, segure o pé esquerdo com a mão esquerda e empurre o quadril para a frente enquanto pressiona o pé contra a mão; depois troque de lado."]},
"One-Arm_Dumbbell_Row":{"name":"Remada Unilateral com Halter (Serrote)","instructions":["Escolha um banco reto e posicione um halter ao lado dele.","Apoie o joelho direito na extremidade do banco, incline o tronco até ficar paralelo ao chão e apoie a mão direita na outra ponta do banco.","Pegue o halter com a mão esquerda mantendo a lombar reta e a palma voltada para o tronco. Esta será a sua posição inicial.","Puxe o halter reto para cima em direção à lateral do peito mantendo o braço próximo ao corpo e o tronco imóvel enquanto expira, focando nas costas.","Desça o halter em linha reta de volta à posição inicial enquanto inspira.","Repita pela quantidade especificada de repetições.","Troque de lado e repita com o outro braço."]},
"One-Arm_Flat_Bench_Dumbbell_Flye":{"name":"Crucifixo Unilateral no Banco Reto com Halter","instructions":["Deite-se em um banco reto com um halter em uma mão apoiado na coxa em pegada neutra.","Use a coxa para erguer o halter e sustente-o acima do peito com o braço estendido e a mão livre segurando na lateral do banco para apoio. Esta será a sua posição inicial.","Com leve flexão no cotovelo, abaixe o braço lateralmente em arco amplo até sentir alongar o peitoral enquanto inspira, movendo apenas o ombro.","Retorne o braço à posição inicial contraindo o peitoral pelo mesmo arco enquanto expira.","Segure por um segundo na contração e repita pela quantidade prescrita.","Troque de braço e repita o exercício."]},
"One-Arm_High-Pulley_Cable_Side_Bends":{"name":"Flexão Lateral Unilateral na Polia Alta","instructions":["Prenda um pegador padrão na posição mais alta da torre de cabo.","Fique de lado para o cabo e segure o pegador com uma mão em pegada supinada.","Puxe o cabo para baixo até o cotovelo encostar na lateral do corpo e o pegador ficar junto ao ombro.","Posicione os pés na largura do quadril e apoie a mão livre na cintura.","Mantendo o braço imóvel, contraia o oblíquo para inclinar o tronco lateralmente para baixo.","Ao atingir a contração máxima, retorne lentamente à posição inicial mantendo tensão contínua no cabo.","Repita até a falha.","Reposicione-se e repita a sequência para o lado oposto."]},
"One-Arm_Incline_Lateral_Raise":{"name":"Elevação Lateral Unilateral no Banco Inclinado","instructions":["Deite-se de lado em um banco inclinado com o ombro de baixo apoiado no encosto.","Segure um halter com o braço de cima estendido à frente do corpo paralelo ao chão. Esta é a sua posição inicial.","Mantendo o halter paralelo ao chão, faça uma elevação lateral subindo o braço até apontar para o teto enquanto expira e segure por um segundo.","Enquanto inspira, abaixe o peso cruzando à frente do corpo de volta à posição inicial.","Repita pela quantidade prescrita de repetições.","Troque de braço e repita o movimento."]},
"One-Arm_Kettlebell_Clean":{"name":"Clean Unilateral com Kettlebell","instructions":["Coloque um kettlebell entre os pés, empurre o quadril para trás e olhe para a frente ao segurá-lo.","Faça o clean até o ombro estendendo pernas e quadril enquanto puxa o kettlebell e gira o punho.","Retorne o peso à posição inicial."]},
"One-Arm_Kettlebell_Clean_and_Jerk":{"name":"Clean and Jerk Unilateral com Kettlebell","instructions":["Segure um kettlebell pela alça.","Faça o clean até o ombro estendendo pernas e quadril enquanto gira o punho com a palma para a frente.","Flexione levemente os joelhos mantendo o tronco ereto.","Inverta imediatamente impulsionando pelos calcanhares para empurrar o kettlebell acima da cabeça aproveitando o impulso do corpo.","Receba o peso acima da cabeça entrando brevemente em agachamento sob a carga.","Fique em pé com o peso travado acima da cabeça e abaixe-o ao chão para a repetição seguinte."]},
"One-Arm_Kettlebell_Floor_Press":{"name":"Supino no Chão Unilateral com Kettlebell","instructions":["Deite-se no chão segurando um kettlebell com uma mão, apoiando a parte superior do braço no solo com a palma voltada para dentro.","Empurre o kettlebell reto para cima em direção ao teto girando o punho.","Abaixe o kettlebell de volta à posição inicial e repita."]},
"One-Arm_Kettlebell_Jerk":{"name":"Jerk Unilateral com Kettlebell","instructions":["Segure um kettlebell pela alça e faça o clean até o ombro girando o punho para a frente. Esta será a sua posição inicial.","Flexione levemente os joelhos mantendo o tronco ereto.","Inverta imediatamente impulsionando pelos calcanhares para empurrar o kettlebell acima da cabeça, recebendo-o sob a carga e ficando em pé.","Abaixe o kettlebell de volta ao ombro para a repetição seguinte."]},
"One-Arm_Kettlebell_Military_Press_To_The_Side":{"name":"Desenvolvimento Militar Lateral Unilateral com Kettlebell","instructions":["Faça o clean de um kettlebell até o ombro girando o punho para que a palma fique voltada para dentro. Esta será a sua posição inicial.","Olhe para o kettlebell e empurre-o para cima e ligeiramente para o lado até travar o braço acima da cabeça.","Abaixe o kettlebell de volta ao ombro sob controle contraindo fortemente dorsal, glúteos e abdômen para maior estabilidade."]},
"One-Arm_Kettlebell_Para_Press":{"name":"Desenvolvimento Lateral (Para Press) com Kettlebell","instructions":["Faça o clean de um kettlebell até o ombro girando o punho para a frente. Esta será a sua posição inicial.","Mantenha o cotovelo aberto para o lado e empurre o kettlebell para cima e para o lado até travar o braço acima da cabeça.","Abaixe o kettlebell de volta ao ombro sob controle contraindo dorsal, glúteos e abdômen, e repita."]},
"One-Arm_Kettlebell_Push_Press":{"name":"Push Press Unilateral com Kettlebell","instructions":["Segure um kettlebell pela alça e faça o clean até o ombro girando a palma para a frente. Esta será a sua posição inicial.","Flexione levemente os joelhos mantendo o tronco ereto.","Inverta imediatamente impulsionando pelos calcanhares para gerar força e empurrar o kettlebell acima da cabeça, depois abaixe ao ombro para a próxima repetição."]},
"One-Arm_Kettlebell_Row":{"name":"Remada Unilateral com Kettlebell","instructions":["Coloque um kettlebell à frente dos pés, flexione levemente os joelhos, jogue o quadril bem para trás inclinando o tronco com costas retas e puxe o kettlebell até o abdômen retraindo a escápula; depois abaixe e repita."]},
"One-Arm_Kettlebell_Snatch":{"name":"Snatch (Arranque) Unilateral com Kettlebell","instructions":["Coloque um kettlebell entre os pés, flexione os joelhos e empurre o quadril para trás na posição inicial.","Olhe para a frente e balance o kettlebell para trás entre as pernas.","Inverta imediatamente impulsionando com quadril e joelhos; ao subir na altura do ombro, gire a mão e soca para cima recebendo o kettlebell travado acima da cabeça."]},
"One-Arm_Kettlebell_Split_Jerk":{"name":"Split Jerk Unilateral com Kettlebell","instructions":["Faça o clean de um kettlebell até o ombro girando o punho com a palma para a frente. Esta será a sua posição inicial.","Flexione levemente os joelhos mantendo o tronco ereto.","Inverta imediatamente impulsionando pelos calcanhares para empurrar o kettlebell acima da cabeça.","Receba o peso acima da cabeça em base dividida (uma perna à frente e outra atrás).","Junte os pés em pé mantendo o kettlebell acima da cabeça e depois abaixe-o ao ombro para a repetição seguinte."]},
"One-Arm_Kettlebell_Split_Snatch":{"name":"Split Snatch Unilateral com Kettlebell","instructions":["Segure um kettlebell pela alça com uma mão.","Agache levemente e inverta o movimento estendendo quadril, joelhos e tornozelos para lançar o kettlebell para cima.","Após extensão completa, entre em base de avanço (uma perna à frente e outra atrás) recebendo o kettlebell travado acima da cabeça em um movimento contínuo.","Junte os pés ficando em pé e abaixe o kettlebell de volta à posição inicial."]},
"One-Arm_Kettlebell_Swings":{"name":"Swing Unilateral com Kettlebell","instructions":[]},
"One-Arm_Long_Bar_Row":{"name":"Remada Unilateral no Landmine","instructions":["Encaixe uma barra no landmine (ou no canto de paredes) e carregue o peso na extremidade livre.","Fique ao lado da barra, segure perto da ponta com uma mão e levante-se usando pernas e quadril.","Assuma base com joelhos flexionados, quadril para trás, peito aberto e braço estendido. Esta será a sua posição inicial.","Puxe o peso para o lado do tronco retraindo o ombro e flexionando o cotovelo, sem dar trancos.","Após uma breve pausa, retorne à posição inicial."]},
"One-Arm_Medicine_Ball_Slam":{"name":"Arremesso Unilateral no Chão (Slam) com Medicine Ball","instructions":["Fique em postura atlética alternada segurando uma bola medicinal em uma mão do mesmo lado da perna de trás. Esta será a sua posição inicial.","Eleve o braço levando a bola acima da cabeça enquanto estende quadril, joelhos e tornozelos.","No pico da extensão, flexione ombro, coluna e quadril para arremessar a bola com força no chão à sua frente.","Segure a bola no quique e continue pelo número desejado de repetições."]},
"One-Arm_Open_Palm_Kettlebell_Clean":{"name":"Clean Unilateral com Palma Aberta com Kettlebell","instructions":["Coloque um kettlebell entre os pés.","Segure a alça com uma mão e puxe rapidamente deixando o kettlebell girar para que a esfera pouse na palma da sua mão aberta.","Projete o kettlebell à frente e pegue a alça novamente com a mesma mão.","Leve-o ao chão e repita, trabalhando ambos os braços."]},
"One-Arm_Overhead_Kettlebell_Squats":{"name":"Agachamento Unilateral Acima da Cabeça com Kettlebell","instructions":["Faça o clean e o desenvolvimento acima da cabeça com um kettlebell usando um braço. Esta será a sua posição inicial.","Olhando para a frente e mantendo o braço travado acima da cabeça, agache entre as pernas mantendo cabeça e peito erguidos.","Pause na posição inferior por um segundo antes de subir empurrando pelos calcanhares."]},
"One-Arm_Side_Deadlift":{"name":"Levantamento Terra Lateral Unilateral (Mala)","instructions":["Fique ao lado do centro de uma barra no chão, flexione os joelhos e abaixe o corpo até alcançar a barra.","Segure a barra no meio como se pegasse uma mala (palma voltada para você). Esta é a sua posição inicial.","Use as pernas para levantar a barra enquanto expira até ficar totalmente em pé com o braço estendido.","Abaixe a barra lentamente enquanto inspira flexionando os joelhos para proteger a coluna.","Repita pela quantidade recomendada de repetições.","Troque de braço e repita o movimento."]},
"One-Arm_Side_Laterals":{"name":"Elevação Lateral Unilateral com Halter","instructions":["Segure um halter em uma mão e use a mão livre para segurar em um apoio firme como um banco inclinado, inclinando o corpo na direção do braço ativo.","Fique com o tronco alinhado e o halter ao lado do corpo com a palma voltada para você. Esta será a sua posição inicial.","Mantendo o tronco imóvel, eleve o halter para o lado com leve flexão no cotovelo e punho levemente inclinado até o braço ficar paralelo ao chão enquanto expira, segurando um segundo no topo.","Abaixe lentamente o halter de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições.","Troque de braço e repita o exercício."]},
"One-Legged_Cable_Kickback":{"name":"Coice para Glúteos no Cabo","instructions":["Prenda uma tornozeleira na polia baixa e encaixe-a no seu tornozelo.","Fique de frente para a torre a cerca de dois pés de distância segurando na estrutura para apoio.","Mantendo joelhos levemente flexionados e abdômen contraído, contraia o glúteo para chutar a perna para trás em arco o mais alto possível enquanto expira, segurando um segundo no topo.","Retorne lentamente a perna à frente resistindo à tração do cabo até a posição inicial.","Repita pela quantidade recomendada de repetições.","Troque de perna e repita para o outro lado."]},
"One_Arm_Against_Wall":{"name":"Alongamento Unilateral de Dorsal na Parede","instructions":["Em pé, apoie um braço dobrado contra uma parede ou batente de porta.","Incline-se lentamente na direção do braço até sentir o alongamento na dorsal."]},
"One_Arm_Chin-Up":{"name":"Barra Fixa Unilateral Assistida com Toalha","instructions":["Passe uma toalha ao redor da barra fixa.","Segure a barra com uma mão em pegada supinada e segure a toalha com a outra mão.","Incline o tronco cerca de 30 graus para trás abrindo o peito. Esta é a sua posição inicial.","Puxe o corpo para cima até a barra tocar a parte superior do peito enquanto expira, contraindo as costas no topo.","Após segurar um segundo na contração, desça lentamente enquanto inspira até estender totalmente os braços.","Repita pela quantidade prescrita de repetições.","Troque as mãos de posição e repita o movimento."]},
"One_Arm_Dumbbell_Bench_Press":{"name":"Supino Reto Unilateral com Halter","instructions":["Deite-se em um banco reto com um halter em uma mão apoiado sobre a coxa.","Use a coxa para impulsionar o halter até segurá-lo à frente do ombro (a mão livre pode auxiliar no posicionamento).","Gire o punho para a frente de modo que a palma fique voltada para fora. Esta será a sua posição inicial.","Desça o halter lentamente para o lado enquanto inspira mantendo controle total; mantenha a mão livre ao lado para equilíbrio.","Ao expirar, empurre o halter para cima usando o peitoral, estenda o braço, contraia por um segundo e desça devagar (descida cerca de duas vezes mais lenta que a subida).","Repita pela quantidade prescrita de repetições.","Troque de braço e repita o movimento."]},
"One_Arm_Dumbbell_Preacher_Curl":{"name":"Rosca Scott Unilateral com Halter","instructions":["Segure um halter com o braço direito e apoie a parte posterior do braço sobre o apoio do banco Scott. Esta será a sua posição inicial.","Enquanto inspira, abaixe lentamente o halter até estender o braço e alongar totalmente o bíceps.","Ao expirar, contraia o bíceps subindo o halter até a altura do ombro (mantendo o dedo mínimo ligeiramente mais alto que o polegar para máxima contração).","Aperte bem o bíceps por um segundo no topo e repita pela quantidade recomendada de repetições.","Troque de braço e repita o movimento."]},
"One_Arm_Floor_Press":{"name":"Supino no Chão Unilateral com Barra","instructions":["Deite-se de costas no chão ou colchonete com os joelhos flexionados.","Peça a um parceiro para entregar a barra em uma das mãos com o braço quase totalmente estendido e pegada neutra (palma voltada para o tronco).","Mantenha o braço livre apoiado ao lado do corpo.","Inicie abaixando a barra até o cotovelo encostar no chão enquanto inspira.","Empurre a barra de volta à posição inicial estendendo o braço enquanto expira.","Repita até completar as repetições recomendadas.","Troque de braço e repita o movimento."]},
"One_Arm_Lat_Pulldown":{"name":"Puxada Alta Unilateral no Cabo","instructions":["Selecione a carga adequada, ajuste o apoio de joelhos e segure o pegador unilateral com pegada pronada. Esta será a sua posição inicial.","Puxe o pegador para baixo trazendo o cotovelo em direção à lateral do tronco.","Pause no ponto mais baixo e retorne lentamente à posição inicial.","Para séries com várias repetições, evite encostar totalmente a carga no descanso para manter a tensão muscular."]},
"One_Arm_Pronated_Dumbbell_Triceps_Extension":{"name":"Extensão de Tríceps Unilateral Deitado com Halter - Pegada Pronada","instructions":["Deite-se de costas em um banco segurando um halter com o braço estendido perpendicular ao corpo e palma voltada para os pés (pegada pronada).","Apoie a mão livre sobre o bíceps para estabilizar o braço.","Abaixe lentamente o halter flexionando o cotovelo enquanto inspira.","Empurre o halter de volta para cima contraindo o tríceps enquanto expira.","Repita até completar as repetições da série.","Troque de braço e repita o movimento."]},
"One_Arm_Supinated_Dumbbell_Triceps_Extension":{"name":"Extensão de Tríceps Unilateral Deitado com Halter - Pegada Supinada","instructions":["Deite-se de costas em um banco segurando um halter com o braço estendido perpendicular ao corpo e palma voltada para o rosto (pegada supinada).","Apoie a mão livre sobre o bíceps para estabilizar o braço.","Abaixe lentamente o halter flexionando o cotovelo enquanto inspira.","Empurre o halter de volta para cima contraindo o tríceps enquanto expira.","Repita até completar as repetições da série.","Troque de braço e repita o movimento.","Execute a mesma quantidade de séries para ambos os lados."]},
"One_Half_Locust":{"name":"Meio Gafanhoto (Alongamento)","instructions":["Deite-se de bruços no chão.","Coloque a mão esquerda sob o osso do quadril esquerdo para acolchoá-lo.","Flexione o joelho direito segurando o pé direito com a mão direita.","Eleve o pé no ar enquanto desencosta os ombros do chão para alongar flexores do quadril, peito e ombros; depois troque de lado."]},
"One_Handed_Hang":{"name":"Suspensão Unilateral na Barra","instructions":["Segure a barra fixa com uma mão em pegada pronada mantendo os pés no chão ou em um degrau e deixe a maior parte do peso suspensa por esse braço; segure por 10-20 segundos e troque de lado."]},
"One_Knee_To_Chest":{"name":"Um Joelho ao Peito","instructions":["Deite-se de costas no chão.","Estenda uma perna no chão e puxe o outro joelho em direção ao peito segurando por baixo da articulação para proteger a patela.","Puxe suavemente o joelho em direção ao nariz.","Troque de lado para alongar glúteo e lombar da perna flexionada e o flexor do quadril da perna estendida."]},
"One_Leg_Barbell_Squat":{"name":"Agachamento Búlgaro com Barra","instructions":["Fique em pé 2 a 3 pés à frente de um banco reto de costas para ele, com uma barra no chão à sua frente e pés na largura dos ombros.","Flexione os joelhos e erga a barra até apoiá-la na parte superior do peito.","Passe a barra por cima da cabeça apoiando-a na base do pescoço e apoie o peito de um pé atrás sobre o banco reto, mantendo a cabeça erguida e costas retas.","Enquanto inspira, desça lentamente até a coxa da frente ficar paralela ao chão com o joelho alinhado sobre o pé.","Empurrando com o quadríceps e conduzindo com peito e quadril, retorne à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições.","Troque as pernas e repita o movimento."]},
"Open_Palm_Kettlebell_Clean":{"name":"Clean com Palma Aberta com Kettlebell","instructions":["Coloque um kettlebell entre os pés e faça o clean estendendo pernas e quadril para elevá-lo em direção aos ombros.","Solte brevemente a alça na subida deixando o kettlebell girar para que a esfera pouse nas palmas abertas.","Projete o kettlebell à frente pegando a alça com as duas mãos, abaixe à posição inicial e repita."]},
"Otis-Up":{"name":"Abdominal Otis-Up","instructions":["Prenda os pés e deite-se de costas no chão com joelhos flexionados segurando um peso junto ao peito com as duas mãos. Esta será a sua posição inicial.","Flexione quadril e coluna para elevar o tronco do chão.","Durante a subida, empurre o peso para cima até ficar estendido acima da cabeça no topo do movimento.","Retorne o peso ao peito ao inverter a descida do abdominal sem encostar totalmente as costas no chão."]},
"Overhead_Cable_Curl":{"name":"Rosca Direta Acima da Cabeça no Cabo","instructions":["Selecione a mesma carga confortável em ambos os lados da polia dupla.","Ajuste as polias em uma altura acima dos ombros.","Fique no centro segurando um pegador em cada mão com pegada supinada (palmas para cima), braços totalmente estendidos paralelos ao chão e pés na largura dos ombros. Esta é a posição inicial.","Ao expirar, flexione os cotovelos contraindo o bíceps até os antebraços encostarem no bíceps.","Ao inspirar, retorne os antebraços à posição inicial mantendo todo o resto do corpo imóvel.","Repita pela quantidade recomendada de repetições."]},
"Overhead_Lat":{"name":"Alongamento de Dorsal Acima da Cabeça","instructions":["Sente-se ereto no chão com seu parceiro atrás, eleve um braço e flexione o cotovelo tentando tocar a mão nas costas enquanto seu parceiro segura tríceps e punho. Esta será a sua posição inicial.","Tente puxar o braço para baixo contra a resistência do seu parceiro por 10-20 segundos.","Relaxe o braço e deixe seu parceiro aprofundar o alongamento pressionando suavemente o tríceps por 10-20 segundos; depois troque de lado."]},
"Overhead_Slam":{"name":"Arremesso no Chão Acima da Cabeça (Slam) com Medicine Ball","instructions":["Segure uma bola medicinal com as duas mãos com os pés na largura dos ombros. Esta será a sua posição inicial.","Eleve a bola acima da cabeça estendendo todo o corpo.","Inverta com força arremessando a bola diretamente no chão à sua frente o mais forte possível.","Pegue a bola no quique com as duas mãos e repita o movimento."]},
"Overhead_Squat":{"name":"Agachamento Acima da Cabeça (Overhead Squat)","instructions":["Com uma barra no chão à sua frente, afaste os pés além da largura dos ombros.","Flexione os joelhos, segure a barra com pegada pronada aberta e erga-a até apoiar no peito.","Empurre a barra acima e ligeiramente atrás da cabeça com braços totalmente estendidos, escápulas retraídas, cabeça erguida e costas retas. Esta é a sua posição inicial.","Desça lentamente flexionando os joelhos até as coxas ficarem paralelas ao chão enquanto inspira, mantendo costas retas e braços estendidos acima da cabeça o tempo todo.","Empurre o chão com pés e pernas para retornar à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Overhead_Stretch":{"name":"Alongamento Estendido Acima da Cabeça","instructions":["Em pé com postura reta, entrelace os dedos com as palmas voltadas para o teto e estenda os braços para cima mantendo os ombros encaixados para baixo.","Estabilize o tronco contraindo levemente o abdômen para alongar toda a parte frontal e posterior do tronco."]},
"Overhead_Triceps":{"name":"Alongamento de Tríceps Acima da Cabeça (Com Parceiro)","instructions":["Sente-se ereto no chão com seu parceiro atrás, eleve um braço e flexione o cotovelo tentando tocar a mão nas costas enquanto seu parceiro segura cotovelo e punho. Esta será a sua posição inicial.","Tente estender o braço para cima enquanto seu parceiro impede o movimento por 10-20 segundos.","Relaxe o braço e deixe seu parceiro alongar o tríceps aplicando leve pressão no punho por 10-20 segundos; depois troque de lado."]},
"Pallof_Press":{"name":"Pallof Press no Cabo","instructions":["Conecte um pegador padrão à torre na altura dos ombros (ou polia baixa se não houver ajuste).","Fique de lado para o cabo segurando o pegador com as duas mãos e dê um passo para longe gerando tensão no cabo.","Com os pés na largura do quadril e joelhos levemente flexionados, segure o pegador no centro do peito. Esta será a sua posição inicial.","Empurre o pegador à frente afastando-o do peito até estender totalmente os dois braços mantendo o core bem contraído.","Segure a extensão por alguns segundos antes de retornar à posição inicial.","Ao concluir a série, repita virado para o lado oposto."]},
"Pallof_Press_With_Rotation":{"name":"Pallof Press com Rotação","instructions":["Conecte um pegador padrão na torre na altura dos ombros.","Fique de lado para o cabo, segure o pegador com uma mão e afaste-se cerca de um braço da polia gerando tensão.","Com pés na largura do quadril, traga o cabo ao peito e segure o pegador com as duas mãos.","Olhando à frente, empurre o cabo para longe do peito mantendo o core contraído.","Mantendo o quadril fixo, gire o tronco para longe da polia em um quarto de volta completa.","Mantendo os braços estendidos, retorne de forma lenta e controlada à posição neutra à frente.","Ainda com tensão lateral no core, traga as mãos ao peito e empurre novamente à frente (isso completa uma repetição).","Repita até a falha.","Reposicione-se e repita a série para o lado oposto."]},
"Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench":{"name":"Rosca de Punho Inversa com Halteres no Banco","instructions":["Coloque dois halteres de um lado de um banco reto.","Ajoelhe-se no chão de frente para o banco.","Segure ambos os halteres com pegada pronada (palmas para baixo) apoiando os antebraços sobre o banco e deixando os punhos pendurados além da borda.","Flexione os punhos para cima (extensão dorsal) enquanto expira.","Abaixe lentamente os punhos de volta à posição inicial enquanto inspira.","Mantenha os antebraços totalmente imóveis; apenas os punhos se movem.","Repita pela quantidade recomendada de repetições."]},
"Palms-Down_Wrist_Curl_Over_A_Bench":{"name":"Rosca de Punho Inversa com Barra no Banco","instructions":["Coloque uma barra de um lado de um banco reto.","Ajoelhe-se no chão de frente para o banco.","Segure a barra com pegada pronada (palmas para baixo) apoiando os antebraços sobre o banco e deixando os punhos pendurados além da borda.","Eleve os punhos para cima enquanto expira.","Abaixe lentamente os punhos de volta à posição inicial enquanto inspira.","Mantenha os antebraços imóveis; apenas os punhos se movem.","Repita pela quantidade recomendada de repetições."]},
"Palms-Up_Barbell_Wrist_Curl_Over_A_Bench":{"name":"Rosca de Punho com Barra no Banco","instructions":["Coloque uma barra de um lado de um banco reto.","Ajoelhe-se no chão de frente para o banco.","Segure a barra com pegada supinada (palmas para cima) apoiando os antebraços sobre o banco e deixando os punhos pendurados além da borda.","Flexione os punhos para cima enquanto expira.","Abaixe lentamente os punhos de volta à posição inicial enquanto inspira.","Mantenha os antebraços imóveis; apenas os punhos se movem.","Repita pela quantidade recomendada de repetições."]},
"Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench":{"name":"Rosca de Punho com Halteres no Banco","instructions":["Coloque dois halteres de um lado de um banco reto.","Ajoelhe-se no chão de frente para o banco.","Segure ambos os halteres com pegada supinada (palmas para cima) apoiando os antebraços sobre o banco e deixando os punhos pendurados além da borda.","Flexione os punhos para cima enquanto expira.","Abaixe lentamente os punhos de volta à posição inicial enquanto inspira.","Mantenha os antebraços imóveis; apenas os punhos se movem.","Repita pela quantidade recomendada de repetições."]},
"Parallel_Bar_Dip":{"name":"Mergulho nas Barras Paralelas","instructions":["Posicione-se entre as barras paralelas, apoie uma mão em cada barra e dê um pequeno salto para sustentar o corpo com os braços estendidos.","Flexione os cotovelos descendo o corpo até os braços ultrapassarem 90 graus, evitando balançar.","Inverta o movimento estendendo os cotovelos para empurrar o corpo de volta à posição inicial.","Repita pelo número desejado de repetições."]},
"Pelvic_Tilt_Into_Bridge":{"name":"Inclinação Pélvica até Ponte","instructions":["Deite-se de costas com os pés no chão e os calcanhares diretamente abaixo dos joelhos.","Eleve apenas o cóccix em direção ao teto contraindo o abdômen para alongar a lombar sem levantar ainda toda a coluna.","Em seguida, suba para a ponte elevando toda a coluna exceto o pescoço."]},
"Peroneals-SMR":{"name":"Liberação Miofascial dos Fibulares","instructions":["Deite-se de lado apoiando o peso no antebraço e em um rolo de espuma posicionado sob a parte lateral externa da perna abaixo do joelho. Esta será a sua posição inicial.","Eleve o quadril do chão e deslize de logo abaixo do joelho até acima do tornozelo, pausando nos pontos de tensão por 10-30 segundos; repita na outra perna."]},
"Peroneals_Stretch":{"name":"Alongamento dos Fibulares","instructions":["Sentado, passe um cinto, corda ou faixa ao redor de um pé. Esta será a sua posição inicial.","Com a perna estendida e o calcanhar fora do chão, puxe a faixa invertendo o pé (puxando a borda interna em sua direção); segure por 10-20 segundos e troque de lado."]},
"Physioball_Hip_Bridge":{"name":"Ponte de Quadril na Bola Suíça","instructions":["Apoie a parte superior das costas sobre uma bola suíça deixando o quadril suspenso, com os pés firmes no chão na largura do quadril ou mais abertos. Esta será a sua posição inicial.","Estenda o quadril usando glúteos e posteriores de coxa elevando o quadril até formar uma ponte alinhada.","Pause no topo do movimento e retorne à posição inicial."]},
"Pin_Presses":{"name":"Supino nos Pinos (Pin Press)","instructions":["O supino nos pinos remove a fase excêntrica para desenvolver força de arrancada e trabalhar amplitudes específicas.","Posicione o banco dentro de um power rack e ajuste os pinos na altura desejada (próximo ao peito ou perto do travamento), apoiando a barra sobre eles.","Deite-se com a barra alinhada ao ponto de contato no peito, encaixe os pés no chão, arqueie as costas e retraia as escápulas firmando o trapézio no banco.","Use pegada padrão de supino ou na largura dos ombros para focar no tríceps, mantendo barra, punhos e cotovelos alinhados.","Empurre a barra para cima com o máximo de força possível mantendo os cotovelos fechados até estender os braços.","Retorne a barra aos pinos e faça uma breve pausa antes da repetição seguinte."]},
"Piriformis-SMR":{"name":"Liberação Miofascial do Piriforme","instructions":["Sente-se com os glúteos sobre um rolo de espuma, flexione os joelhos e cruze uma perna apoiando o tornozelo sobre o joelho oposto. Esta será a sua posição inicial.","Transfira o peso para o lado da perna cruzada e deslize sobre a parte superior do glúteo até encontrar pontos de tensão (você pode puxar o joelho cruzado para o peito com a mão); segure por 10-30 segundos e troque de lado."]},
"Plank":{"name":"Prancha Abdominal","instructions":["Deite-se de bruços no chão apoiando o peso nas pontas dos pés e nos antebraços com os cotovelos diretamente abaixo dos ombros.","Mantenha o corpo alinhado e reto o tempo todo e sustente a posição pelo máximo de tempo possível (para dificultar, eleve um braço ou uma perna)."]},
"Plate_Pinch":{"name":"Pinça com Anilhas (Plate Pinch)","instructions":["Junte duas anilhas com o lado liso voltado para fora.","Segure as anilhas juntas usando os dedos de um lado e o polegar do outro. Esta é a posição inicial.","Aperte as anilhas firmemente entre os dedos e o polegar e segure pelo máximo de tempo que conseguir.","Repita pela quantidade recomendada de séries.","Troque de braço e repita o movimento."]},
"Plate_Twist":{"name":"Giro Russo com Anilha","instructions":["Sente-se no chão ou colchonete com o tronco inclinado para trás em equilíbrio e segure uma anilha pelas laterais à frente do abdômen com os braços levemente flexionados.","Cruze levemente os tornozelos e tire os pés do chão com joelhos levemente flexionados. Esta é a posição inicial.","Gire o tronco levando a anilha para o lado esquerdo até quase tocar o chão enquanto expira.","Retorne ao centro inspirando e gire para o lado direito de forma controlada sem trancos para proteger a lombar.","Repita pela quantidade recomendada de repetições."]},
"Platform_Hamstring_Slides":{"name":"Flexão Deslizante de Posteriores no Solo","instructions":["Em um piso liso, deite-se de costas com as pernas estendidas e coloque uma toalha ou anilha leve sob um calcanhar. Esta será a sua posição inicial.","Inicie flexionando o joelho dessa perna enquanto mantém a outra estendida.","Continue deslizando o calcanhar pelo chão até aproximá-lo ao máximo de você.","Na flexão máxima do joelho, inverta o movimento deslizando de volta à posição inicial."]},
"Plie_Dumbbell_Squat":{"name":"Agachamento Sumô (Plié) com Halter","instructions":["Segure um halter na vertical pela base superior com as duas mãos e fique em pé com os pés bem afastados além dos ombros e joelhos levemente flexionados.","Aponte os dedos dos pés para fora e mantenha os braços imóveis segurando o halter à frente. Esta é a posição inicial.","Flexione lentamente os joelhos descendo até as coxas ficarem paralelas ao chão enquanto inspira.","Empurre principalmente pelos calcanhares para retornar à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Plyo_Kettlebell_Pushups":{"name":"Flexão Pliométrica com Kettlebell","instructions":["Coloque um kettlebell no chão e entre em posição de flexão de braço com uma mão no solo e a outra segurando o kettlebell, com cotovelos estendidos. Esta será a sua posição inicial.","Desça o corpo o máximo possível mantendo as costas retas.","Impulsione-se com força e rapidez saltando para o outro lado do kettlebell e trocando as mãos, continuando o movimento de um lado para o outro."]},
"Plyo_Push-up":{"name":"Flexão de Braço Pliométrica","instructions":["Assuma posição de flexão de braço no chão sustentando o peso nas mãos e pontas dos pés.","Mantenha braços estendidos com mãos na largura dos ombros e corpo totalmente reto. Esta será a sua posição inicial.","Desça flexionando os cotovelos até aproximar o peito do chão.","Em baixo, empurre-se para cima com máxima explosão até as mãos saírem do chão.","Aterrisse amortecendo e repita o exercício.","Para maior dificuldade, bata palmas no ar antes de retornar as mãos ao chão."]},
"Posterior_Tibialis_Stretch":{"name":"Alongamento do Tibial Posterior","instructions":["Sentado, passe um cinto, corda ou faixa ao redor de um pé. Esta será a sua posição inicial.","Com a perna estendida e o calcanhar fora do chão, puxe a faixa fazendo eversão do pé (puxando a borda externa em sua direção); segure por 10-20 segundos e troque de lado."]},
"Power_Clean":{"name":"Power Clean","instructions":["Fique em pé com os pés um pouco mais abertos que a largura dos ombros e pontas levemente para fora.","Agache e segure a barra com pegada pronada fechada um pouco mais aberta que os ombros, por fora dos joelhos e com braços estendidos.","Posicione a barra cerca de 1 polegada à frente das canelas sobre o meio dos pés.","Mantenha as costas retas ou levemente arqueadas, peito aberto e escápulas retraídas.","Mantenha a cabeça neutra olhando para a frente e inspire nessa preparação.","Tire a barra do chão estendendo com força quadril e joelhos enquanto expira, mantendo constante o ângulo do tronco sem deixar o quadril subir antes dos ombros.","Mantenha os cotovelos totalmente estendidos e os ombros sobre a barra.","Durante a subida, mantenha a barra o mais próxima possível das canelas.","Quando a barra passar pelos joelhos, projete o quadril à frente mantendo as coxas próximas à barra.","Mantenha costas firmes, braços estendidos e cabeça neutra preparando a aceleração.","Estenda explosivamente quadril, joelhos e tornozelos subindo na ponta dos pés.","Mantenha a barra bem próxima ao corpo com ombros acima dela e braços estendidos pelo maior tempo possível.","Quando as articulações inferiores atingirem extensão total, encolha os ombros rapidamente para cima enquanto expira.","No pico do encolhimento, flexione os cotovelos para começar a puxar o corpo para baixo da barra.","Continue puxando com vigor enquanto o tronco permanece ereto.","Após a extensão completa, entre rapidamente sob a barra girando os braços por baixo dela.","Simultaneamente, flexione quadril e joelhos entrando em um quarto de agachamento.","Eleve os cotovelos posicionando os braços paralelos ao chão e apoie a barra sobre a parte frontal dos ombros e clavículas.","Receba a barra com tronco firme e ereto, cabeça neutra e pés plantados no chão enquanto expira.","Levante-se estendendo quadril e joelhos até ficar totalmente ereto.","Abaixe a barra de forma controlada até a altura das coxas enquanto inspira.","Flexione levemente quadril e joelhos para amortecer o peso nas coxas.","Agache com os braços estendidos acompanhando a barra até tocar o chão.","Reinicie a partir da posição inicial pela quantidade recomendada de repetições."]},
"Power_Clean_from_Blocks":{"name":"Power Clean dos Blocos","instructions":["Com a barra apoiada em caixas na altura desejada, segure-a logo por fora das pernas com peso nos calcanhares, costas retas, peito aberto e ombros à frente da barra. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pelos calcanhares e estendendo os joelhos mantendo constante o ângulo das costas até a barra chegar ao meio das coxas.","Estenda explosivamente quadril, joelhos e tornozelos como em um salto para acelerar a barra para cima mantendo os braços estendidos.","No pico da extensão, encolha os ombros e entre rapidamente sob a barra girando os cotovelos para recebê-la apoiada nos ombros em meio agachamento.","Recupere-se imediatamente empurrando pelos calcanhares até ficar em pé e retorne a barra às caixas para concluir a repetição."]},
"Power_Jerk":{"name":"Power Jerk","instructions":["Em pé com a barra apoiada na frente dos ombros e pés sob o quadril, faça uma leve flexão rápida dos joelhos sem jogar o quadril para trás e inverta com máxima potência.","Impulsione pelos calcanhares gerando velocidade e recue a cabeça do caminho quando a barra subir dos ombros.","No momento em que os pés saírem do chão, abra-os rapidamente para uma base um pouco mais larga com joelhos semiflexionados.","Receba a barra com os braços totalmente estendidos e travados acima da cabeça.","Junte os pés retornando à posição ereta."]},
"Power_Partials":{"name":"Elevação Lateral Pesada Parcial (Power Partials)","instructions":["Fique em pé com o tronco ereto segurando um halter em cada mão com os braços estendidos e cotovelos próximos ao tronco.","Mantenha as palmas voltadas para o corpo e os pés na largura dos ombros. Esta será a sua posição inicial.","Mantendo os braços retos e o tronco imóvel, eleve os halteres lateralmente até aproximadamente a altura dos ombros enquanto expira.","Sinta a contração por um segundo e abaixe lentamente de volta à posição inicial enquanto inspira, mantendo o dedo mínimo levemente mais alto que o polegar.","Repita pela quantidade recomendada de repetições."]},
"Power_Snatch":{"name":"Power Snatch","instructions":["Com a barra carregada no chão próxima às canelas, segure-a com pegada aberta, pés sob o quadril, quadril baixo, peito aberto e ombros à frente da barra. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pela parte anterior dos calcanhares mantendo o ângulo das costas constante até passar pelos joelhos.","Faça a segunda puxada estendendo explosivamente quadril, joelhos e tornozelos mantendo a barra rente ao corpo; no pico, encolha os ombros e flexione os cotovelos para os lados.","Ao abrir os pés para a base de recepção, puxe-se rapidamente sob a barra recebendo-a em agachamento parcial com os braços totalmente travados acima da cabeça.","Retorne à posição em pé com a barra acima da cabeça."]},
"Power_Snatch_from_Blocks":{"name":"Power Snatch dos Blocos","instructions":["Com a barra apoiada sobre caixas na altura desejada, faça pegada aberta, pés sob o quadril, quadril baixo, peito aberto e ombros à frente da barra com cotovelos para fora. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pela parte anterior dos calcanhares para tirar a barra das caixas.","Faça a segunda puxada estendendo explosivamente quadril, joelhos e tornozelos mantendo a barra rente ao corpo; no pico, encolha os ombros e flexione os cotovelos para os lados.","Ao abrir os pés para fora da linha do quadril, puxe-se rapidamente sob a barra recebendo-a acima do agachamento completo com os braços totalmente estendidos acima da cabeça.","Mantendo a barra alinhada sobre os calcanhares e peito erguido, levante-se empurrando pelos calcanhares e devolva a barra às caixas com cuidado."]},
"Power_Stairs":{"name":"Escada de Potência (Power Stairs)","instructions":["Nesta prova de strongman, implementos pesados são elevados degrau por degrau (ou com pneu/caixa no treino).","Segure o implemento com as duas mãos em base bem aberta com peito e cabeça erguidos e empurre pelos calcanhares estendendo joelhos e quadril para tirar o peso do chão.","Inclinando-se levemente para trás, balance o peso até apoiá-lo no degrau seguinte (cerca de 16-18 polegadas de altura).","Repita por 3-5 degraus avançando para cargas maiores o mais rápido possível."]},
"Preacher_Curl":{"name":"Rosca Scott com Barra W","instructions":["No banco Scott, segure a barra W na pegada interna fechada com as palmas voltadas para a frente e levemente inclinadas para dentro.","Apoie a parte posterior dos braços e o peito no suporte acolchoado mantendo a barra à frente na altura dos ombros. Esta será a sua posição inicial.","Enquanto inspira, abaixe lentamente a barra até estender o braço e alongar totalmente o bíceps.","Ao expirar, flexione os cotovelos contraindo o bíceps até a barra voltar à altura dos ombros e segure a contração por um segundo.","Repita pela quantidade recomendada de repetições."]},
"Preacher_Hammer_Dumbbell_Curl":{"name":"Rosca Martelo no Banco Scott com Halteres","instructions":["Apoie a parte posterior dos dois braços no banco Scott segurando um halter em cada mão em pegada neutra (palmas voltadas uma para a outra).","Enquanto inspira, abaixe lentamente os halteres até estender os braços e alongar totalmente o bíceps.","Ao expirar, flexione os cotovelos contraindo o bíceps até os halteres alcançarem a altura dos ombros.","Aperte forte o bíceps por um segundo na contração e repita pela quantidade recomendada de repetições."]},
"Press_Sit-Up":{"name":"Abdominal com Supino com Barra","instructions":["Deite-se em um banco abdominal prendendo os pés no apoio e segurando uma barra apoiada sobre o peito. Esta é a sua posição inicial.","Inspire, contraia abdômen e glúteos e execute a subida do abdominal enquanto empurra a barra acima da cabeça ao expirar.","Retorne o tronco à posição inicial trazendo a barra de volta ao peito enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Prone_Manual_Hamstring":{"name":"Flexão Manual de Posteriores de Bruços (Com Parceiro)","instructions":["Deite-se de bruços com as pernas estendidas enquanto seu parceiro apoia a mão sobre o seu calcanhar.","Flexione o joelho puxando a perna para cima contra a resistência aplicada pelo parceiro (começando leve e aumentando gradualmente conforme combinado).","Pause no topo e retorne a perna à posição inicial resistindo à pressão do parceiro na descida."]},
"Prowler_Sprint":{"name":"Sprint Empurrando Trenó (Prowler)","instructions":["Posicione o trenó em uma superfície adequada carregado com peso que exija esforço sem impedir o deslocamento.","Segure os pegadores verticais ou baixos com os braços estendidos inclinando o corpo contra o trenó.","Mantendo boa postura, empurre o chão com passos curtos, rápidos e alternados deslocando-se o mais rápido possível por uma curta distância."]},
"Pull_Through":{"name":"Pull Through no Cabo","instructions":["Fique alguns pés à frente de uma polia baixa com corda ou pegador acoplado, de costas para a máquina, com o cabo passando entre os pés bem afastados.","Incline o tronco flexionando o quadril e levando as mãos bem para trás entre as pernas com joelhos levemente flexionados; depois estenda o quadril com braços retos até ficar ereto sem puxar com os ombros."]},
"Pullups":{"name":"Barra Fixa Pronada","instructions":["Segure a barra fixa com as palmas voltadas para a frente na largura prescrita (aberta, média ou fechada).","Pendurado com os braços estendidos, incline o tronco cerca de 30 graus para trás criando leve curvatura lombar e abrindo o peito. Esta é a sua posição inicial.","Puxe o tronco para cima levando ombros e braços para baixo e para trás até o peito superior encostar na barra enquanto expira, contraindo as costas no topo.","Após segurar um segundo na contração, desça lentamente enquanto inspira até estender totalmente os braços e alongar as dorsais.","Repita esse movimento pela quantidade prescrita de repetições."]},
"Push-Up_Wide":{"name":"Flexão de Braço Aberta","instructions":["Em posição de prancha apoiado nas pontas dos pés e mãos bem abertas além da largura dos ombros, mantenha braços estendidos e corpo reto sem deixar o quadril cair. Esta será a sua posição inicial.","Flexione os cotovelos descendo o peito em direção ao chão enquanto inspira.","Usando o peitoral, empurre o corpo de volta à posição inicial estendendo os cotovelos enquanto expira.","Após uma breve pausa no topo, repita o movimento pela quantidade prescrita de repetições."]},
"Push-Ups_-_Close_Triceps_Position":{"name":"Flexão de Braço Fechada (Foco Tríceps)","instructions":["Deite-se de bruços apoiando as mãos mais próximas que a largura dos ombros sustentando o corpo com braços estendidos.","Desça o corpo até o peito quase tocar o chão enquanto inspira.","Usando o tríceps e o peitoral, empurre o corpo de volta à posição inicial contraindo o peito enquanto expira.","Após uma pausa de um segundo no topo, repita o movimento pela quantidade prescrita de repetições."]},
"Push-Ups_With_Feet_Elevated":{"name":"Flexão de Braço com Pés Elevados","instructions":["Deite-se de bruços apoiando as mãos afastadas cerca de 36 polegadas sustentando o tronco com braços estendidos.","Apoie as pontas dos pés sobre um banco reto para elevar o corpo (quanto maior a altura do banco, maior a dificuldade).","Desça até o peito quase tocar o chão enquanto inspira.","Usando o peitoral, empurre o corpo de volta à posição inicial contraindo o peito enquanto expira.","Após uma pausa de um segundo no topo, repita o movimento pela quantidade prescrita de repetições."]},
"Push-Ups_With_Feet_On_An_Exercise_Ball":{"name":"Flexão de Braço com Pés na Bola Suíça","instructions":["Deite-se de bruços apoiando as mãos afastadas cerca de 36 polegadas sustentando o tronco com braços estendidos.","Apoie as pontas dos pés em cima de uma bola suíça para elevar e instabilizar o corpo.","Desça até o peito quase tocar o chão enquanto inspira.","Usando o peitoral, empurre o corpo de volta à posição inicial contraindo o peito enquanto expira.","Após uma pausa de um segundo no topo, repita o movimento pela quantidade prescrita de repetições."]},
"Push_Press":{"name":"Push Press com Barra","instructions":[]},
"Push_Press_-_Behind_the_Neck":{"name":"Push Press por Trás da Nuca","instructions":["Em pé com a barra apoiada na parte posterior dos ombros e pés sob o quadril, faça uma leve flexão rápida dos joelhos sem jogar o quadril para trás e inverta com máxima potência pelos calcanhares.","Aproveitando o impulso gerado, finalize empurrando a barra acima da cabeça estendendo os braços.","Retorne a barra à posição inicial amortecendo o impacto com as pernas."]},
"Push_Up_to_Side_Plank":{"name":"Flexão de Braço com Prancha Lateral","instructions":["Entre em posição de flexão de braço apoiado nas pontas dos pés com mãos um pouco além da largura dos ombros.","Execute uma flexão dobrando os cotovelos e mantendo o corpo alinhado.","Ao subir da flexão, transfira o peso para o braço esquerdo e gire o corpo elevando o braço direito em direção ao teto em prancha lateral.","Abaixe a mão de volta ao chão, faça outra flexão e gire para o lado oposto.","Repita a sequência alternando os lados por 10 ou mais repetições."]},
"Pushups":{"name":"Flexão de Braço","instructions":["Deite-se de bruços no chão com as mãos afastadas cerca de 36 polegadas sustentando o tronco com braços estendidos.","Desça o corpo até o peito quase tocar o chão enquanto inspira.","Expire e empurre o corpo de volta à posição inicial contraindo o peitoral.","Após uma breve pausa no topo, desça novamente repetindo quantas vezes forem necessárias."]},
"Pushups_Close_and_Wide_Hand_Positions":{"name":"Flexão de Braço (Pegada Fechada e Aberta)","instructions":["Deite-se de bruços com corpo reto, pontas dos pés no chão e mãos mais abertas que os ombros (para pegada aberta) ou mais próximas (para pegada fechada), sustentando o tronco com braços estendidos.","Desça até o peito quase tocar o chão enquanto inspira.","Usando o peitoral, empurre o corpo de volta à posição inicial contraindo o peito enquanto expira.","Após uma pausa de um segundo no topo, repita o movimento pela quantidade prescrita de repetições."]},
"Pyramid":{"name":"Pirâmide na Bola Suíça","instructions":["Role o tronco para a frente sobre a bola suíça de modo que o quadril fique apoiado no topo da bola como o ponto mais alto do corpo.","Apoie mãos e pés no chão mantendo braços e pernas retos ou levemente flexionados conforme o tamanho da bola e sua flexibilidade para desenvolver estabilidade de tronco e ombros."]},
"Quad_Stretch":{"name":"Alongamento de Quadríceps com Faixa","instructions":["Deite-se de lado, passe um cinto ou faixa ao redor do pé de cima, flexione o joelho e estenda o quadril tentando aproximar o pé dos glúteos enquanto segura a faixa. Esta será a sua posição inicial.","Passando a faixa sobre o ombro ou acima da cabeça, puxe suavemente para intensificar o alongamento do quadríceps; segure por 10-20 segundos e troque de lado."]},
"Quadriceps-SMR":{"name":"Liberação Miofascial do Quadríceps","instructions":["Deite-se de bruços apoiado nas mãos ou antebraços com um rolo de espuma sob o quadríceps de uma perna relaxada e pé fora do chão. Esta será a sua posição inicial.","Transferindo o máximo de peso suportável para a perna, deslize sobre o rolo de acima do joelho até abaixo do quadril segurando pontos de tensão por 10-30 segundos; depois troque de lado."]},
"Quick_Leap":{"name":"Salto Rápido na Caixa (Quick Leap)","instructions":["Posicione uma caixa à sua frente.","Fique de frente para a caixa a 1-2 pés da borda.","Usando o quadril, salte sobre a caixa aterrissando com os dois pés firmes e joelhos flexionados.","Imediatamente após aterrissar, estenda todo o corpo balançando os braços acima da cabeça para saltar para longe da caixa e absorva a aterrissagem com as pernas."]},
"Rack_Delivery":{"name":"Recepção da Barra nos Ombros (Rack Delivery)","instructions":["Segure uma barra na posição de espantalho (braços paralelos ao chão e antebraços para baixo) usando pegada hook grip.","Gire rapidamente os cotovelos ao redor e por baixo da barra levando-a aos ombros enquanto relaxa os dedos e projeta os ombros à frente para formar um apoio próximo à garganta.","Mantenha a barra sempre rente ao corpo para evitar impactos e aumente gradualmente velocidade e carga conforme o movimento ficar fluido."]},
"Rack_Pull_with_Bands":{"name":"Levantamento Terra Parcial nos Pinos com Elásticos","instructions":["Ajuste a barra sobre os pinos de um power rack na altura desejada (logo abaixo ou acima dos joelhos ou meio da coxa) e prenda elásticos da base do rack (ou halteres pesados) até a barra.","Assuma a postura de levantamento terra com pés sob o quadril, pegada na largura dos ombros (mista, hook grip ou com straps), costas firmes e quadril para trás.","Olhando para a frente, estenda quadril e joelhos puxando a carga para cima e para trás até travar os ombros para trás, depois retorne a barra aos pinos e repita."]},
"Rack_Pulls":{"name":"Levantamento Terra Parcial nos Pinos (Rack Pulls)","instructions":["Ajuste a barra sobre os pinos do power rack na altura desejada (abaixo ou acima dos joelhos ou meio da coxa) e posicione-se com pés sob o quadril, costas firmes e pegada na largura dos ombros (mista, hook grip ou com straps).","Olhando à frente, estenda quadril e joelhos puxando o peso para cima e para trás até travar com os ombros encaixados.","Retorne a barra aos pinos e repita."]},
"Rear_Leg_Raises":{"name":"Elevação Posterior de Perna em Quatro Apoios","instructions":["Apoie-se em quatro apoios em um colchonete com a cabeça olhando à frente e joelhos a 90 graus. Esta será a sua posição inicial.","Estenda uma perna para trás e para cima estendendo joelho e quadril; repita 5-10 vezes e depois troque de lado."]},
"Recumbent_Bike":{"name":"Bicicleta Ergométrica Horizontal","instructions":["Sente-se na bicicleta horizontal e ajuste a distância do assento à sua altura.","Selecione o programa ou modo manual no painel, ajuste a resistência durante o treino e use os sensores nos apoios laterais para monitorar a frequência cardíaca.","Mantenha ritmo constante pela duração desejada aproveitando o baixo impacto articular da posição reclinada."]},
"Return_Push_from_Stance":{"name":"Passe com Deslocamento (Medicine Ball)","instructions":["Este exercício requer um parceiro.","Comece em postura atlética de 2 ou 3 apoios.","Ao sinal, desloque-se para a posição de recepção do passe do parceiro.","Segure a bola medicinal com as duas mãos e devolva imediatamente ao parceiro.","Você pode variar o exercício correndo por diferentes trajetos."]},
"Reverse_Band_Bench_Press":{"name":"Supino Reto com Elásticos Reversos","instructions":["Posicione um banco dentro do power rack e prenda elásticos no topo da estrutura conectando a outra ponta na barra para aliviar parte da carga na base.","Deite-se no banco, firme os pés no chão, arqueie as costas e retraia as escápulas no banco mantendo o corpo todo tenso.","Retire a barra do suporte sem protrair os ombros e abaixe-a até a parte inferior do peito ou topo do abdômen mantendo barra, punhos e cotovelos alinhados.","Pause quando a barra tocar o tronco e empurre para cima com o máximo de força mantendo os cotovelos fechados até travar os braços."]},
"Reverse_Band_Box_Squat":{"name":"Agachamento na Caixa com Elásticos Reversos","instructions":["Em um power rack com uma caixa atrás na altura desejada, prenda elásticos no topo do rack conectando-os diretamente acima da barra.","Entre sob a barra, apoie-a na parte posterior dos ombros apertando as escápulas, retire-a do suporte e posicione os pés conforme a ênfase desejada olhando à frente.","Com core firme, empurre os joelhos para fora e sente-se para trás na caixa mantendo as canelas verticais; pause na caixa sem quicar.","Mantendo o peso nos calcanhares, suba explosivamente guiando com a cabeça e mantendo o corpo firme, e recoloque a barra no suporte com cuidado."]},
"Reverse_Band_Deadlift":{"name":"Levantamento Terra com Elásticos Reversos","instructions":["Monte a barra dentro de um power rack e prenda elásticos do topo da estrutura até a barra.","Aproxime-se da barra centralizada sobre os pés (largura do quadril), flexione o quadril e segure a barra na largura dos ombros com pegada pronada ou mista.","Inspire fundo, abaixe o quadril até as canelas tocarem a barra, mantenha peito aberto e empurre o chão pelos calcanhares.","Após a barra passar pelos joelhos, puxe os ombros para trás aproximando as escápulas enquanto projeta o quadril contra a barra.","Abaixe a barra flexionando o quadril e guiando-a até o chão."]},
"Reverse_Band_Power_Squat":{"name":"Agachamento Power com Elásticos Reversos","instructions":["Em um power rack com barra e pinos ajustados, prenda elásticos do topo da estrutura até a barra.","Entre sob a barra, apoie-a na parte posterior dos ombros apertando as escápulas, retire-a do suporte e posicione os pés bem abertos.","Olhando para a frente com tronco firme, empurre joelhos e quadril para trás descendo até ultrapassar o paralelo (dobra do quadril alinhada ao topo do joelho).","Mantendo o peso nos calcanhares e joelhos para fora, suba explosivamente conduzindo pela cabeça até retornar à posição inicial."]},
"Reverse_Band_Sumo_Deadlift":{"name":"Levantamento Terra Sumô com Elásticos Reversos","instructions":["Com a barra no chão dentro de um power rack, prenda elásticos do topo da estrutura até a barra.","Aproxime-se com os pés bem abertos próximos às anilhas, flexione o quadril para segurar a barra por dentro das pernas com os braços perpendiculares ao chão (pegada pronada, mista ou hook grip).","Inspire, abaixe o quadril olhando à frente com peito aberto e empurre o chão afastando os pés com o peso na metade traseira dos pés.","Ao passar pelos joelhos, incline-se levemente para trás projetando o quadril contra a barra e aproximando as escápulas.","Retorne o peso ao chão flexionando o quadril de forma controlada."]},
"Reverse_Barbell_Curl":{"name":"Rosca Inversa com Barra","instructions":["Fique em pé com o tronco ereto segurando uma barra na largura dos ombros com pegada pronada (palmas para baixo) e cotovelos próximos ao corpo. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos elevando a barra até a altura dos ombros enquanto expira e segure um segundo no topo, movendo apenas os antebraços.","Abaixe lentamente a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Reverse_Barbell_Preacher_Curls":{"name":"Rosca Scott Inversa com Barra","instructions":["Segure uma barra W com pegada pronada (palmas para baixo) na largura dos ombros.","Apoie a parte posterior dos braços sobre o banco Scott com os braços estendidos. Esta será a sua posição inicial.","Ao expirar, flexione os cotovelos elevando a barra até a altura dos ombros e segure a contração por um segundo.","Enquanto inspira, abaixe lentamente a barra até estender totalmente os braços.","Repita pela quantidade recomendada de repetições."]},
"Reverse_Cable_Curl":{"name":"Rosca Inversa no Cabo","instructions":["Fique em pé segurando uma barra acoplada à polia baixa com pegada pronada (palmas para baixo) na largura dos ombros e cotovelos próximos ao tronco. Esta será a sua posição inicial.","Mantendo os braços imóveis, flexione os cotovelos puxando a barra até a altura dos ombros enquanto expira e segure um segundo no topo, movendo apenas os antebraços.","Abaixe lentamente a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Reverse_Crunch":{"name":"Abdominal Reverso (Infra)","instructions":["Deite-se de costas no chão com as pernas estendidas e os braços ao lado do corpo com palmas no solo (mantenha os braços imóveis).","Eleve as pernas até as coxas ficarem perpendiculares ao chão com os joelhos dobrados a 90 graus e pés juntos. Esta é a posição inicial.","Ao expirar/contrair o abdômen, traga os joelhos em direção ao peito girando a pelve para trás e tirando o quadril do chão.","Segure a contração por um segundo e retorne as pernas à posição inicial de forma controlada.","Repita pela quantidade recomendada de repetições."]},
"Reverse_Flyes":{"name":"Crucifixo Inverso no Banco Inclinado com Halteres","instructions":["Deite-se de bruços em um banco inclinado segurando um halter em cada mão em pegada neutra (palmas voltadas uma para a outra).","Estenda os braços para baixo perpendiculares ao chão apoiando-se na ponta dos pés. Esta é a posição inicial.","Mantendo leve flexão nos cotovelos, abra os braços lateralmente em arco enquanto expira, apertando bem as escápulas.","Eleve os braços até ficarem paralelos ao chão.","Sinta a contração e abaixe lentamente os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Reverse_Flyes_With_External_Rotation":{"name":"Crucifixo Inverso com Rotação Externa","instructions":["Deite-se de bruços em um banco inclinado a 30 graus.","Segure um halter em cada mão com as palmas voltadas para baixo, braços pendurados à frente com leve flexão nos cotovelos e pés firmes nas pontas. Esta é a posição inicial.","Mantendo a leve flexão nos cotovelos, abra os braços lateralmente em arco enquanto expira.","Ao elevar os braços, gire externamente os punhos em 90 graus passando de pegada pronada para pegada neutra e apertando as escápulas.","Eleve os braços até ficarem na altura da cabeça.","Sinta a contração e abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Reverse_Grip_Bent-Over_Rows":{"name":"Remada Curvada Pegada Supinada","instructions":["Fique em pé segurando uma barra com pegada supinada (palmas para cima).","Flexione levemente os joelhos e incline o tronco à frente mantendo as costas retas até quase ficar paralelo ao chão, com a cabeça erguida e os braços pendurados. Esta é a posição inicial.","Mantendo o tronco imóvel, puxe a barra em direção ao abdômen enquanto expira com os cotovelos próximos ao corpo, contraindo as costas por um segundo no topo.","Abaixe lentamente a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Reverse_Grip_Triceps_Pushdown":{"name":"Tríceps Pulley Pegada Supinada (Invertida)","instructions":["Prenda uma barra reta ou barra W na polia alta.","De frente para a máquina, segure a barra com pegada supinada (palmas para cima) na largura dos ombros, cotovelos fechados junto ao tronco e braços estendidos para baixo. Esta é a posição inicial.","Suba lentamente a barra até a altura do peito enquanto inspira mantendo braços e cotovelos imóveis ao lado do corpo.","Empurre a barra de volta para baixo estendendo os cotovelos e contraindo forte o tríceps enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Reverse_Hyperextension":{"name":"Hiperextensão Reversa (Reverse Hyper)","instructions":["Apoie os pés nas alças após carregar o peso adequado e deite-se de bruços no apoio superior deixando o quadril livre na borda traseira enquanto segura os pegadores.","Flexione o quadril trazendo as pernas para a frente por baixo do aparelho.","Inverta estendendo o quadril para elevar as pernas para trás sem hiperestender demais a lombar.","Retorne flexionando novamente o quadril levando o pêndulo à frente.","Repita pelo número desejado de repetições."]},
"Reverse_Machine_Flyes":{"name":"Crucifixo Inverso na Máquina (Peck Deck Invertido)","instructions":["Ajuste os braços da máquina totalmente para a frente, selecione a carga, regule o assento na altura dos ombros e segure os pegadores com as palmas voltadas para dentro. Esta será a sua posição inicial.","Em movimento semicircular, puxe os braços para os lados e para trás contraindo os deltoides posteriores.","Mantenha os cotovelos levemente flexionados durante todo o movimento, movendo apenas a articulação dos ombros.","Pause na parte posterior do movimento e retorne lentamente à posição inicial."]},
"Reverse_Plate_Curls":{"name":"Rosca Inversa com Anilha","instructions":["Fique em pé segurando uma anilha pelas laterais nas posições de 11 e 1 horas com pegada pronada (dedos do lado áspero e polegares no lado liso) e braços estendidos.","Mantenha os pés na largura dos ombros e a anilha à frente do quadril. Esta é a posição inicial.","Eleve lentamente a anilha mantendo cotovelos fechados e braços imóveis até os antebraços tocarem o bíceps enquanto expira.","Sinta a contração por um segundo e abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Reverse_Triceps_Bench_Press":{"name":"Supino Invertido (Pegada Supinada) para Tríceps","instructions":["Deite-se em um banco reto, retire a barra do suporte usando pegada supinada fechada (largura dos ombros) e segure-a acima de você com os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça a barra lentamente até sentir tocar o meio do peito mantendo os cotovelos próximos ao tronco o tempo todo.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando o tríceps, segure um segundo no topo e desça devagar novamente.","Repita o movimento pela quantidade prescrita de repetições.","Ao terminar, recoloque a barra no suporte."]},
"Rhomboids-SMR":{"name":"Liberação Miofascial dos Romboides","instructions":["Deite-se de costas com um rolo de espuma sob a parte superior das costas e cruze os braços à frente do peito protraindo os ombros. Esta será a sua posição inicial.","Eleve o quadril do chão apoiando o peso no rolo e incline-se para um lado de cada vez deslizando pelo meio e topo das costas, pausando nos pontos de tensão por 10-30 segundos."]},
"Rickshaw_Carry":{"name":"Caminhada com Estrutura Rickshaw","instructions":["Carregue a estrutura com o peso adequado, posicione-se no centro, segure as alças e levante impulsionando pelos calcanhares com peito erguido e costas retas.","Caminhe rapidamente com passos curtos e controlados olhando para a frente e respirando normalmente até atingir a linha final, onde deve apoiar a estrutura no chão."]},
"Rickshaw_Deadlift":{"name":"Levantamento Terra na Estrutura Rickshaw","instructions":["Carregue a estrutura com o peso desejado, centralize-se entre as alças com os pés na largura do quadril e flexione o quadril para segurar as alças.","Inspire fundo, abaixe o quadril, flexione os joelhos mantendo peito aberto e costas firmes, e empurre pelos calcanhares aproximando as escápulas e projetando o quadril à frente na subida.","Abaixe a carga flexionando o quadril e guiando-a de volta até o chão."]},
"Ring_Dips":{"name":"Mergulho nas Argolas","instructions":["Segure uma argola em cada mão e dê um pequeno salto para entrar na posição inicial com os braços estendidos.","Flexione os cotovelos descendo o corpo até os braços ultrapassarem 90 graus, evitando balançar e mantendo boa postura.","Inverta o movimento estendendo os cotovelos para empurrar o corpo de volta à posição inicial.","Repita pelo número desejado de repetições."]},
"Rocket_Jump":{"name":"Salto Foguete (Rocket Jump)","instructions":["Comece em postura relaxada com os pés na largura dos ombros e os braços próximos ao corpo.","Faça um meio agachamento e exploda verticalmente o mais alto possível.","Estenda todo o corpo levando os braços bem alto acima da cabeça e amorteça a aterrissagem com as pernas."]},
"Rocking_Standing_Calf_Raise":{"name":"Elevação de Panturrilha em Pé com Barra (Balancinho)","instructions":["Dentro de um rack de agachamento, ajuste a barra na altura ideal e apoie-a na parte posterior dos ombros (logo abaixo do pescoço).","Segure a barra com as duas mãos e retire-a do suporte estendendo pernas e tronco.","Afaste-se com pés na largura dos ombros, cabeça erguida, costas retas e joelhos levemente destravados. Esta será a sua posição inicial.","Eleve os calcanhares o máximo possível enquanto expira contraindo as panturrilhas sem dobrar os joelhos e segure por um segundo.","Retorne lentamente abaixando os calcanhares no chão enquanto inspira.","Em seguida, eleve a ponta dos pés contraindo o tibial anterior enquanto expira.","Segure por um segundo e abaixe os pés de volta enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Rocky_Pull-Ups_Pulldowns":{"name":"Barra Fixa Rocky (Alternada Frente e Nuca)","instructions":["Segure a barra fixa com pegada pronada aberta (palmas voltadas para a frente).","Pendurado com braços estendidos, incline o tronco cerca de 30 graus para trás abrindo o peito. Esta é a posição inicial.","Puxe o tronco para cima até a parte superior do peito tocar a barra enquanto expira contraindo as costas.","Após segurar um segundo no topo, desça lentamente enquanto inspira até estender totalmente os braços.","Na repetição seguinte, mantenha o tronco mais reto e puxe levando a barra em direção à nuca (inclinando levemente a cabeça à frente).","Desça à posição inicial e continue alternando pela quantidade prescrita de repetições."]},
"Romanian_Deadlift":{"name":"Levantamento Terra Romeno (Stiff Romeno)","instructions":["Coloque uma barra no chão à sua frente e segure-a com pegada pronada um pouco mais aberta que a largura dos ombros.","Flexione levemente os joelhos mantendo canelas verticais, quadril para trás e costas retas. Esta será a sua posição inicial.","Mantendo costas e braços totalmente retos, estenda o quadril para levantar a barra de forma firme e controlada enquanto expira.","Em pé, abaixe a barra empurrando o quadril para trás mantendo os joelhos apenas levemente flexionados e o peito aberto enquanto inspira na descida e expira ao retornar.","Repita pela quantidade recomendada de repetições."]},
"Romanian_Deadlift_from_Deficit":{"name":"Levantamento Terra Romeno em Déficit","instructions":["Fique em pé sobre uma plataforma elevada segurando uma barra com braços estendidos à frente das coxas.","Flexione levemente os joelhos e empurre o quadril o máximo possível para trás descendo o tronco até onde sua flexibilidade permitir, mantendo as costas totalmente retas e a barra rente às pernas.","Inverta o movimento estendendo o quadril para retornar à posição inicial."]},
"Rope_Climb":{"name":"Subida na Corda","instructions":["Segure a corda com as duas mãos acima da cabeça e puxe para baixo dando um pequeno salto.","Envolva a corda em uma perna usando os pés para travá-la e alcance o mais alto possível com as mãos segurando firme.","Solte a trava dos pés enquanto puxa o corpo para cima com os braços trazendo os joelhos em direção ao peito.","Prenda novamente a corda com os pés, estenda as pernas e alcance mais alto com as mãos até chegar ao topo.","Para descer, afrouxe a pressão dos pés e deslize com controle alternando uma mão abaixo da outra."]},
"Rope_Crunch":{"name":"Abdominal Ajoelhado com Corda no Cabo","instructions":["Ajoelhe-se 1-2 pés à frente de uma torre de cabo com corda acoplada.","Selecione a carga adequada e segure a corda com as duas mãos acima da cabeça mantendo o tronco ereto na posição inicial.","Flexione a coluna tentando aproximar a caixa torácica das pernas enquanto puxa o cabo para baixo.","Pause no ponto mais baixo e retorne lentamente à posição inicial.","Você pode adicionar rotações laterais para enfatizar os oblíquos."]},
"Rope_Jumping":{"name":"Pular Corda","instructions":["Segure uma ponta da corda em cada mão com a corda atrás do corpo no chão, gire-a por cima da cabeça e salte quando ela passar sob os pés mantendo um ritmo constante.","Varie velocidade e estilos de salto conforme seu condicionamento e objetivo cardiovascular."]},
"Rope_Straight-Arm_Pulldown":{"name":"Pulldown com Braços Estendidos e Corda","instructions":["Prenda uma corda na polia alta, selecione a carga, dê alguns passos para trás em base alternada e incline o tronco à frente pelo quadril mantendo costas retas e braços estendidos à frente. Esta será a sua posição inicial.","Mantendo os braços estendidos, estenda os ombros puxando a corda para baixo até as coxas.","Pause na parte inferior apertando bem as dorsais.","Retorne à posição inicial sem deixar o peso encostar totalmente na pilha."]},
"Round_The_World_Shoulder_Stretch":{"name":"Alongamento de Ombros Volta ao Mundo com Bastão","instructions":["Fique em pé com as pernas juntas segurando um bastão ou cabo de vassoura.","Segure o bastão atrás do quadril com pegada mais larga que os ombros, palmas para trás e polegares para fora.","Eleve lentamente os braços por trás até acima da cabeça sem forçar além do limite confortável."]},
"Rowing_Stationary":{"name":"Remo Ergômetro (Remo Seco)","instructions":["Sente-se no remo ergômetro, prenda bem os pés nas tiras, selecione o programa desejado, mantenha costas retas e incline-se à frente pelo quadril.","Na fase inicial, com joelhos dobrados junto ao peito, empurre o apoio com as pernas estendendo-as enquanto puxa o pegador em direção à parte superior do abdômen apertando os ombros para trás.","Na fase de recuperação, estenda os braços, flexione os joelhos e deslize o corpo à frente para reiniciar o ciclo."]},
"Runners_Stretch":{"name":"Alongamento do Corredor","instructions":["Comece em pé, dê um passo longo para trás com uma perna e apoie as mãos no chão ao lado do pé da frente.","Mantenha o calcanhar da frente apoiado no chão (se levantar, leve a perna de trás um pouco mais para trás).","Para aprofundar o alongamento, eleve levemente o quadril em direção ao teto e depois abaixe-o novamente alongando flexor do quadril atrás e posterior na frente."]},
"Running_Treadmill":{"name":"Corrida na Esteira","instructions":["Suba na esteira e selecione o modo manual ou programa desejado no painel, ajustando inclinação e velocidade conforme sua intensidade.","Mantenha boa postura ao correr e segure nos apoios laterais apenas ao subir, descer ou verificar a frequência cardíaca."]},
"Russian_Twist":{"name":"Torção Russa (Russian Twist)","instructions":["Sente-se no chão com joelhos flexionados e pés apoiados sob um suporte fixo ou segurados por um parceiro.","Incline o tronco para trás formando um \"V\" com as coxas e estenda os braços unidos à frente perpendiculares ao tronco. Esta é a posição inicial.","Gire o tronco para a direita até os braços ficarem paralelos ao chão enquanto expira.","Segure a contração por um segundo, retorne ao centro e gire para o lado esquerdo executando a mesma técnica.","Repita pela quantidade recomendada de repetições."]},
"Sandbag_Load":{"name":"Carregamento de Saco de Areia (Sandbag Load)","instructions":["Posicione os sacos de areia a uma distância da plataforma de carregamento (geralmente 50 pés).","Abrace o saco de areia o mais ao redor possível e estenda quadril e joelhos para erguê-lo bem alto contra o peito.","Desloque-se o mais rápido possível até a plataforma e coloque o saco em cima estendendo quadril, joelhos e tornozelos sem deixá-lo cair.","Retorne para buscar o próximo saco e repita até completar a prova."]},
"Scapular_Pull-Up":{"name":"Puxada Escapular na Barra Fixa","instructions":["Segure uma barra fixa com pegada pronada.","Pendurado com os braços estendidos, eleve o corpo alguns centímetros sem dobrar os cotovelos apenas deprimindo as escápulas.","Pause no topo e retorne lentamente à posição inicial antes da próxima repetição."]},
"Scissor_Kick":{"name":"Tesoura Abdominal (Scissor Kick)","instructions":["Deite-se de costas no chão ou colchonete com os braços estendidos ao lado do corpo e palmas para baixo.","Com leve flexão nos joelhos, eleve as pernas deixando os calcanhares cerca de 6 polegadas acima do solo. Esta é a posição inicial.","Eleve a perna esquerda até cerca de 45 graus enquanto abaixa a direita até 2-3 polegadas do chão.","Alterne subindo a perna direita e descendo a esquerda mantendo a respiração contínua.","Repita pela quantidade recomendada de repetições."]},
"Scissors_Jump":{"name":"Salto Tesoura (Avanço com Salto)","instructions":["Assuma a posição de avanço com um pé à frente, joelho flexionado e joelho de trás quase tocando o chão.","Mantendo o joelho da frente alinhado ao pé, impulsione com ambas as pernas saltando o mais alto possível com ajuda dos braços.","No ar, troque rapidamente a posição das pernas levando a da frente para trás e a de trás para a frente.","Aterrisse amortecendo na posição de avanço e repita continuamente."]},
"Seated_Band_Hamstring_Curl":{"name":"Flexão de Joelhos Sentado com Elástico","instructions":["Prenda um elástico próximo ao chão e posicione um banco alguns pés à frente.","Sente-se no banco e prenda o elástico atrás dos tornozelos com as pernas estendidas à frente. Esta será a sua posição inicial.","Flexione os joelhos trazendo os pés em direção ao banco (incline-se levemente para trás se necessário para os pés não tocarem o chão).","Pause na contração máxima e retorne lentamente à posição inicial."]},
"Seated_Barbell_Military_Press":{"name":"Desenvolvimento Militar Sentado com Barra","instructions":["Sente-se em um banco com encosto com a barra atrás ou à frente e pegue-a cuidadosamente com pegada pronada mais aberta que os ombros.","Retire a barra e estenda os braços acima da cabeça; em seguida, segure na altura dos ombros ligeiramente à frente da cabeça. Esta é a sua posição inicial.","Desça a barra lentamente até a clavícula enquanto inspira.","Empurre a barra de volta à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Seated_Barbell_Twist":{"name":"Rotação de Tronco Sentado com Barra","instructions":["Sente-se na extremidade de um banco reto com uma barra sobre as coxas e pés na largura dos ombros.","Segure a barra com pegada pronada aberta e passe-a por cima da cabeça.","Apoie a barra atrás da cabeça sobre a base do pescoço. Esta é a posição inicial.","Mantendo pés e cabeça imóveis, gire a cintura de um lado para o outro de forma lenta e controlada até sentir a contração dos oblíquos, sem forçar além do limite natural.","Expire ao girar para o lado e inspire ao voltar para o centro.","Repita pela quantidade recomendada de repetições."]},
"Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":{"name":"Coice Unilateral Sentado com Halter","instructions":["Sente-se na extremidade de um banco reto segurando um halter em uma mão em pegada neutra.","Incline o tronco à frente mantendo as costas retas até ficar quase paralelo ao chão e olhe para a frente.","Eleve o braço junto ao tronco paralelo ao chão com o antebraço apontando para baixo formando 90 graus no cotovelo. Esta é a posição inicial.","Mantendo a parte superior do braço imóvel, estenda o cotovelo usando o tríceps até o antebraço ficar paralelo ao chão enquanto expira.","Após segurar um segundo no topo, abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade prescrita de repetições.","Troque de braço e repita o exercício."]},
"Seated_Bent-Over_Rear_Delt_Raise":{"name":"Crucifixo Inverso Sentado com Halteres","instructions":["Coloque um par de halteres no chão à frente de um banco reto.","Sente-se na extremidade do banco com as pernas juntas e os halteres atrás das panturrilhas.","Incline o tronco à frente mantendo as costas retas para segurar os halteres com as palmas voltadas uma para a outra. Esta será a sua posição inicial.","Mantendo o tronco inclinado e imóvel com leve flexão nos cotovelos, eleve os halteres lateralmente até os braços ficarem paralelos ao chão enquanto expira, sem balançar o corpo.","Após uma contração de um segundo no topo, abaixe lentamente os halteres de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":{"name":"Coice Bilateral Sentado com Halteres","instructions":["Sente-se na extremidade de um banco reto segurando um halter em cada mão em pegada neutra.","Incline o tronco à frente mantendo as costas retas até ficar quase paralelo ao chão e olhe para a frente.","Eleve os dois braços juntos ao tronco paralelos ao chão com os antebraços apontando para baixo formando 90 graus nos cotovelos. Esta é a posição inicial.","Mantendo a parte superior dos braços imóvel, estenda os cotovelos usando o tríceps até os braços ficarem totalmente estendidos enquanto expira.","Após segurar um segundo no topo, abaixe lentamente os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade prescrita de repetições."]},
"Seated_Biceps":{"name":"Alongamento de Bíceps Sentado (Com Parceiro)","instructions":["Sente-se no chão com joelhos flexionados e seu parceiro em pé atrás de você; estenda os braços para trás com palmas voltadas uma para a outra enquanto seu parceiro segura seus punhos. Esta será a sua posição inicial.","Tente flexionar os cotovelos enquanto seu parceiro impede qualquer movimento.","Após 10-20 segundos, relaxe os braços enquanto seu parceiro puxa suavemente seus punhos para cima para alongar o bíceps, avisando quando estiver adequado."]},
"Seated_Cable_Rows":{"name":"Remada Baixa Sentada no Cabo (Triângulo)","instructions":["Sente-se na máquina de remada baixa com pegador triângulo (barra em V), apoie os pés na plataforma frontal deixando os joelhos levemente flexionados.","Incline-se à frente mantendo o alinhamento natural das costas para segurar o pegador triângulo.","Com braços estendidos, puxe o tronco para trás até formar 90 graus com as pernas, peito aberto e leve curvatura lombar, sentindo alongar as dorsais. Esta é a posição inicial.","Mantendo o tronco imóvel, puxe o pegador em direção ao abdômen com os braços rentes ao corpo enquanto expira, apertando bem as costas por um segundo e retornando devagar enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Seated_Cable_Shoulder_Press":{"name":"Desenvolvimento Sentado no Cabo","instructions":["Ajuste a carga adequada e sente-se segurando os pegadores com braços a cerca de 90 graus do corpo, cabeça e peito erguidos e cotovelos dobrados a 90 graus. Esta será a sua posição inicial.","Estenda os cotovelos empurrando os pegadores juntos acima da cabeça.","Após pausar no topo, retorne os pegadores à posição inicial mantendo tensão nos cabos.","Você também pode executar sem apoiar as costas no encosto ou alternando os braços."]},
"Seated_Calf_Raise":{"name":"Elevação de Panturrilha Sentado na Máquina","instructions":["Sente-se na máquina e apoie a ponta dos pés na borda inferior da plataforma com os calcanhares livres.","Ajuste e posicione o apoio acolchoado sobre a parte inferior das coxas e apoie as mãos em cima dele para estabilizar.","Eleve levemente os calcanhares e solte a trava de segurança. Esta será a sua posição inicial.","Abaixe lentamente os calcanhares flexionando os tornozelos até alongar totalmente as panturrilhas enquanto inspira.","Eleve os calcanhares o máximo possível contraindo as panturrilhas enquanto expira e segure no topo por um segundo.","Repita pela quantidade recomendada de repetições."]},
"Seated_Calf_Stretch":{"name":"Alongamento de Panturrilha Sentado","instructions":["Sente-se ereto em um colchonete.","Flexione um joelho apoiando o pé no chão para estabilizar o tronco.","Estenda a outra perna e flexione o tornozelo.","Usando uma faixa, toalha ou a própria mão, puxe a ponta do pé em sua direção; segure por 10 a 20 segundos e troque de lado."]},
"Seated_Close-Grip_Concentration_Barbell_Curl":{"name":"Rosca Concentrada Sentado com Barra - Pegada Fechada","instructions":["Sente-se em um banco reto com os joelhos afastados, pés no chão e uma barra ou barra W entre as pernas.","Segure a barra com pegada supinada fechada apoiando a parte posterior dos braços na face interna das coxas (cerca de 3,5 polegadas acima dos joelhos) com braços estendidos. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos contraindo o bíceps enquanto expira até chegar à altura dos ombros e segure um segundo, movendo apenas os antebraços.","Abaixe lentamente a barra de volta à posição inicial enquanto inspira sem balançar o corpo.","Repita pela quantidade recomendada de repetições."]},
"Seated_Dumbbell_Curl":{"name":"Rosca Direta Sentado com Halteres","instructions":["Sente-se em um banco reto com um halter em cada mão, braços estendidos e cotovelos próximos ao tronco.","Mantenha as palmas voltadas para o corpo. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos girando os punhos após passar pelas coxas para que as palmas fiquem para a frente no topo enquanto contrai o bíceps e expira, segurando um segundo.","Abaixe lentamente os halteres de volta à posição inicial enquanto inspira girando os punhos de volta para pegada neutra.","Repita pela quantidade recomendada de repetições."]},
"Seated_Dumbbell_Inner_Biceps_Curl":{"name":"Rosca Sentado para Bíceps Interno com Halteres","instructions":["Sente-se na extremidade de um banco reto segurando um halter em cada mão com braços estendidos e cotovelos próximos ao tronco.","Mantenha as palmas voltadas para dentro em pegada neutra. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, eleve os halteres para fora e para cima girando as palmas para fora alinhados aos deltoides laterais.","Mova apenas os antebraços até contrair totalmente o bíceps na altura dos ombros e segure por um segundo.","Abaixe lentamente de volta à posição inicial enquanto inspira girando de volta à pegada neutra.","Repita pela quantidade recomendada de repetições."]},
"Seated_Dumbbell_Palms-Down_Wrist_Curl":{"name":"Rosca de Punho Inversa Sentado com Halteres","instructions":["Coloque dois halteres no chão à frente de um banco reto.","Sente-se na borda do banco com as pernas na largura dos ombros e os pés firmes no chão.","Segure os halteres e apoie os antebraços sobre as coxas com as palmas voltadas para baixo e os punhos pendurados além da borda das coxas.","Eleve os punhos para cima enquanto expira.","Abaixe lentamente os punhos de volta à posição inicial enquanto inspira mantendo os antebraços imóveis.","Repita pela quantidade recomendada de repetições.","Ao terminar, coloque os halteres no chão."]},
"Seated_Dumbbell_Palms-Up_Wrist_Curl":{"name":"Rosca de Punho Sentado com Halteres","instructions":["Coloque dois halteres no chão à frente de um banco reto.","Sente-se na borda do banco com as pernas na largura dos ombros e os pés firmes no chão.","Segure os halteres e apoie os antebraços sobre as coxas com as palmas voltadas para cima e os punhos pendurados além da borda das coxas.","Flexione os punhos para cima enquanto expira.","Abaixe lentamente os punhos de volta à posição inicial enquanto inspira mantendo os antebraços imóveis.","Repita pela quantidade recomendada de repetições.","Ao terminar, coloque os halteres no chão."]},
"Seated_Dumbbell_Press":{"name":"Desenvolvimento Sentado com Halteres","instructions":["Pegue dois halteres, sente-se em um banco com encosto e apoie-os na vertical sobre as coxas.","Impulsione os halteres até a altura dos ombros um de cada vez com ajuda das coxas.","Gire os punhos para que as palmas fiquem voltadas para a frente. Esta é a sua posição inicial.","Ao expirar, empurre os halteres para cima até quase se tocarem no topo.","Após uma pausa de um segundo, retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Seated_Flat_Bench_Leg_Pull-In":{"name":"Abdominal Puxada de Joelhos Sentado no Banco","instructions":["Sente-se em um banco reto com as pernas estendidas à frente levemente abaixo do paralelo, segurando as laterais do banco e inclinando o tronco para trás cerca de 45 graus. Esta será a sua posição inicial.","Traga os joelhos em direção ao peito enquanto aproxima o tronco deles ao mesmo tempo expirando.","Após uma pausa de um segundo, retorne à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Seated_Floor_Hamstring_Stretch":{"name":"Alongamento de Posteriores Sentado no Chão","instructions":["Sente-se em um colchonete com a perna direita estendida à frente e a esquerda flexionada apoiando o pé na face interna da coxa direita.","Incline-se para a frente pelo quadril alcançando o tornozelo até sentir alongar os posteriores; segure por 15 segundos e depois repita do outro lado."]},
"Seated_Front_Deltoid":{"name":"Alongamento de Deltoide Anterior Sentado (Com Parceiro)","instructions":["Sente-se ereto no chão com pernas flexionadas e seu parceiro atrás; estenda os braços para trás com palmas para baixo o máximo possível enquanto ele segura seus punhos. Esta será a sua posição inicial.","Mantendo os cotovelos retos, tente trazer os braços à frente enquanto seu parceiro impede o movimento por 10-20 segundos.","Relaxe os músculos e deixe seu parceiro aprofundar suavemente o alongamento de ombros e peitoral por 10 a 20 segundos."]},
"Seated_Glute":{"name":"Alongamento de Glúteo Sentado (Com Parceiro)","instructions":["Sentado com joelhos flexionados, cruze um tornozelo sobre o joelho oposto e incline-se à frente enquanto seu parceiro apoia as mãos nos seus ombros. Esta será a sua posição inicial.","Tente empurrar o tronco para trás por 10-20 segundos enquanto seu parceiro impede qualquer movimento.","Relaxe os músculos enquanto seu parceiro aumenta o alongamento empurrando suavemente seu tronco para a frente por 10-20 segundos."]},
"Seated_Good_Mornings":{"name":"Bom Dia Sentado na Caixa","instructions":["Posicione uma caixa dentro de um power rack com pinos na altura adequada. Entre sob a barra apoiando-a na parte posterior dos ombros e aperte as escápulas girando os cotovelos à frente.","Retire a barra do suporte mantendo a lombar firme e sente-se para trás sobre a caixa. Esta será a sua posição inicial.","Mantendo a barra firme nas costas, incline o tronco para a frente pelo quadril o máximo possível até próximo dos pinos.","Pause logo acima dos pinos e inverta o movimento até o tronco voltar à vertical."]},
"Seated_Hamstring":{"name":"Alongamento de Posteriores Sentado (Com Parceiro)","instructions":["Sentado no chão com as pernas estendidas à frente e seu parceiro em pé atrás, incline-se para a frente enquanto ele apoia as mãos nos seus ombros. Esta será a sua posição inicial.","Tente empurrar o tronco para trás por 10-20 segundos enquanto seu parceiro impede o movimento.","Relaxe os músculos enquanto seu parceiro aumenta o alongamento empurrando suavemente seu tronco para a frente por 10-20 segundos."]},
"Seated_Hamstring_and_Calf_Stretch":{"name":"Alongamento de Posteriores e Panturrilha Sentado com Faixa","instructions":["Passe um cinto, corda ou faixa ao redor de um pé e sente-se com as duas pernas estendidas à frente. Esta será a sua posição inicial.","Inclinando-se levemente à frente, puxe a faixa trazendo a ponta do pé para trás; segure por 10-20 segundos e repita com a outra perna."]},
"Seated_Head_Harness_Neck_Resistance":{"name":"Extensão de Pescoço Sentado com Capacete/Alça","instructions":["Coloque uma alça de pescoço com peso no chão na ponta de um banco reto e sente-se na borda com os pés bem afastados.","Incline o tronco à frente, ajuste a alça na cabeça com o peso ainda no chão, segure o peso com as mãos se necessário ao erguer o tronco quase à vertical levemente inclinado à frente.","Apoie as mãos sobre os joelhos. Esta é a posição inicial.","Abaixe lentamente a cabeça até o queixo encostar na parte superior do peito enquanto inspira.","Ao expirar, eleve a cabeça de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Seated_Leg_Curl":{"name":"Cadeira Flexora (Flexão de Pernas Sentado)","instructions":["Ajuste a alavanca da cadeira flexora à sua altura e sente-se apoiando totalmente as costas no encosto.","Apoie a parte posterior das pernas sobre o rolo acolchoado (logo abaixo das panturrilhas), trave o apoio superior sobre as coxas acima dos joelhos, segure as alças laterais e mantenha as pernas estendidas à frente. Esta será a sua posição inicial.","Ao expirar, flexione os joelhos puxando a alavanca o máximo possível para baixo mantendo o tronco imóvel e segure por um segundo.","Retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Seated_Leg_Tucks":{"name":"Abdominal Canivete Sentado no Banco","instructions":["Sente-se em um banco com as pernas estendidas à frente levemente abaixo do paralelo, segurando as laterais do banco com o tronco inclinado para trás a cerca de 45 graus. Esta será a sua posição inicial.","Traga os joelhos em direção ao peito aproximando o tronco simultaneamente enquanto expira.","Após uma pausa de um segundo, retorne à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl":{"name":"Rosca de Punho Inversa Unilateral Sentado com Halter","instructions":["Sente-se em um banco reto com um halter na mão direita.","Apoie os pés firmemente no chão um pouco mais abertos que a largura dos ombros.","Incline-se à frente e apoie o antebraço direito sobre a coxa direita com a palma para baixo e o punho além do joelho. Esta será a sua posição inicial.","Abaixe o halter o máximo possível mantendo a pegada firme enquanto inspira.","Eleve o halter o máximo possível contraindo o antebraço enquanto expira e segure por um segundo, movendo apenas o punho.","Execute pela quantidade recomendada de repetições, troque de braço e repita."]},
"Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl":{"name":"Rosca de Punho Unilateral Sentado com Halter","instructions":["Sente-se em um banco reto com um halter na mão direita.","Apoie os pés firmemente no chão um pouco mais abertos que a largura dos ombros.","Incline-se à frente e apoie o antebraço direito sobre a coxa direita com a palma para cima e o punho além do joelho. Esta será a sua posição inicial.","Abaixe o halter o máximo possível mantendo a pegada firme enquanto inspira.","Flexione o punho para cima o máximo possível contraindo o antebraço enquanto expira e segure por um segundo, movendo apenas o punho.","Execute pela quantidade recomendada de repetições, troque de braço e repita."]},
"Seated_One-arm_Cable_Pulley_Rows":{"name":"Remada Unilateral Sentada no Cabo","instructions":["Sente-se na máquina de remada baixa e apoie os pés na plataforma frontal deixando os joelhos levemente flexionados.","Incline-se à frente mantendo o alinhamento natural das costas e segure o pegador unilateral com a mão esquerda em pegada pronada.","Puxe o tronco até formar 90 graus com as pernas, peito aberto e leve curvatura lombar, alongando a dorsal com a mão direita na cintura. Esta é a posição inicial.","Mantendo o tronco imóvel, puxe o pegador em direção ao abdômen girando o punho para terminar em pegada neutra junto ao corpo enquanto expira, contraindo bem as costas.","Segure por um segundo e retorne lentamente à posição inicial enquanto inspira girando a palma de volta para baixo.","Repita pela quantidade recomendada de repetições e depois execute com a mão direita."]},
"Seated_Overhead_Stretch":{"name":"Alongamento Lateral Acima da Cabeça Sentado","instructions":["Sente-se ereto em um colchonete.","Junte as solas dos pés a cerca de 6 a 8 polegadas à frente do quadril.","Apoie uma mão no chão ao lado do corpo e coloque a outra mão atrás da cabeça.","Aponte o cotovelo elevado para o teto enquanto inclina o tronco para o lado oposto; segure por 10 a 20 segundos e troque de lado."]},
"Seated_Palm-Up_Barbell_Wrist_Curl":{"name":"Rosca de Punho Sentado com Barra","instructions":["Segure uma barra com as duas mãos na largura dos ombros e palmas voltadas para cima.","Apoie os pés no chão um pouco mais abertos que a largura dos ombros.","Incline-se à frente e apoie os antebraços sobre as coxas com os punhos além dos joelhos. Esta será a sua posição inicial.","Abaixe a barra o máximo possível enquanto inspira mantendo a pegada firme.","Flexione os punhos para cima o máximo possível contraindo os antebraços enquanto expira e segure por um segundo, movendo apenas os punhos."]},
"Seated_Palms-Down_Barbell_Wrist_Curl":{"name":"Rosca de Punho Inversa Sentado com Barra","instructions":["Segure uma barra com as duas mãos na largura dos ombros e palmas voltadas para baixo.","Apoie os pés no chão um pouco mais abertos que a largura dos ombros.","Incline-se à frente e apoie os antebraços sobre as coxas com os punhos além dos joelhos. Esta será a sua posição inicial.","Abaixe a barra o máximo possível enquanto inspira mantendo a pegada firme.","Eleve os punhos para cima o máximo possível contraindo os antebraços enquanto expira e segure por um segundo, movendo apenas os punhos."]},
"Seated_Side_Lateral_Raise":{"name":"Elevação Lateral Sentado com Halteres","instructions":["Sente-se na extremidade de um banco reto com os pés firmes no chão segurando um halter em cada mão com palmas voltadas para dentro e braços estendidos ao lado do corpo. Esta será a sua posição inicial.","Mantendo o tronco imóvel, eleve os halteres lateralmente com leve flexão nos cotovelos e mãos levemente inclinadas até os braços ficarem paralelos ao chão enquanto expira, pausando um segundo no topo.","Abaixe lentamente os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Seated_Triceps_Press":{"name":"Tríceps Francês Sentado com Halter","instructions":["Sente-se em um banco com encosto e segure um halter com as duas mãos acima da cabeça com braços estendidos, apoiando as palmas sob a anilha superior e polegares ao redor. Esta será a sua posição inicial.","Mantendo os braços próximos à cabeça e perpendiculares ao chão, abaixe o halter em semicírculo atrás da cabeça até os antebraços tocarem o bíceps enquanto inspira, movendo apenas os antebraços.","Retorne à posição inicial usando o tríceps para empurrar o halter para cima enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl":{"name":"Rosca de Punho Sentado na Polia Baixa","instructions":["Posicione um banco reto à frente de uma polia baixa com barra reta ou barra W acoplada.","Afaste o banco o suficiente para gerar tensão no cabo ao apoiar a barra sobre as coxas.","Segure a barra com as duas mãos na largura dos ombros com palmas para cima.","Sente-se no banco com os pés firmes no chão na largura dos ombros.","Incline-se à frente apoiando os antebraços nas coxas com os punhos além dos joelhos. Esta será a sua posição inicial.","Abaixe a barra o máximo possível enquanto inspira mantendo a pegada firme.","Flexione os punhos para cima o máximo possível contraindo os antebraços (movendo apenas os punhos).","Após segurar um segundo no topo, retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"See-Saw_Press_Alternating_Side_Press":{"name":"Desenvolvimento Gangorra com Halteres (Alternado)","instructions":["Fique em pé ereto segurando um halter em cada mão.","Leve os halteres até a altura dos ombros com as palmas voltadas para você como na posição inicial do desenvolvimento Arnold. Esta será a sua posição inicial.","Empurre o braço esquerdo acima da cabeça girando o punho para a frente enquanto inclina levemente o quadril para o lado oposto ao expirar.","Inspire no topo e depois desça o halter esquerdo enquanto empurra o halter direito acima da cabeça inclinando para o outro lado.","Repita pela quantidade recomendada de repetições."]},
"Shotgun_Row":{"name":"Remada Unilateral em Pé no Cabo (Shotgun Row)","instructions":["Prenda um pegador unilateral em uma polia baixa.","Selecione a carga e dê alguns passos para trás em base alternada ampla com o braço estendido e o ombro projetado à frente. Esta será a sua posição inicial.","Puxe o pegador retraindo o ombro e flexionando o cotovelo enquanto faz rotação supinada (girando a palma para cima).","Após uma breve pausa, retorne à posição inicial."]},
"Shoulder_Circles":{"name":"Círculos com os Ombros","instructions":["Com os ombros relaxados e os braços soltos ao lado do corpo (ou no colo se sentado), gire suavemente os ombros para a frente, para cima, para trás e para baixo.","Inverta o sentido (pode ser feito alternando os ombros ou ambos ao mesmo tempo)."]},
"Shoulder_Press_-_With_Bands":{"name":"Desenvolvimento de Ombros com Elástico","instructions":["Pise no centro de um elástico gerando tensão com os braços estendidos, segure as alças e eleve as mãos até a altura dos ombros de cada lado.","Gire os punhos para que as palmas fiquem voltadas para a frente com os cotovelos flexionados alinhados ao tronco. Esta é a sua posição inicial.","Ao expirar, empurre as alças para cima até os braços ficarem totalmente estendidos acima da cabeça."]},
"Shoulder_Raise":{"name":"Elevação de Ombros (Encolhimento Suave)","instructions":["Relaxe os braços ao lado do corpo e eleve os ombros em direção às orelhas, depois abaixe lentamente."]},
"Shoulder_Stretch":{"name":"Alongamento de Ombro","instructions":["Estenda um braço cruzando à frente do corpo mantendo-o reto e puxe suavemente com a outra mão."]},
"Side-Lying_Floor_Stretch":{"name":"Alongamento Lateral no Chão","instructions":["Deite-se sobre o lado esquerdo flexionando o joelho esquerdo à frente para estabilizar o tronco.","Estenda a perna direita apoiando o pé direito no chão atrás da esquerda, estenda o braço direito acima da cabeça e puxe suavemente o punho direito para alongar toda a lateral direita do corpo; depois troque de lado."]},
"Side_Bridge":{"name":"Prancha Lateral","instructions":[]},
"Side_Hop-Sprint":{"name":"Salto Lateral com Sprint","instructions":["Fique em pé ao lado de um cone ou barreira.","Salte lateralmente por cima do obstáculo rebatendo imediatamente para saltar de volta ao ponto inicial.","Execute o número prescrito de saltos o mais rápido possível e finalize com um sprint curto após a última aterrissagem."]},
"Side_Jackknife":{"name":"Abdominal Canivete Lateral","instructions":[]},
"Side_Lateral_Raise":{"name":"Elevação Lateral com Halteres","instructions":["Fique em pé com o tronco ereto segurando um halter em cada mão ao lado do corpo com os braços estendidos e palmas voltadas para você. Esta será a sua posição inicial.","Mantendo o tronco imóvel, eleve os halteres lateralmente com leve flexão nos cotovelos e mãos levemente inclinadas (como ao despejar água) até os braços ficarem paralelos ao chão enquanto expira, pausando um segundo no topo.","Abaixe lentamente os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Side_Laterals_to_Front_Raise":{"name":"Elevação Lateral para Frontal com Halteres","instructions":["Fique em pé segurando um par de halteres ao lado do corpo. Esta será a sua posição inicial.","Mantendo os cotovelos levemente flexionados, eleve os halteres lateralmente até a altura dos ombros sem balançar o corpo.","No topo, traga os halteres para a frente mantendo os braços estendidos.","Abaixe os halteres à frente de forma controlada.","Na repetição seguinte, eleve os halteres à frente até a altura dos ombros e depois abra-os lateralmente para os lados.","Abaixe os halteres de volta à posição inicial."]},
"Side_Leg_Raises":{"name":"Balanço Lateral de Perna","instructions":["Fique em pé ao lado de uma cadeira para apoio equilibrando-se em uma perna. Esta será a sua posição inicial.","Mantendo a perna estendida, eleve-a lateralmente o máximo possível e balance de volta cruzando à frente da perna de apoio.","Repita esse balanço 5-10 vezes aumentando gradualmente a amplitude e depois troque de lado."]},
"Side_Lying_Groin_Stretch":{"name":"Alongamento de Virilha Deitado de Lado","instructions":["Deite-se sobre o lado direito flexionando o joelho direito à frente para estabilizar o tronco.","Apoie a cabeça na mão ou ombro direito, eleve a perna esquerda segurando atrás do joelho ou no pé.","Puxe o joelho esquerdo em direção ao ombro esquerdo enquanto pressiona levemente para baixo (estenda a perna para intensificar); depois troque de lado."]},
"Side_Neck_Stretch":{"name":"Alongamento Lateral de Pescoço","instructions":["Com os ombros relaxados, incline suavemente a cabeça em direção a um ombro.","Auxilie o alongamento aplicando leve pressão com a mão na lateral da cabeça e depois troque de lado."]},
"Side_Standing_Long_Jump":{"name":"Salto Lateral em Distância","instructions":["Fique em postura atlética com os pés na largura do quadril, cabeça e peito erguidos e joelhos e quadril levemente flexionados. Esta será a sua posição inicial.","Inclinando para a direita, estenda quadril, joelhos e tornozelos impulsionando com os braços para saltar o mais longe possível para a direita.","Aterrisse virado para a mesma direção com os pés na largura do quadril amortecendo o impacto com as pernas."]},
"Side_To_Side_Chins":{"name":"Barra Fixa Alternada Lateral (Lado a Lado)","instructions":["Segure a barra fixa com pegada pronada aberta (palmas voltadas para a frente).","Pendurado com braços estendidos, incline o tronco cerca de 30 graus para trás abrindo o peito. Esta é a posição inicial.","Puxe o corpo para cima inclinando para o lado esquerdo até a barra quase tocar a parte superior do peito enquanto expira, contraindo bem as costas sem balançar.","Após segurar um segundo na contração, desça inspirando até a posição inicial.","Agora puxe o corpo inclinando para o lado direito até a barra quase tocar a parte superior do peito enquanto expira, contraindo as costas.","Após segurar um segundo na contração, retorne à posição inicial enquanto inspira.","Repita os passos 3 a 6 até completar as repetições prescritas para cada lado."]},
"Side_Wrist_Pull":{"name":"Puxada Lateral de Punho (Alongamento de Costas)","instructions":["Em pé, cruze o braço esquerdo à frente do corpo na altura do quadril com o cotovelo dobrado e segure o punho esquerdo com a mão direita.","Estenda, puxe e eleve suavemente o braço até a altura do ombro sentindo o alongamento nas costas sem forçar a articulação do ombro; depois troque de lado."]},
"Side_to_Side_Box_Shuffle":{"name":"Troca Lateral Rápida na Caixa","instructions":["Fique ao lado de uma caixa baixa apoiando o pé esquerdo no centro dela.","Salte para cima e para o outro lado da caixa aterrissando com o pé direito em cima da caixa e o pé esquerdo no chão, balançando os braços.","Continue alternando rapidamente de um lado para o outro sobre a caixa."]},
"Single-Arm_Cable_Crossover":{"name":"Crossover Unilateral no Cabo","instructions":["Ajuste as polias na posição alta, selecione a carga e segure um pegador em cada mão.","Dê um passo à frente em base alternada unindo as mãos à frente do corpo com peito aberto e braços estendidos. Esta será a sua posição inicial.","Mantendo o braço esquerdo fixo à frente, abra o braço direito lateralmente com leve flexão no cotovelo até ficar perpendicular ao corpo na altura do ombro.","Retorne o braço direito à posição inicial puxando a mão de volta à linha média do corpo.","Segure um segundo no centro e repita do lado oposto, alternando continuamente pelas repetições prescritas."]},
"Single-Arm_Linear_Jammer":{"name":"Empurrão Explosivo Unilateral no Landmine","instructions":["Encaixe uma barra no landmine (ou canto seguro) e carregue o peso adequado.","Erga a ponta da barra do chão até o ombro em base bem aberta. Esta será a sua posição inicial.","Empurre a barra para cima estendendo o cotovelo de forma explosiva enquanto estende completamente quadril e joelhos.","Retorne à posição inicial."]},
"Single-Arm_Push-Up":{"name":"Flexão de Braço Unilateral","instructions":["Entre em posição de flexão apoiando-se nas pontas dos pés bem afastados e em apenas um braço estendido diretamente abaixo do ombro.","Mantenha a postura firme e coloque a mão livre atrás das costas. Esta será a sua posição inicial.","Desça flexionando o cotovelo até o peito se aproximar do chão.","Controle a descida e inverta estendendo o braço para retornar à posição inicial."]},
"Single-Cone_Sprint_Drill":{"name":"Treino de Agilidade em Cone Único","instructions":["Fique em pé ao lado de um cone com um braço atrás e outro à frente.","Faça passadas rápidas e curtas contornando o cone com joelhos altos e movimento vigoroso dos braços.","Descanse após completar três voltas ao redor do cone."]},
"Single-Leg_High_Box_Squat":{"name":"Subida na Caixa Alta Unilateral (Pistola Assistida)","instructions":["Posicione uma caixa alta dentro do rack e prenda um elástico ou corda acima dela.","Fique de frente para a caixa, suba nela com uma perna até ficar totalmente em pé deixando a outra perna suspensa, segurando o elástico para equilíbrio.","Continue subindo e descendo com a mesma perna antes de trocar para o lado oposto."]},
"Single-Leg_Hop_Progression":{"name":"Progressão de Saltos Unilaterais","instructions":["Alinhe uma fileira de cones à sua frente e equilibre-se em uma perna com o joelho oposto elevado. Esta será a sua posição inicial.","Salte para a frente sobre o cone aterrissando com a mesma perna.","Use um pequeno contramovimento para saltar continuamente de cone em cone.","Ao final da fila, vire-se e retorne com a outra perna."]},
"Single-Leg_Lateral_Hop":{"name":"Salto Lateral Unilateral em Cone","instructions":["Fique ao lado de um cone ou barreira equilibrando-se em uma perna com o joelho levemente flexionado.","Execute um contramovimento para saltar lateralmente por cima do cone.","Aterrisse na mesma perna e rebata imediatamente saltando de volta à posição inicial.","Continue saltando de um lado para o outro."]},
"Single-Leg_Leg_Extension":{"name":"Cadeira Extensora Unilateral","instructions":["Sente-se na cadeira extensora ajustando o encosto ao eixo do joelho e o rolo sobre a parte inferior da canela acima do tornozelo, selecionando a carga adequada.","Mantendo boa postura, estenda totalmente uma perna pausando no topo do movimento.","Retorne à posição inicial sem deixar o peso descansar totalmente para manter tensão muscular.","Repita pelo número desejado de repetições e depois troque de perna."]},
"Single-Leg_Stride_Jump":{"name":"Salto Unilateral na Caixa (Stride Jump)","instructions":["Fique ao lado de uma caixa apoiando o pé interno em cima dela próximo à borda.","Balance os braços para cima enquanto empurra com a perna de apoio na caixa para saltar o mais alto possível elevando o joelho oposto.","Aterrisse na mesma posição inicial amortecendo o impacto com a perna de apoio."]},
"Single_Dumbbell_Raise":{"name":"Elevação Frontal com Halter Único","instructions":["Com base bem aberta, segure um halter por uma das cabeças com as duas mãos e os braços estendidos à frente da cintura. Esta será a sua posição inicial.","Eleve o halter à frente até acima da altura dos ombros mantendo os braços estendidos e tronco e quadril imóveis.","Retorne à posição inicial e repita pela quantidade recomendada de repetições."]},
"Single_Leg_Butt_Kick":{"name":"Salto Unilateral com Calcanhar no Glúteo","instructions":["Equilibre-se em uma perna com o joelho oposto dobrado e elevado. Esta será a sua posição inicial.","Com contramovimento, salte verticalmente estendendo quadril, joelho e tornozelo da perna de apoio.","No ar, flexione rapidamente o joelho tentando encostar o calcanhar no glúteo.","Retorne a perna à posição semiflexionada sob o quadril para aterrissar mantendo a perna oposta elevada."]},
"Single_Leg_Glute_Bridge":{"name":"Elevação Pélvica Unilateral no Chão","instructions":["Deite-se de costas no chão com os joelhos flexionados e pés apoiados.","Tire uma perna do chão puxando o joelho em direção ao peito. Esta será a sua posição inicial.","Empurre pelo calcanhar da perna apoiada estendendo o quadril para cima e tirando os glúteos do chão.","Estenda o máximo possível, pause e retorne à posição inicial."]},
"Single_Leg_Push-off":{"name":"Impulsão Unilateral na Caixa","instructions":["Fique em pé no chão com um pé apoiado sobre uma caixa e o calcanhar próximo à borda.","Impulsione com o pé em cima da caixa estendendo quadril e joelho para ganhar a maior altura possível.","Aterrisse com o mesmo pé sobre a caixa enquanto o outro retorna ao chão."]},
"Sit-Up":{"name":"Abdominal Completo (Sit-Up)","instructions":["Deite-se de costas no chão com joelhos flexionados prendendo os pés sob um apoio ou com ajuda de um parceiro.","Coloque as mãos atrás da cabeça entrelaçando suavemente os dedos sem puxar o pescoço. Esta é a posição inicial.","Eleve o tronco até formar um \"V\" com as coxas enquanto expira.","Após sentir a contração por um segundo, abaixe lentamente o tronco de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Sit_Squats":{"name":"Meio Agachamento com Peso Corporal","instructions":["Fique em pé com os pés na largura dos ombros. Esta será a sua posição inicial.","Inicie flexionando joelhos e quadril jogando o quadril para trás.","Desça parcialmente acima da linha paralela ao chão e inverta rapidamente até voltar à posição inicial. Repita 5-10 vezes."]},
"Skating":{"name":"Patinação","instructions":["Use equipamento de proteção adequado e mantenha postura equilibrada com joelhos levemente flexionados dominando curvas e frenagens.","Patine em ritmo confortável por 30 minutos contínuos ou faça intervalos alternando dois minutos em alta velocidade e três minutos de recuperação."]},
"Sled_Drag_-_Harness":{"name":"Arraste de Trenó com Colete/Cinto","instructions":["Carregue o trenó com o peso desejado e prenda a tira de tração ao colete, cinto ou pegadores.","Puxando para a frente ou para trás, incline o corpo na direção do deslocamento e avance estendendo quadril e joelhos."]},
"Sled_Overhead_Backward_Walk":{"name":"Caminhada de Costas com Braços Elevados Puxando Trenó","instructions":["Prenda pegadores duplos por corda ou corrente a um trenó com carga leve.","De frente para o trenó, dê passos para trás até tensionar a linha e eleve as mãos diretamente acima da cabeça com os cotovelos estendidos. Esta será a sua posição inicial.","Caminhe para trás mantendo os braços estendidos acima da cabeça sem dar trancos."]},
"Sled_Overhead_Triceps_Extension":{"name":"Extensão de Tríceps Acima da Cabeça no Trenó","instructions":["Prenda pegadores duplos por corrente ou corda a um trenó com carga adequada.","De costas para o trenó, afaste-se até tensionar a linha e posicione as mãos atrás/acima da cabeça juntas com palmas frente a frente e cotovelos flexionados apontando para cima. Esta será a sua posição inicial.","Estenda os cotovelos esticando os braços para a frente mantendo a parte superior dos braços fixa para isolar o tríceps.","Ao estender totalmente, dê um passo à frente para tirar a folga da linha e repita."]},
"Sled_Push":{"name":"Empurrão de Trenó (Sled Push)","instructions":["Carregue o trenó com o peso desejado.","Assuma postura atlética inclinando-se contra o trenó com braços estendidos segurando as hastes e empurre o mais rápido possível estendendo bem quadril e joelhos."]},
"Sled_Reverse_Flye":{"name":"Crucifixo Inverso no Trenó","instructions":["Prenda pegadores duplos por corda ou corrente a um trenó com carga leve.","De frente para o trenó, recue até tensionar a linha segurando os pegadores à frente na altura da cintura com joelhos levemente flexionados e peito aberto. Esta será a sua posição inicial.","Sem dobrar os cotovelos, puxe os pegadores para cima e para os lados em crucifixo inverso com leve rotação externa até as palmas apontarem para a frente.","Retorne à posição inicial dando alguns passos para trás para manter a linha tensa."]},
"Sled_Row":{"name":"Remada no Trenó","instructions":["Prenda pegadores duplos por corda ou corrente a um trenó com carga adequada e recue até tensionar a linha.","Com um pegador em cada mão, flexione levemente os joelhos, mantenha peito e cabeça erguidos e comece com os braços estendidos.","Flexione os cotovelos retraindo as escápulas para puxar o trenó em sua direção.","Dê um ou dois passos para trás para esticar novamente a linha e repita."]},
"Sledgehammer_Swings":{"name":"Marretadas no Pneu","instructions":["Fique em pé cerca de dois pés à frente de um pneu em base alternada segurando uma marreta.","Se for destro, mantenha a mão esquerda na base do cabo e a direita próxima à cabeça da marreta.","Ao erguer a marreta e descer com força contra o pneu, deslize a mão direita até encontrar a esquerda e controle o rebote.","Repita alternando também o lado oposto."]},
"Smith_Incline_Shoulder_Raise":{"name":"Elevação de Ombros Inclinado no Smith","instructions":["Posicione um banco inclinado sob a máquina Smith, selecione a carga e deite-se alinhando os ombros diretamente sob a barra.","Com pegada pronada na largura dos ombros, destrave a barra e segure-a acima com leve flexão nos cotovelos. Esta será a sua posição inicial.","Ao expirar, empurre a barra para cima desencostando os ombros do banco até estender totalmente os braços.","Após uma pausa de um segundo, retorne os ombros à posição inicial enquanto inspira.","Repita o movimento pela quantidade prescrita de repetições.","Ao terminar, recoloque a barra no suporte."]},
"Smith_Machine_Behind_the_Back_Shrug":{"name":"Encolhimento por Trás das Costas no Smith","instructions":["Ajuste a barra na altura das coxas e carregue o peso adequado.","Fique em pé à frente da barra segurando-a atrás das costas com pegada pronada na largura dos ombros, destrave-a e mantenha peito aberto e braços estendidos. Esta será a sua posição inicial.","Encolha os ombros diretamente para cima sem flexionar braços ou punhos.","Após uma breve pausa, retorne à posição inicial.","Repita pelo número desejado de repetições antes de travar a barra no suporte."]},
"Smith_Machine_Bench_Press":{"name":"Supino Reto no Smith","instructions":["Posicione um banco reto sob a máquina Smith, deite-se alinhando o meio do peito à barra, segure com pegada pronada mais larga que os ombros e destrave a barra com os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça a barra lentamente até sentir tocar o meio do peito.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando o peitoral, segure um segundo no topo e desça devagar (cerca do dobro do tempo da subida).","Repita pela quantidade prescrita de repetições.","Ao terminar, trave a barra de volta no suporte."]},
"Smith_Machine_Bent_Over_Row":{"name":"Remada Curvada no Smith","instructions":["Ajuste a barra do Smith cerca de 2 polegadas abaixo dos joelhos.","Flexione levemente os joelhos e incline o tronco à frente pelo quadril mantendo costas retas até quase ficar paralelo ao chão e cabeça erguida.","Segure a barra com pegada pronada, destrave-a e deixe-a pendurada perpendicular ao chão. Esta é a posição inicial.","Mantendo o tronco imóvel, puxe a barra em direção ao abdômen enquanto expira com cotovelos próximos ao corpo, apertando as costas por um segundo no topo.","Abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Smith_Machine_Calf_Raise":{"name":"Elevação de Panturrilha no Smith","instructions":["Coloque um bloco ou anilha sob a barra do Smith, ajuste a altura, pise com a ponta dos pés sobre o bloco e apoie a barra na parte posterior dos ombros.","Segure a barra com as duas mãos e gire-a para destravar. Esta será a sua posição inicial.","Eleve os calcanhares o máximo possível contraindo as panturrilhas com os joelhos estendidos e segure por um segundo no topo.","Retorne lentamente abaixando os calcanhares enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Smith_Machine_Close-Grip_Bench_Press":{"name":"Supino Fechado no Smith","instructions":["Posicione um banco reto sob o Smith, deite-se, segure a barra com pegada pronada fechada (largura dos ombros) e destrave-a com os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça a barra lentamente até sentir tocar o meio do peito mantendo os cotovelos bem próximos ao tronco o tempo todo.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando o tríceps, segure um segundo e desça lentamente novamente.","Repita pela quantidade prescrita de repetições.","Ao terminar, trave a barra de volta no suporte."]},
"Smith_Machine_Decline_Press":{"name":"Supino Declinado no Smith (Alternativo)","instructions":["Posicione um banco declinado no Smith alinhando a barra acima do peito, carregue o peso e deite-se.","Gire a barra para destravá-la e estenda totalmente os braços mantendo leve arco lombar e escápulas retraídas. Esta será a sua posição inicial.","Flexione os braços descendo a barra até o peito.","Pause brevemente e estenda os braços empurrando a barra de volta à posição inicial.","Ao concluir as repetições desejadas, gire a barra para travá-la no suporte."]},
"Smith_Machine_Hang_Power_Clean":{"name":"Hang Power Clean no Smith","instructions":["Posicione a barra na altura dos joelhos e carregue o peso adequado.","Segure a barra com pegada pronada além da largura dos ombros, destrave-a com braços estendidos, peito aberto, cotovelos para fora e quadril para trás tensionando os posteriores. Esta será a sua posição inicial.","Estenda vigorosamente quadril e joelhos acelerando a barra para cima mantendo os braços estendidos.","Na extensão completa, flexione novamente quadril e joelhos entrando sob a barra.","Gire os cotovelos ao redor da barra recebendo-a apoiada na frente dos ombros.","Estenda quadril e joelhos até ficar em pé com a barra nos ombros para concluir o movimento."]},
"Smith_Machine_Hip_Raise":{"name":"Elevação de Quadril Invertida no Smith (Prensa Vertical)","instructions":["Posicione um banco sob o Smith, deite-se de costas, apoie a sola dos pés contra a barra, destrave-a e estenda as pernas segurando as laterais da máquina. Esta será a sua posição inicial.","Inicie girando a pelve e flexionando a coluna para elevar o quadril do banco mantendo leve flexão nos joelhos.","Após uma breve pausa, retorne o quadril ao banco.","Repita pelo número desejado de repetições."]},
"Smith_Machine_Incline_Bench_Press":{"name":"Supino Inclinado no Smith","instructions":["Posicione um banco inclinado sob a máquina Smith alinhando a parte superior do peito à barra, segure com pegada pronada mais aberta que os ombros e destrave com os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça a barra lentamente até sentir tocar a parte superior do peito.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando o peitoral, segure um segundo no topo e desça devagar.","Repita pela quantidade prescrita de repetições.","Ao terminar, trave a barra de volta no suporte."]},
"Smith_Machine_Leg_Press":{"name":"Leg Press Vertical no Smith","instructions":["Posicione a barra do Smith alguns pés acima do chão apoiada nas travas de segurança, deite-se abaixo dela e apoie o meio dos pés na barra com joelhos dobrados junto ao peito. Esta será a sua posição inicial.","Empurre a barra para cima estendendo quadril e joelhos sem travar os joelhos no topo.","Pause brevemente no topo e retorne de forma controlada à posição inicial."]},
"Smith_Machine_One-Arm_Upright_Row":{"name":"Remada Alta Unilateral no Smith","instructions":["Ajuste a barra na altura das coxas e carregue o peso adequado.","Segure a barra com pegada aberta, destrave o peso e retire a mão livre mantendo o braço ativo estendido e tronco ereto. Esta será a sua posição inicial.","Flexione o cotovelo puxando o braço para cima com o cotovelo apontado para fora até o braço ficar paralelo ao chão.","Após uma breve pausa, retorne à posição inicial.","Repita pelo número desejado de repetições antes de travar a barra no suporte."]},
"Smith_Machine_Overhead_Shoulder_Press":{"name":"Desenvolvimento Sentado no Smith","instructions":["Posicione um banco com encosto sob o Smith ajustando a barra na altura quase máxima dos braços estendidos.","Sente-se alinhado logo atrás da linha da barra, segure com pegada pronada, destrave e estenda totalmente os braços acima da cabeça. Esta é a posição inicial.","Desça lentamente a barra até a altura do queixo enquanto inspira.","Empurre a barra de volta à posição inicial usando os ombros enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Smith_Machine_Pistol_Squat":{"name":"Agachamento Pistol no Smith","instructions":["Ajuste a barra na sua altura, entre sob ela apoiando-a na parte posterior dos ombros.","Segure a barra com as palmas para a frente, destrave-a e retire-a do suporte estendendo as pernas.","Avance um pé cerca de 12 polegadas à frente da linha da barra e mantenha a outra perna estendida à frente sem tocar o chão, olhando sempre à frente. Esta será a sua posição inicial.","Mantendo boa postura, desça flexionando joelho e quadril até onde a flexibilidade permitir.","Pause brevemente em baixo e suba empurrando pelo calcanhar até retornar à posição inicial."]},
"Smith_Machine_Reverse_Calf_Raises":{"name":"Flexão Dorsal (Tibial) no Smith","instructions":["Ajuste a barra do Smith à sua altura com uma plataforma elevada logo abaixo.","Suba na plataforma apoiando apenas os calcanhares e deixando a ponta dos pés para fora na largura dos ombros.","Apoie os ombros sob a barra, destrave-a estendendo pernas e quadril com joelhos levemente destravados. Esta será a sua posição inicial.","Eleve a ponta dos pés o máximo possível enquanto expira contraindo a parte anterior das canelas sem dobrar os joelhos e segure por um segundo.","Abaixe lentamente a ponta dos pés de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Smith_Machine_Squat":{"name":"Agachamento no Smith","instructions":["Ajuste a barra na sua altura, entre sob ela apoiando-a na parte posterior dos ombros.","Segure a barra com as duas mãos, destrave-a e retire-a empurrando com as pernas.","Posicione os pés na largura dos ombros com as pontas levemente para fora, cabeça erguida e costas retas. Esta será a sua posição inicial.","Desça lentamente flexionando os joelhos até as coxas ficarem abaixo do paralelo enquanto inspira, evitando que os joelhos ultrapassem excessivamente os dedos dos pés.","Suba enquanto expira empurrando pelos calcanhares até estender as pernas e retornar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Smith_Machine_Stiff-Legged_Deadlift":{"name":"Stiff no Smith","instructions":["Ajuste a barra do Smith na altura do meio das coxas e segure-a com pegada pronada na largura dos ombros.","Levante a barra mantendo as costas retas, pés na largura dos ombros ou mais fechados e joelhos levemente flexionados. Esta é a posição inicial.","Mantendo os joelhos fixos nessa leve flexão, desça a barra à frente das pernas flexionando o quadril com costas retas até sentir alongar bem os posteriores de coxa.","Estenda quadril e cintura para retornar à posição inicial ereta.","Repita pela quantidade recomendada de repetições."]},
"Smith_Machine_Upright_Row":{"name":"Remada Alta no Smith","instructions":["Ajuste a barra do Smith na altura do meio das coxas e segure-a com pegada pronada na largura dos ombros.","Erga a barra mantendo braços estendidos e costas retas com leve flexão nos cotovelos. Esta é a posição inicial.","Use os ombros para puxar a barra rente ao corpo enquanto expira até quase tocar o queixo, com os cotovelos sempre mais altos que os antebraços, e pause um segundo no topo.","Abaixe a barra lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Smith_Single-Leg_Split_Squat":{"name":"Agachamento Búlgaro no Smith","instructions":["Posicione um banco reto 2-3 pés atrás do Smith, ajuste a barra na sua altura e apoie-a na parte posterior dos ombros.","Segure a barra com as duas mãos, destrave-a e fique em pé.","Avance um pé ligeiramente à frente da barra e apoie o peito do outro pé atrás sobre o banco. Esta será a sua posição inicial.","Desça lentamente flexionando o joelho da frente com postura ereta até a coxa passar levemente do paralelo enquanto inspira, sem deixar o joelho passar dos dedos do pé.","Suba enquanto expira empurrando principalmente pelo calcanhar do pé da frente.","Repita pela quantidade recomendada de repetições.","Troque as pernas e repita o movimento."]},
"Snatch":{"name":"Snatch (Arranque Olímpico)","instructions":["Posicione os pés na largura dos ombros com a barra sobre a base dos dedos dos pés.","Com pegada pronada aberta (além da largura dos ombros), agache com as costas retas mantendo o quadril baixo. Esta será a sua posição inicial.","Empurre o chão com os pés iniciando a subida da barra rente às canelas.","Quando a barra chegar ao meio das coxas, empurre o chão explosivamente estendendo completamente o corpo.","Encolha os ombros e puxe os cotovelos para cima e para os lados mantendo a barra próxima ao corpo.","Entre rapidamente sob a barra em agachamento profundo travando os braços totalmente estendidos acima da cabeça.","Finalize levantando-se do agachamento com os pés alinhados e os braços travados acima da cabeça."]},
"Snatch_Balance":{"name":"Snatch Balance","instructions":["Comece com os pés na base de puxada, a barra apoiada na parte posterior dos ombros e as mãos em pegada aberta de snatch.","Faça um pequeno impulso rápido com os joelhos para aliviar a barra e entre agressivamente por baixo dela abrindo os pés para a base de recepção.","Receba a barra com os braços travados acima da cabeça perto do fundo do agachamento mantendo o tronco vertical.","Complete a descida se necessário, levante-se em pé e abaixe o peso com cuidado."]},
"Snatch_Deadlift":{"name":"Levantamento Terra para Snatch","instructions":["Assuma pegada aberta de snatch na barra no chão com pés sob o quadril levemente voltados para fora, agachando com a coluna totalmente estendida e olhar à frente.","Inicie empurrando pelos calcanhares elevando o quadril e mantendo constante o ângulo das costas até a barra passar dos joelhos.","Em seguida, projete o quadril contra a barra até ficar ereto e depois retorne a barra ao chão invertendo o movimento."]},
"Snatch_Pull":{"name":"Puxada de Snatch (Snatch Pull)","instructions":["Com a barra no chão próxima às canelas, faça uma pegada aberta de snatch, quadril baixo com peso nos calcanhares, costas retas, peito aberto e ombros à frente da barra. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pelos calcanhares e estendendo os joelhos mantendo constante o ângulo das costas e os braços estendidos até passar dos joelhos.","Na segunda puxada, quando a barra chegar ao meio das coxas, estenda explosivamente quadril, joelhos e tornozelos como em um salto para acelerar a barra para cima.","Mantenha os braços estendidos sem puxar com eles; finalize na extensão completa abrupta inclinando-se levemente para trás."]},
"Snatch_Shrug":{"name":"Encolhimento de Snatch","instructions":["Segure a barra na altura do meio das coxas com pegada aberta (pronada ou hook grip), costas retas e levemente inclinadas à frente.","Encolha os ombros em direção às orelhas com explosão, evitando cargas excessivas que comprometam a velocidade de execução."]},
"Snatch_from_Blocks":{"name":"Snatch dos Blocos","instructions":["Com a barra apoiada em caixas na altura desejada, faça pegada aberta, pés sob o quadril, quadril baixo, peito aberto e ombros à frente da barra com cotovelos para fora. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pela parte anterior dos calcanhares para tirar a barra das caixas.","Na segunda puxada, estenda explosivamente quadril, joelhos e tornozelos mantendo a barra rente ao corpo; no pico, encolha os ombros e flexione os cotovelos para os lados.","Ao abrir os pés para fora do quadril, puxe-se rapidamente sob a barra recebendo-a no ponto mais baixo possível com os braços totalmente estendidos acima da cabeça.","Levante-se empurrando pelos calcanhares com a barra alinhada e depois devolva o peso às caixas com cuidado."]},
"Speed_Band_Overhead_Triceps":{"name":"Tríceps Francês Rápido com Elástico","instructions":["Prenda um elástico próximo ao chão (na base de um banco ou pisando nele).","Puxe o elástico atrás da cabeça segurando com pegada pronada e cotovelos altos. Esta será a sua posição inicial.","Estenda os cotovelos para esticar os braços mantendo a parte superior dos braços fixa.","Pause e retorne à posição inicial."]},
"Speed_Box_Squat":{"name":"Agachamento Rápido na Caixa com Elásticos","instructions":["Prenda elásticos na barra ancorados próximos ao chão com tensão adequada.","Posicione uma caixa na altura adequada e carregue a barra com carga moderada (50-70% de 1RM) que permita alta velocidade.","Apoie a barra na parte superior das costas com escápulas retraídas e corpo firme dos pés à cabeça. Esta será a sua posição inicial.","Retire a barra, posicione-se à frente da caixa e sente-se para trás sob controle sem despencar sobre a caixa.","Pause brevemente na caixa e exploda para cima estendendo quadril e joelhos."]},
"Speed_Squats":{"name":"Agachamento Rápido com Barra (Speed Squats)","instructions":["Dentro de um rack de agachamento, ajuste a barra na sua altura, entre sob ela apoiando-a na parte posterior dos ombros.","Segure a barra com as duas mãos e retire-a empurrando com as pernas.","Afaste-se com os pés na largura dos ombros e pontas levemente para fora, mantendo cabeça erguida e costas retas. Esta será a sua posição inicial.","Desça flexionando os joelhos até as coxas ficarem abaixo do paralelo enquanto inspira, sem deixar os joelhos ultrapassarem os dedos dos pés.","Suba o mais rápido possível enquanto expira empurrando pelos calcanhares sem perder a técnica perfeita.","Repita pela quantidade recomendada de repetições."]},
"Spell_Caster":{"name":"Giro Pendular com Halteres (Spell Caster)","instructions":["Segure um halter em cada mão com pegada pronada em base bem aberta e pernas estendidas. Esta será a sua posição inicial.","Puxe ambos os halteres para um lado ao lado do quadril girando o tronco.","Mantendo os braços estendidos e os halteres paralelos ao chão, gire o tronco balançando os pesos para o lado oposto.","Continue alternando de um lado para o outro até completar a série."]},
"Spider_Crawl":{"name":"Passo da Aranha (Spider Crawl)","instructions":["Deite-se em posição de flexão sustentando o peso nas mãos e pontas dos pés, pés juntos, corpo reto e cotovelos dobrados a 90 graus. Esta será a sua posição inicial.","Tire um pé do chão, gire a perna externamente e traga o joelho em direção ao cotovelo o mais à frente possível.","Retorne essa perna à posição inicial e repita com o lado oposto."]},
"Spider_Curl":{"name":"Rosca Spider no Banco Scott","instructions":["Posicione a barra no apoio ou assento do banco Scott de forma equilibrada.","Apoie o peito e o abdômen contra a parte frontal inclinada do banco Scott a cerca de 45 graus.","Firme as pontas dos pés no chão e posicione a parte posterior dos braços contra o lado interno do apoio.","Segure a barra com pegada supinada (palmas para cima) na largura dos ombros ou levemente mais fechada.","Eleve a barra contraindo o bíceps enquanto expira e segure um segundo no topo.","Abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Spinal_Stretch":{"name":"Alongamento Espinhal na Cadeira","instructions":["Sente-se em uma cadeira com as costas retas e os pés apoiados no chão.","Entrelace os dedos atrás da cabeça com cotovelos abertos e queixo abaixado.","Gire o tronco para um lado o máximo possível e depois incline à frente levando o cotovelo em direção à parte interna do joelho.","Retorne à posição ereta e repita para o outro lado."]},
"Split_Clean":{"name":"Split Clean","instructions":["Com a barra no chão próxima às canelas, faça pegada pronada logo por fora das pernas, quadril baixo, costas retas, peito aberto e ombros à frente da barra. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pelos calcanhares mantendo constante o ângulo das costas e braços estendidos até passar dos joelhos.","Na segunda puxada, ao chegar ao meio das coxas, estenda explosivamente quadril, joelhos e tornozelos mantendo os braços estendidos.","No pico da extensão, encolha os ombros e entre rapidamente sob a barra girando os cotovelos para cima e para a frente.","Receba a barra apoiada nos ombros com os pés em base dividida (um pé à frente e outro atrás) descendo brevemente para amortecer.","Recupere-se imediatamente empurrando pelos calcanhares com tronco ereto e cotovelos altos, juntando os pés em pé."]},
"Split_Jerk":{"name":"Split Jerk","instructions":["Em pé com a barra apoiada na frente dos ombros e pés sob o quadril, faça uma leve flexão rápida dos joelhos sem jogar o quadril para trás.","Inverta imediatamente impulsionando pelos calcanhares com máxima velocidade e recue a cabeça do caminho quando a barra subir.","No momento em que os pés saírem do chão, posicione-os rapidamente em base dividida (um pé à frente e outro atrás) recebendo a barra com os braços totalmente travados acima da cabeça.","Retorne à posição ereta juntando os pés."]},
"Split_Jump":{"name":"Salto em Base Dividida (Split Jump)","instructions":["Assuma posição de avanço com um pé à frente, joelho dobrado e joelho de trás quase tocando o chão.","Garanta que o joelho da frente esteja alinhado sobre o meio do pé.","Impulsione estendendo ambas as pernas para saltar o mais alto possível balançando os braços.","No ar, junte os pés brevemente e volte à base dividida inicial ao aterrissar.","Amorteça o impacto retornando à posição inicial e repita."]},
"Split_Snatch":{"name":"Split Snatch","instructions":["Com a barra carregada no chão próxima às canelas, faça pegada aberta, pés sob o quadril, quadril baixo, peito aberto e ombros à frente da barra. Esta será a sua posição inicial.","Inicie a primeira puxada empurrando pela parte anterior dos calcanhares mantendo o ângulo das costas até passar dos joelhos.","Na segunda puxada, estenda explosivamente quadril, joelhos e tornozelos mantendo a barra rente ao corpo e, no pico, encolha os ombros flexionando os cotovelos para os lados.","Entre rapidamente sob a barra em base dividida (um pé à frente e outro atrás) recebendo-a com os braços totalmente estendidos acima da cabeça.","Levante-se empurrando pelos calcanhares com a barra alinhada e junte os pés em pé.","Abaixe a barra ao chão com cuidado."]},
"Split_Squat_with_Dumbbells":{"name":"Agachamento Búlgaro com Halteres","instructions":["Assuma base alternada com o pé de trás elevado sobre um banco e o pé da frente à frente.","Segure um halter em cada mão ao lado do corpo. Esta será a sua posição inicial.","Desça flexionando joelho e quadril mantendo boa postura e o joelho da frente alinhado ao pé.","No ponto mais baixo, empurre pelo calcanhar estendendo joelho e quadril para retornar à posição inicial."]},
"Split_Squats":{"name":"Agachamento Alternado com Salto (Split Squats)","instructions":["Comece em pé, salte caindo em base dividida (uma perna à frente e outra atrás) flexionando os joelhos e abaixando levemente o quadril.","Inverta imediatamente subindo e saltando para trocar a posição das pernas no ar; repita 5-10 vezes com cada perna."]},
"Squat_Jerk":{"name":"Squat Jerk","instructions":["Em pé com a barra apoiada na frente dos ombros e pés sob o quadril, flexione levemente os joelhos sem jogar o quadril para trás e impulsione pelos calcanhares com máxima força recuando a cabeça.","Quando os pés saírem do chão, abra-os rapidamente para fora da linha do quadril e receba a barra em agachamento completo com os braços totalmente estendidos acima da cabeça.","Com a barra alinhada, levante-se empurrando pelos calcanhares até ficar em pé e abaixe o peso com cuidado."]},
"Squat_with_Bands":{"name":"Agachamento com Elásticos","instructions":["Prenda os elásticos nas pontas da barra ancorados nos pinos do rack ou em halteres pesados com tensão adequada.","Entre sob a barra apoiando-a na parte posterior dos ombros, aperte as escápulas, retire do suporte e posicione os pés bem abertos olhando para a frente.","Com tronco e core firmes, empurre joelhos e quadril para trás descendo até ultrapassar o paralelo (dobra do quadril na linha do topo do joelho).","Mantendo o peso nos calcanhares e joelhos para fora, suba conduzindo pela cabeça até retornar à posição inicial."]},
"Squat_with_Chains":{"name":"Agachamento com Correntes","instructions":["Passe as correntes guias sobre as mangas da barra e prenda as correntes pesadas com mosquetões deixando alguns elos no chão no topo do movimento.","Entre sob a barra apoiando-a na parte posterior dos ombros, aperte as escápulas, retire do suporte e posicione os pés bem abertos olhando para a frente.","Com tronco e core firmes, empurre joelhos e quadril para trás descendo até ultrapassar o paralelo.","Mantendo o peso nos calcanhares e joelhos para fora, suba conduzindo pela cabeça até retornar à posição inicial."]},
"Squat_with_Plate_Movers":{"name":"Agachamento Deslocando Anilha","instructions":["Ajuste a barra no rack logo abaixo dos ombros e coloque uma anilha no chão alguns passos atrás; entre sob a barra apoiando-a nos ombros.","Segure a barra com as duas mãos e retire-a empurrando com as pernas.","Afaste-se em base bem aberta apoiando um pé sobre a anilha e mantendo a cabeça erguida. Esta será a sua posição inicial.","Desça lentamente flexionando joelhos e quadril até as coxas passarem ligeiramente dos 90 graus.","Suba enquanto expira empurrando pelos calcanhares.","No topo, dê um passo lateral juntando os pés do lado oposto da anilha.","Com o pé interno, deslize a anilha pelo chão para onde você estava antes.","Apoie novamente o pé interno sobre a anilha assumindo a base aberta para a repetição seguinte."]},
"Squats_-_With_Bands":{"name":"Agachamento com Elástico","instructions":["Pise no meio de um elástico com os pés na largura dos ombros dividindo igualmente os dois lados.","Segure as alças na altura dos ombros/rosto com palmas voltadas para a frente gerando tensão igual em ambos os lados. Esta é a posição inicial.","Flexione lentamente os joelhos descendo até as coxas ficarem paralelas ao chão.","Empurre pelos calcanhares para retornar à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Stairmaster":{"name":"Simulador de Escada (Stairmaster)","instructions":["Suba no simulador de escada e selecione o modo manual ou programa desejado no painel.","Mantenha um ritmo constante de subida sem descer os degraus até o fim do curso, segurando levemente nos apoios para equilíbrio e monitoramento cardíaco.","Continue pelo tempo ou objetivo programado mantendo a postura ereta."]},
"Standing_Alternating_Dumbbell_Press":{"name":"Desenvolvimento Alternado em Pé com Halteres","instructions":["Fique em pé com um halter em cada mão na altura dos ombros, palmas voltadas para a frente e cotovelos para fora. Esta será a sua posição inicial.","Estenda um braço empurrando o halter diretamente para cima mantendo o outro imóvel, sem inclinar ou dar trancos com o tronco.","Após uma breve pausa, retorne o halter à posição inicial.","Repita com o lado oposto, alternando continuamente entre os braços."]},
"Standing_Barbell_Calf_Raise":{"name":"Elevação de Panturrilha em Pé com Barra","instructions":["Dentro de um rack de agachamento, ajuste a barra na altura ideal e apoie-a na parte posterior dos ombros (logo abaixo do pescoço).","Segure a barra com as duas mãos e retire-a do suporte empurrando com as pernas.","Afaste-se com os pés na largura dos ombros (opcionalmente sobre um bloco firme para maior amplitude), cabeça erguida, costas retas e joelhos levemente destravados. Esta será a sua posição inicial.","Eleve os calcanhares o máximo possível enquanto expira contraindo as panturrilhas sem dobrar os joelhos e segure por um segundo no topo.","Retorne lentamente à posição inicial abaixando os calcanhares até alongar as panturrilhas enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Barbell_Press_Behind_Neck":{"name":"Desenvolvimento por Trás da Nuca em Pé com Barra","instructions":["Dentro de um rack de agachamento, ajuste a barra na altura ideal e apoie-a na parte posterior dos ombros (logo abaixo do pescoço).","Segure a barra com as duas mãos e retire-a do suporte empurrando com as pernas.","Afaste-se com pés na largura dos ombros, pontas levemente para fora e costas retas. Esta será a sua posição inicial.","Empurre a barra acima da cabeça estendendo totalmente os braços enquanto expira.","Segure a contração por um segundo e abaixe a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":{"name":"Coice Unilateral em Pé com Halter","instructions":["Com um halter em uma mão e palma voltada para o corpo, flexione levemente os joelhos e incline o tronco à frente mantendo costas retas até quase ficar paralelo ao chão e olhe à frente.","Eleve o braço junto ao tronco paralelo ao chão com o antebraço apontando para baixo formando 90 graus no cotovelo. Esta é a posição inicial.","Mantendo a parte superior do braço imóvel, estenda o cotovelo usando o tríceps até o antebraço ficar paralelo ao chão enquanto expira.","Após segurar um segundo no topo, abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade prescrita de repetições.","Troque de braço e repita o exercício."]},
"Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":{"name":"Coice Bilateral em Pé com Halteres","instructions":["Com um halter em cada mão e palmas voltadas para o corpo, flexione levemente os joelhos e incline o tronco à frente com costas retas até quase ficar paralelo ao chão; eleve os braços juntos ao tronco formando 90 graus nos cotovelos. Esta é a posição inicial.","Mantendo a parte superior dos braços imóvel, estenda os cotovelos usando o tríceps até os braços ficarem paralelos ao chão enquanto expira.","Após segurar um segundo no topo, abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade prescrita de repetições."]},
"Standing_Biceps_Cable_Curl":{"name":"Rosca Direta em Pé no Cabo","instructions":["Fique em pé com o tronco ereto segurando a barra acoplada à polia baixa na largura dos ombros com pegada supinada (palmas para cima) e cotovelos próximos ao corpo. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos contraindo o bíceps enquanto expira até a barra chegar à altura dos ombros e segure um segundo no topo, movendo apenas os antebraços.","Abaixe lentamente a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Biceps_Stretch":{"name":"Alongamento de Bíceps em Pé","instructions":["Entrelace as mãos atrás das costas com as palmas juntas, estenda os braços e gire os punhos para que as palmas apontem para baixo.","Eleve os braços para trás e segure até sentir alongar o bíceps."]},
"Standing_Bradford_Press":{"name":"Desenvolvimento Bradford em Pé","instructions":["Posicione uma barra carregada na altura dos ombros e apoie-a na frente dos ombros com pegada pronada na largura dos ombros. Esta é a sua posição inicial.","Empurre a barra acima da cabeça estendendo os cotovelos sem travá-los completamente ao passá-la atrás da cabeça.","Abaixe a barra atrás da cabeça até os cotovelos formarem um ângulo reto.","Eleve a barra de volta acima da cabeça estendendo os cotovelos.","Abaixe a barra de volta à posição inicial à frente.","Continue alternando frente e trás até completar as repetições recomendadas."]},
"Standing_Cable_Chest_Press":{"name":"Supino em Pé no Cabo","instructions":["Ajuste duas polias na altura do peito, selecione a carga e dê um ou dois passos à frente segurando um pegador em cada mão em base alternada para equilíbrio.","Posicione os cotovelos a 90 graus com as escápulas juntas. Esta será a sua posição inicial.","Mantendo o corpo estável, estenda os cotovelos empurrando os pegadores à frente até aproximá-los diante do peito.","Pause na extensão completa e retorne à posição inicial."]},
"Standing_Cable_Lift":{"name":"Levantamento Diagonal em Pé no Cabo","instructions":["Prenda um pegador padrão na posição mais baixa da torre.","Fique de lado para o cabo, segure o pegador com uma mão e afaste-se cerca de um braço gerando tensão no cabo.","Com os pés na largura dos ombros, agache e segure o pegador com as duas mãos mantendo os braços estendidos.","Em um movimento contínuo, puxe o pegador para cima e cruzando à frente do corpo até estender os braços acima da cabeça.","Mantenha as costas retas girando o pé de trás e estendendo as pernas para amplitude completa.","Retorne de forma lenta e controlada à posição inicial.","Repita até a falha.","Reposicione-se e repita a sequência para o lado oposto."]},
"Standing_Cable_Wood_Chop":{"name":"Lenhador em Pé no Cabo (Wood Chop)","instructions":["Prenda um pegador padrão na posição mais alta da torre.","Fique de lado para o cabo, segure o pegador com uma mão e afaste-se cerca de um braço gerando tensão.","Com os pés na largura dos ombros, alcance para cima e segure o pegador com as duas mãos mantendo os braços estendidos.","Em um movimento contínuo, puxe o pegador para baixo e cruzando o corpo em direção ao joelho da frente enquanto gira o tronco.","Mantenha costas e braços retos e core contraído girando o pé de trás e flexionando os joelhos.","Retorne de forma lenta e controlada à posição inicial.","Repita até a falha.","Reposicione-se e repita a sequência para o lado oposto."]},
"Standing_Calf_Raises":{"name":"Elevação de Panturrilha em Pé na Máquina","instructions":["Ajuste o apoio acolchoado da máquina de panturrilha à sua altura.","Encaixe os ombros sob os apoios, posicione a ponta dos pés sobre o degrau com os calcanhares livres e estenda pernas e tronco mantendo os joelhos levemente destravados. Esta será a sua posição inicial.","Eleve os calcanhares o máximo possível enquanto expira contraindo as panturrilhas sem dobrar os joelhos e segure por um segundo no topo.","Retorne lentamente à posição inicial abaixando os calcanhares até alongar as panturrilhas enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Concentration_Curl":{"name":"Rosca Concentrada em Pé (Inclinado)","instructions":["Segurando um halter em uma mão, incline o tronco à frente deixando o braço pendurado perpendicular ao chão com o cotovelo apontando para fora. Esta será a sua posição inicial.","Flexione o cotovelo elevando o halter enquanto mantém a parte superior do braço imóvel e pause contraindo o bíceps no topo.","Abaixe o halter de volta à posição inicial.","Repita pela quantidade prescrita de repetições e depois troque de braço."]},
"Standing_Dumbbell_Calf_Raise":{"name":"Elevação de Panturrilha em Pé com Halteres","instructions":["Fique em pé com tronco ereto segurando dois halteres ao lado do corpo e apoie a ponta dos pés sobre um bloco estável (2-3 polegadas de altura) com os calcanhares fora tocando o chão. Esta será a sua posição inicial.","Com os dedos apontando para a frente (ou levemente para dentro/fora conforme o foco), eleve os calcanhares o máximo possível enquanto expira contraindo as panturrilhas e segure um segundo.","Ao inspirar, retorne lentamente abaixando os calcanhares.","Repita pela quantidade recomendada de repetições."]},
"Standing_Dumbbell_Press":{"name":"Desenvolvimento em Pé com Halteres","instructions":["Fique em pé com os pés na largura dos ombros segurando um halter em cada mão na altura da cabeça com cotovelos abertos a cerca de 90 graus. Esta será a sua posição inicial.","Mantendo técnica estrita sem impulso das pernas nem inclinação do tronco, estenda os cotovelos empurrando os halteres juntos diretamente acima da cabeça.","Pause no topo e retorne lentamente à posição inicial."]},
"Standing_Dumbbell_Reverse_Curl":{"name":"Rosca Inversa em Pé com Halteres","instructions":["Fique em pé com um halter em cada mão em pegada pronada (palmas para baixo), braços estendidos e pés na largura dos ombros. Esta é a posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos elevando os halteres até a altura dos ombros enquanto expira e segure um segundo no topo, movendo apenas os antebraços.","Abaixe lentamente os halteres de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head":{"name":"Elevação Frontal Completa Acima da Cabeça com Halteres","instructions":["Segure os halteres à frente das coxas com as palmas voltadas para o corpo.","Mantenha os braços estendidos com leve flexão fixa nos cotovelos. Esta será a sua posição inicial.","Eleve os halteres em movimento semicircular à frente até ficarem estendidos acima da cabeça enquanto expira.","Retorne lentamente à posição inicial pelo mesmo trajeto enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Dumbbell_Triceps_Extension":{"name":"Tríceps Francês em Pé com Halter","instructions":["Fique em pé com pés na largura dos ombros, segure um halter com as duas mãos e eleve-o acima da cabeça com os braços totalmente estendidos.","Apoie as palmas sob a anilha superior com os polegares ao redor. Esta será a sua posição inicial.","Mantendo os braços próximos à cabeça (cotovelos fechados) e perpendiculares ao chão, abaixe o halter em semicírculo atrás da cabeça até os antebraços tocarem o bíceps enquanto inspira, movendo apenas os antebraços.","Retorne à posição inicial estendendo os cotovelos com o tríceps enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Dumbbell_Upright_Row":{"name":"Remada Alta em Pé com Halteres","instructions":["Segure um halter em cada mão com pegada pronada apoiados à frente das coxas, braços estendidos com leve flexão nos cotovelos e costas retas. Esta será a sua posição inicial.","Use os ombros para puxar os halteres rente ao corpo enquanto expira até quase encostar no queixo, conduzindo sempre com os cotovelos acima dos antebraços, e pause um segundo no topo.","Abaixe os halteres lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Elevated_Quad_Stretch":{"name":"Alongamento de Quadríceps em Pé com Pé Apoiado","instructions":["Fique em pé de costas a dois ou três pés de distância de um banco ou degrau.","Eleve uma perna para trás apoiando o peito ou a ponta do pé sobre o banco.","Mantenha o joelho de apoio levemente flexionado sem deixá-lo passar dos dedos do pé; depois troque de lado."]},
"Standing_Front_Barbell_Raise_Over_Head":{"name":"Elevação Frontal Acima da Cabeça com Barra","instructions":["Fique em pé segurando uma barra com pegada pronada (palmas para baixo) um pouco mais fechada que a largura dos ombros.","Mantenha os pés na largura dos ombros e leve flexão nos cotovelos. Esta é a posição inicial.","Eleve a barra à frente até ficar diretamente acima da cabeça enquanto expira mantendo a leve flexão nos cotovelos.","Ao sentir a contração, abaixe a barra lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Gastrocnemius_Calf_Stretch":{"name":"Alongamento do Gastrocnêmio em Pé","instructions":["Apoie o calcanhar direito sobre um degrau com o joelho estendido e incline-se à frente para segurar a ponta do pé direito com a mão direita mantendo as costas retas.","Sustente o peso na perna esquerda levemente flexionada apoiando a mão esquerda na coxa esquerda.","Puxe os dedos do pé direito em direção ao joelho até sentir alongar a panturrilha e depois troque de lado."]},
"Standing_Hamstring_and_Calf_Stretch":{"name":"Alongamento de Posteriores e Panturrilha em Pé","instructions":["Passe um cinto, faixa ou corda ao redor de um pé e posicione esse pé à frente em pé.","Flexione a perna de trás mantendo a da frente estendida, eleve a ponta do pé da frente do chão e incline-se à frente.","Use a faixa para puxar a ponta do pé intensificando o alongamento na panturrilha; segure por 10-20 segundos e repita com o outro pé."]},
"Standing_Hip_Circles":{"name":"Círculos com o Quadril em Pé","instructions":["Fique em pé apoiado em uma perna segurando em um suporte vertical.","Eleve o joelho oposto a 90 graus. Esta será a sua posição inicial.","Abra o quadril o máximo possível tentando desenhar um círculo amplo com o joelho.","Execute lentamente por algumas repetições e depois repita do outro lado."]},
"Standing_Hip_Flexors":{"name":"Alongamento de Flexores do Quadril em Pé","instructions":["Fique ereto com o pé esquerdo ligeiramente à frente do direito.","Flexione ambos os joelhos tirando o calcanhar de trás do chão enquanto projeta o quadril direito para a frente; depois troque de lado."]},
"Standing_Inner-Biceps_Curl":{"name":"Rosca Aberta em Pé para Bíceps Interno","instructions":["Fique em pé com pés na largura dos ombros segurando um halter em cada mão com braços estendidos e cotovelos próximos ao corpo.","Mantenha as palmas voltadas para dentro em pegada neutra. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, eleve os halteres para fora girando os punhos para pegada supinada (palmas para cima) enquanto expira.","Mova apenas os antebraços alinhados aos deltoides laterais até o bíceps contrair totalmente na altura dos ombros.","Segure a contração por um segundo apertando o bíceps.","Abaixe lentamente de volta à posição inicial enquanto inspira girando de volta à pegada neutra.","Repita pela quantidade recomendada de repetições."]},
"Standing_Lateral_Stretch":{"name":"Alongamento Lateral em Pé","instructions":["Afaste os pés um pouco além da largura do quadril com os joelhos levemente flexionados.","Apoie a mão direita no quadril direito para dar suporte à coluna.","Eleve o braço esquerdo na vertical colocando a mão esquerda atrás da cabeça e incline o tronco para a direita.","Mantenha o peso distribuído igualmente entre as duas pernas e depois troque de lado."]},
"Standing_Leg_Curl":{"name":"Flexão de Perna em Pé na Máquina","instructions":["Ajuste a alavanca da máquina à sua altura e apoie o tronco inclinado a 30-45 graus com o rolo na parte posterior da perna direita (logo abaixo da panturrilha) e a coxa no apoio frontal.","Segure as alças laterais mantendo a perna estendida. Esta será a sua posição inicial.","Ao expirar, flexione a perna direita para cima o máximo possível sem tirar a coxa do apoio e segure por um segundo no topo.","Ao inspirar, retorne à posição inicial pela quantidade recomendada de repetições.","Execute o mesmo exercício para a perna esquerda."]},
"Standing_Long_Jump":{"name":"Salto Horizontal Parado","instructions":["Em uma superfície macia como areia, posicione-se em meio agachamento com os pés na largura dos ombros.","Usando um amplo balanço dos braços e contramovimento das pernas, salte para a frente o mais longe possível.","Tente aterrissar com os pés projetados à frente buscando a maior distância possível.","Meça a distância entre o ponto de partida e a aterrissagem."]},
"Standing_Low-Pulley_Deltoid_Raise":{"name":"Elevação Lateral Unilateral na Polia Baixa","instructions":["Fique em pé ao lado direito de uma polia baixa, cruze a mão esquerda à frente do corpo para segurar o pegador com pegada pronada e apoie a mão direita na máquina.","Mantenha as costas retas e os pés na largura dos ombros. Esta é a posição inicial.","Eleve o braço esquerdo cruzando para fora até a altura dos ombros enquanto expira.","Segure a contração no topo por um segundo e abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições.","Troque de braço e repita o exercício."]},
"Standing_Low-Pulley_One-Arm_Triceps_Extension":{"name":"Tríceps Francês Unilateral em Pé no Cabo","instructions":["De costas para uma polia baixa, segure o pegador unilateral com a mão esquerda e eleve o braço verticalmente acima da cabeça com palma para a frente, apoiando a mão direita no cotovelo esquerdo para estabilizar. Esta é a posição inicial.","Mantendo o braço imóvel junto à cabeça, abaixe o pegador em semicírculo atrás da cabeça até o antebraço encostar no bíceps enquanto inspira, movendo apenas o antebraço.","Estenda o cotovelo usando o tríceps para retornar à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições.","Troque de braço e repita o exercício."]},
"Standing_Military_Press":{"name":"Desenvolvimento Militar em Pé com Barra","instructions":["Posicione a barra em um rack na altura do peito e segure-a com pegada pronada um pouco mais aberta que a largura dos ombros.","Apoie a barra na parte superior do peito/clavícula e dê um passo para trás com os pés na largura dos ombros.","Empurre a barra acima da cabeça travando os braços e segure na altura dos ombros ligeiramente à frente da cabeça. Esta é a sua posição inicial.","Desça a barra lentamente até a clavícula enquanto inspira.","Empurre a barra de volta à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Olympic_Plate_Hand_Squeeze":{"name":"Pegada Pinça Estática com Anilhas","instructions":["Fique em pé segurando uma anilha pela borda em cada mão com os braços estendidos ao lado do corpo em pegada neutra e pés na largura dos ombros. Esta será a sua posição inicial.","Abra lentamente os dedos deixando a anilha descer até quase a ponta dos dedos sem soltá-la enquanto inspira.","Feche as mãos puxando as anilhas de volta à posição inicial enquanto expira.","Repita pela quantidade prescrita de repetições."]},
"Standing_One-Arm_Cable_Curl":{"name":"Rosca Direta Unilateral em Pé no Cabo","instructions":["Segure o pegador unilateral da polia baixa afastando-se o suficiente para gerar tensão no cabo.","Mantenha o braço imóvel perpendicular ao chão com cotovelo junto ao tronco e palma para a frente, apoiando a mão livre na cintura para equilíbrio.","Flexione lentamente o cotovelo levando o pegador para cima até o antebraço tocar o bíceps enquanto expira, movendo apenas o antebraço.","Segure a contração apertando o bíceps e depois abaixe de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições.","Troque de braço e execute o outro lado."]},
"Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench":{"name":"Rosca Scott Unilateral em Pé no Banco Inclinado","instructions":["Fique em pé atrás de um banco inclinado e apoie um braço sobre o encosto segurando um halter com pegada supinada (palma para cima).","Segure a lateral do banco com a mão livre, apoie o peito no topo do encosto e mantenha os pés afastados no chão. Esta é a posição inicial.","Mantendo a parte superior do braço imóvel, flexione o cotovelo contraindo o bíceps enquanto expira até o halter chegar à altura do ombro e segure um segundo.","Abaixe lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições.","Troque de braço e execute o outro lado."]},
"Standing_One-Arm_Dumbbell_Triceps_Extension":{"name":"Tríceps Francês Unilateral em Pé com Halter","instructions":["Fique em pé com pés na largura dos ombros segurando um halter em uma mão estendido acima da cabeça, com o dedo mínimo voltado para o teto e palma para a frente.","Esta será a sua posição inicial.","Mantendo o braço imóvel junto à cabeça e perpendicular ao chão, abaixe o halter em semicírculo atrás da cabeça até o antebraço tocar o bíceps enquanto inspira, movendo apenas o antebraço.","Retorne à posição inicial usando o tríceps para estender o braço enquanto expira.","Repita pela quantidade recomendada de repetições.","Troque de braço e repita o exercício."]},
"Standing_Overhead_Barbell_Triceps_Extension":{"name":"Tríceps Francês em Pé com Barra","instructions":["Fique em pé com pés na largura dos ombros segurando uma barra reta ou barra W com pegada pronada mais fechada que a largura dos ombros.","Eleve a barra acima da cabeça até estender totalmente os braços mantendo os cotovelos fechados. Esta será a sua posição inicial.","Mantendo os braços próximos à cabeça e perpendiculares ao chão, abaixe a barra em semicírculo atrás da cabeça até os antebraços tocarem o bíceps enquanto inspira, movendo apenas os antebraços.","Retorne à posição inicial estendendo os braços com o tríceps enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Palm-In_One-Arm_Dumbbell_Press":{"name":"Desenvolvimento Unilateral em Pé com Halter - Pegada Neutra","instructions":["Segure um halter em uma mão com o braço estendido ao lado em pegada neutra e use a outra mão para segurar em um banco inclinado para manter o equilíbrio.","Com os pés na largura dos ombros, eleve o halter até o braço formar um ângulo de 90 graus com o antebraço perpendicular ao chão mantendo pegada neutra.","Empurre o halter lentamente até estender totalmente o braço acima da cabeça. Esta é a sua posição inicial.","Enquanto inspira, abaixe o peso de volta até o braço formar 90 graus.","Segure um segundo e empurre de volta à posição inicial enquanto expira mantendo firmeza no apoio.","Repita pela quantidade recomendada de repetições.","Troque de braço e repita o exercício."]},
"Standing_Palms-In_Dumbbell_Press":{"name":"Desenvolvimento em Pé com Halteres - Pegada Neutra","instructions":["Fique em pé com pés na largura dos ombros segurando um halter em cada mão com pegada neutra e eleve os halteres até formar 90 graus nos cotovelos com os antebraços perpendiculares ao chão. Esta é a sua posição inicial.","Mantendo a pegada neutra durante todo o exercício, empurre os halteres acima da cabeça até estender totalmente os braços.","Enquanto inspira, abaixe os halteres de volta ao ângulo de 90 graus.","Repita pela quantidade recomendada de repetições."]},
"Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl":{"name":"Rosca de Punho por Trás das Costas com Barra","instructions":["Fique em pé segurando uma barra atrás dos glúteos com os braços estendidos na largura dos ombros e pegada voltada para trás.","Olhe para a frente com os pés na largura dos ombros. Esta é a posição inicial.","Ao expirar, flexione os punhos elevando a barra em semicírculo em direção ao teto movendo apenas os punhos.","Segure a contração por um segundo e abaixe a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições.","Ao terminar, abaixe a barra dobrando os joelhos até o suporte ou o chão."]},
"Standing_Pelvic_Tilt":{"name":"Inclinação Pélvica em Pé","instructions":["Fique em pé com os pés afastados na largura do quadril.","Flexione levemente os joelhos para mantê-los soltos.","Bascule a pelve para a frente e para trás algumas vezes antes de sustentar o cóccix projetado à frente neste alongamento."]},
"Standing_Rope_Crunch":{"name":"Abdominal em Pé no Cabo com Corda","instructions":["Prenda uma corda na polia alta e selecione a carga adequada.","Fique de costas para a torre segurando a corda sobre os ombros junto à parte superior do peito com as duas mãos. Esta será a sua posição inicial.","Flexione a coluna curvando o tronco para baixo o máximo possível.","Segure a contração máxima por um instante antes de retornar à posição inicial."]},
"Standing_Soleus_And_Achilles_Stretch":{"name":"Alongamento de Sóleo e Tendão de Aquiles em Pé","instructions":["Fique em pé com os pés afastados na largura do quadril, um pé ligeiramente à frente do outro.","Flexione ambos os joelhos mantendo o calcanhar de trás totalmente apoiado no chão e depois troque de lado."]},
"Standing_Toe_Touches":{"name":"Alongamento Tocando os Pés em Pé","instructions":["Fique em pé com espaço livre à frente e atrás.","Incline o tronco para a frente pela cintura mantendo as pernas estendidas e deixe braços e tronco relaxarem pendurados à frente por 10 a 20 segundos."]},
"Standing_Towel_Triceps_Extension":{"name":"Extensão de Tríceps em Pé com Toalha (Com Parceiro)","instructions":["Fique em pé com pés na largura dos ombros e ambos os braços estendidos acima da cabeça segurando uma ponta de uma toalha com cotovelos fechados. Esta é a posição inicial.","Peça ao seu parceiro para segurar a outra ponta da toalha aplicando resistência; mantendo os braços imóveis junto à cabeça, abaixe as mãos em semicírculo atrás da cabeça até os antebraços tocarem o bíceps enquanto inspira.","Retorne à posição inicial usando o tríceps para puxar a toalha para cima enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Standing_Two-Arm_Overhead_Throw":{"name":"Arremesso Frontal Acima da Cabeça com Medicine Ball","instructions":["Fique em pé com pés na largura dos ombros segurando uma bola medicinal com as duas mãos, leve-a atrás da cabeça flexionando levemente os joelhos e inclinando o tronco para trás.","Arremesse a bola com força para a frente flexionando o quadril e usando todo o corpo.","Arremesse para um parceiro ou contra uma parede e pegue-a no rebote."]},
"Star_Jump":{"name":"Salto Estrela","instructions":["Comece em postura relaxada com os pés na largura dos ombros e os braços próximos ao corpo.","Faça um meio agachamento e salte explosivamente o mais alto possível abrindo braços e pernas no ar.","Ao aterrissar, junte novamente os membros e amorteça o impacto com as pernas."]},
"Step-up_with_Knee_Raise":{"name":"Subida no Banco (Step-Up) com Elevação de Joelho","instructions":["Fique de frente para uma caixa ou banco de altura adequada com os pés juntos. Esta será a sua posição inicial.","Suba apoiando o pé esquerdo no banco e estendendo quadril e joelho esquerdos enquanto eleva o joelho direito o mais alto possível.","Inverta o movimento descendo da caixa e repita a sequência com a perna oposta."]},
"Step_Mill":{"name":"Escada Ergométrica (Step Mill)","instructions":["Suba na escada ergométrica e selecione o modo manual ou programa no painel, mantendo as mãos nos apoios laterais para segurança.","Mantenha passadas firmes em ritmo contínuo evitando tropeçar nos degraus pela duração desejada."]},
"Stiff-Legged_Barbell_Deadlift":{"name":"Stiff com Barra","instructions":["Segure uma barra com pegada pronada (palmas para baixo) na largura dos ombros.","Fique em pé com o tronco ereto, pés na largura dos ombros ou mais próximos e joelhos levemente flexionados. Esta é a posição inicial.","Mantendo os joelhos fixos, abaixe a barra à frente das pernas flexionando o quadril com as costas retas até sentir alongar os posteriores de coxa enquanto inspira.","Retorne à posição inicial estendendo o quadril enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Stiff-Legged_Dumbbell_Deadlift":{"name":"Stiff com Halteres","instructions":["Segure um par de halteres ao lado do corpo com os braços estendidos.","Fique em pé com o tronco ereto, pés na largura dos ombros ou mais próximos e joelhos levemente flexionados. Esta é a posição inicial.","Mantendo os joelhos fixos, abaixe os halteres à frente das pernas flexionando o quadril com as costas retas até sentir alongar os posteriores de coxa enquanto inspira.","Retorne à posição inicial estendendo o quadril enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Stiff_Leg_Barbell_Good_Morning":{"name":"Bom Dia com Pernas Estendidas e Barra","instructions":["Dentro de um rack de agachamento, ajuste a barra na sua altura, entre sob ela apoiando-a na parte posterior dos ombros.","Segure a barra com as duas mãos e retire-a empurrando com as pernas.","Afaste-se em base média mantendo cabeça erguida, costas retas e pernas quase totalmente estendidas. Esta será a sua posição inicial.","Mantendo as pernas fixas, incline o tronco à frente flexionando o quadril enquanto inspira até ficar paralelo ao chão.","Suba o tronco de volta à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Stomach_Vacuum":{"name":"Vácuo Abdominal (Stomach Vacuum)","instructions":["Fique em pé com os pés na largura dos ombros e as mãos na cintura. Esta é a posição inicial.","Inspire devagar e depois expire todo o ar puxando o abdômen o máximo possível para dentro (visualizando o umbigo encostando na coluna) e segure a posição.","Mantenha a contração isométrica por cerca de 20 segundos respirando suavemente e depois relaxe inspirando.","Com a prática, aumente gradualmente o tempo de sustentação para 40-60 segundos.","Repita pela quantidade recomendada de séries."]},
"Straight-Arm_Dumbbell_Pullover":{"name":"Pullover com Braços Estendidos e Halter","instructions":["Coloque um halter em pé sobre um banco reto.","Deite-se perpendicularmente ao banco apoiando apenas os ombros, com quadril abaixo do banco, pernas dobradas, pés no chão e cabeça fora do banco.","Segure o halter com as duas mãos acima do peito com os braços estendidos e palmas pressionando a face interna da anilha superior. Cuidado: certifique-se de que as anilhas do halter estejam bem travadas. Esta será a sua posição inicial.","Mantendo os braços estendidos, abaixe lentamente o halter em arco atrás da cabeça enquanto inspira até sentir alongar o peitoral.","Traga o halter de volta à posição inicial pelo mesmo arco enquanto expira.","Segure por um segundo na posição inicial e repita pelo número prescrito de repetições."]},
"Straight-Arm_Pulldown":{"name":"Pulldown com Braços Estendidos na Barra","instructions":["Segure a barra reta na polia alta com pegada pronada mais aberta que os ombros e dê cerca de dois passos para trás.","Incline o tronco à frente cerca de 30 graus com os braços totalmente estendidos à frente (leve flexão fixa nos cotovelos) e ative as dorsais.","Mantendo os braços estendidos, puxe a barra para baixo contraindo as dorsais até as mãos encostarem nas coxas enquanto expira.","Retorne lentamente à posição inicial mantendo os braços estendidos enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Straight_Bar_Bench_Mid_Rows":{"name":"Remada Curvada sobre o Banco com Barra","instructions":["Coloque uma barra montada na ponta de um banco reto, suba no banco atrás da barra com quadril para trás, peito aberto, coluna neutra e segure com pegada pronada média. Esta será a sua posição inicial.","Puxe a barra em direção ao tronco retraindo as escápulas e flexionando os cotovelos sem dar trancos.","Após uma breve pausa, abaixe lentamente a barra até a extensão completa na posição inicial."]},
"Straight_Raises_on_Incline_Bench":{"name":"Elevação Frontal com Barra no Banco Inclinado","instructions":["Coloque uma barra no chão atrás da cabeceira de um banco inclinado.","Deite-se de bruços no banco e segure a barra com pegada pronada deixando os braços pendurados estendidos. Esta será a sua posição inicial.","Eleve a barra à frente da cabeça mantendo os braços totalmente estendidos.","Retorne lentamente à posição inicial."]},
"Stride_Jump_Crossover":{"name":"Salto Alternado sobre a Caixa","instructions":["Fique ao lado de uma caixa com o pé interno apoiado em cima dela próximo à borda.","Balance os braços para cima impulsionando com a perna sobre a caixa para saltar o mais alto possível elevando o joelho oposto.","Aterrisse do outro lado da caixa trocando os pés (o pé que estava no chão cai em cima da caixa e o outro no chão).","Repita saltando de volta para o outro lado."]},
"Sumo_Deadlift":{"name":"Levantamento Terra Sumô","instructions":["Com a barra no chão, posicione-se com os pés bem abertos próximos às anilhas e flexione o quadril para segurar a barra com os braços verticais por dentro das pernas (pegada pronada, mista ou hook grip).","Inspire fundo, abaixe o quadril olhando à frente com peito aberto e empurre o chão afastando os pés com o peso na metade traseira dos pés.","Quando a barra passar dos joelhos, incline-se levemente para trás projetando o quadril contra a barra e aproximando as escápulas.","Retorne a barra ao chão flexionando o quadril de forma controlada."]},
"Sumo_Deadlift_with_Bands":{"name":"Levantamento Terra Sumô com Elásticos","instructions":["Passe elásticos curtos sobre a barra e pise sobre eles com a metade traseira dos pés para gerar tensão.","Posicione os pés bem abertos próximos às anilhas e flexione o quadril para segurar a barra por dentro das pernas com pegada pronada, mista ou hook grip.","Inspire, abaixe o quadril olhando à frente com peito aberto e empurre o chão afastando os pés.","Quando a barra passar dos joelhos, aproxime as escápulas e projete o quadril contra a barra.","Abaixe o peso de volta ao chão flexionando o quadril sob controle."]},
"Sumo_Deadlift_with_Chains":{"name":"Levantamento Terra Sumô com Correntes","instructions":["Prenda as correntes nas mangas da barra ou sobre o centro dela mantendo as pontas longe das anilhas.","Posicione os pés bem abertos próximos às anilhas, flexione o quadril e segure a barra por dentro das pernas com os braços verticais (pegada pronada, mista ou hook grip).","Inspire, abaixe o quadril olhando à frente com peito aberto e empurre o chão afastando os pés com o peso na metade traseira dos pés.","Quando a barra passar dos joelhos, aproxime as escápulas e projete o quadril contra a barra.","Retorne a barra ao chão flexionando o quadril de forma controlada."]},
"Superman":{"name":"Extensão Lombar Superman","instructions":["Deite-se de bruços no chão ou colchonete com os braços totalmente estendidos à frente. Esta é a posição inicial.","Eleve simultaneamente braços, peito e pernas do chão contraindo a lombar e segure por 2 segundos enquanto expira.","Abaixe lentamente braços, pernas e peito de volta à posição inicial enquanto inspira.","Repita pela quantidade prescrita de repetições."]},
"Supine_Chest_Throw":{"name":"Arremesso Vertical Deitado com Medicine Ball","instructions":["Deite-se de costas no chão com os joelhos flexionados.","Apoie a bola medicinal sobre o peito segurando por baixo com as duas mãos.","Exploda para cima estendendo os cotovelos para arremessar a bola verticalmente o mais alto possível.","Segure a bola com as duas mãos quando ela descer."]},
"Supine_One-Arm_Overhead_Throw":{"name":"Arremesso Unilateral Deitado com Medicine Ball","instructions":["Deite-se de costas com os joelhos flexionados segurando uma bola medicinal em uma mão com o braço estendido atrás da cabeça. Esta será a sua posição inicial.","Inicie pelo ombro arremessando a bola diretamente à frente enquanto sobe o tronco buscando máxima distância.","A bola pode ser lançada para um parceiro ou contra uma parede."]},
"Supine_Two-Arm_Overhead_Throw":{"name":"Arremesso Bilateral Deitado com Medicine Ball","instructions":["Deite-se de costas no chão com os joelhos flexionados.","Segure a bola medicinal com as duas mãos estendendo os braços atrás da cabeça. Esta será a sua posição inicial.","Inicie pelo ombro arremessando a bola à frente enquanto sobe o tronco buscando máxima distância.","A bola pode ser lançada para um parceiro ou contra uma parede."]},
"Suspended_Fallout":{"name":"Extensão Abdominal em Fitas de Suspensão (Fallout)","instructions":["Ajuste as fitas de suspensão abaixo da altura da cintura.","Fique em pé segurando as alças e incline-se à frente em posição de prancha inclinada. Esta será a sua posição inicial.","Mantendo os braços estendidos e o corpo alinhado, incline-se ainda mais à frente levando os braços acima da cabeça movendo apenas os ombros.","Mantenha a coluna neutra e o restante do corpo firme.","Pause na extensão máxima e depois retorne à posição inicial."]},
"Suspended_Push-Up":{"name":"Flexão de Braço em Fitas de Suspensão","instructions":["Prenda as fitas de suspensão no topo de um rack ou suporte firme.","Segure uma alça em cada mão e incline-se à frente em posição de prancha o mais próximo possível do paralelo ao chão com os braços estendidos.","Mantendo o tronco firme e reto, desça lentamente flexionando os cotovelos.","Desça até os cotovelos ultrapassarem 90 graus, pause e estenda os braços retornando à posição inicial."]},
"Suspended_Reverse_Crunch":{"name":"Abdominal Reverso em Fitas de Suspensão","instructions":["Ajuste as fitas de suspensão com as alças a cerca de 1 pé do chão e entre em posição de prancha de costas para o ponto de fixação.","Encaixe os pés nas alças mantendo o corpo reto sem deixar o quadril ceder. Esta será a sua posição inicial.","Flexione joelhos e quadril trazendo os joelhos em direção ao peito enquanto gira a pelve e flexiona a coluna.","No ponto máximo controlado, retorne à posição inicial."]},
"Suspended_Row":{"name":"Remada em Fitas de Suspensão","instructions":["Ajuste as fitas na altura do peito, segure uma alça em cada mão, incline o corpo para trás mantendo-o reto com cabeça e peito erguidos e braços estendidos. Esta será a sua posição inicial.","Flexione os cotovelos puxando o corpo para cima enquanto retrai as escápulas.","Pause no topo do movimento e depois retorne à posição inicial."]},
"Suspended_Split_Squat":{"name":"Agachamento Búlgaro em Fitas de Suspensão","instructions":["Ajuste as fitas de suspensão a 18-30 polegadas do chão.","De costas para o suporte, encaixe o pé de trás na alça mantendo cabeça à frente, peito aberto e joelho da frente levemente flexionado. Esta será a sua posição inicial.","Desça flexionando joelho e quadril mantendo o peso no calcanhar da frente e boa postura.","No ponto mais baixo, inverta o movimento estendendo quadril e joelho até retornar à posição inicial."]},
"Svend_Press":{"name":"Supino Isométrico com Anilhas (Svend Press)","instructions":["Fique em pé com postura ereta.","Pressione duas anilhas leves uma contra a outra entre as palmas junto ao peito com os dedos apontando para a frente. Esta é a posição inicial.","Mantendo forte pressão entre as palmas, estenda os braços diretamente à frente de forma controlada.","Pause na extensão completa e retorne lentamente à posição inicial."]},
"T-Bar_Row_with_Handle":{"name":"Remada Cavalinho com Pegador Triângulo","instructions":["Encaixe uma barra no landmine (ou canto seguro) e carregue o peso na extremidade livre.","Posicione-se sobre a barra, encaixe um pegador triângulo (barra em V) logo abaixo das anilhas e levante-se usando pernas e quadril.","Adote base ampla com quadril para trás, peito aberto e braços estendidos. Esta será a sua posição inicial.","Puxe a barra em direção ao abdômen superior retraindo as escápulas e flexionando os cotovelos sem dar trancos.","Após uma breve pausa, retorne à posição inicial."]},
"Tate_Press":{"name":"Supino Tate com Halteres (Tate Press)","instructions":["Deite-se em um banco reto segurando um halter em cada mão apoiados sobre as coxas.","Impulsione os halteres para cima na largura dos ombros com pegada pronada (palmas para a frente) e cotovelos apontados para os lados. Esta é a posição inicial.","Mantendo a parte superior dos braços imóvel, desça os halteres para dentro e para baixo em semicírculo flexionando os cotovelos até tocarem a parte superior do peito enquanto inspira, sem descansar no peito.","Ao expirar, empurre os halteres de volta para cima pelo mesmo trajeto usando o tríceps até estender os braços, segurando um segundo no topo.","Repita pela quantidade prescrita de repetições."]},
"The_Straddle":{"name":"Alongamento Sentado em V (Straddle)","instructions":["Sente-se ereto no chão com as pernas estendidas e abertas à frente formando um \"V\".","Com as mãos apoiadas no chão à frente, incline o tronco para a frente o máximo possível e segure por 10 a 20 segundos."]},
"Thigh_Abductor":{"name":"Cadeira Abdutora","instructions":["Sente-se na cadeira abdutora, selecione a carga, posicione as pernas nos apoios externos e segure as alças laterais mantendo o tronco imóvel. Esta é a posição inicial.","Empurre os apoios para fora afastando as pernas enquanto expira.","Segure a contração por um segundo e retorne lentamente à posição inicial enquanto inspira mantendo o tronco estável.","Repita pela quantidade recomendada de repetições."]},
"Thigh_Adductor":{"name":"Cadeira Adutora","instructions":["Sente-se na cadeira adutora, selecione a carga, posicione as pernas nos apoios internos e segure as alças laterais mantendo o tronco imóvel. Esta é a posição inicial.","Empurre os apoios para dentro fechando as pernas enquanto expira.","Segure a contração por um segundo e retorne lentamente à posição inicial enquanto inspira sem trancos.","Repita pela quantidade recomendada de repetições."]},
"Tire_Flip":{"name":"Virada de Pneu (Tire Flip)","instructions":["Agache atrás do pneu, segure a borda inferior pela banda de rodagem e encoste o peito contra o pneu com os pés posicionados atrás.","Para erguer o pneu, estenda quadril, joelhos e tornozelos empurrando contra o pneu para cima e para a frente.","Quando o pneu atingir cerca de 45 graus, dê um passo à frente, apoie o joelho se necessário, mude as mãos para empurrar e tombe o pneu com força para a frente."]},
"Toe_Touchers":{"name":"Abdominal Toque nos Pés","instructions":["Deite-se de costas no chão ou colchonete com os braços ao lado do corpo.","Eleve as pernas juntas quase perpendiculares ao chão com leve flexão nos joelhos.","Estenda os braços a cerca de 45 graus apontando para cima. Esta é a posição inicial.","Mantendo a lombar pressionada no chão, eleve o tronco tentando tocar os dedos dos pés com as mãos enquanto expira.","Abaixe lentamente o tronco e os braços de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Torso_Rotation":{"name":"Rotação de Tronco com Bola Suíça","instructions":["Fique ereto segurando uma bola suíça com as duas mãos e braços estendidos à frente. Esta será a sua posição inicial.","Gire o tronco para um lado acompanhando a bola com o olhar e depois gire para o lado oposto; repita 10-20 vezes."]},
"Trail_Running_Walking":{"name":"Corrida ou Caminhada em Trilha","instructions":["Use calçado adequado e, nas descidas, dê passos mais curtos mantendo os joelhos levemente flexionados para reduzir o impacto articular.","Mantenha ritmo compatível com o terreno tanto nas subidas quanto nas descidas pela duração desejada."]},
"Trap_Bar_Deadlift":{"name":"Levantamento Terra na Barra Hexagonal (Trap Bar)","instructions":["Carregue a barra hexagonal no chão, entre no centro dela e segure ambas as alças laterais.","Abaixe o quadril, olhe para a frente e mantenha o peito aberto.","Empurre pelos calcanhares estendendo quadril e joelhos sem arredondar as costas.","Ao concluir a extensão, abaixe o peso de volta ao chão sob controle."]},
"Tricep_Dumbbell_Kickback":{"name":"Coice Bilateral com Halteres","instructions":["Segure um halter em cada mão com palmas voltadas para o corpo, flexione levemente os joelhos e incline o tronco à frente mantendo costas retas até quase ficar paralelo ao chão; eleve os braços juntos ao tronco formando 90 graus nos cotovelos. Esta é a posição inicial.","Mantendo a parte superior dos braços imóvel, expire e estenda os cotovelos usando o tríceps até os braços ficarem totalmente estendidos.","Após uma breve pausa no topo, inspire e abaixe lentamente os halteres de volta à posição inicial.","Repita pela quantidade prescrita de repetições."]},
"Tricep_Side_Stretch":{"name":"Alongamento Lateral de Tríceps e Ombro","instructions":["Cruze o braço direito à frente do corpo na altura do peito segurando o cotovelo com a mão esquerda até sentir alongar tríceps e ombro; depois repita com o outro braço."]},
"Triceps_Overhead_Extension_with_Rope":{"name":"Tríceps Francês na Polia Baixa com Corda","instructions":["Prenda uma corda na polia baixa, selecione a carga, segure a corda com as duas mãos e vire-se de costas para o cabo.","Posicione as mãos atrás da cabeça com os cotovelos flexionados apontando para cima em base alternada inclinada levemente à frente. Esta será a sua posição inicial.","Estenda os cotovelos elevando as mãos acima da cabeça mantendo a parte superior dos braços fixa.","Contraia o tríceps no topo e abaixe lentamente de volta à posição inicial."]},
"Triceps_Pushdown":{"name":"Tríceps Pulley na Barra","instructions":["Prenda uma barra reta ou barra W na polia alta e segure com pegada pronada (palmas para baixo) na largura dos ombros.","Em pé com leve inclinação à frente, encoste os cotovelos ao lado do corpo mantendo a parte superior dos braços perpendicular ao chão e os antebraços apontando para cima. Esta é a posição inicial.","Usando o tríceps, empurre a barra para baixo até tocar a frente das coxas com os braços estendidos enquanto expira, movendo apenas os antebraços.","Após segurar um segundo na contração, retorne a barra lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Triceps_Pushdown_-_Rope_Attachment":{"name":"Tríceps Pulley com Corda","instructions":["Prenda uma corda na polia alta e segure com pegada neutra (palmas frente a frente).","Em pé com leve inclinação à frente, mantenha os braços junto ao corpo perpendiculares ao chão e antebraços apontando para cima. Esta é a posição inicial.","Usando o tríceps, puxe a corda para baixo abrindo as pontas ao lado das coxas até estender totalmente os braços enquanto expira, movendo apenas os antebraços.","Após segurar um segundo na contração, retorne a corda lentamente ao ponto inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Triceps_Pushdown_-_V-Bar_Attachment":{"name":"Tríceps Pulley com Barra V","instructions":["Prenda uma barra V na polia alta e segure com pegada pronada na largura dos ombros.","Em pé com leve inclinação à frente, mantenha os braços junto ao corpo perpendiculares ao chão com os polegares mais altos que os dedos mínimos. Esta é a posição inicial.","Usando o tríceps, empurre a barra V para baixo até tocar a frente das coxas com os braços totalmente estendidos enquanto expira, movendo apenas os antebraços.","Após segurar um segundo na contração, retorne lentamente ao ponto inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Triceps_Stretch":{"name":"Alongamento de Tríceps","instructions":["Leve uma mão atrás da cabeça entre as escápulas, segure o cotovelo com a outra mão e puxe suavemente por 10 a 20 segundos; depois troque de lado."]},
"Tuck_Crunch":{"name":"Abdominal Grupado (Tuck Crunch)","instructions":["Deite-se de costas no chão ou colchonete com os braços ao lado do corpo.","Cruze os tornozelos e eleve as pernas até as coxas ficarem perpendiculares ao chão com os joelhos dobrados a 90 graus.","Cruze os braços sobre o peito. Esta é a posição inicial.","Mantendo a lombar pressionada no chão, eleve o tronco em direção às pernas enquanto expira.","Abaixe lentamente o tronco de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Two-Arm_Dumbbell_Preacher_Curl":{"name":"Rosca Scott Bilateral com Halteres","instructions":["Segure um halter em cada mão e apoie a parte posterior dos braços sobre o banco Scott segurando na altura dos ombros. Esta será a sua posição inicial.","Enquanto inspira, abaixe lentamente os halteres até estender os braços e alongar totalmente o bíceps.","Ao expirar, flexione os cotovelos contraindo o bíceps até os halteres chegarem à altura dos ombros.","Aperte forte o bíceps por um segundo na contração e repita pela quantidade recomendada de repetições."]},
"Two-Arm_Kettlebell_Clean":{"name":"Clean Bilateral com Kettlebells","instructions":["Coloque dois kettlebells entre os pés, empurre o quadril para trás e olhe à frente para entrar na posição inicial.","Faça o clean dos kettlebells até os ombros estendendo pernas e quadril enquanto gira os punhos.","Abaixe os kettlebells de volta à posição inicial e repita."]},
"Two-Arm_Kettlebell_Jerk":{"name":"Jerk Bilateral com Kettlebells","instructions":["Faça o clean de dois kettlebells até os ombros, flexione levemente os joelhos e impulsione rapidamente empurrando ambos acima da cabeça, entrando brevemente em agachamento sob o peso antes de estender as pernas em pé."]},
"Two-Arm_Kettlebell_Military_Press":{"name":"Desenvolvimento Militar Bilateral com Kettlebells","instructions":["Faça o clean de dois kettlebells até os ombros estendendo pernas e quadril enquanto gira os punhos com as palmas para a frente.","Empurre os kettlebells acima da cabeça projetando levemente o tronco à frente quando passarem pela cabeça e contraindo dorsais, glúteos e abdômen para estabilidade."]},
"Two-Arm_Kettlebell_Row":{"name":"Remada Curvada Bilateral com Kettlebells","instructions":["Coloque dois kettlebells à frente dos pés, flexione levemente os joelhos e empurre o quadril bem para trás inclinando o tronco com costas retas.","Segure ambos os kettlebells e puxe-os em direção ao abdômen retraindo as escápulas e flexionando os cotovelos; abaixe e repita."]},
"Underhand_Cable_Pulldowns":{"name":"Puxada Alta Pegada Supinada no Cabo","instructions":["Sente-se no aparelho de puxada alta com barra longa acoplada na polia superior e ajuste o apoio de joelhos.","Segure a barra com pegada supinada (palmas voltadas para você) mais fechada que a largura dos ombros.","Com os braços estendidos acima, incline o tronco cerca de 30 graus para trás criando leve curvatura lombar e abrindo o peito. Esta é a sua posição inicial.","Ao expirar, puxe a barra para baixo até tocar a parte superior do peito levando ombros e cotovelos junto ao corpo e contraindo bem as costas.","Após segurar um segundo na contração, eleve lentamente a barra de volta à posição inicial enquanto inspira até alongar totalmente as dorsais.","Repita esse movimento pela quantidade prescrita de repetições."]},
"Upper_Back-Leg_Grab":{"name":"Alongamento de Costas Superiores Abraçando as Pernas","instructions":["Sentado no chão, incline-se para a frente abraçando a parte de trás das coxas por baixo com os dois braços.","Mantenha os joelhos juntos e as pernas estendidas aproximando o peito dos joelhos; puxe suavemente as costas para trás contra os braços para intensificar o alongamento."]},
"Upper_Back_Stretch":{"name":"Alongamento da Parte Superior das Costas","instructions":["Entrelace os dedos à frente com os polegares apontando para baixo e arredonde os ombros empurrando as mãos para a frente."]},
"Upright_Barbell_Row":{"name":"Remada Alta com Barra","instructions":["Segure uma barra com pegada pronada um pouco mais fechada que a largura dos ombros, apoiada à frente das coxas com braços estendidos, leve flexão nos cotovelos e costas retas. Esta será a sua posição inicial.","Expire e use os ombros para elevar a barra rente ao corpo conduzindo com os cotovelos (sempre acima dos antebraços) até quase tocar o queixo, pausando um segundo no topo.","Abaixe a barra lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Upright_Cable_Row":{"name":"Remada Alta no Cabo","instructions":["Segure uma barra reta acoplada à polia baixa com pegada pronada um pouco mais fechada que os ombros à frente das coxas, braços estendidos e costas retas. Esta será a sua posição inicial.","Use os ombros para puxar a barra rente ao corpo enquanto expira até quase tocar o queixo, mantendo os cotovelos acima dos antebraços, e pause um segundo no topo.","Abaixe a barra lentamente de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Upright_Row_-_With_Bands":{"name":"Remada Alta com Elástico","instructions":["Pise no centro de um elástico e segure as alças à frente das coxas com pegada pronada um pouco mais fechada que os ombros, braços estendidos e costas retas. Esta será a sua posição inicial.","Use os ombros para puxar as alças rente ao corpo enquanto expira até quase a linha do queixo, conduzindo com os cotovelos acima dos antebraços, e pause um segundo no topo.","Abaixe lentamente as alças de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Upward_Stretch":{"name":"Alongamento Estendido para Cima","instructions":["Estenda os dois braços diretamente acima da cabeça juntando as palmas das mãos.","Empurre lentamente as mãos para cima e ligeiramente para trás mantendo as costas retas."]},
"V-Bar_Pulldown":{"name":"Puxada Alta com Barra V (Triângulo)","instructions":["Sente-se no aparelho de puxada alta com um pegador triângulo (barra V) acoplado na polia superior.","Ajuste o apoio de joelhos à sua altura para firmar as pernas.","Segure o pegador com pegada neutra (palmas frente a frente), abra o peito e incline-se cerca de 30 graus para trás. Esta será a sua posição inicial.","Usando as dorsais, puxe o pegador para baixo apertando as escápulas até quase tocar o peito enquanto expira, mantendo o tronco imóvel.","Após segurar um segundo na contração, retorne lentamente à posição inicial enquanto inspira.","Repita pela quantidade prescrita de repetições."]},
"V-Bar_Pullup":{"name":"Barra Fixa com Pegador V (Triângulo)","instructions":["Encaixe o meio de um pegador triângulo (barra V) sobre a barra fixa com as alças apontando para baixo.","Segure as alças em pegada neutra, pendure-se abrindo o peito e inclinando levemente o tronco para trás. Esta será a sua posição inicial.","Usando as dorsais, puxe o tronco para cima inclinando levemente a cabeça para trás até o peito quase tocar o pegador enquanto expira.","Após segurar um segundo na contração, abaixe o corpo lentamente à posição inicial enquanto inspira.","Repita pela quantidade prescrita de repetições."]},
"Vertical_Swing":{"name":"Swing Vertical com Halter","instructions":["Segure um halter com as duas mãos pendurado entre as pernas com braços estendidos, costas retas e cabeça erguida.","Balance o halter para trás entre as pernas flexionando o quadril e dobrando levemente os joelhos.","Inverta com potência estendendo quadril, joelhos e tornozelos para saltar balançando o halter acima da cabeça.","Ao aterrissar, amorteça com as pernas trazendo o halter de volta junto ao tronco antes da próxima repetição."]},
"Walking_Treadmill":{"name":"Caminhada na Esteira","instructions":["Suba na esteira e selecione o modo manual ou programa desejado no painel, ajustando inclinação e velocidade conforme o objetivo.","Mantenha passo firme e postura ereta ao caminhar, segurando nos apoios apenas ao subir, descer ou verificar a frequência cardíaca."]},
"Weighted_Ball_Hyperextension":{"name":"Hiperextensão Lombar na Bola Suíça com Peso","instructions":["Deite-se de bruços sobre uma bola suíça com o tronco paralelo ao chão, pontas dos pés firmes no solo e segurando uma anilha sob o queixo ou atrás da nuca. Esta é a posição inicial.","Eleve lentamente o tronco estendendo a lombar enquanto expira.","Segure a contração lombar por um segundo e desça de volta à posição inicial enquanto inspira.","Repita pela quantidade prescrita de repetições."]},
"Weighted_Ball_Side_Bend":{"name":"Flexão Lateral na Bola Suíça com Anilha","instructions":["Deite-se de lado apoiando a lateral esquerda do tronco (cintura, quadril e ombro) sobre uma bola suíça.","Firme os pés no chão com pernas cruzadas e segure uma anilha com a mão direita junto ao lado direito da cabeça (lado liso apoiado na cabeça).","Cruze o braço esquerdo sobre o tronco apoiando a mão nos oblíquos. Esta é a posição inicial.","Eleve a lateral do tronco flexionando a cintura lateralmente enquanto expira.","Segure a contração por um segundo e desça lentamente à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições.","Troque de lado e repita o exercício."]},
"Weighted_Bench_Dip":{"name":"Mergulho no Banco com Peso","instructions":["Posicione dois bancos paralelos entre si; de costas para um deles, apoie as mãos na borda na largura dos ombros com os braços estendidos.","Apoie as pernas estendidas sobre o outro banco à frente e peça a um parceiro para colocar uma anilha ou halter sobre o seu colo. Esta será a sua posição inicial.","Desça lentamente flexionando os cotovelos até formar um ângulo ligeiramente menor que 90 graus enquanto inspira, mantendo os cotovelos próximos ao corpo.","Empurre o corpo de volta à posição inicial usando o tríceps enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Weighted_Crunches":{"name":"Abdominal Supra com Peso","instructions":["Deite-se de costas com os pés apoiados no chão ou sobre um banco com os joelhos flexionados a 90 graus.","Segure uma anilha ou halter junto ao peito ou estendido acima do tronco. Esta será a sua posição inicial.","Expire e desencoste lentamente os ombros cerca de 4 polegadas do chão mantendo a lombar pressionada no solo.","No topo, contraia bem o abdômen e faça uma breve pausa.","Inspire e desça lentamente de volta à posição inicial."]},
"Weighted_Jump_Squat":{"name":"Agachamento com Salto com Carga","instructions":["Posicione uma barra leve na parte posterior dos ombros (ou use colete com peso).","Mantenha os pés um pouco além da largura dos ombros com cabeça e peito erguidos. Esta será a sua posição inicial.","Agache parcialmente e inverta imediatamente explodindo para cima estendendo quadril, joelhos e tornozelos com boa postura.","Ao aterrissar, amorteça o impacto flexionando as pernas."]},
"Weighted_Pull_Ups":{"name":"Barra Fixa com Carga Adicional","instructions":["Prenda um peso a um cinto de sobrecarga na cintura e segure a barra fixa com pegada pronada na largura dos ombros e braços estendidos.","Incline o tronco cerca de 30 graus para trás criando leve curvatura lombar e abrindo o peito. Esta será a sua posição inicial.","Expire e puxe o corpo para cima até a cabeça passar das mãos, apertando as escápulas para trás e para baixo no topo.","Após uma breve pausa no topo, inspire e desça lentamente até estender os braços e alongar totalmente as dorsais."]},
"Weighted_Sissy_Squat":{"name":"Agachamento Sissy com Peso","instructions":["Fique em pé com pés na largura dos ombros e calcanhares elevados (na ponta dos pés), segurando a coluna de um rack com uma mão e uma anilha junto ao peito com a outra. Esta é a posição inicial.","Flexione os joelhos projetando joelhos e pelve para a frente enquanto inclina o tronco para trás até quase formar 90 graus nos joelhos enquanto inspira, segurando um segundo.","Use a força dos quadríceps para retornar o tronco à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Weighted_Sit-Ups_-_With_Bands":{"name":"Abdominal no Banco Declinado com Elástico","instructions":["Prenda os elásticos na base do banco declinado deixando as alças acessíveis na parte interna ao deitar.","Prenda as pernas no apoio, deite-se e segure as alças junto às clavículas em pegada neutra mantendo os braços imóveis durante todo o exercício. Esta é a posição inicial.","Eleve o tronco até ficar perpendicular ao chão enquanto expira, segure por um segundo e desça de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Weighted_Squat":{"name":"Agachamento com Cinto de Carga entre Bancos","instructions":["Posicione dois bancos retos paralelos na largura dos ombros, suba sobre eles com pontas dos pés para fora e prenda um cinto com carga pendurado entre as pernas.","Fique ereto com os braços estendidos ao lado do corpo. Esta é a posição inicial.","Agache flexionando os joelhos mantendo cabeça erguida e costas retas até as coxas ficarem abaixo do paralelo enquanto inspira, sem deixar os joelhos passarem dos dedos dos pés.","Empurre pelos pés estendendo as pernas para retornar à posição inicial enquanto expira.","Repita pela quantidade recomendada de repetições."]},
"Wide-Grip_Barbell_Bench_Press":{"name":"Supino Reto com Barra - Pegada Aberta","instructions":["Deite-se em um banco reto com os pés firmes no chão, segure a barra com pegada pronada aberta (cerca de 3 polegadas além da largura dos ombros de cada lado) e mantenha os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça a barra lentamente até sentir tocar o meio do peito.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando o peitoral, segure um segundo no topo e desça lentamente novamente (descida cerca do dobro da subida).","Repita pela quantidade prescrita de repetições."]},
"Wide-Grip_Decline_Barbell_Bench_Press":{"name":"Supino Declinado com Barra - Pegada Aberta","instructions":["Deite-se em um banco declinado com os pés travados no apoio, retire a barra com pegada pronada aberta (cerca de 3 polegadas além dos ombros de cada lado) e segure-a com os braços estendidos. Esta será a sua posição inicial.","Enquanto inspira, desça a barra lentamente até sentir tocar a parte inferior do peito.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial enquanto expira usando o peitoral, segure um segundo no topo e desça lentamente novamente.","Repita pela quantidade prescrita de repetições."]},
"Wide-Grip_Decline_Barbell_Pullover":{"name":"Pullover Declinado com Barra - Pegada Aberta","instructions":["Deite-se em um banco declinado com as pernas presas, alcance a barra atrás da cabeça com pegada pronada mais aberta que os ombros e erga-a acima do peito.","Mantenha os braços totalmente estendidos perpendiculares ao chão. Esta é a posição inicial.","Abaixe a barra em semicírculo atrás da cabeça até os braços ficarem paralelos ao chão mantendo os cotovelos estendidos enquanto inspira.","Traga a barra de volta à posição inicial enquanto expira mantendo controle total.","Repita pela quantidade prescrita de repetições.","Ao finalizar a série, abaixe lentamente a barra atrás da cabeça até o chão."]},
"Wide-Grip_Lat_Pulldown":{"name":"Puxada Frontal Aberta (Pulley Frente)","instructions":["Sente-se no aparelho de puxada alta com a barra longa acoplada na polia superior e ajuste o apoio de joelhos.","Segure a barra com pegada pronada aberta (mais larga que a largura dos ombros).","Com os braços estendidos acima, incline o tronco cerca de 30 graus para trás criando leve curvatura lombar e abrindo o peito. Esta é a posição inicial.","Ao expirar, puxe a barra para baixo até tocar a parte superior do peito levando ombros e braços para baixo e para trás e contraindo as costas sem mover o tronco.","Após segurar um segundo apertando as escápulas, eleve lentamente a barra de volta à posição inicial com as dorsais alongadas enquanto inspira.","Repita pela quantidade prescrita de repetições."]},
"Wide-Grip_Pulldown_Behind_The_Neck":{"name":"Puxada Atrás da Nuca (Pulley Costas)","instructions":["Sente-se no aparelho de puxada alta com barra longa acoplada na polia superior e ajuste o apoio de joelhos.","Segure a barra com pegada pronada aberta (mais larga que a largura dos ombros).","Com os braços estendidos acima, incline levemente o tronco e a cabeça à frente alinhando a barra à nuca. Esta é a posição inicial.","Ao expirar, puxe a barra para baixo até tocar suavemente a nuca levando ombros e braços para baixo e para trás enquanto contrai as costas sem mover o tronco.","Após segurar um segundo apertando as escápulas, eleve lentamente a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade prescrita de repetições."]},
"Wide-Grip_Rear_Pull-Up":{"name":"Barra Fixa Atrás da Nuca - Pegada Aberta","instructions":["Segure a barra fixa com pegada pronada aberta (palmas voltadas para a frente).","Pendurado com braços estendidos, incline levemente tronco e cabeça à frente alinhando a barra à nuca. Esta é a posição inicial.","Puxe o corpo para cima até a barra se aproximar da nuca levando ombros e braços para baixo e para trás enquanto expira, contraindo bem as costas sem balançar.","Após segurar um segundo na contração, desça lentamente enquanto inspira até estender os braços e alongar as dorsais.","Repita pela quantidade prescrita de repetições."]},
"Wide-Grip_Standing_Barbell_Curl":{"name":"Rosca Direta em Pé com Barra - Pegada Aberta","instructions":["Fique em pé com o tronco ereto segurando a barra com pegada aberta e palmas voltadas para a frente, cotovelos próximos ao tronco. Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos contraindo o bíceps enquanto expira, movendo apenas os antebraços.","Continue até o bíceps contrair totalmente com a barra na altura dos ombros e segure um segundo apertando forte.","Abaixe lentamente a barra de volta à posição inicial enquanto inspira.","Repita pela quantidade recomendada de repetições."]},
"Wide_Stance_Barbell_Squat":{"name":"Agachamento com Barra - Base Aberta","instructions":["Dentro de um rack de agachamento, ajuste a barra na sua altura, entre sob ela apoiando-a na parte posterior dos ombros.","Segure a barra com as duas mãos e retire-a do suporte empurrando com as pernas.","Afaste-se em base mais aberta que a largura dos ombros com as pontas dos pés levemente para fora, mantendo cabeça erguida e costas retas. Esta será a sua posição inicial.","Desça lentamente flexionando os joelhos até as coxas ficarem abaixo do paralelo enquanto inspira, evitando que os joelhos ultrapassem os dedos dos pés.","Suba enquanto expira empurrando pelos calcanhares até estender as pernas e voltar à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Wide_Stance_Stiff_Legs":{"name":"Stiff com Base Aberta e Barra","instructions":["Com uma barra no chão, adote base bem aberta e flexione o quadril para segurar a barra com o quadril bem recuado, pernas quase estendidas, costas retas e peito aberto. Esta será a sua posição inicial.","Estenda o quadril projetando-o à frente com os braços pendurados retos até ficar totalmente em pé e retorne lentamente à posição inicial sem precisar tocar o chão entre repetições."]},
"Wind_Sprints":{"name":"Corrida Suspensa na Barra (Wind Sprints)","instructions":["Pendure-se na barra fixa com pegada pronada e braços e pernas estendidos. Esta será a sua posição inicial.","Eleve rapidamente um joelho o mais alto possível sem balançar o corpo.","Inverta imediatamente abaixando essa perna enquanto eleva o outro joelho o mais alto possível.","Continue alternando as pernas rapidamente até completar a série."]},
"Windmills":{"name":"Moinho Deitado (Alongamento)","instructions":["Deite-se de costas com os braços abertos para os lados e as pernas estendidas. Esta será a sua posição inicial.","Eleve uma perna e cruze-a rapidamente sobre o corpo tentando tocar o chão próximo à mão oposta.","Retorne à posição inicial e repita com a outra perna, alternando por 10-20 repetições."]},
"Worlds_Greatest_Stretch":{"name":"Maior Alongamento do Mundo (World's Greatest Stretch)","instructions":["Dê um passo longo à frente em avanço com o pé da frente todo no chão e o de trás na ponta, descendo até o joelho de trás quase tocar o solo com tronco ereto; segure por 10-20 segundos.","Apoie o braço do mesmo lado da perna da frente no chão com o cotovelo próximo ao pé e a outra mão no chão ao lado para apoio.","Após 10-20 segundos, apoie uma mão de cada lado do pé da frente, eleve a ponta do pé e estenda a perna da frente por 10-20 segundos; depois repita toda a sequência para o outro lado."]},
"Wrist_Circles":{"name":"Círculos com os Punhos","instructions":["Fique em pé com pés na largura dos ombros e braços estendidos lateralmente paralelos ao chão na altura dos ombros (formando um \"T\") com palmas para baixo. Esta é a posição inicial.","Mantendo o restante do corpo imóvel, gire ambos os punhos em movimento circular para a frente respirando normalmente.","Repita pela quantidade recomendada de repetições."]},
"Wrist_Roller":{"name":"Rolo de Punho (Wrist Roller)","instructions":["Fique em pé com pés na largura dos ombros segurando um rolo de punho com pegada pronada (palmas para baixo).","Estenda os dois braços à frente paralelos ao chão com a corda desenrolada, mantendo todo o corpo imóvel exceto os antebraços. Esta é a posição inicial.","Gire um punho de cada vez para cima enrolando a corda no bastão até o peso subir até a barra.","Quando o peso chegar ao topo, desenrole lentamente girando os punhos no sentido inverso até o peso retornar à posição inicial.","Repita pela quantidade prescrita de repetições."]},
"Wrist_Rotations_with_Straight_Bar":{"name":"Rotações de Punho com Barra Reta","instructions":["Segure uma barra com as duas mãos na largura dos ombros e palmas voltadas para baixo. Esta será a sua posição inicial.","Alternando entre as mãos, estenda os punhos girando a barra como se enrolasse um jornal até a falha.","Inverta o movimento flexionando os punhos para girar no sentido oposto alternadamente até a falha."]},
"Yoke_Walk":{"name":"Caminhada com Canga (Yoke Walk)","instructions":["Este exercício utiliza a estrutura yoke (canga) apoiada nas costas.","Entre sob a canga apoiando-a na parte posterior dos ombros, olhe para a frente com costas firmes e tire a carga do chão empurrando pelos calcanhares.","Caminhe o mais rápido possível com passos curtos e rápidos segurando as hastes laterais para estabilizar até completar a distância (geralmente 75-100 pés)."]},
"Zercher_Squats":{"name":"Agachamento Zercher","instructions":["Dentro de um rack de agachamento, ajuste a barra entre a cintura e o peito, entrelace as mãos e encaixe a barra na dobra dos cotovelos entre braços e antebraços.","Retire a barra mantendo-a apoiada nos antebraços com os braços cruzados à frente do tronco.","Afaste-se em base média na largura dos ombros com pontas levemente para fora, cabeça erguida e costas retas. Esta será a sua posição inicial.","Desça flexionando os joelhos com postura ereta até as coxas ficarem abaixo do paralelo enquanto inspira, sem deixar os joelhos ultrapassarem os dedos dos pés.","Suba enquanto expira empurrando principalmente pela parte anterior dos pés até estender as pernas de volta à posição inicial.","Repita pela quantidade recomendada de repetições."]},
"Zottman_Curl":{"name":"Rosca Zottman","instructions":["Fique em pé com o tronco ereto segurando um halter em cada mão ao lado do corpo com cotovelos próximos ao tronco.","Mantenha as palmas voltadas uma para a outra (pegada neutra). Esta será a sua posição inicial.","Mantendo a parte superior dos braços imóvel, flexione os cotovelos girando os punhos para pegada supinada (palmas para cima) enquanto contrai o bíceps e expira até chegar à altura dos ombros.","Segure a contração por um segundo apertando o bíceps.","No topo, gire os punhos para pegada pronada (palmas para baixo) com polegares mais altos que os dedos mínimos.","Abaixe lentamente os halteres usando a pegada pronada.","Ao aproximar das coxas, gire os punhos de volta para pegada neutra.","Repita pela quantidade recomendada de repetições."]},
"Zottman_Preacher_Curl":{"name":"Rosca Zottman no Banco Scott","instructions":["Segure um halter em cada mão apoiando os braços sobre o banco Scott na altura dos ombros com cotovelos flexionados e palmas voltadas para baixo. Esta será a sua posição inicial.","Enquanto inspira, abaixe lentamente os halteres mantendo as palmas para baixo até estender os braços e alongar totalmente o bíceps.","Em baixo, gire os punhos para pegada supinada (palmas para cima).","Ao expirar, flexione os cotovelos contraindo o bíceps até a altura dos ombros (mantendo o dedo mínimo ligeiramente mais alto que o polegar).","Aperte o bíceps por um segundo no topo e gire os punhos novamente para pegada pronada.","Repita pela quantidade recomendada de repetições."]}
}
$pt$::jsonb) AS t
  WHERE e.external_id = t.key;

  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 876 THEN
    RAISE EXCEPTION 'exercise_library pt-BR: esperado 876 linhas, atualizadas %', n;
  END IF;
END
$do$;

COMMENT ON COLUMN public.exercise_library.name_en IS
  'Nome original em inglês (free-exercise-db), preservado após a tradução do catálogo para pt-BR (#124).';
COMMENT ON COLUMN public.exercise_library.instructions_en IS
  'Instruções originais em inglês (free-exercise-db), preservadas após a tradução do catálogo para pt-BR (#124).';

NOTIFY pgrst, 'reload schema';
